INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12971, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "表示物体运动快慢的物理量，是速度的大小。", "primary_collocate": null, "pronunciation": "sù lǜ", "ipa": "su˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "子弹离开枪口时的速率非常高。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的速率是每小时六十公里。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流的速率变快了。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验数据表明，小球下落时的速率逐渐增大。", "target_word": "速率", "complexity_tier": "T3", "furigana": "sù lǜ", "sentence_source": "generated"}, {"text": "速率越大，物体跑得越快。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家测量了小球的速率。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风的速率是每秒十米。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨后，河水的速率增加了。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的转动速率很稳定。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中，速率最快的是红色小球。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反应速率", "label": "复合词"}, {"form": "平均速率", "label": "复合词"}, {"form": "速率快", "label": "短语"}], "register": "科技书面语", "sense_fingerprint": "物体运动快慢的物理量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5af2ec-2319-44fd-ab0e-6a7a7c95acf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12971, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "速率", "is_correct": true, "explanation": "正确。“子弹离开枪口时的速率”指子弹运动的快慢，“非常高”正是对速率大小的描述。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能用“非常高”来形容，句子不通。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”指长短，子弹的长短不能说“非常高”，句子不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不用来形容子弹，“子弹的年龄非常高”搭配不当。"}], "explanations": {"速率": "正确。“子弹离开枪口时的速率”指子弹运动的快慢，“非常高”正是对速率大小的描述。", "颜色": "语义：“颜色”指色彩，不能用“非常高”来形容，句子不通。", "长度": "语义：“长度”指长短，子弹的长短不能说“非常高”，句子不通。", "年龄": "搭配：“年龄”不用来形容子弹，“子弹的年龄非常高”搭配不当。"}, "sentence_index": 0, "correct_answer": "速率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "银行的速率越来越高。", "explanation": "这里应该用〈利率〉。利率指利息与本金的比率，速率指运动的快慢，银行的利息比率不说速率。"}, {"text": "这个班的男女速率是一比一。", "explanation": "这里应该用〈比率〉。比率指两个数量的比值，速率指运动快慢，二者不能互换。"}, {"text": "这块金属的速率很大。", "explanation": "这里应该用〈密度〉。密度指单位体积的质量，速率指运动快慢，金属的密度不说速率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12971, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速率", "is_correct": true, "explanation": "正确。“速率”指风的运动快慢，“每秒十米”正是速率的数值。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热的程度，不能用“每秒十米”来衡量，“风的温度是每秒十米”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，不能用来描述风，句子不通。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：“湿度”指空气干湿的程度，不能用“每秒十米”来表示，句子不通。"}], "explanations": {"速率": "正确。“速率”指风的运动快慢，“每秒十米”正是速率的数值。", "温度": "语义：“温度”指冷热的程度，不能用“每秒十米”来衡量，“风的温度是每秒十米”说不通。", "体重": "语义：“体重”指身体的重量，不能用来描述风，句子不通。", "湿度": "语义：“湿度”指空气干湿的程度，不能用“每秒十米”来表示，句子不通。"}, "sentence_index": 6, "correct_answer": "速率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的速率每年增加两千人。", "explanation": "这里应该用〈出生率〉。出生率指单位时间内出生人数的比例，速率指运动快慢，人口出生不能说速率。"}, {"text": "这次考试的速率很高。", "explanation": "这里应该用〈合格率〉。合格率指合格人数的比例，速率指运动快慢，考试不说速率。"}, {"text": "今天的速率是三十度。", "explanation": "这里应该用〈温度〉。温度指冷热的程度，速率指物体移动的快慢，天气不能用速率来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这艘船的速率到达每小时二十公里。", "corrected_sentence": "这艘船的速率达到每小时二十公里。", "error_description": "错误形式是“到达”，正确形式是“达到”。“达到”表示数值达到某个标准，“到达”是指到某个地方，不能用于速率的数值。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下雨以后，小溪的速率变了快。", "corrected_sentence": "下雨以后，小溪的速率变快了。", "error_description": "错误形式是“变了快”，正确形式是“变快了”。“了”表示变化的完成，应放在补语“快”之后，不能放在“变”和“快”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
