INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12972, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事科学研究或学术探索的人。", "primary_collocate": null, "pronunciation": "yán jiū zhě", "ipa": "jɛn˧˥ tɕjoʊ˥ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这位研究者每天都在实验室工作。", "target_word": "研究者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者发现了一种新的治疗方法。", "target_word": "研究者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在海洋馆工作，是一名优秀的研究者。", "target_word": "研究者", "complexity_tier": "T3", "furigana": "tā zài hǎiyáng guǎn gōngzuò, shì yì míng yōuxiù de yán jiū zhě。", "sentence_source": "generated"}, {"text": "几位研究者正在讨论这次实验的结果。", "target_word": "研究者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就想当一名研究者。", "target_word": "研究者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者需要认真记录每一个数据。", "target_word": "研究者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究者写过很多关于气候的文章。", "target_word": "研究者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者们把样品放进了冰箱。", "target_word": "研究者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的研究者向老师请教了这个问题。", "target_word": "研究者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者对这个问题很感兴趣，所以一直在查资料。", "target_word": "研究者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位研究者", "label": "量词"}, {"form": "一名研究者", "label": "量词"}, {"form": "研究者们", "label": "复数"}], "register": "中性", "sense_fingerprint": "从事科学研究、学术探索的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82b7b2-23d4-4ad6-a0b8-5954ca1e3faa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12972, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究者", "is_correct": true, "explanation": "正确：研究者指从事研究的人，在实验室工作与句意相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师在厨房工作，不在实验室做研究。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员主要在舞台或片场工作，与实验室无关。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：「司机」一般说「开车」，不说「在实验室工作」。"}], "explanations": {"研究者": "正确：研究者指从事研究的人，在实验室工作与句意相符。", "厨师": "语义：厨师在厨房工作，不在实验室做研究。", "演员": "语义：演员主要在舞台或片场工作，与实验室无关。", "司机": "搭配：「司机」一般说「开车」，不说「在实验室工作」。"}, "sentence_index": 0, "correct_answer": "研究者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所研究所每年都招收很多新员工，它是一位研究者。", "explanation": "这里把〈研究者〉用来指机构。研究者只指做研究的人，不能用来称呼单位或机构。"}, {"text": "这位研究者每天在街上巡逻，维护治安。", "explanation": "这里应该用〈警察〉。研究者指做研究的人，不负责巡逻、维护治安。"}, {"text": "这位研究者每天在操场上带学生跑步。", "explanation": "这里应该用〈体育老师〉。研究者指做研究的人，不负责带学生跑步、做体育训练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12972, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究者", "is_correct": true, "explanation": "正确：研究者能写关于气候的研究文章，与句意相符。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：「写文章」的主语须是人，「桌子」不能写文章。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会写文章，句中需要的是写文章的人。"}, {"text": "饭馆", "is_correct": false, "explanation": "搭配：「饭馆」不能作「写」的主语，句中需要的是写文章的人。"}], "explanations": {"研究者": "正确：研究者能写关于气候的研究文章，与句意相符。", "桌子": "搭配：「写文章」的主语须是人，「桌子」不能写文章。", "石头": "语义：石头不会写文章，句中需要的是写文章的人。", "饭馆": "搭配：「饭馆」不能作「写」的主语，句中需要的是写文章的人。"}, "sentence_index": 6, "correct_answer": "研究者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一名研究者，每天开车送客人去机场。", "explanation": "这里应该用〈司机〉。研究者指做研究的人，不负责开车送客人。"}, {"text": "这家公司是研究者，专门生产汽车零件。", "explanation": "这里应该用〈企业〉。研究者指人，不能用来指公司。"}, {"text": "那棵树是研究者。", "explanation": "这里应该用〈植物〉。研究者指人，不能用来指树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三名研究者们在实验室里工作。", "corrected_sentence": "三名研究者在实验室里工作。", "error_description": "错误在「研究者们」：「们」不能与数词连用，应说「三名研究者」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这头研究者很有名。", "corrected_sentence": "这位研究者很有名。", "error_description": "错误在量词：「头」用于牲畜，不能用于人，应说「这位研究者」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
