INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12973, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "加入某些物质中用来填充空隙或增加体积、重量、改变性能的材料。", "primary_collocate": null, "pronunciation": "tián liào", "ipa": "tʰjɛn˧˥ ljɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "研究者通过引入纳米填料或光敏基团，使材料在紫外线或机械应力下预先产生微裂纹，从而扩大微生物附着的比表面积，加速降解进程。", "target_word": "填料", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工人在塑料里加了一些填料。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种填料可以让纸更重。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "橡胶中加入填料，可以降低成本。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "填料能填满材料里的小空隙。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每天用很多填料。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塔里一层一层地装着填料，气体从下往上穿过。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加入太多填料，产品会变脆。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师选了一种便宜的填料。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋填料是白色的粉末。", "target_word": "填料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种填料", "label": "量词"}, {"form": "一些填料", "label": "量词"}, {"form": "无机填料", "label": "复合"}, {"form": "惰性填料", "label": "复合"}], "register": "科技", "sense_fingerprint": "加入材料中填充空隙、增加体积或改变性能的物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82b7b2-23d4-4ad6-a0b8-5954ca1e3faa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12973, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "填料", "is_correct": true, "explanation": "正确：填料是加入材料中的物质，与句中的纳米添加物相符。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食品，不能作为引入材料中的成分。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池是供电装置，不能作为加入材料中的填充成分。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：「纳米」修饰的应是材料或添加物，「窗帘」是成品，不能被「引入」材料中。"}], "explanations": {"填料": "正确：填料是加入材料中的物质，与句中的纳米添加物相符。", "面包": "语义：面包是食品，不能作为引入材料中的成分。", "电池": "语义：电池是供电装置，不能作为加入材料中的填充成分。", "窗帘": "搭配：「纳米」修饰的应是材料或添加物，「窗帘」是成品，不能被「引入」材料中。"}, "sentence_index": 0, "correct_answer": "填料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用填料把两块木板粘在一起。", "explanation": "这里应该用〈粘合剂〉。填料用来填充空隙，不起粘合作用，不能把东西粘在一起。"}, {"text": "画家用填料画了一幅画。", "explanation": "这里应该用〈颜料〉。填料用来填充材料，不用来作画。"}, {"text": "医生给病人开了一些填料。", "explanation": "这里应该用〈药品〉。填料不能治病，也不能开给病人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12973, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "填料", "is_correct": true, "explanation": "正确：塔里一层层装的是填充用的填料，与句意相符。"}, {"text": "香肠", "is_correct": false, "explanation": "语义：香肠是食品，不会在塔里一层层装着充当填充物。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，与塔中填充的用途不符。"}, {"text": "枕头", "is_correct": false, "explanation": "搭配：「一层一层的」装在塔里的应是填充物，「枕头」不这样装。"}], "explanations": {"填料": "正确：塔里一层层装的是填充用的填料，与句意相符。", "香肠": "语义：香肠是食品，不会在塔里一层层装着充当填充物。", "饼干": "语义：饼干是食品，与塔中填充的用途不符。", "枕头": "搭配：「一层一层的」装在塔里的应是填充物，「枕头」不这样装。"}, "sentence_index": 6, "correct_answer": "填料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "化学反应中要加入填料，反应才能加快。", "explanation": "这里应该用〈催化剂〉。填料用于填充空隙，不能加快化学反应。"}, {"text": "汽车需要加填料才能跑。", "explanation": "这里应该用〈燃料〉。填料不能提供能量，汽车要加的是燃料。"}, {"text": "厨师在汤里加了一点填料，味道很鲜。", "explanation": "这里应该用〈香料〉。填料是用于材料的填充物，不用于调味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们选了三条新填料。", "corrected_sentence": "我们选了三种新填料。", "error_description": "错误在量词：「条」用于细长的东西，不用于填料，应说「三种新填料」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这头填料很重。", "corrected_sentence": "这包填料很重。", "error_description": "错误在量词：「头」用于牲畜，不能用于填料，应说「这包填料」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
