INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12974, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物质或器件对光线敏感，容易受光照影响而产生反应。", "primary_collocate": null, "pronunciation": "guāng mǐn", "ipa": "kwɑŋ˥ min˨˩˦", "syllable_count": 2, "sentences": [{"text": "研究者通过引入纳米填料或光敏基团，使材料在紫外线或机械应力下预先产生微裂纹，从而扩大微生物附着的比表面积，加速降解进程。", "target_word": "光敏", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种药很光敏，要放在暗处。", "target_word": "光敏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光敏的材料见光就会变色。", "target_word": "光敏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种胶非常光敏，不能放在阳光下。", "target_word": "光敏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种树脂很光敏，要避光保存。", "target_word": "光敏", "complexity_tier": "T3", "furigana": "zhè zhǒng shù zhī hěn guāng mǐn, yào bì guāng bǎo cún.", "sentence_source": "generated"}, {"text": "这种纸比普通纸更光敏。", "target_word": "光敏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种溶液很光敏，要用黑布盖着。", "target_word": "光敏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种涂料光敏，晒太阳后会变硬。", "target_word": "光敏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相用的底片也很光敏。", "target_word": "光敏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶液体太光敏了，请关掉灯。", "target_word": "光敏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "光敏电阻", "label": "复合"}, {"form": "光敏材料", "label": "复合"}, {"form": "光敏树脂", "label": "复合"}], "register": "科技", "sense_fingerprint": "物质或器件对光线敏感，受光照易起反应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82b7b2-23d4-4ad6-a0b8-5954ca1e3faa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光敏", "is_correct": true, "explanation": "正确。“光敏基团”指对光线敏感、受光照会起反应的原子组合，符合句中“紫外线”的语境。"}, {"text": "光滑", "is_correct": false, "explanation": "体貌：“光滑”形容表面平整，不能用来说明化学基团的光学反应，句中也没有相关线索。"}, {"text": "柔软", "is_correct": false, "explanation": "体貌：“柔软”描述质地，与基团在光照下产生微裂纹的作用无关。"}, {"text": "易碎", "is_correct": false, "explanation": "语义：“易碎”说的是物体容易破裂，与句中“紫外线”“微裂纹”的语境不符。"}], "explanations": {"光敏": "正确。“光敏基团”指对光线敏感、受光照会起反应的原子组合，符合句中“紫外线”的语境。", "光滑": "体貌：“光滑”形容表面平整，不能用来说明化学基团的光学反应，句中也没有相关线索。", "柔软": "体貌：“柔软”描述质地，与基团在光照下产生微裂纹的作用无关。", "易碎": "语义：“易碎”说的是物体容易破裂，与句中“紫外线”“微裂纹”的语境不符。"}, "sentence_index": 0, "correct_answer": "光敏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对价格很光敏，一涨价就不买了。", "explanation": "这里应该用〈敏感〉。光敏只用于物质或器件遇光产生反应，不能用来形容人对价格的反应。"}, {"text": "这个孩子对花粉很光敏，一出门就打喷嚏。", "explanation": "这里应该用〈过敏〉。光敏指物质受光照影响而变化，花粉引起的反应与光照无关，不能说光敏。"}, {"text": "这个计划很光敏，大家一看就同意了。", "explanation": "这里把“光敏”用成了〈吸引人〉的意思。光敏指物质或器件遇光产生反应，计划与光照无关，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光敏", "is_correct": true, "explanation": "正确。“光敏”说明溶液怕光，所以要用黑布盖着，符合句意。"}, {"text": "粘稠", "is_correct": false, "explanation": "体貌：“粘稠”形容液体浓稠的样子，与需要用黑布遮盖的理由无关。"}, {"text": "甜", "is_correct": false, "explanation": "语义：溶液的甜味与是否需要避光无关，句中没有这样的线索。"}, {"text": "咸", "is_correct": false, "explanation": "语义：咸味不能说明溶液要用黑布盖着，句意不通。"}], "explanations": {"光敏": "正确。“光敏”说明溶液怕光，所以要用黑布盖着，符合句意。", "粘稠": "体貌：“粘稠”形容液体浓稠的样子，与需要用黑布遮盖的理由无关。", "甜": "语义：溶液的甜味与是否需要避光无关，句中没有这样的线索。", "咸": "语义：咸味不能说明溶液要用黑布盖着，句意不通。"}, "sentence_index": 6, "correct_answer": "光敏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的耳朵很光敏，一有声音就醒了。", "explanation": "这里应该用〈灵敏〉。光敏指东西遇光起变化，不能用来说耳朵对声音的反应。"}, {"text": "这把椅子很光敏，坐久了会变形。", "explanation": "这里应该用〈不结实〉。光敏指物质或器件遇光产生反应，椅子坐久变形与光照无关，不能用来形容它。"}, {"text": "他今天的心情很光敏，一句玩笑就哭了。", "explanation": "这里应该用〈脆弱〉。光敏指物质或器件遇光产生反应，不能用来形容人的情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种膜很光敏地，遇光就会变色。", "corrected_sentence": "这种膜很光敏，遇光就会变色。", "error_description": "错误在「地」的位置：形容词「光敏」作谓语时后面不加「地」，应说「很光敏」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这层涂料光敏厉害，见光就发黄。", "corrected_sentence": "这层涂料光敏得厉害，见光就发黄。", "error_description": "程度补语的标志“得”漏掉了。应说“光敏得厉害”，“光敏”后面要用“得”引出程度补语，不能直接说“光敏厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
