INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12975, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12975, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "基团是指分子中具有特定化学性质或结构特征的原子组合，是化合物中的基本组成部分。", "primary_collocate": null, "pronunciation": "jī tuán", "ipa": "tɕi˥ tʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "研究者通过引入纳米填料或光敏基团，使材料在紫外线或机械应力下预先产生微裂纹，从而扩大微生物附着的比表面积，加速降解进程。", "target_word": "基团", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种分子含有一个特殊的基团。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基团由几个原子组成。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学家研究了这个基团的结构。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机分子上的基团决定它的性质。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在分子上加了一个新基团。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的基团让化合物有不同的性质。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个分子的基团完全不同。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中这个基团很容易发生反应。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画出了这个基团。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "官能团", "label": "复合词"}], "register": "科技", "sense_fingerprint": "化学：分子中具有特定性质或结构的原子组合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82b7b2-23d4-4ad6-a0b8-5954ca1e3faa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12975, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基团", "is_correct": true, "explanation": "正确。“光敏基团”是分子中对光有反应的原子组合，符合句中“引入”“产生微裂纹”的语境。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是生物体，句中是为了改变材料性质而引入的化学结构，不能说引入病毒。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：乐曲不是化学结构，“引入乐曲”无法让材料产生微裂纹。"}, {"text": "大楼", "is_correct": false, "explanation": "搭配：“引入”不搭配“大楼”，也不能说“光敏大楼”。"}], "explanations": {"基团": "正确。“光敏基团”是分子中对光有反应的原子组合，符合句中“引入”“产生微裂纹”的语境。", "病毒": "语义：病毒是生物体，句中是为了改变材料性质而引入的化学结构，不能说引入病毒。", "乐曲": "语义：乐曲不是化学结构，“引入乐曲”无法让材料产生微裂纹。", "大楼": "搭配：“引入”不搭配“大楼”，也不能说“光敏大楼”。"}, "sentence_index": 0, "correct_answer": "基团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个基团有三十名成员。", "explanation": "这里应该用〈团体〉。基团是分子中的原子组合，不指一群人，不能说有多少名成员。"}, {"text": "这台机器的基团坏了。", "explanation": "这里应该用〈零件〉。基团是化学术语，指分子中的原子组合，不能指机器的零件。"}, {"text": "这个基团很可爱，孩子们都喜欢它。", "explanation": "这里应该用〈小动物〉。基团是化学术语，指分子中的原子组合，不是可爱的动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12975, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基团", "is_correct": true, "explanation": "正确。“不同的基团”让化合物有不同的性质，是化学中的组成部分，符合句意。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不是分子的组成部分，无法让化合物有不同的性质。"}, {"text": "旋律", "is_correct": false, "explanation": "语义：旋律是音乐的组成部分，与化合物的性质无关，句意不通。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不是化学结构，句中讲的是化合物的性质，没有这样的语境。"}], "explanations": {"基团": "正确。“不同的基团”让化合物有不同的性质，是化学中的组成部分，符合句意。", "老虎": "语义：老虎是动物，不是分子的组成部分，无法让化合物有不同的性质。", "旋律": "语义：旋律是音乐的组成部分，与化合物的性质无关，句意不通。", "花朵": "语义：花朵不是化学结构，句中讲的是化合物的性质，没有这样的语境。"}, "sentence_index": 6, "correct_answer": "基团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家基团有三万名员工。", "explanation": "这里应该用〈集团〉。基团是化学术语，指分子中的原子组合，不能指公司或企业。"}, {"text": "他的数学基团很扎实，考试没问题。", "explanation": "这里应该用〈基础〉。基团是化学术语，指分子中的原子组合，不能用来说数学的根基。"}, {"text": "他把这个基团送给了朋友。", "explanation": "这里应该用〈物件〉。基团是化学术语，指分子中的原子组合，不是可以拿来送人的实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12975, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个分子里有一条基团，决定了它的性质。", "corrected_sentence": "这个分子里有一个基团，决定了它的性质。", "error_description": "量词用错。“基团”应该用“个”，“条”用于细长的东西，不能用来数基团。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那种分子的基团特别。", "corrected_sentence": "那种分子的基团很特别。", "error_description": "程度副词“很”漏掉了。应说“基团很特别”，形容词“特别”作谓语，肯定陈述时前面一般要加“很”等程度副词，不能直接说“基团特别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12976, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12976, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12976, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "紫外线是太阳光中波长比可见光短、能量较高的电磁辐射，过量照射会损伤皮肤和眼睛。", "primary_collocate": null, "pronunciation": "zǐ wài xiàn", "ipa": "tsɨ˨˩˦ waɪ˥˩ ɕjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "研究者通过引入纳米填料或光敏基团，使材料在紫外线或机械应力下预先产生微裂纹，从而扩大微生物附着的比表面积，加速降解进程。", "target_word": "紫外线", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "紫外线的波长比可见光短。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过量的紫外线会损伤皮肤和眼睛。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "臭氧层能挡住大部分紫外线。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院用紫外线给房间杀菌。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "紫外线的能量比可见光高。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的紫外线特别强，要涂防晒霜。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的眼睛看不见紫外线。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用仪器测量紫外线的强度。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种塑料遇到紫外线就会变脆。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "束", "label": "量词"}, {"form": "紫外辐射", "label": "复合词"}], "register": "科技", "sense_fingerprint": "物理：波长比可见光短、能量较高的电磁辐射", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82b7b2-23d4-4ad6-a0b8-5954ca1e3faa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "紫外线", "is_correct": true, "explanation": "正确答案。句中“在紫外线或机械应力下”的紫外线是使材料产生微裂纹的光照条件之一。"}, {"text": "科学家", "is_correct": false, "explanation": "语义：科学家是人，不是能使材料受到作用的条件，与句中“材料在……下”不符。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“在……下”后接的是环境或作用条件，不能说“性格”。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不是能使材料产生微裂纹的光或力，与句中光敏基团的语境不符。"}], "explanations": {"紫外线": "正确答案。句中“在紫外线或机械应力下”的紫外线是使材料产生微裂纹的光照条件之一。", "科学家": "语义：科学家是人，不是能使材料受到作用的条件，与句中“材料在……下”不符。", "性格": "搭配：“在……下”后接的是环境或作用条件，不能说“性格”。", "咖啡": "语义：咖啡不是能使材料产生微裂纹的光或力，与句中光敏基团的语境不符。"}, "sentence_index": 0, "correct_answer": "紫外线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台遥控器靠紫外线来控制电视。", "explanation": "这里应该用〈红外线〉。遥控器靠红外线传递信号；紫外线能量高，会伤害皮肤和眼睛，不用于遥控。"}, {"text": "这台灯的紫外线很柔和。", "explanation": "这里应该用〈光线〉。紫外线是看不见、能量高的光，不能用“柔和”来形容。"}, {"text": "夜里路灯的紫外线很亮，我们能看清路。", "explanation": "这里应该用〈可见光〉。可见光人眼能看见，能照明；紫外线人眼看不见，不能用来照亮道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紫外线", "is_correct": true, "explanation": "正确答案。“夏天的紫外线特别强”指夏天的阳光中紫外线很强，所以要涂防晒霜。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音与后文“要涂防晒霜”的语境不符，防晒霜是针对光照的。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“强”不能修饰树叶，这里要表示光照的强弱。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉不能有“强”的光照，与夏天防晒的语境不符。"}], "explanations": {"紫外线": "正确答案。“夏天的紫外线特别强”指夏天的阳光中紫外线很强，所以要涂防晒霜。", "声音": "语义：声音与后文“要涂防晒霜”的语境不符，防晒霜是针对光照的。", "树叶": "搭配：“强”不能修饰树叶，这里要表示光照的强弱。", "香蕉": "语义：香蕉不能有“强”的光照，与夏天防晒的语境不符。"}, "sentence_index": 6, "correct_answer": "紫外线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋子里有一本紫外线。", "explanation": "这里应该用〈束〉。“本”用于书册，紫外线是光，计量光线要用“束”。"}, {"text": "实验室里有一块紫外线。", "explanation": "这里应该用〈束〉。“块”用于块状的固体，紫外线是光，计量光线要用“束”。"}, {"text": "墙角有一张紫外线。", "explanation": "这里应该用〈束〉。“张”用于纸、桌子等扁平的东西，紫外线是光，计量光线要用“束”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "紫外线地能量很高。", "corrected_sentence": "紫外线的能量很高。", "error_description": "结构助词用错。“紫外线”修饰名词“能量”，应用“的”，说“紫外线的能量”；“地”用于修饰动词，不能放在名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种塑料很快会紫外线下变脆。", "corrected_sentence": "这种塑料很快会在紫外线下变脆。", "error_description": "介词漏用：「紫外线下」前缺少“在”，应为「在紫外线下」，表示在紫外线照射的条件下。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
