INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12978, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12978, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体受到外力作用时，内部产生的抵抗变形的力。", "primary_collocate": null, "pronunciation": "yìng lì", "ipa": "iŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "研究者通过引入纳米填料或光敏基团，使材料在紫外线或机械应力下预先产生微裂纹，从而扩大微生物附着的比表面积，加速降解进程。", "target_word": "应力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "桥受到重压时，里面会产生应力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "应力太大，材料就会裂开。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师计算了钢梁里的应力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物体变形时，内部会出现应力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块玻璃里的应力很大，容易碎。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "应力是抵抗变形的力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度变化会让金属内部产生应力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "测量应力可以判断桥是否安全。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "材料受到拉力后，应力随之增大。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应力集中", "label": "复合词"}, {"form": "残余应力", "label": "复合词"}], "register": "科技", "sense_fingerprint": "力学：物体受外力时内部抵抗变形的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82b7b2-23d4-4ad6-a0b8-5954ca1e3faa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应力", "is_correct": true, "explanation": "正确答案。“机械应力”指材料受外力时内部抵抗变形的力。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“机械”修饰的是力，不能与“温度”搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是使材料产生微裂纹的作用力，与句中语境不符。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：微笑与材料受力无关，不能作为产生微裂纹的条件。"}], "explanations": {"应力": "正确答案。“机械应力”指材料受外力时内部抵抗变形的力。", "温度": "搭配：“机械”修饰的是力，不能与“温度”搭配。", "颜色": "语义：颜色不是使材料产生微裂纹的作用力，与句中语境不符。", "微笑": "语义：微笑与材料受力无关，不能作为产生微裂纹的条件。"}, "sentence_index": 0, "correct_answer": "应力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最近工作应力很大。", "explanation": "这里应该用〈压力〉。应力指物体内部抵抗变形的力，人的心理负担要用“压力”。"}, {"text": "空气应力会让飞机变慢。", "explanation": "这里应该用〈阻力〉。应力指物体内部产生的力，阻碍运动的空气阻力不能说应力。"}, {"text": "汽车的应力很足。", "explanation": "这里应该用〈动力〉。应力是物体内部的力，指推动汽车运动的能力要用“动力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应力", "is_correct": true, "explanation": "正确答案。应力是物体受外力时内部抵抗变形的力，与句中定义相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是力，不能抵抗变形，与句中的定义相悖。"}, {"text": "疾病", "is_correct": false, "explanation": "搭配：“抵抗变形”的主语应是力，疾病不能抵抗变形。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，与“抵抗变形的力”的定义无关。"}], "explanations": {"应力": "正确答案。应力是物体受外力时内部抵抗变形的力，与句中定义相符。", "颜色": "语义：颜色不是力，不能抵抗变形，与句中的定义相悖。", "疾病": "搭配：“抵抗变形”的主语应是力，疾病不能抵抗变形。", "蛋糕": "语义：蛋糕是食物，与“抵抗变形的力”的定义无关。"}, "sentence_index": 6, "correct_answer": "应力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "材料里有一颗应力。", "explanation": "这里应该用〈种〉。“颗”用于颗粒状的东西，应力是一类力，应用“种”。"}, {"text": "钢梁里有一块应力。", "explanation": "这里应该用〈种〉。“块”用于块状的实物，应力是一种力，应用“种”。"}, {"text": "金属里有一张应力。", "explanation": "这里应该用〈种〉。“张”用于扁平的东西，应力应用“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块应力很大。", "corrected_sentence": "这种应力很大。", "error_description": "量词错误：「这块应力」应为「这种应力」。应力是一类力，不是块状的实物，应用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "钢梁受力后，应力增大了着。", "corrected_sentence": "钢梁受力后，应力增大了。", "error_description": "动态助词叠用：“了”和“着”不能同时用在“增大”之后，应只说“增大了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
