INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12979, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在事情发生或进行之前，事先做好准备或安排。", "primary_collocate": null, "pronunciation": "yù xiān", "ipa": "y˥˩ ɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "开会前，请预先把材料发给大家。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人要来，妈妈预先做好了饭。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去旅行前，我预先订好了酒店。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师预先告诉我们明天要考试。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能来的话，请预先告诉我。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜很难做，要预先准备材料。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他预先买好了票，所以没排队。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请预先交钱，再来上课。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以前，我们预先收好了衣服。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司预先通知了所有的客人。", "target_word": "预先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：事情发生或进行之前，事先做好准备或安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f70ce21-a5b1-4c2c-be9e-0c290ce26038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12979, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刚", "is_correct": false, "explanation": "语义：刚表示动作刚刚完成，与「开会前」的将来时间矛盾，也不能用于「请……」的祈使句。"}, {"text": "预先", "is_correct": true, "explanation": "预先表示事情发生之前先做好准备，与「开会前」和「请……」的事先安排相合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：忽然表示出乎意料地突然发生，与事先安排「请……」相反。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：一直修饰持续的动作，不能修饰「发」这样一次性完成的动作，也与「开会前」的时间点不合。"}], "explanations": {"刚": "语义：刚表示动作刚刚完成，与「开会前」的将来时间矛盾，也不能用于「请……」的祈使句。", "预先": "预先表示事情发生之前先做好准备，与「开会前」和「请……」的事先安排相合。", "忽然": "语义：忽然表示出乎意料地突然发生，与事先安排「请……」相反。", "一直": "搭配：一直修饰持续的动作，不能修饰「发」这样一次性完成的动作，也与「开会前」的时间点不合。"}, "sentence_index": 0, "correct_answer": "预先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们努力了很久，预先失败了。", "explanation": "这里应该用〈结果〉。预先表示事先做好准备，「失败」是努力之后的结果，不能事先安排，所以「预先」用在这里不通。"}, {"text": "会议结束以后，我们预先整理了资料。", "explanation": "这里应该用〈事后〉。预先指事情发生之前做准备，与「会议结束以后」的时间顺序矛盾。"}, {"text": "一开始大家不熟，预先成了朋友。", "explanation": "这里应该用〈后来〉。预先只用于事情发生前的准备，不能描述关系逐渐发生的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12979, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白白", "is_correct": false, "explanation": "语义：白白表示徒劳无益，与「所以没排队」的好结果相反。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：从来要与否定词连用，不能和「买好了」这样的肯定完成句搭配。"}, {"text": "预先", "is_correct": true, "explanation": "预先表示事先做好准备，与「买好了票」的结果相合，所以不用排队。"}, {"text": "正在", "is_correct": false, "explanation": "语义：正在表示动作进行中，与「买好了」的已完成状态矛盾。"}], "explanations": {"白白": "语义：白白表示徒劳无益，与「所以没排队」的好结果相反。", "从来": "搭配：从来要与否定词连用，不能和「买好了」这样的肯定完成句搭配。", "预先": "预先表示事先做好准备，与「买好了票」的结果相合，所以不用排队。", "正在": "语义：正在表示动作进行中，与「买好了」的已完成状态矛盾。"}, "sentence_index": 6, "correct_answer": "预先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在街上预先遇到了老同学。", "explanation": "这里应该用〈偶然〉。预先表示事先准备，遇到老同学是没有计划的意外。"}, {"text": "我预先说错了话。", "explanation": "这里应该用〈无意中〉。预先表示事先准备，说错话是无意发生的，不可能事先安排。"}, {"text": "他预先笑了一下。", "explanation": "这里应该用〈忽然〉。预先指事先做准备，笑的动作是突然发生的，不是事先安排的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们预先了把票订好了。", "corrected_sentence": "我们预先把票订好了。", "error_description": "错误：「预先」是副词，后面不能直接加「了」。「了」应放在动词「订好」之后，应写作「我们预先把票订好了」，不能说「预先了把票订好了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天把预先买好了票。", "corrected_sentence": "他昨天预先买好了票。", "error_description": "错误：「把」字后直接接副词「预先」，缺少名词宾语，「把」字结构不成立。应写作「他昨天预先买好了票」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
