INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12981, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指物体表面出现的细长缝隙或裂痕。", "primary_collocate": null, "pronunciation": "liè wén", "ipa": "ljɛ˥˩ wən˧˥", "syllable_count": 2, "sentences": [{"text": "研究者通过引入纳米填料或光敏基团，使材料在紫外线或机械应力下预先产生微裂纹，从而扩大微生物附着的比表面积，加速降解进程。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个杯子上有一条小裂纹。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上出现了很多裂纹。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天太冷，玻璃上有了裂纹。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我发现手机屏幕上有一条裂纹。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅用胶把碗上的裂纹补好了。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头的裂纹越来越大。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥面上的裂纹要马上检查。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只花瓶很旧，表面有细细的裂纹。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，房子的墙壁出了裂纹。", "target_word": "裂纹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "微裂纹", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：物体表面细长的缝隙或裂痕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f70ce21-a5b1-4c2c-be9e-0c290ce26038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12981, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裂纹", "is_correct": true, "explanation": "手机屏幕表面的细长裂痕，与句意相合。"}, {"text": "围巾", "is_correct": false, "explanation": "搭配：围巾是衣物，不会出现在屏幕表面。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能是屏幕上的痕迹。"}, {"text": "辫子", "is_correct": false, "explanation": "语义：辫子是人的发式，与屏幕无关。"}], "explanations": {"裂纹": "手机屏幕表面的细长裂痕，与句意相合。", "围巾": "搭配：围巾是衣物，不会出现在屏幕表面。", "面包": "语义：面包是食物，不能是屏幕上的痕迹。", "辫子": "语义：辫子是人的发式，与屏幕无关。"}, "sentence_index": 0, "correct_answer": "裂纹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个杯子上有一只裂纹。", "explanation": "这里应该用〈条〉。「只」多用于动物或成对器物，裂纹是细长的线状，应用「条」计量。"}, {"text": "我发现屏幕上有一头裂纹。", "explanation": "这里应该用〈条〉。「头」用于牛马等大型牲畜，裂纹不能用「头」计量。"}, {"text": "墙上有一朵裂纹。", "explanation": "这里应该用〈条〉。「朵」用于花、云等，裂纹不能用「朵」计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12981, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "搭配：「越来越大」不能用来描述名字，名字没有大小的变化。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气属于有情感的人或动物，石头不会有脾气，与语境不符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色只说深浅，不说「越来越大」，与「大」搭配不当。"}, {"text": "裂纹", "is_correct": true, "explanation": "裂纹指石头表面的细长裂缝，会随时间变大，与「越来越大」相合。"}], "explanations": {"名字": "搭配：「越来越大」不能用来描述名字，名字没有大小的变化。", "脾气": "语义：脾气属于有情感的人或动物，石头不会有脾气，与语境不符。", "颜色": "搭配：颜色只说深浅，不说「越来越大」，与「大」搭配不当。", "裂纹": "裂纹指石头表面的细长裂缝，会随时间变大，与「越来越大」相合。"}, "sentence_index": 6, "correct_answer": "裂纹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上有一张裂纹，要尽快修补。", "explanation": "这里应该用〈条〉。「张」用于纸、床等平面的东西，裂纹是细长的线，不能用「张」计量。"}, {"text": "墙角有一颗裂纹。", "explanation": "这里应该用〈条〉。「颗」用于颗粒状的小东西，裂纹不能用「颗」计量。"}, {"text": "桌面上有一把裂纹。", "explanation": "这里应该用〈条〉。「把」用于有柄或可以握住的东西，裂纹不能用「把」计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌面上有一个裂纹。", "corrected_sentence": "桌面上有一条裂纹。", "error_description": "量词错误：「裂纹」是细长的线状，应用「条」，不能用「个」；正确说法是「桌面上有一条裂纹」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一条很小裂纹。", "corrected_sentence": "这是一条很小的裂纹。", "error_description": "定语「很小」修饰「裂纹」时中间要加「的」，应写「这是一条很小的裂纹」；漏掉「的」是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12982, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩小", "is_correct": true, "explanation": "缩小与扩大互为反义，指范围、规模变小。"}, {"text": "保持", "is_correct": false, "explanation": "保持指维持原样，与扩大没有反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "完成指做完某件事，与扩大没有反义关系。"}, {"text": "开始", "is_correct": false, "explanation": "开始指起始，与扩大没有反义关系。"}], "correct_answer": "缩小", "explanations": {"缩小": "缩小与扩大互为反义，指范围、规模变小。", "保持": "保持指维持原样，与扩大没有反义关系。", "完成": "完成指做完某件事，与扩大没有反义关系。", "开始": "开始指起始，与扩大没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12982, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩小", "is_correct": true, "explanation": "缩小与扩大互为反义，指范围、规模变小。"}, {"text": "保留", "is_correct": false, "explanation": "保留指留存，与扩大没有反义关系。"}, {"text": "开展", "is_correct": false, "explanation": "开展指展开工作，与扩大没有反义关系。"}, {"text": "结束", "is_correct": false, "explanation": "结束指终止，与扩大没有反义关系。"}], "correct_answer": "缩小", "explanations": {"缩小": "缩小与扩大互为反义，指范围、规模变小。", "保留": "保留指留存，与扩大没有反义关系。", "开展": "开展指展开工作，与扩大没有反义关系。", "结束": "结束指终止，与扩大没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12982, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使范围、规模、数量等增加或扩展。", "primary_collocate": null, "pronunciation": "kuò dà", "ipa": "kʰuo˥˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司想扩大生产规模。", "target_word": "扩大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板决定扩大店里的经营范围。", "target_word": "扩大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年他们扩大了工厂的规模。", "target_word": "扩大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校今年扩大了招生人数。", "target_word": "扩大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要扩大朋友圈，多认识一些人。", "target_word": "扩大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市越来越大，公园的面积也扩大了。", "target_word": "扩大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想扩大市场，所以要多做广告。", "target_word": "扩大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的生意很好，所以扩大了店面。", "target_word": "扩大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多读书能扩大你的词汇量。", "target_word": "扩大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个活动很受欢迎，他们打算把范围扩大到全国。", "target_word": "扩大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扩大了", "label": "体标（了）"}, {"form": "扩大过", "label": "体标（过）"}, {"form": "扩大化", "label": "复合词"}], "register": "中性", "sense_fingerprint": "使范围、规模、数量等变大或增多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f70ce21-a5b1-4c2c-be9e-0c290ce26038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扩大", "is_correct": true, "explanation": "扩大生产规模表示使规模变大，符合公司想要发展的语境。"}, {"text": "养活", "is_correct": false, "explanation": "语义：养活指供养人或动物，不能用于生产规模。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理用于器物或设备，不能与生产规模搭配。"}, {"text": "喂", "is_correct": false, "explanation": "配价：喂的宾语须是人或动物，生产规模不能作其宾语。"}], "explanations": {"扩大": "扩大生产规模表示使规模变大，符合公司想要发展的语境。", "养活": "语义：养活指供养人或动物，不能用于生产规模。", "修理": "搭配：修理用于器物或设备，不能与生产规模搭配。", "喂": "配价：喂的宾语须是人或动物，生产规模不能作其宾语。"}, "sentence_index": 0, "correct_answer": "扩大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个学生的成绩扩大了三十分。", "explanation": "这里应该用〈提高〉。扩大用于范围、规模，成绩的上升要说提高。"}, {"text": "他这一年扩大了体重三公斤。", "explanation": "这里应该用〈增加〉。扩大强调范围或规模变大，体重的增长要说增加。"}, {"text": "会议扩大了一个小时。", "explanation": "这里应该用〈延长〉。扩大用于空间或范围，时间的增长要说延长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扩大", "is_correct": true, "explanation": "扩大市场表示使市场范围变大，与多做广告的语境相符。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：熄灭指火或灯光消失，不能用于市场。"}, {"text": "栽培", "is_correct": false, "explanation": "搭配：栽培用于植物或人才，市场不能被栽培。"}, {"text": "缝补", "is_correct": false, "explanation": "配价：缝补的对象是衣物等有形物品，市场不能被缝补。"}], "explanations": {"扩大": "扩大市场表示使市场范围变大，与多做广告的语境相符。", "熄灭": "语义：熄灭指火或灯光消失，不能用于市场。", "栽培": "搭配：栽培用于植物或人才，市场不能被栽培。", "缝补": "配价：缝补的对象是衣物等有形物品，市场不能被缝补。"}, "sentence_index": 6, "correct_answer": "扩大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "多锻炼能扩大你的身体素质。", "explanation": "这里应该用〈增强〉。扩大指范围、规模变大，身体素质的加强要说增强。"}, {"text": "我们要扩大服务质量，让客人更满意。", "explanation": "这里应该用〈提升〉。扩大用于范围、规模，服务质量的提高要说提升。"}, {"text": "我们要扩大工作进度，尽快完成项目。", "explanation": "这里应该用〈加快〉。扩大用于范围或规模，进度的提速要说加快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司计划把业务扩大海外。", "corrected_sentence": "这家公司计划把业务扩大到海外。", "error_description": "错误：“扩大”后缺少补语“到”。表示范围扩展到某处时，应说“扩大到海外”，不能直接接地点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的生意扩大地很快。", "corrected_sentence": "这家店的生意扩大得很快。", "error_description": "错误：补语标记用错。“扩大”后表示程度的补语要用“得”，不能用状语标记“地”；应说“扩大得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
