INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12985, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体外部所有面的面积之和。", "primary_collocate": null, "pronunciation": "biǎo miàn jī", "ipa": "piɑʊ̯˨˩˦ mjɛn˥˩ tɕi˥", "syllable_count": 3, "sentences": [{"text": "这个正方体的表面积是六十平方厘米。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么算圆柱的表面积。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子越大，它的表面积也越大。", "target_word": "表面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要给箱子刷漆，先要算出它的表面积。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球的表面积公式比较难记。", "target_word": "表面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把这个长方体切成两块，表面积会变大。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同样的体积，扁盒子的表面积更大。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "包这个盒子用的纸，正好是它的表面积。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球的表面积大约是五亿平方千米。", "target_word": "表面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰块的表面积越大，化得越快。", "target_word": "表面积", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "表面積", "label": "繁体"}, {"form": "总表面积", "label": "复合"}], "register": "中性", "sense_fingerprint": "表面积：物体外部所有面的面积之和，如正方体、圆柱、球的表面积", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd41bb3f0-444d-44a7-aecf-74c5fab366ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12985, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表面积", "is_correct": true, "explanation": "正确。正方体的表面积是六个面面积之和，单位是平方厘米。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：体积是立体空间的大小，单位是立方，不能用“平方厘米”。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量是物体的轻重，不是面的大小，不能用平方厘米计量。"}, {"text": "长度", "is_correct": false, "explanation": "语义：长度是一条线的距离，应用厘米计量，不能说“平方厘米”。"}], "explanations": {"表面积": "正确。正方体的表面积是六个面面积之和，单位是平方厘米。", "体积": "搭配：体积是立体空间的大小，单位是立方，不能用“平方厘米”。", "重量": "语义：重量是物体的轻重，不是面的大小，不能用平方厘米计量。", "长度": "语义：长度是一条线的距离，应用厘米计量，不能说“平方厘米”。"}, "sentence_index": 0, "correct_answer": "表面积"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块操场的表面积是一万平方米。", "explanation": "这里应该用〈面积〉。操场是平面，只说面积；表面积指立体物体外部所有面面积的总和。"}, {"text": "这个水箱的表面积很大，能装两吨水。", "explanation": "这里应该用〈体积〉。表面积只量外表的面，装不了东西；装多少水要用体积。"}, {"text": "这块木板的表面积很光滑。", "explanation": "这里应该用〈表层〉。表面积是面的大小，不能形容光滑、粗糙；说木板光不光滑，指的是表层的性质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表面积", "is_correct": true, "explanation": "正确。体积相同时，扁盒子的表面更多，所以表面积更大。"}, {"text": "容积", "is_correct": false, "explanation": "语义：句中已说“同样的体积”，又说容积更大，前后矛盾。"}, {"text": "高度", "is_correct": false, "explanation": "语义：“扁”说的是外形矮，高度更大与“扁”矛盾。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：形状是外形，不能用“更大”来比较。"}], "explanations": {"表面积": "正确。体积相同时，扁盒子的表面更多，所以表面积更大。", "容积": "语义：句中已说“同样的体积”，又说容积更大，前后矛盾。", "高度": "语义：“扁”说的是外形矮，高度更大与“扁”矛盾。", "形状": "搭配：形状是外形，不能用“更大”来比较。"}, "sentence_index": 6, "correct_answer": "表面积"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块冰的表面积是两公斤。", "explanation": "这里应该用〈重量〉。表面积是面积，单位是平方；公斤是质量单位，不能用来量表面积。"}, {"text": "这根冰柱的表面积是一米。", "explanation": "这里应该用〈长度〉。表面积是面的大小，单位是平方；“一米”是长度，要说长度。"}, {"text": "这块冰的表面积很低，摸上去很凉。", "explanation": "这里应该用〈温度〉。表面积不能用高低来形容，冷热要说温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个纸箱的表面积是八百厘米。", "corrected_sentence": "这个纸箱的表面积是八百平方厘米。", "error_description": "错在“表面积”的单位：应说“平方厘米”。表面积是面的面积，要用平方单位；“厘米”是长度单位，只用于量线段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个水箱的表面积是三立方米。", "corrected_sentence": "这个水箱的表面积是三平方米。", "error_description": "错在单位：表面积是面积，应说“平方米”；“立方米”是体积的单位，不能用来量表面积。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
