INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12992, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12992, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "冷凉指温度较低，略带寒意，常形容天气或物体给人以凉爽而稍冷的感觉。", "primary_collocate": null, "pronunciation": "lěng liáng", "ipa": "lɤŋ˨˩˦ ljɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "海洋、土壤与淡水生态系统中的微生物群落差异巨大，许多标称“可降解”的材料仅在工业堆肥条件下有效分解，在自然冷凉水域或缺氧环境中则降解缓慢，甚至产生微塑料残留。", "target_word": "冷凉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "秋天的早晨，空气有点冷凉。", "target_word": "冷凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的夜晚很冷凉，要多穿一件衣服。", "target_word": "冷凉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蔬菜喜欢生长在冷凉的地方。", "target_word": "冷凉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一阵冷凉的风吹过来，让人很舒服。", "target_word": "冷凉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的傍晚，天气变得冷凉了。", "target_word": "冷凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "清晨的湖边很冷凉，我把外套穿上了。", "target_word": "冷凉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水冷凉，我们在岸边坐了一会儿。", "target_word": "冷凉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手放进冷凉的泉水里。", "target_word": "冷凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的夏天冷凉，不用开空调。", "target_word": "冷凉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷涼", "label": "繁体"}, {"form": "冷凉气候", "label": "复合"}], "register": "书面", "sense_fingerprint": "冷凉：温度较低、略带寒意，形容天气、气候、水、风等凉爽而稍冷", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd41bb3f0-444d-44a7-aecf-74c5fab366ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”指缺水，与“水域”的含义矛盾，水域本身就是有水的地方。"}, {"text": "冷凉", "is_correct": true, "explanation": "“冷凉”指温度较低、略带寒意，与“自然”水域的凉意相合，也符合后文降解缓慢的语境。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容地形坡度，不能用来形容水域的温度。"}, {"text": "迟钝", "is_correct": false, "explanation": "搭配：“迟钝”形容反应慢，不能修饰水域或它的温度。"}], "explanations": {"干燥": "语义：“干燥”指缺水，与“水域”的含义矛盾，水域本身就是有水的地方。", "冷凉": "“冷凉”指温度较低、略带寒意，与“自然”水域的凉意相合，也符合后文降解缓慢的语境。", "陡峭": "搭配：“陡峭”形容地形坡度，不能用来形容水域的温度。", "迟钝": "搭配：“迟钝”形容反应慢，不能修饰水域或它的温度。"}, "sentence_index": 0, "correct_answer": "冷凉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对我的态度很冷凉，让我很难过。", "explanation": "这里应该用〈冷淡〉。冷凉只描述温度，不用来形容人的态度，态度冷淡要说冷淡。"}, {"text": "这间小店的生意很冷凉，每天没几个客人。", "explanation": "这里应该用〈冷清〉。冷凉只描述温度，不能形容生意或地方人少、没有热闹，这种情况要说冷清。"}, {"text": "他冷凉地笑了一声，没有说话。", "explanation": "这里应该用〈冷笑〉。冷凉只描述温度，不能修饰笑声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "炎热", "is_correct": false, "explanation": "语义：“炎热”指气温很高，与“穿上外套”的语境矛盾。"}, {"text": "冷凉", "is_correct": true, "explanation": "正确。“冷凉”表示略带寒意，与清晨湖边的凉意相合，也与“穿上外套”一致。"}, {"text": "闷热", "is_correct": false, "explanation": "语义：“闷热”指湿热难受，同样与“穿上外套”的语境矛盾。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”形容温度极高，不能用于清晨湖边这种略带凉意的环境。"}], "explanations": {"炎热": "语义：“炎热”指气温很高，与“穿上外套”的语境矛盾。", "冷凉": "正确。“冷凉”表示略带寒意，与清晨湖边的凉意相合，也与“穿上外套”一致。", "闷热": "语义：“闷热”指湿热难受，同样与“穿上外套”的语境矛盾。", "滚烫": "搭配：“滚烫”形容温度极高，不能用于清晨湖边这种略带凉意的环境。"}, "sentence_index": 6, "correct_answer": "冷凉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一月的北方，夜里冷凉得让人直打哆嗦。", "explanation": "这里应该用〈寒冷〉。冷凉只表示略带寒意，冷得让人直打哆嗦要说寒冷。"}, {"text": "冷凉的寒风刮得人脸上生疼。", "explanation": "这里应该用〈凛冽〉。冷凉只表示略带凉意，不能形容刺骨的寒风。"}, {"text": "今年冬天特别冷凉，老人们都不敢出门。", "explanation": "这里应该用〈严寒〉。冷凉只表示略带寒意，程度很深、让人不敢出门的寒冷要说严寒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "傍晚的湖面吹来一阵冷凉地风。", "corrected_sentence": "傍晚的湖面吹来一阵冷凉的风。", "error_description": "修饰名词要用“的”，不用“地”。“地”用于修饰动词，这里应说“冷凉的风”，不能说“冷凉地风”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "黄昏时分，天气把冷凉了。", "corrected_sentence": "黄昏时分，天气冷凉了。", "error_description": "“把”字句的宾语应是名词或动词性成分，形容词“冷凉”不能直接接在“把”后面。这里应说“天气冷凉了”，不能说“天气把冷凉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
