INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12993, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12993, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指江河湖海等由水覆盖的区域。", "primary_collocate": null, "pronunciation": "shuǐ yù", "ipa": "ʂueɪ˨˩˦ y˥˩", "syllable_count": 2, "sentences": [{"text": "这片水域很深，不能游泳。", "target_word": "水域", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "湖边立着牌子：这片水域禁止钓鱼。", "target_word": "水域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，这片水域里有很多小鱼。", "target_word": "水域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔民说，这一带水域冬天会结冰。", "target_word": "水域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船慢慢开进了一片安静的水域。", "target_word": "水域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的水域面积很大，有很多湖。", "target_word": "水域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂的污水流进河里，整片水域都变臭了。", "target_word": "水域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海警在边境水域发现了一条可疑的船。", "target_word": "水域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天孩子们常在这片水域边玩。", "target_word": "水域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要保护这片水域，不能乱扔垃圾。", "target_word": "水域", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "水域面积", "label": "复合"}], "register": "中性", "sense_fingerprint": "江河湖海等被水覆盖的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd41bb3f0-444d-44a7-aecf-74c5fab366ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12993, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陆地", "is_correct": false, "explanation": "语义：“陆地”是陆上的地面，不是水，与“很深”和“不能游泳”的语境矛盾。"}, {"text": "水域", "is_correct": true, "explanation": "“水域”指水覆盖的区域，可以说“很深”，因为有深度所以不能游泳。"}, {"text": "沙漠", "is_correct": false, "explanation": "搭配：“很深”用来说水的深浅，沙漠不能这样形容。"}, {"text": "草原", "is_correct": false, "explanation": "搭配：“很深”不能用于草原，草原上也不存在“游泳”的问题。"}], "explanations": {"陆地": "语义：“陆地”是陆上的地面，不是水，与“很深”和“不能游泳”的语境矛盾。", "水域": "“水域”指水覆盖的区域，可以说“很深”，因为有深度所以不能游泳。", "沙漠": "搭配：“很深”用来说水的深浅，沙漠不能这样形容。", "草原": "搭配：“很深”不能用于草原，草原上也不存在“游泳”的问题。"}, "sentence_index": 0, "correct_answer": "水域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在金融水域很有研究。", "explanation": "这里应该用〈领域〉。水域指江河湖海等水覆盖的区域，不指专业范围，专业范围要说领域。"}, {"text": "今年降水很少，我们要节约水域。", "explanation": "这里应该用〈水资源〉。水域指江河湖海等水覆盖的区域，本身不能被节约；要节约的是水资源。"}, {"text": "这片水域上长满了庄稼。", "explanation": "这里应该用〈陆地〉。水域是水覆盖的地方，不能种庄稼，长庄稼的地方应是陆地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12993, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "搭配：“变臭”不能用于天空，整片天空也与污水流进河里无关。"}, {"text": "水域", "is_correct": true, "explanation": "“水域”指河湖等水体，污水流进河里后，整片水域都会变臭。"}, {"text": "冰原", "is_correct": false, "explanation": "语义：“冰原”是冰雪覆盖的地方，与污水流入河中无关。"}, {"text": "云层", "is_correct": false, "explanation": "语义：“云层”在天空中，与河里的污水没有关系。"}], "explanations": {"天空": "搭配：“变臭”不能用于天空，整片天空也与污水流进河里无关。", "水域": "“水域”指河湖等水体，污水流进河里后，整片水域都会变臭。", "冰原": "语义：“冰原”是冰雪覆盖的地方，与污水流入河中无关。", "云层": "语义：“云层”在天空中，与河里的污水没有关系。"}, "sentence_index": 6, "correct_answer": "水域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个水域的人口密度很高。", "explanation": "这里应该用〈区域〉。水域指江河湖海等水覆盖的地方，没有人口密度；泛指一块地方、谈人口时要说区域。"}, {"text": "这条水域流过了三个省。", "explanation": "这里应该用〈河流〉。水域是一片区域，不会流动，也不用“条”，流过多个省要说河流。"}, {"text": "牧民们在水域上放牧。", "explanation": "这里应该用〈草场〉。水域是水覆盖的地方，不能放牧，放牧的地方应是草场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渔船驶进了一座很宽的水域。", "corrected_sentence": "渔船驶进了一片很宽的水域。", "error_description": "水域的量词应用“片”，不能用“座”，“座”多用于山和建筑。这里应说“一片很宽的水域”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些鱼生活这片水域里。", "corrected_sentence": "这些鱼生活在这片水域里。", "error_description": "表示处所要用“在”，“生活”后面应加“在”，应说“生活在这片水域里”，不能漏掉“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
