INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12994, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指身体组织或环境中缺少氧气，导致不适或危险。", "primary_collocate": null, "pronunciation": "quē yǎng", "ipa": "tɕʰɥe˥ jaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "海洋、土壤与淡水生态系统中的微生物群落差异巨大，许多标称“可降解”的材料仅在工业堆肥条件下有效分解，在自然冷凉水域或缺氧环境中则降解缓慢，甚至产生微塑料残留。", "target_word": "缺氧", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "山上很高，爬山的人容易缺氧。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间不开窗，人会缺氧，头也会疼。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鱼缸里的鱼缺氧了，都游到水面上来。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他爬到山顶时，脑子有点缺氧。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人缺氧的时候，嘴唇会变紫。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "池塘里水草太多，晚上水会缺氧。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "潜水时他缺氧了，马上浮出水面。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间太闷，大家都觉得缺氧。", "target_word": "缺氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长时间戴着口罩跑步，会让人缺氧。", "target_word": "缺氧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缺氧了", "label": "体标"}, {"form": "缺氧症", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体或环境缺少氧气而不适或危险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd41bb3f0-444d-44a7-aecf-74c5fab366ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12994, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缺氧", "is_correct": true, "explanation": "正确。原句“缺氧环境”指氧气不足的环境，与“自然冷凉水域”并列，说明这类环境中降解缓慢。"}, {"text": "加热", "is_correct": false, "explanation": "语义：“加热”指升温，与前面的“冷凉水域”正相反，放进空格后读起来与语境冲突。"}, {"text": "升温", "is_correct": false, "explanation": "语义：升温会加快分解，与“降解缓慢”及前面的“冷凉”相反，放进空格后语境冲突。"}, {"text": "充氧", "is_correct": false, "explanation": "语义：充氧环境氧气充足，微生物分解更快，与“降解缓慢”正相反。"}], "explanations": {"缺氧": "正确。原句“缺氧环境”指氧气不足的环境，与“自然冷凉水域”并列，说明这类环境中降解缓慢。", "加热": "语义：“加热”指升温，与前面的“冷凉水域”正相反，放进空格后读起来与语境冲突。", "升温": "语义：升温会加快分解，与“降解缓慢”及前面的“冷凉”相反，放进空格后语境冲突。", "充氧": "语义：充氧环境氧气充足，微生物分解更快，与“降解缓慢”正相反。"}, "sentence_index": 0, "correct_answer": "缺氧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种沉闷的气氛让人缺氧，大家都想出去。", "explanation": "这里应该用〈窒息〉。缺氧只指身体或环境里氧气不足，不能用来形容压抑的气氛。"}, {"text": "这家店的服务很缺氧，客人都不满意。", "explanation": "这里应该用〈差劲〉。缺氧只指身体或环境里氧气不足，不能用来评价服务，服务不好要说差劲。"}, {"text": "他一天没吃东西，现在很缺氧，走路都没劲。", "explanation": "这里应该用〈饿〉。缺氧指氧气不足，没吃东西的饥饿感要说饿，不能用缺氧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缺氧", "is_correct": true, "explanation": "正确。原句“晚上水会缺氧”，说明夜间水草消耗氧气，水因此缺氧。"}, {"text": "变清", "is_correct": false, "explanation": "语义：水草太多的池塘不会因此变清，与原句的因果关系不符。"}, {"text": "沸腾", "is_correct": false, "explanation": "搭配：“沸腾”指水达到沸点，不能用来描述池塘夜间的水况。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：水不会呼吸，这里的说法与池塘的生态语境不符。"}], "explanations": {"缺氧": "正确。原句“晚上水会缺氧”，说明夜间水草消耗氧气，水因此缺氧。", "变清": "语义：水草太多的池塘不会因此变清，与原句的因果关系不符。", "沸腾": "搭配：“沸腾”指水达到沸点，不能用来描述池塘夜间的水况。", "呼吸": "语义：水不会呼吸，这里的说法与池塘的生态语境不符。"}, "sentence_index": 6, "correct_answer": "缺氧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他连续加班一周，已经非常缺氧了。", "explanation": "这里应该用〈疲惫〉。缺氧指氧气不足，不能用来形容劳累后的状态。"}, {"text": "这次考试失利，他心里很缺氧。", "explanation": "这里应该用〈憋屈〉。缺氧不能形容心里的委屈，那种不痛快的感觉要说憋屈。"}, {"text": "这次方案的创意很缺氧，没有新意。", "explanation": "这里应该用〈平淡〉。缺氧指氧气不足，创意没有新意要说平淡，不能用缺氧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "潜水员被缺氧了，马上浮上水面。", "corrected_sentence": "潜水员在水下缺氧了，马上浮上水面。", "error_description": "“缺氧”是不及物动词，不能用“被”构成被动句。应去掉“被”，改为“在水下缺氧了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们救出了缺氧地工人。", "corrected_sentence": "我们救出了缺氧的工人。", "error_description": "“缺氧”修饰名词时要用“的”，不能用“地”。“地”用于修饰动词，应写作“缺氧的工人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
