INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12996, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指物体或物质在主要部分被使用、分离或移除后所剩余的部分。", "primary_collocate": null, "pronunciation": "cán liú", "ipa": "tsʰan˨˩˦ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "杯底还残留着一点茶。", "target_word": "残留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜上的农药没洗干净，会残留在菜里。", "target_word": "残留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上还残留着孩子画的画。", "target_word": "残留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完以后，衣服上没有残留的洗衣粉。", "target_word": "残留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火灾后，房子里残留着很浓的烟味。", "target_word": "残留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上残留的雪很快就化了。", "target_word": "残留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "药物残留在身体里，对人不好。", "target_word": "残留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种肥料不会在土里残留太久。", "target_word": "残留", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上残留着昨天的饭菜。", "target_word": "残留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走了，房间里仍残留着他的香水味。", "target_word": "残留", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "残留着", "label": "体标"}, {"form": "残留了", "label": "体标"}, {"form": "残留物", "label": "复合"}], "register": "中性", "sense_fingerprint": "主要部分被用掉或移除后剩下的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd41bb3f0-444d-44a7-aecf-74c5fab366ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12996, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残留", "is_correct": true, "explanation": "正确。原句“杯底还残留着一点茶”，指喝完后剩下的少量茶。"}, {"text": "清除", "is_correct": false, "explanation": "语义：“清除”是去掉，与“还有一点茶”相矛盾。"}, {"text": "消失", "is_correct": false, "explanation": "语义：“消失”表示不见了，与“还”所表示的仍然存在相矛盾。"}, {"text": "倒掉", "is_correct": false, "explanation": "搭配：“倒掉”是动作完成后的结果，后面不能用“着”表示持续在杯底。"}], "explanations": {"残留": "正确。原句“杯底还残留着一点茶”，指喝完后剩下的少量茶。", "清除": "语义：“清除”是去掉，与“还有一点茶”相矛盾。", "消失": "语义：“消失”表示不见了，与“还”所表示的仍然存在相矛盾。", "倒掉": "搭配：“倒掉”是动作完成后的结果，后面不能用“着”表示持续在杯底。"}, "sentence_index": 0, "correct_answer": "残留"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他毕业后残留在这个城市工作。", "explanation": "这里应该用〈留〉。残留指物体用完后剩下的一点，不能用来说人留在某地。"}, {"text": "这个月的生活费只残留了一半。", "explanation": "这里应该用〈剩下〉。残留多指用完后的少量痕迹，生活费剩下一半要说剩下。"}, {"text": "他的钱包残留在出租车上，忘了拿。", "explanation": "这里应该用〈落下〉。残留强调用完或移除后剩下的一点，整件物品遗失要说落下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残留", "is_correct": true, "explanation": "正确。原句“药物残留在身体里”，指药物用后仍在体内，与“对人不好”相呼应。"}, {"text": "排泄", "is_correct": false, "explanation": "语义：“排泄”指排出体外，与“在身体里”相矛盾。"}, {"text": "排出", "is_correct": false, "explanation": "语义：“排出”指排到体外，同样与“在身体里”相矛盾。"}, {"text": "发挥", "is_correct": false, "explanation": "搭配：“发挥”通常接“作用”之类的宾语，不能直接用在“在身体里”这样的地点结构前。"}], "explanations": {"残留": "正确。原句“药物残留在身体里”，指药物用后仍在体内，与“对人不好”相呼应。", "排泄": "语义：“排泄”指排出体外，与“在身体里”相矛盾。", "排出": "语义：“排出”指排到体外，同样与“在身体里”相矛盾。", "发挥": "搭配：“发挥”通常接“作用”之类的宾语，不能直接用在“在身体里”这样的地点结构前。"}, "sentence_index": 6, "correct_answer": "残留"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脚残留在泥里，动弹不得。", "explanation": "这里应该用〈陷〉。残留指用完或分离后剩下的一点，脚被泥困住要说陷在泥里，不能用残留。"}, {"text": "这份工作残留到现在，他已经干了三十年。", "explanation": "这里应该用〈坚持〉。残留指剩下的痕迹，一直做下去、不放弃要说坚持。"}, {"text": "会议的剩余时间很短，只残留了十分钟。", "explanation": "这里应该用〈剩余〉。残留多指物体或痕迹的剩下部分，时间的剩余要说剩余。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "杯子里残留了着几滴酒。", "corrected_sentence": "杯子里残留着几滴酒。", "error_description": "“了”和“着”不能同时用在“残留”后面。应去掉“了”，写作“残留着几滴酒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "衣服上被残留着一些油渍。", "corrected_sentence": "衣服上残留着一些油渍。", "error_description": "“残留”是不及物动词，不能加“被”构成被动句。应去掉“被”，写作“衣服上残留着一些油渍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12998, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12998, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12998, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "鸿沟指事物之间巨大的差异或隔阂，就像一条难以跨越的深沟。", "primary_collocate": null, "pronunciation": "hóng gōu", "ipa": "xʊŋ˧˥ kou˥˥", "syllable_count": 2, "sentences": [{"text": "这揭示了实验室研究与真实环境之间的鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "富人和穷人之间有一道很深的鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两代人之间的鸿沟让他们很难沟通。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想办法填平城乡之间的鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言不同，在他们之间造成了一道鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贫富之间的鸿沟越来越大，大家都很担心。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他努力学习，想跨越理想和现实之间的鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国在文化上存在着一条难以跨越的鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次谈话缩小了我们之间的鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生之间的鸿沟，需要用耐心来填平。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道鸿沟", "label": "量词"}, {"form": "一条鸿沟", "label": "量词"}, {"form": "鴻溝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物之间巨大的差异或隔阂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93f1010e-ee55-4e33-9cf5-8af6804f420b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鸿沟", "is_correct": true, "explanation": "鸿沟指难以跨越的巨大差异或隔阂，与“揭示……之间”的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是可见的属性，不能指两个领域之间的差异，“之间的颜色”说不通。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票是交通凭证，与实验室研究和真实环境的关系无关，句子不通。"}, {"text": "乱子", "is_correct": false, "explanation": "语域：“乱子”是口语，指麻烦事，与“揭示”这样的书面语体不协调，也不指差异。"}], "explanations": {"鸿沟": "鸿沟指难以跨越的巨大差异或隔阂，与“揭示……之间”的语境相符。", "颜色": "语义：颜色是可见的属性，不能指两个领域之间的差异，“之间的颜色”说不通。", "车票": "语义：车票是交通凭证，与实验室研究和真实环境的关系无关，句子不通。", "乱子": "语域：“乱子”是口语，指麻烦事，与“揭示”这样的书面语体不协调，也不指差异。"}, "sentence_index": 0, "correct_answer": "鸿沟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的成绩只比他低两分，我们之间却有一道相差两分的鸿沟。", "explanation": "这里应该用〈差距〉。鸿沟指难以跨越的隔阂，不能用“相差两分”这样的数量来计算；说数量上的差别要用差距。"}, {"text": "我家到学校有三公里的鸿沟，走路要一个小时。", "explanation": "这里应该用〈距离〉。“三公里”是距离的计量单位，鸿沟是抽象的隔阂，不能用公里计算。"}, {"text": "他们之间有一只鸿沟，谁也不愿意先迈过去。", "explanation": "这里应该用〈道〉或〈条〉。“只”多用于动物，不能用来搭配鸿沟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鸿沟", "is_correct": true, "explanation": "鸿沟指难以跨越的差异，与“跨越”搭配，指理想与现实之间的巨大落差。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是透明的材料，不是理想与现实之间的隔阂，无法被“跨越”。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，与理想和现实之间的落差无关，句子不通。"}, {"text": "烂摊子", "is_correct": false, "explanation": "语域：“烂摊子”是口语，指混乱的局面，与“跨越”的书面语境不合，也不指难以跨越的差异。"}], "explanations": {"鸿沟": "鸿沟指难以跨越的差异，与“跨越”搭配，指理想与现实之间的巨大落差。", "玻璃": "语义：玻璃是透明的材料，不是理想与现实之间的隔阂，无法被“跨越”。", "饭菜": "语义：饭菜是食物，与理想和现实之间的落差无关，句子不通。", "烂摊子": "语域：“烂摊子”是口语，指混乱的局面，与“跨越”的书面语境不合，也不指难以跨越的差异。"}, "sentence_index": 6, "correct_answer": "鸿沟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师和学生之间的鸿沟终于解开了。", "explanation": "这里应该用〈误会〉。“解开”多用于误会、疙瘩，鸿沟是差异或隔阂，要填平或跨越，不能解开。"}, {"text": "两国之间的鸿沟越来越激化了。", "explanation": "这里应该用〈矛盾〉。“激化”用于矛盾、冲突，鸿沟指难以跨越的差异，不会激化。"}, {"text": "他们要和过去划清鸿沟。", "explanation": "这里应该用〈界限〉。“划清”搭配界限、关系，鸿沟不能被划清。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国在政策上存在着一只明显的鸿沟。", "corrected_sentence": "两国在政策上存在着一道明显的鸿沟。", "error_description": "量词用错：鸿沟是抽象的隔阂，应该用“道”或“条”，不能用“只”（“只”多用于动物）。正确的说法是“存在着一道明显的鸿沟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于跨过着那道鸿沟。", "corrected_sentence": "他终于跨过了那道鸿沟。", "error_description": "动态助词用错：“终于”表示动作已经完成，应该用“了”，不能用“着”。正确的说法是“终于跨过了那道鸿沟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13002, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13002, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13002, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使用或耗费，使物品或精力减少。", "primary_collocate": null, "pronunciation": "xiāo hào", "ipa": "ɕjɑʊ˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "从棉花种植阶段的大量灌溉，到印染、整理等后处理环节的高耗水作业，每一吨纺织品的诞生往往伴随着数万升淡水的消耗。", "target_word": "消耗", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其次，推广节水型印染技术、闭环水循环系统与无水染色工艺，能在不牺牲效率的前提下显著降低单位产出的水资源消耗。", "target_word": "消耗", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "更深层的矛盾在于：若大规模推广生物基塑料，可能引发与粮争地、水资源消耗等新的生态伦理问题。", "target_word": "消耗", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "跑步会消耗很多力气。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台旧冰箱每天消耗很多电。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们一个星期就消耗了所有的食物。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子玩了一天，消耗了不少体力。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车开得越快，消耗的油越多。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做这个工作消耗了她太多的精力。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂每个月消耗大量的水和电。", "target_word": "消耗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "消耗了", "label": "体标"}, {"form": "消耗着", "label": "体标"}, {"form": "消耗量", "label": "复合"}, {"form": "消耗品", "label": "复合"}], "register": "中性", "sense_fingerprint": "用掉或耗费物资、精力使其减少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de9a87f-9352-48aa-a1f5-bcc350764b12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13002, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消耗", "is_correct": true, "explanation": "正确：消耗指耗用淡水，与前文高耗水作业的语境相符。"}, {"text": "补充", "is_correct": false, "explanation": "语义：“补充”指增添，与“伴随着……的消耗”的句意相反。"}, {"text": "储存", "is_correct": false, "explanation": "语义：“储存”指保存备用，句中的淡水是被耗用掉的，并非储存。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”用于水平、质量，不用于淡水的数量变化。"}], "explanations": {"消耗": "正确：消耗指耗用淡水，与前文高耗水作业的语境相符。", "补充": "语义：“补充”指增添，与“伴随着……的消耗”的句意相反。", "储存": "语义：“储存”指保存备用，句中的淡水是被耗用掉的，并非储存。", "提高": "搭配：“提高”用于水平、质量，不用于淡水的数量变化。"}, "sentence_index": 0, "correct_answer": "消耗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他读书很快，很快就消耗了这些知识。", "explanation": "这里应该用〈消化〉。知识被理解吸收用消化；消耗指物资或精力被用掉，不用于知识。"}, {"text": "他的笑容慢慢消耗了。", "explanation": "这里应该用〈消失〉。笑容慢慢不见用消失；消耗指物资或精力被用掉，不能用于表情。"}, {"text": "这家工厂的产量消耗了一半。", "explanation": "这里应该用〈减少〉。产量下降用减少；消耗指物资、精力被用掉，产量不能被消耗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消耗", "is_correct": true, "explanation": "正确：消耗指耗去体力，与“玩了一天”的语境相符。"}, {"text": "恢复", "is_correct": false, "explanation": "语义：“恢复”指体力回升，与“玩了一天”耗费体力的语境相反。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”说数量变多，与句中体力减少的意思相反。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“体力”作宾语。"}], "explanations": {"消耗": "正确：消耗指耗去体力，与“玩了一天”的语境相符。", "恢复": "语义：“恢复”指体力回升，与“玩了一天”耗费体力的语境相反。", "增加": "语义：“增加”说数量变多，与句中体力减少的意思相反。", "睡": "配价：“睡”是不及物动词，不能带“体力”作宾语。"}, "sentence_index": 6, "correct_answer": "消耗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "发烧后，身上的红疹慢慢消耗了。", "explanation": "这里应该用〈消退〉。红疹、肿胀慢慢减轻消失用消退；消耗指物资或精力被用掉。"}, {"text": "冰雪在春天慢慢消耗了。", "explanation": "这里应该用〈消融〉。冰雪遇热变成水用消融；消耗不表示冰雪熔化。"}, {"text": "早晨的雾气慢慢消耗了。", "explanation": "这里应该用〈消散〉。雾气逐渐散去用消散；消耗指物资、精力被用掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场比赛下来，他的体力几乎消耗了完。", "corrected_sentence": "这场比赛下来，他的体力几乎消耗完了。", "error_description": "错误形式：“消耗了完”；正确形式：“消耗完了”。结果补语“完”要紧跟动词，动词后再加“了”，“了”与“完”的位置不能颠倒。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的大部分精力都消耗工作上了。", "corrected_sentence": "他的大部分精力都消耗在工作上了。", "error_description": "错误形式：“消耗工作上”；正确形式：“消耗在工作上”。表示耗费在某处时，“消耗”后要用介词“在”引出处所，不能直接接处所名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13003, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13003, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13003, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指能够通过编程来设定其功能或行为的特性。", "primary_collocate": null, "pronunciation": "kě biān chéng", "ipa": "kʰɤ˨˩ pjɛn˥ ʈʂʰɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "因此，前沿研究正转向合成生物学路径，设计可编程的工程菌株，使其在特定信号触发下高效表达聚合物裂解酶，实现“精准生物降解”。", "target_word": "可编程", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种可编程芯片可以按需要改变功能。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂买了一台可编程的控制器。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "可编程电路的好处是功能可以修改。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这款可编程的灯能按程序变换颜色。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室用可编程的细胞做新药研究。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢可编程的玩具，因为可以自己设计动作。", "target_word": "可编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "可编程设备比普通设备更灵活。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种可编程材料遇热会改变形状。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校买了几块可编程的开发板。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "可编程的", "label": "定语形式"}, {"form": "可编程性", "label": "名词化形式"}, {"form": "可編程", "label": "繁体"}], "register": "书面", "sense_fingerprint": "可通过编程设定功能或行为的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93f1010e-ee55-4e33-9cf5-8af6804f420b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13003, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可编程", "is_correct": true, "explanation": "可编程指能通过编程设定功能或行为，与“设计……工程菌株并让其按信号表达酶”的语境相符。"}, {"text": "可拆卸", "is_correct": false, "explanation": "语义：可拆卸指能拆开，与通过编程控制菌株功能的意思不符，菌株不靠拆装来工作。"}, {"text": "可折叠", "is_correct": false, "explanation": "语义：可折叠指能折起来收放，与按信号改变菌株行为的意思不符。"}, {"text": "可口的", "is_correct": false, "explanation": "语义：可口指食物味道好，工程菌株不是食物，句意不通。"}], "explanations": {"可编程": "可编程指能通过编程设定功能或行为，与“设计……工程菌株并让其按信号表达酶”的语境相符。", "可拆卸": "语义：可拆卸指能拆开，与通过编程控制菌株功能的意思不符，菌株不靠拆装来工作。", "可折叠": "语义：可折叠指能折起来收放，与按信号改变菌株行为的意思不符。", "可口的": "语义：可口指食物味道好，工程菌株不是食物，句意不通。"}, "sentence_index": 0, "correct_answer": "可编程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个可编程的人。", "explanation": "这里应该用〈可靠〉。“可编程”指机器能按命令设定功能，不能用来形容人。"}, {"text": "他的话可编程。", "explanation": "这里应该用〈可信〉。“可编程”只用于能按命令设定功能的机器，不能用来说话语的可信度。"}, {"text": "这场地震可编程。", "explanation": "这里应该用〈可怕〉。“可编程”指可以按命令设定功能，地震是自然现象，不能被编程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可编程", "is_correct": true, "explanation": "可编程指能通过编程设定功能，与“自己设计动作”的意思相符。"}, {"text": "可溶的", "is_correct": false, "explanation": "语义：可溶指能溶解在液体里，玩具不能溶解，句子不通。"}, {"text": "可消化的", "is_correct": false, "explanation": "语义：可消化指食物能被身体吸收，玩具不能消化，句子不通。"}, {"text": "可冷冻的", "is_correct": false, "explanation": "语义：可冷冻指能放进冰箱保存，与“自己设计动作”无关，句子不通。"}], "explanations": {"可编程": "可编程指能通过编程设定功能，与“自己设计动作”的意思相符。", "可溶的": "语义：可溶指能溶解在液体里，玩具不能溶解，句子不通。", "可消化的": "语义：可消化指食物能被身体吸收，玩具不能消化，句子不通。", "可冷冻的": "语义：可冷冻指能放进冰箱保存，与“自己设计动作”无关，句子不通。"}, "sentence_index": 6, "correct_answer": "可编程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次的收获十分可编程。", "explanation": "这里应该用〈可观〉。“可编程”指能按命令设定功能，不能用来形容收获的多少。"}, {"text": "他的行踪可编程。", "explanation": "这里应该用〈可疑〉。“可编程”只用于能按命令设定功能的机器，不能说人的行踪。"}, {"text": "那位老人非常可编程。", "explanation": "这里应该用〈可怜〉。“可编程”指能按命令设定功能，不能用来形容老人的处境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种芯片很可编程，可以按需要改变功能。", "corrected_sentence": "这种芯片可编程，可以按需要改变功能。", "error_description": "程度副词用错：“可编程”描述的是能否编程的属性，不能用“很”修饰。正确的说法是“这种芯片可编程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13003, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小车能可编程，能按指令转弯。", "corrected_sentence": "这个小车可编程，能按指令转弯。", "error_description": "助动词用错：“可编程”是性质词，前面不能再加“能”。正确的说法是“这个小车可编程，能按指令转弯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
