INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13004, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "菌株是指从某种微生物中分离出来的、具有特定遗传特征的一个纯种群体。", "primary_collocate": null, "pronunciation": "jūn zhū", "ipa": "tɕyn˥ ʈʂu˥", "syllable_count": 2, "sentences": [{"text": "因此，前沿研究正转向合成生物学路径，设计可编程的工程菌株，使其在特定信号触发下高效表达聚合物裂解酶，实现“精准生物降解”。", "target_word": "菌株", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "科学家从土里找到了一种新菌株。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个菌株能分解塑料。", "target_word": "菌株", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "实验室里保存着很多菌株。", "target_word": "菌株", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员把菌株放进培养液里。", "target_word": "菌株", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种菌株在高温下也能生长。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们看了培养皿里的菌株。", "target_word": "菌株", "complexity_tier": "T3", "furigana": "jūn zhū", "sentence_source": "generated"}, {"text": "这个菌株是从河水里分离出来的。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用基因改造过这个菌株。", "target_word": "菌株", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野生菌株的生长速度比较慢。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个菌株", "label": "量词"}, {"form": "工程菌株", "label": "复合"}, {"form": "野生菌株", "label": "复合"}], "register": "书面", "sense_fingerprint": "从微生物中分离出的具有特定遗传特征的纯种群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f995feb-01f2-46a0-bd0f-015ea5999b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "菌株", "is_correct": true, "explanation": "正确：“工程菌株”指经过改造、从微生物中分离出的纯种，与“可编程”“表达酶”的语境相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是微生物，不能被设计去表达聚合物裂解酶。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是空间，不是能被设计并表达酶的生物体。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“工程”后接“窗户”不成搭配，且与“可编程”“裂解酶”毫无关系。"}], "explanations": {"菌株": "正确：“工程菌株”指经过改造、从微生物中分离出的纯种，与“可编程”“表达酶”的语境相符。", "手机": "语义：手机不是微生物，不能被设计去表达聚合物裂解酶。", "教室": "语义：教室是空间，不是能被设计并表达酶的生物体。", "窗户": "搭配：“工程”后接“窗户”不成搭配，且与“可编程”“裂解酶”毫无关系。"}, "sentence_index": 0, "correct_answer": "菌株"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "森林里长着很多菌株。", "explanation": "这里应该用〈蘑菇〉。菌株指从微生物中分离出的纯种，不指森林里可见的蘑菇。"}, {"text": "墙角长满了菌株。", "explanation": "这里应该用〈苔藓〉。墙角长出的绿色一层是苔藓，菌株指从微生物中分离出的纯种，不指这类植物。"}, {"text": "他把这些菌株当作果酱，抹在面包上吃。", "explanation": "这里应该用〈果酱〉。菌株是从微生物中分离出的纯种，不能当作食物涂在面包上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "菌株", "is_correct": true, "explanation": "正确：“培养皿里的菌株”指培养皿中的微生物纯种，可以拿给学生看。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：培养皿里装的是微生物，不会是饼干。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“培养皿里的”修饰钥匙不搭配，培养皿不用来装钥匙。"}, {"text": "硬币", "is_correct": false, "explanation": "语义：硬币不是培养皿中展示的生物材料。"}], "explanations": {"菌株": "正确：“培养皿里的菌株”指培养皿中的微生物纯种，可以拿给学生看。", "饼干": "语义：培养皿里装的是微生物，不会是饼干。", "钥匙": "搭配：“培养皿里的”修饰钥匙不搭配，培养皿不用来装钥匙。", "硬币": "语义：硬币不是培养皿中展示的生物材料。"}, "sentence_index": 6, "correct_answer": "菌株"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花园里种着很多菌株。", "explanation": "这里应该用〈花〉。菌株指从微生物中分离出的纯种，不指花园里种的植物。"}, {"text": "书架上积了很多菌株。", "explanation": "这里应该用〈灰尘〉。书架上积的是灰尘，菌株是纯种微生物，不能说“积”。"}, {"text": "他在手机里下载了很多菌株。", "explanation": "这里应该用〈软件〉。手机里下载的是软件，菌株是微生物纯种，不能下载。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小王把菌株移了到新的培养基上。", "corrected_sentence": "小王把菌株移到了新的培养基上。", "error_description": "“移到”是动补结构，“了”应放在补语“到”之后，应说“把菌株移到了”；“移了到”把“了”插在补语之前，是语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员在河水里找到了一棵新菌株。", "corrected_sentence": "研究人员在河水里找到了一个新菌株。", "error_description": "量词“棵”用于树木等植物，菌株应用“个”或“种”，此处应为“一个新菌株”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
