INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13005, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能启动某种生物反应的特定化学或物理刺激", "primary_collocate": null, "pronunciation": "xìn hào", "ipa": "ɕin⁵¹ xaʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "因此，前沿研究正转向合成生物学路径，设计可编程的工程菌株，使其在特定信号触发下高效表达聚合物裂解酶，实现“精准生物降解”。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "细胞接收到化学信号，就会开始分裂。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经细胞用电信号传递消息。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物能感觉到光信号，所以叶子会转向太阳。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂靠气味信号找到同伴。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血液中的激素是一种重要的化学信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细菌数量增多后会释放化学信号，启动群体反应。", "target_word": "信号", "complexity_tier": "T3", "furigana": "xìn hào", "sentence_source": "generated"}, {"text": "这种信号太弱，细胞没有反应。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想弄清楚细胞怎样接收信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力信号会让植物关上叶子上的小孔。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种信号", "label": "量词"}, {"form": "信号分子", "label": "复合"}], "register": "中性", "sense_fingerprint": "生物学中能引起细胞或生物体反应的化学或物理刺激", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f995feb-01f2-46a0-bd0f-015ea5999b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13005, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信号", "is_correct": true, "explanation": "正确：“特定信号触发”指能启动细胞或基因表达反应的特定刺激。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是能引起细胞反应的刺激，无法触发基因表达。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：书籍不是能引起生物反应的刺激，与“表达酶”无关。"}, {"text": "舞蹈", "is_correct": false, "explanation": "搭配：“触发”一般接刺激、信号、条件，不接“舞蹈”。"}], "explanations": {"信号": "正确：“特定信号触发”指能启动细胞或基因表达反应的特定刺激。", "手机": "语义：手机不是能引起细胞反应的刺激，无法触发基因表达。", "书籍": "语义：书籍不是能引起生物反应的刺激，与“表达酶”无关。", "舞蹈": "搭配：“触发”一般接刺激、信号、条件，不接“舞蹈”。"}, "sentence_index": 0, "correct_answer": "信号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生用信号治疗病人。", "explanation": "这里应该用〈药物〉。信号是引起生物反应的刺激，不能用来治疗病人，治疗应说〈药物〉。"}, {"text": "他把信号装进了口袋。", "explanation": "这里应该用〈钥匙〉。信号是引起生物反应的刺激，不能装进口袋，能装进口袋的应是钥匙。"}, {"text": "工厂用信号制造汽车。", "explanation": "这里应该用〈原料〉。信号是引起生物反应的刺激，不是制造汽车的材料，应说〈原料〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信号", "is_correct": true, "explanation": "正确：细菌释放的化学信号可以启动群体反应，与“化学”“启动”相符。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声不是化学物质，细菌不会释放歌声来启动群体反应。"}, {"text": "灰尘", "is_correct": false, "explanation": "搭配：“化学”与“灰尘”不搭配，“释放灰尘”也无法启动群体反应。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶不是细菌释放的化学物质，无法启动群体反应。"}], "explanations": {"信号": "正确：细菌释放的化学信号可以启动群体反应，与“化学”“启动”相符。", "歌声": "语义：歌声不是化学物质，细菌不会释放歌声来启动群体反应。", "灰尘": "搭配：“化学”与“灰尘”不搭配，“释放灰尘”也无法启动群体反应。", "树叶": "语义：树叶不是细菌释放的化学物质，无法启动群体反应。"}, "sentence_index": 6, "correct_answer": "信号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师按照信号做了一道菜。", "explanation": "这里应该用〈菜谱〉。做菜要按照菜谱，信号是引起生物反应的刺激，不能用来指导做菜。"}, {"text": "他一边唱着信号，一边走进了教室。", "explanation": "这里应该用〈歌〉。唱的是歌，信号是引起生物反应的刺激，不能唱。"}, {"text": "他们把信号搬进了新家。", "explanation": "这里应该用〈家具〉。搬进新家的是家具，信号不是可以搬运的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究人员测量了细胞发出的一只电信号。", "corrected_sentence": "研究人员测量了细胞发出的一种电信号。", "error_description": "量词“只”用于动物或成对之物，信号不能用“只”计量，应说“一种电信号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学家发现了一只新的化学信号。", "corrected_sentence": "科学家发现了一种新的化学信号。", "error_description": "量词“只”用于动物或成对之物，信号不能用“只”计量，应说“一种新的化学信号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
