INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13006, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使某种反应或现象开始出现。", "primary_collocate": null, "pronunciation": "chù fā", "ipa": "ʈʂʰu⁵¹ fa⁵⁵", "syllable_count": 2, "sentences": [{"text": "因此，前沿研究正转向合成生物学路径，设计可编程的工程菌株，使其在特定信号触发下高效表达聚合物裂解酶，实现“精准生物降解”。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "烟太多会触发警报。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花粉会触发过敏反应。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度过高会触发保护装置。", "target_word": "触发", "complexity_tier": "T3", "furigana": "wēndù guògāo huì chùfā bǎohù zhuāngzhì", "sentence_source": "generated"}, {"text": "一句玩笑话触发了他的旧回忆。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强烈的光触发了眼睛的保护反应。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震可能触发山体滑坡。", "target_word": "触发", "complexity_tier": "T3", "furigana": "dìzhèn kěnéng chùfā shāntǐ huápō", "sentence_source": "generated"}, {"text": "冷空气触发了我的咳嗽。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门一打开，就会触发感应灯亮起。", "target_word": "触发", "complexity_tier": "T3", "furigana": "mén yī dǎkāi, jiù huì chùfā gǎnyìngdēng liàngqǐ", "sentence_source": "generated"}, {"text": "小小的误会触发了一场争吵。", "target_word": "触发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "触发了", "label": "体标"}, {"form": "触发过", "label": "体标"}, {"form": "触发器", "label": "复合"}], "register": "书面", "sense_fingerprint": "刺激或条件使某种反应、装置或现象开始出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f995feb-01f2-46a0-bd0f-015ea5999b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13006, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "触发", "is_correct": true, "explanation": "正确。触发（chù fā）：使某种反应或现象开始出现。"}, {"text": "出发", "is_correct": false, "explanation": "chū（第一声）与 chù（第四声）声调不同，意思是动身、起程。"}, {"text": "处罚", "is_correct": false, "explanation": "chǔ（第三声）与 chù（第四声）、fá（第二声）与 fā（第一声）声调都不同，意思是给予惩罚。"}, {"text": "除法", "is_correct": false, "explanation": "chú（第二声）与 chù（第四声）、fǎ（第三声）与 fā（第一声）声调都不同，意思是数学中的除法运算。"}], "explanations": {"触发": "正确。触发（chù fā）：使某种反应或现象开始出现。", "出发": "chū（第一声）与 chù（第四声）声调不同，意思是动身、起程。", "处罚": "chǔ（第三声）与 chù（第四声）、fá（第二声）与 fā（第一声）声调都不同，意思是给予惩罚。", "除法": "chú（第二声）与 chù（第四声）、fǎ（第三声）与 fā（第一声）声调都不同，意思是数学中的除法运算。"}, "sentence_index": null, "correct_answer": "触发"}, "level_3": {"options": [{"text": "触发", "is_correct": true, "explanation": "正确。“触发”指信号引起反应开始，与“在特定信号…下高效表达”的条件关系吻合。"}, {"text": "抑制", "is_correct": false, "explanation": "语义：“抑制”使反应受阻，与后文“使其高效表达”相矛盾。"}, {"text": "阻断", "is_correct": false, "explanation": "语义：“阻断”切断信号通路，与后文“高效表达”自相矛盾。"}, {"text": "屏蔽", "is_correct": false, "explanation": "搭配：“屏蔽”多指遮挡信号或声音，不能构成“在特定信号…下高效表达”的条件。"}], "explanations": {"触发": "正确。“触发”指信号引起反应开始，与“在特定信号…下高效表达”的条件关系吻合。", "抑制": "语义：“抑制”使反应受阻，与后文“使其高效表达”相矛盾。", "阻断": "语义：“阻断”切断信号通路，与后文“高效表达”自相矛盾。", "屏蔽": "搭配：“屏蔽”多指遮挡信号或声音，不能构成“在特定信号…下高效表达”的条件。"}, "sentence_index": 0, "correct_answer": "触发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会谈触发了两国的合同。", "explanation": "这里应该用〈签订〉。触发的对象是反应或现象，合同是文件，应说签订。"}, {"text": "这次合作触发了一座新桥。", "explanation": "这里应该用〈修建〉。触发指条件引起反应或现象，桥梁是工程，应说修建。"}, {"text": "这篇文章触发了我的心。", "explanation": "这里应该用〈触动〉。触发的宾语是反应或现象，不能用来指人的内心被打动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "触发", "is_correct": true, "explanation": "正确。“触发”表示地震这类条件引起山体滑坡，符合语境。"}, {"text": "预防", "is_correct": false, "explanation": "配价：“预防”需要有意志的施事，地震不能预防山体滑坡。"}, {"text": "躲避", "is_correct": false, "explanation": "配价：“躲避”的施事须是有意识的人或动物，地震不能躲避山体滑坡。"}, {"text": "扑灭", "is_correct": false, "explanation": "语义：“扑灭”指消灭火焰，与“山体滑坡”不能搭配，也与语境不符。"}], "explanations": {"触发": "正确。“触发”表示地震这类条件引起山体滑坡，符合语境。", "预防": "配价：“预防”需要有意志的施事，地震不能预防山体滑坡。", "躲避": "配价：“躲避”的施事须是有意识的人或动物，地震不能躲避山体滑坡。", "扑灭": "语义：“扑灭”指消灭火焰，与“山体滑坡”不能搭配，也与语境不符。"}, "sentence_index": 6, "correct_answer": "触发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暴雨触发了一台新电脑。", "explanation": "这里应该用〈生产〉。触发的对象是反应或现象，电脑是产品，应说生产。"}, {"text": "这项改革触发了新的时代。", "explanation": "这里应该用〈开启〉。触发不用于开启时代、局面这类大的阶段。"}, {"text": "这项技术触发了便利。", "explanation": "这里应该用〈带来〉。触发引出的是反应或现象，“便利”这类好处应说带来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "高温时，烟雾会被触发报警器。", "corrected_sentence": "高温时，烟雾会触发报警器。", "error_description": "“被”字句误用：“烟雾”是“触发”的施事，应直接说“烟雾会触发报警器”；加“被”会把“烟雾”变成承受者，与“报警器”构成的语义关系颠倒，应去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "长时间的强降雨会触发一把山体滑坡。", "corrected_sentence": "长时间的强降雨会触发山体滑坡。", "error_description": "量词错误：“山体滑坡”是事件，不能用“把”计量（“把”用于有柄的器具），应去掉“一把”，直接说“会触发山体滑坡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
