INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13007, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13007, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "细胞制造并释放某种蛋白质，如酶或激素", "primary_collocate": null, "pronunciation": "biǎo dá", "ipa": "pjɑʊ˨˩˦ ta˧˥", "syllable_count": 2, "sentences": [{"text": "因此，前沿研究正转向合成生物学路径，设计可编程的工程菌株，使其在特定信号触发下高效表达聚合物裂解酶，实现“精准生物降解”。", "target_word": "表达", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种细菌能表达一种新的蛋白质。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家让酵母细胞表达胰岛素。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "肝细胞在夜里会表达更多的酶。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个基因在肌肉里不表达。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究人员想让大肠杆菌表达绿色荧光蛋白。", "target_word": "表达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受到刺激后，细胞开始表达这种激素。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用植物细胞表达了抗体。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有在低温下，这些细胞才会表达该蛋白。", "target_word": "表达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验的目的是让细菌表达更多的酶。", "target_word": "表达", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表达了", "label": "完成体"}, {"form": "表达过", "label": "经历体"}, {"form": "基因表达", "label": "复合词"}], "register": "书面", "sense_fingerprint": "细胞合成并释放蛋白质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93f1010e-ee55-4e33-9cf5-8af6804f420b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13007, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表达", "is_correct": true, "explanation": "正确：细胞或工程菌制造并释放蛋白质，符合“表达”在此处的意思。"}, {"text": "解读", "is_correct": false, "explanation": "搭配：“解读”的对象是文字、信息、数据，不能说解读酶。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：整句说的是设计菌株高效产生酶以实现降解，“隐藏”与此相反。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”针对语言或文字，不能用于蛋白质或酶。"}], "explanations": {"表达": "正确：细胞或工程菌制造并释放蛋白质，符合“表达”在此处的意思。", "解读": "搭配：“解读”的对象是文字、信息、数据，不能说解读酶。", "隐藏": "语义：整句说的是设计菌株高效产生酶以实现降解，“隐藏”与此相反。", "翻译": "搭配：“翻译”针对语言或文字，不能用于蛋白质或酶。"}, "sentence_index": 0, "correct_answer": "表达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汗腺会表达大量的汗水。", "explanation": "这里应该用〈分泌〉。表达指细胞制造蛋白质或基因产物，汗水不是蛋白质，不能说表达。"}, {"text": "工厂每天表达大量的塑料。", "explanation": "这里应该用〈合成〉。表达只用于细胞或基因制造蛋白质，塑料是化工产品，应说合成。"}, {"text": "运动时身体会表达大量的能量。", "explanation": "这里应该用〈产生〉。表达指细胞制造蛋白质，能量不是蛋白质，应说产生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表达", "is_correct": true, "explanation": "正确：受刺激后细胞开始制造并释放这种激素，符合“表达”的意思。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是对人或事物表示接待，细胞开始欢迎激素说不通。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的宾语一般是问题或话题，不能接激素。"}, {"text": "尊敬", "is_correct": false, "explanation": "语义：“尊敬”针对有德行的人，不能用来描述细胞对激素的反应。"}], "explanations": {"表达": "正确：受刺激后细胞开始制造并释放这种激素，符合“表达”的意思。", "欢迎": "语义：“欢迎”是对人或事物表示接待，细胞开始欢迎激素说不通。", "讨论": "搭配：“讨论”的宾语一般是问题或话题，不能接激素。", "尊敬": "语义：“尊敬”针对有德行的人，不能用来描述细胞对激素的反应。"}, "sentence_index": 6, "correct_answer": "表达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "细胞在夜里会表达更多的热量。", "explanation": "这里应该用〈释放〉。表达指细胞制造蛋白质，热量不是蛋白质，应说释放。"}, {"text": "工厂表达了更多的汽车。", "explanation": "这里应该用〈制造〉。表达只用于细胞或基因制造蛋白质，汽车不属于这类产物。"}, {"text": "花朵表达出更多的香味。", "explanation": "这里应该用〈散发〉。表达不用于气味，香味不是蛋白质，应说散发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种细胞能把表达一种生长因子。", "corrected_sentence": "这种细胞能表达一种生长因子。", "error_description": "错误形式是“能把表达一种生长因子”，多出了“把”。“把”字句须为“把＋宾语＋动词”，这里“把”后直接接动词“表达”，结构不成立，应删去“把”，写成“能表达一种生长因子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个基因在大脑里被不表达。", "corrected_sentence": "这个基因在大脑里不表达。", "error_description": "错误形式是“在大脑里被不表达”，多出了“被”。否定词“不”应直接修饰动词“表达”，“被”字句在此不成立，应删去“被”，写成“不表达”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
