INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13008, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "酶是一种生物催化剂，能加速体内的化学反应，对消化、代谢等生命活动至关重要。", "primary_collocate": null, "pronunciation": "méi", "ipa": "mei˧˥", "syllable_count": 1, "sentences": [{"text": "因此，前沿研究正转向合成生物学路径，设计可编程的工程菌株，使其在特定信号触发下高效表达聚合物裂解酶，实现“精准生物降解”。", "target_word": "酶", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "唾液里有一种酶，能分解淀粉。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酶可以让身体里的反应变快。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温度太高时，酶会失去作用。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "胃里的酶帮助人消化食物。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每种酶只能催化一种反应。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些酶在三十七度时最活跃。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗衣粉里加入酶，更容易洗掉油污。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人缺少某种酶时，可能会生病。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家从细菌中找到了一种新的酶。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种酶", "label": "量词"}, {"form": "消化酶", "label": "复合词"}, {"form": "酶活性", "label": "复合词"}], "register": "书面", "sense_fingerprint": "生物催化剂，加速体内化学反应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93f1010e-ee55-4e33-9cf5-8af6804f420b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13008, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "酶", "is_correct": true, "explanation": "正确：酶 méi，指生物催化剂。"}, {"text": "美", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）声调不同，意思是美丽。"}, {"text": "萌", "is_correct": false, "explanation": "méng 与 méi 韵母不同，意思是萌发。"}, {"text": "门", "is_correct": false, "explanation": "mén 与 méi 韵母不同，意思是门。"}, {"text": "妹", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。"}], "explanations": {"酶": "正确：酶 méi，指生物催化剂。", "美": "měi（第三声）与 méi（第二声）声调不同，意思是美丽。", "萌": "méng 与 méi 韵母不同，意思是萌发。", "门": "mén 与 méi 韵母不同，意思是门。", "妹": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。"}, "sentence_index": null, "correct_answer": "酶"}, "level_3": {"options": [{"text": "酶", "is_correct": true, "explanation": "正确：“聚合物裂解酶”是一种能分解聚合物的酶，符合句意。"}, {"text": "菌", "is_correct": false, "explanation": "语义：“表达”的对象是蛋白质，细菌不能被表达，句意不通。"}, {"text": "液", "is_correct": false, "explanation": "搭配：“表达”的宾语要求是蛋白质，“裂解液”是溶液，不能说表达。"}, {"text": "剂", "is_correct": false, "explanation": "语义：“裂解剂”是化学试剂，工程菌不会被设计来表达一种试剂。"}], "explanations": {"酶": "正确：“聚合物裂解酶”是一种能分解聚合物的酶，符合句意。", "菌": "语义：“表达”的对象是蛋白质，细菌不能被表达，句意不通。", "液": "搭配：“表达”的宾语要求是蛋白质，“裂解液”是溶液，不能说表达。", "剂": "语义：“裂解剂”是化学试剂，工程菌不会被设计来表达一种试剂。"}, "sentence_index": 0, "correct_answer": "酶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "胃里有一只酶，能帮助消化食物。", "explanation": "这里应该用〈种〉。“只”多用于动物或个体，酶是一类物质，应说“一种酶”。"}, {"text": "酶每晚都能照亮整个房间。", "explanation": "这里应该用〈灯泡〉。酶是催化剂，不能发光，照亮房间要靠灯泡。"}, {"text": "酶能传递神经信号。", "explanation": "这里应该用〈神经递质〉。酶是催化剂，不传递信号；传递神经信号靠神经递质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13008, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "酶", "is_correct": true, "explanation": "正确：酶 méi，指生物催化剂。"}, {"text": "每", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）声调不同，意思是每个。"}, {"text": "镁", "is_correct": false, "explanation": "měi 与 méi 声调不同，意思是镁元素。"}, {"text": "陪", "is_correct": false, "explanation": "péi 与 méi 声母不同，意思是陪伴。"}], "explanations": {"酶": "正确：酶 méi，指生物催化剂。", "每": "měi（第三声）与 méi（第二声）声调不同，意思是每个。", "镁": "měi 与 méi 声调不同，意思是镁元素。", "陪": "péi 与 méi 声母不同，意思是陪伴。"}, "sentence_index": null, "correct_answer": "酶"}, "level_3": {"options": [{"text": "酶", "is_correct": true, "explanation": "正确：酶在三十七度时最活跃，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命活动，不会在三十七度时变得活跃。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不会活跃，句中说的是催化反应的物质。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“活跃”一般用于有生命或有行为的主体，窗户不能说活跃。"}], "explanations": {"酶": "正确：酶在三十七度时最活跃，符合句意。", "石头": "语义：石头没有生命活动，不会在三十七度时变得活跃。", "课本": "语义：课本不会活跃，句中说的是催化反应的物质。", "窗户": "搭配：“活跃”一般用于有生命或有行为的主体，窗户不能说活跃。"}, "sentence_index": 6, "correct_answer": "酶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "酶能分裂繁殖。", "explanation": "这里应该用〈细胞〉。酶不是生命体，不能分裂繁殖，应说细胞。"}, {"text": "酶需要寄生在细胞里。", "explanation": "这里应该用〈病毒〉。酶是催化剂，不能寄生在细胞中，寄生的是病毒。"}, {"text": "酶能预防坏血病。", "explanation": "这里应该用〈维生素〉。预防坏血病靠维生素，酶不是营养素。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只酶能催化淀粉分解。", "corrected_sentence": "这种酶能催化淀粉分解。", "error_description": "错误形式是“这只酶”，正确形式是“这种酶”。酶是一类物质，应用“种”；“只”多用于动物或个体，不能用于酶。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "胃里有一条消化酶。", "corrected_sentence": "胃里有一种消化酶。", "error_description": "错误形式是“一条消化酶”，正确形式是“一种消化酶”。“条”用于细长的物品，消化酶是一类物质，应用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
