INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13009, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容用途广、功能多，能胜任各种事情。", "primary_collocate": null, "pronunciation": "wàn néng", "ipa": "wan˥˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "从全生命周期评估视角看，可降解塑料并非万能解药。", "target_word": "万能", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这把万能钥匙能打开很多门。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种万能胶什么材料都能粘。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机很有用，但不是万能的。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个工具真万能，修车、修电器都行。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱不是万能的，买不到健康。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种万能充电器可以给各种手机充电。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个万能插座可以插各种插头。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有一种药是万能的，用错了会有危险。", "target_word": "万能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台相机很万能，风景、人像、夜景都能拍。", "target_word": "万能", "complexity_tier": "T3", "furigana": "zhè tái xiàngjī hěn wànnéng, fēngjǐng, rénxiàng, yèjǐng dōu néng pāi", "sentence_source": "generated"}], "morphological_forms": [{"form": "万能钥匙", "label": "复合"}, {"form": "万能胶", "label": "复合"}, {"form": "萬能", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容物品、方法用途广、功能多，什么场合都能用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58fcc8cb-7a7f-4d32-9843-a69e1fc8fe4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13009, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "易碎", "is_correct": false, "explanation": "语义：“易碎”说容易破裂，与解药的药效无关，“并非易碎解药”说不通。"}, {"text": "万能", "is_correct": true, "explanation": "正确：“并非万能解药”表示解药不是包治百病的，“万能”符合语境。"}, {"text": "慢性", "is_correct": false, "explanation": "搭配：“慢性”多修饰病症或病程，不用来修饰“解药”。"}, {"text": "微小", "is_correct": false, "explanation": "体貌：“微小”形容体积，不描述解药的作用范围，此处不合语境。"}], "explanations": {"易碎": "语义：“易碎”说容易破裂，与解药的药效无关，“并非易碎解药”说不通。", "万能": "正确：“并非万能解药”表示解药不是包治百病的，“万能”符合语境。", "慢性": "搭配：“慢性”多修饰病症或病程，不用来修饰“解药”。", "微小": "体貌：“微小”形容体积，不描述解药的作用范围，此处不合语境。"}, "sentence_index": 0, "correct_answer": "万能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种现象很万能，到处都有。", "explanation": "这里应该用〈普遍〉。“普遍”说范围广、到处都有；“万能”说用途广、能做各种事，不用来形容现象的分布。"}, {"text": "这件衣服的颜色很万能，特别鲜艳。", "explanation": "这里应该用〈鲜艳〉。“鲜艳”形容颜色明亮；“万能”说用途广、能胜任各种事，不用来形容颜色。"}, {"text": "这套插头的标准很万能，只适用于一个国家。", "explanation": "这里应该用〈专用〉。“专用”说只供一种用途、适用范围窄；“万能”说用途广，与“只适用于一个国家”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13009, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专用", "is_correct": false, "explanation": "语义：“专用”说只供一种用途，与“可以给各种手机充电”矛盾。"}, {"text": "万能", "is_correct": true, "explanation": "正确：“这种万能充电器”说明它能给各种手机充电，“万能”符合语境。"}, {"text": "单一", "is_correct": false, "explanation": "搭配：“单一”多修饰功能、类型，不说“单一充电器”。"}, {"text": "专门", "is_correct": false, "explanation": "语义：“专门”指只为某一事物设计，与“给各种手机充电”相悖。"}], "explanations": {"专用": "语义：“专用”说只供一种用途，与“可以给各种手机充电”矛盾。", "万能": "正确：“这种万能充电器”说明它能给各种手机充电，“万能”符合语境。", "单一": "搭配：“单一”多修饰功能、类型，不说“单一充电器”。", "专门": "语义：“专门”指只为某一事物设计，与“给各种手机充电”相悖。"}, "sentence_index": 6, "correct_answer": "万能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种疗法很万能，只对一种病有效。", "explanation": "这里应该用〈专门〉。“专门”说只针对某一方面；“万能”说用途广，与“只对一种病有效”矛盾。"}, {"text": "这种膏药很灵验，抹上就不疼。", "explanation": "这里应该用〈灵验〉。“灵验”说效果显著；“万能”说用途广、能胜任各种事，不用来形容药效。"}, {"text": "这个模具很万能，误差不到一毫米。", "explanation": "这里应该用〈精密〉。“精密”说精确、误差小；“万能”说用途广、能做各种事，不用来说精度高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把很万能钥匙能开很多锁。", "corrected_sentence": "这把万能钥匙能开很多锁。", "error_description": "结构错误：定语“万能”前面不能直接加“很”再接名词，应去掉“很”，说“这把万能钥匙”；如果要用“很”，后面要加“的”，说“这把很万能的钥匙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个插座很的万能，能给各种电器供电。", "corrected_sentence": "这个插座很万能，能给各种电器供电。", "error_description": "结构错误：程度副词“很”后面直接接形容词“万能”，中间不能加“的”，应说“很万能”，不说“很的万能”。目标词“万能”的修饰结构用错了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13010, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13010, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13010, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "解药指能解除毒药或疾病作用的药物。", "primary_collocate": null, "pronunciation": "jiě yào", "ipa": "tɕjɛ˨˩˦ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "从全生命周期评估视角看，可降解塑料并非万能解药。", "target_word": "解药", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "医生给他吃了解药，毒很快就解了。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种蛇毒很强，要马上用解药。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不小心喝了毒药，医院里正好有解药。", "target_word": "解药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病毒现在还没有解药。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影里，坏人把解药藏在了盒子里。", "target_word": "解药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有找到解药，大家才能得救。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，这瓶解药要在两小时内吃。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家正在研究这种毒的解药。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种蛇毒的解药需要冷藏保存。", "target_word": "解药", "complexity_tier": "T3", "furigana": "zhè zhǒng shé dú de jiěyào xūyào lěngcáng bǎocún", "sentence_source": "generated"}], "morphological_forms": [{"form": "一剂解药", "label": "量词"}, {"form": "一瓶解药", "label": "量词"}, {"form": "万能解药", "label": "复合"}, {"form": "解藥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "能解除毒药或疾病作用的药物，也比喻解决问题的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58fcc8cb-7a7f-4d32-9843-a69e1fc8fe4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毒药", "is_correct": false, "explanation": "语义：“毒药”会致人中毒，与“并非万能”后的解毒功能相反，读来矛盾。"}, {"text": "解药", "is_correct": true, "explanation": "正确：“并非万能解药”表示可降解塑料不是包治百病的解毒物，“解药”符合语境。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不能解除毒药或疾病的作用，与“解药”的功能不符。"}, {"text": "毒液", "is_correct": false, "explanation": "搭配：“万能”一般修饰能广泛使用的物品或方法，不用来修饰“毒液”。"}], "explanations": {"毒药": "语义：“毒药”会致人中毒，与“并非万能”后的解毒功能相反，读来矛盾。", "解药": "正确：“并非万能解药”表示可降解塑料不是包治百病的解毒物，“解药”符合语境。", "饮料": "语义：饮料不能解除毒药或疾病的作用，与“解药”的功能不符。", "毒液": "搭配：“万能”一般修饰能广泛使用的物品或方法，不用来修饰“毒液”。"}, "sentence_index": 0, "correct_answer": "解药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他手上烫伤了，抹了解药就好了。", "explanation": "这里应该用〈药膏〉。药膏用于外敷，治疗烫伤这类外伤；解药用于解除毒药或严重疾病的作用，烫伤不用解药。"}, {"text": "孩子们都要打解药来预防这种病。", "explanation": "这里应该用〈疫苗〉。疫苗用于预防，解药用于解除毒药或疾病已经产生的作用。"}, {"text": "他发烧了，吃了解药，很快就退烧了。", "explanation": "这里应该用〈退烧药〉。解药用于解除毒药或严重疾病的作用，发烧要吃退烧药，不说吃解药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”是供玩耍的物品，不能解毒救人，与“只有找到……才能得救”矛盾。"}, {"text": "解药", "is_correct": true, "explanation": "正确：“只有找到解药，大家才能得救”符合语境，“解药”能解除毒性，是得救的条件。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”是废弃物，不能帮助大家得救，与句意相悖。"}, {"text": "零钱", "is_correct": false, "explanation": "语义：“零钱”是找零的钱，不能帮助大家得救，与句意不通。"}], "explanations": {"玩具": "语义：“玩具”是供玩耍的物品，不能解毒救人，与“只有找到……才能得救”矛盾。", "解药": "正确：“只有找到解药，大家才能得救”符合语境，“解药”能解除毒性，是得救的条件。", "垃圾": "语义：“垃圾”是废弃物，不能帮助大家得救，与句意相悖。", "零钱": "语义：“零钱”是找零的钱，不能帮助大家得救，与句意不通。"}, "sentence_index": 6, "correct_answer": "解药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天要多吃解药，身体才不容易生病。", "explanation": "这里应该用〈维生素〉。维生素用于补充营养，解药用于解除毒性，不能用来增强体质。"}, {"text": "手术前，医生给他打了解药。", "explanation": "这里应该用〈麻醉药〉。麻醉药使人暂时失去知觉，便于手术；解药用于解毒，不用于手术前。"}, {"text": "他头疼，吃了解药就不疼了。", "explanation": "这里应该用〈止痛药〉。止痛药用于缓解疼痛，解药用于解除毒药或严重疾病的作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他误食了毒物，医生马上给他一条解药，毒性很快就解了。", "corrected_sentence": "他误食了毒物，医生马上给他一剂解药，毒性很快就解了。", "error_description": "量词错误：解药应用“剂”“瓶”等，“条”用于细长的东西，不说“一条解药”。目标词“解药”的量词用错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把解药要放在阴凉处保存。", "corrected_sentence": "这瓶解药要放在阴凉处保存。", "error_description": "量词错误：解药应用“瓶”“剂”等，“把”用于有柄的东西，不说“这把解药”。目标词“解药”的量词用错了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
