INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13011, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示把某物放在某个位置或使处于某种状态。", "primary_collocate": null, "pronunciation": "zhì yú", "ipa": "ʈʂɨ⁵¹ y³⁵", "syllable_count": 2, "sentences": [{"text": "其环境影响必须置于整个资源循环系统中权衡——从原料提取、生产能耗、使用性能到终端处理。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们应把安全置于第一位。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把家人的健康置于工作之上。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事应置于整个计划中来看。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师总把学生的需要置于首位。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把客户的意见置于最重要的位置。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能把个人的好处置于大家的利益之上。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题要置于当时的历史中来理解。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把孩子的学习置于一切之前。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些数字置于表格中比较。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "把事物放在某个范围、位置或状态之中，多用于抽象语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f995feb-01f2-46a0-bd0f-015ea5999b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13011, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "置于", "is_correct": true, "explanation": "正确。“置于”表示把环境影响放入整个系统中权衡，符合语境。"}, {"text": "排除", "is_correct": false, "explanation": "语义：“排除”指不予考虑，与“在整个系统中权衡”相矛盾。"}, {"text": "割裂", "is_correct": false, "explanation": "语义：“割裂”指分开、切断，与“整个资源循环系统”的整体考虑相矛盾。"}, {"text": "忽略", "is_correct": false, "explanation": "搭配：“忽略”接的是不被顾及的事物，不能用来表示放入整个系统中权衡。"}], "explanations": {"置于": "正确。“置于”表示把环境影响放入整个系统中权衡，符合语境。", "排除": "语义：“排除”指不予考虑，与“在整个系统中权衡”相矛盾。", "割裂": "语义：“割裂”指分开、切断，与“整个资源循环系统”的整体考虑相矛盾。", "忽略": "搭配：“忽略”接的是不被顾及的事物，不能用来表示放入整个系统中权衡。"}, "sentence_index": 0, "correct_answer": "置于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把任务置于小李。", "explanation": "这里应该用〈交给〉。置于指把事物放在某个位置或状态中，人不能作为“置于”的处所，任务要交给人。"}, {"text": "父亲把孩子置于明天。", "explanation": "这里应该用〈留到〉。置于指把事物放在某个位置或状态，时间上的安排要说留到，不能把人置于某个时间。"}, {"text": "他的成绩置于大海之中。", "explanation": "这里应该用〈位居〉。成绩是名次，不是可以放进某个地点的事物，名次要说位居。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13011, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "置于", "is_correct": true, "explanation": "正确。“置于”表示把个人利益放在大家利益之下的位置关系，符合语境。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”指丢掉，与“大家的利益之上”的位置关系不符。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”指藏起来，与“之上”的位置关系不合。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”接好处、待遇，不能构成“享受…之上”的说法。"}], "explanations": {"置于": "正确。“置于”表示把个人利益放在大家利益之下的位置关系，符合语境。", "抛弃": "语义：“抛弃”指丢掉，与“大家的利益之上”的位置关系不符。", "隐藏": "语义：“隐藏”指藏起来，与“之上”的位置关系不合。", "享受": "搭配：“享受”接好处、待遇，不能构成“享受…之上”的说法。"}, "sentence_index": 6, "correct_answer": "置于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司把他置于北京。", "explanation": "这里应该用〈派〉。置于指把事物放在某个位置或状态中，派遣人员去某地应说派。"}, {"text": "他从不把别人置于眼里。", "explanation": "这里应该用〈放在〉。置于用于具体地点，抽象的看法和态度要说放在眼里。"}, {"text": "会议置于明天上午。", "explanation": "这里应该用〈安排在〉。置于指把事物放在某个位置或状态，时间安排要说安排在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13011, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这次比赛的胜负置于在次要位置。", "corrected_sentence": "我把这次比赛的胜负置于次要位置。", "error_description": "“置于”已含介词“于”，其后不能再接“在”，属于于、在重复。应说“置于次要位置”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13011, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们被这些数据置于同一张表格中。", "corrected_sentence": "我们把这些数据置于同一张表格中。", "error_description": "“把”误用为“被”：此句的“我们”是施事，要引出被处置的“这些数据”，应用“把”，说“我们把这些数据置于同一张表格中”；用“被”则变成被动，语义不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
