INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13012, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生物体内由心脏、血管等组成的系统，负责输送血液、氧气和营养物质到全身各处，并带走废物。", "primary_collocate": null, "pronunciation": "xún huán xì tǒng", "ipa": "ɕyn˧˥ xwan˧˥ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "饭后，循环系统会把大量血液分配到消化器官，因此饭后立即剧烈运动容易引起不适。", "target_word": "循环系统", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "长期久坐的人，下肢静脉回流较慢，循环系统的负担会逐渐加重。", "target_word": "循环系统", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "心脏是人体循环系统的中心。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "循环系统把氧气送到全身。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经常运动对循环系统很有好处。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的循环系统有问题。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "循环系统出了问题，人会觉得很累。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的循环系统由心脏和血管组成。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪大了，循环系统会慢慢变弱。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼的循环系统比人的简单。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "血液循环系统", "label": "复合"}], "register": "中性", "sense_fingerprint": "生物体内输送血液与养分的器官系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7833e8da-174d-473c-8fad-ba990596ff35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "循环系统", "is_correct": true, "explanation": "正确。“循环系统”负责输送血液，“把大量血液分配到消化器官”与句意相符。"}, {"text": "呼吸系统", "is_correct": false, "explanation": "语义：呼吸系统负责气体交换，不负责把血液分配到消化器官。"}, {"text": "消化系统", "is_correct": false, "explanation": "语义：消化系统是接受血液的器官，本身不负责分配血液，句意不通。"}, {"text": "生物钟", "is_correct": false, "explanation": "语义：生物钟指生理节律，不输送血液，与句意无关。"}], "explanations": {"循环系统": "正确。“循环系统”负责输送血液，“把大量血液分配到消化器官”与句意相符。", "呼吸系统": "语义：呼吸系统负责气体交换，不负责把血液分配到消化器官。", "消化系统": "语义：消化系统是接受血液的器官，本身不负责分配血液，句意不通。", "生物钟": "语义：生物钟指生理节律，不输送血液，与句意无关。"}, "sentence_index": 0, "correct_answer": "循环系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生说他身体里有一只循环系统。", "explanation": "这里应该用〈套〉。循环系统是成套的器官系统，应用量词“套”，“只”不能用于成套的系统。"}, {"text": "运动以后，他喝了一大口循环系统。", "explanation": "〈循环系统〉指身体里输送血液的器官系统，不是液体，不能与“喝”搭配。"}, {"text": "这次数学考试，循环系统考了第一名。", "explanation": "〈循环系统〉是器官系统，不是人，不能作为“考试”这种行为的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "循环系统", "is_correct": true, "explanation": "“循环系统出了问题”指身体的循环器官出故障，人会因此感到疲劳，句意成立。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架是家具，不会像身体器官那样“出问题”让人觉得很累，句子不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“出了问题”后不接“天空”，天空不会故障，也与“人会觉得很累”无关。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，与人的身体状况无关，“出了问题，人会觉得很累”说的是身体。"}], "explanations": {"循环系统": "“循环系统出了问题”指身体的循环器官出故障，人会因此感到疲劳，句意成立。", "书架": "语义：书架是家具，不会像身体器官那样“出问题”让人觉得很累，句子不通。", "天空": "搭配：“出了问题”后不接“天空”，天空不会故障，也与“人会觉得很累”无关。", "月亮": "语义：月亮是天体，与人的身体状况无关，“出了问题，人会觉得很累”说的是身体。"}, "sentence_index": 6, "correct_answer": "循环系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "循环系统每分钟跳七十次左右。", "explanation": "这里应该用〈心脏〉。“跳”是心脏的动作，循环系统是器官系统的统称，不会跳动。"}, {"text": "妈妈用循环系统来煮饭。", "explanation": "〈循环系统〉指身体里输送血液的结构，不是厨房用具，不能用来煮饭。"}, {"text": "他把循环系统塞进了书包。", "explanation": "〈循环系统〉是身体内部的结构，不能被装进书包；“塞进”的对象应是可以拿起的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人体里有一把循环系统，负责输送血液。", "corrected_sentence": "人体里有一套循环系统，负责输送血液。", "error_description": "错误：“一把”；正确：“一套”。循环系统是成套的器官系统，应用量词“套”，“把”用于有柄的器具。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鱼地循环系统很简单。", "corrected_sentence": "小鱼的循环系统很简单。", "error_description": "错误：“地”；正确：“的”。“的”标记定语，修饰名词要用“的”；“地”标记状语，不能用在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
