INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13015, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13015, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指进行某项活动或维持某种状态所消耗的能量，通常以电、燃料等形式体现。", "primary_collocate": null, "pronunciation": "néng hào", "ipa": "nɤŋ˧˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "其环境影响必须置于整个资源循环系统中权衡——从原料提取、生产能耗、使用性能到终端处理。", "target_word": "能耗", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台新空调的能耗比旧的低很多。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂想办法降低能耗，节约成本。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆电动车每百公里的能耗很低。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数据中心的能耗很高，每天要用很多电。", "target_word": "能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买冰箱时，我先看能耗等级。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天开空调，家里的能耗会增加。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种灯的能耗只有旧灯的一半。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钢铁厂的能耗大，用煤也多。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司换了新机器，生产能耗下降了。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "低能耗", "label": "复合"}, {"form": "高能耗", "label": "复合"}], "register": "中性", "sense_fingerprint": "设备、生产或活动所消耗的能量，以电、燃料等计量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58fcc8cb-7a7f-4d32-9843-a69e1fc8fe4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13015, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能耗", "is_correct": true, "explanation": "正确：从原料到处理的全过程中，生产环节消耗的能量就是能耗，与前后各环节并列，句意通顺。"}, {"text": "人数", "is_correct": false, "explanation": "语义：人数指人的数量，不是产品生产流程中的一个环节，放在这里说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高形容人的外形，不能作为产品生产流程中的一个环节。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：情绪是人的心理状态，产品的生产过程没有情绪，这一处说不通。"}], "explanations": {"能耗": "正确：从原料到处理的全过程中，生产环节消耗的能量就是能耗，与前后各环节并列，句意通顺。", "人数": "语义：人数指人的数量，不是产品生产流程中的一个环节，放在这里说不通。", "身高": "体貌：身高形容人的外形，不能作为产品生产流程中的一个环节。", "情绪": "语义：情绪是人的心理状态，产品的生产过程没有情绪，这一处说不通。"}, "sentence_index": 0, "correct_answer": "能耗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个电池储存的能耗很大。", "explanation": "这里应该用〈能量〉。能耗指消耗掉的能量，“储存”针对的是能量本身，不能用来形容能耗。"}, {"text": "这座城市的能耗很丰富。", "explanation": "这里应该用〈能源〉。能耗指消耗掉的能量，“丰富”形容的是可以供应的能源，不能形容消耗量。"}, {"text": "他的能耗很强，英语说得很流利。", "explanation": "这里应该用〈能力〉。能耗指消耗的能量，不能用来形容语言水平；“很强”形容的是人的本领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13015, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能耗", "is_correct": true, "explanation": "正确：开空调会增加用电，“家里的能耗会增加”符合句意。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指受教育程度，与开空调无关，不能说“家里的学历会增加”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“增加”说的是数量，颜色不能用“增加”来表示变化。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数是文字的数量，与开空调没有关系，放在这里说不通。"}], "explanations": {"能耗": "正确：开空调会增加用电，“家里的能耗会增加”符合句意。", "学历": "语义：学历指受教育程度，与开空调无关，不能说“家里的学历会增加”。", "颜色": "搭配：“增加”说的是数量，颜色不能用“增加”来表示变化。", "字数": "语义：字数是文字的数量，与开空调没有关系，放在这里说不通。"}, "sentence_index": 6, "correct_answer": "能耗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个手机的能耗很足，一天都不用充电。", "explanation": "这里应该用〈电量〉。能耗指消耗的能量，“足”形容的是可供应的电量，不能用来形容消耗量。"}, {"text": "这台空调的能耗很贵，我用不起。", "explanation": "这里应该用〈电费〉。能耗指消耗的能量，电费是用电要付的钱，“贵”形容的是价格，不能用来形容能耗。"}, {"text": "这辆车的能耗很快，十分钟就到了。", "explanation": "这里应该用〈速度〉。能耗指消耗的能量，“快”形容的是速度，不能用来形容能耗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台新机器的很能耗很低。", "corrected_sentence": "这台新机器的能耗很低。", "error_description": "多余的“很”：程度副词“很”不能直接放在名词“能耗”前面，应删去，说“这台新机器的能耗很低”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司已经把很能耗降低了。", "corrected_sentence": "公司已经把能耗降低了。", "error_description": "语序错误：“很”是程度副词，不能直接放在名词“能耗”前面，应去掉。应说“公司已经把能耗降低了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
