INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13016, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指在实际使用中表现出来的效果或能力。", "primary_collocate": null, "pronunciation": "shǐ yòng xìng néng", "ipa": "ʂɻ̩˨˩˦ jʊŋ˥˩ ɕiŋ˥˩ nɤŋ˧˥", "syllable_count": 4, "sentences": [{"text": "其环境影响必须置于整个资源循环系统中权衡——从原料提取、生产能耗、使用性能到终端处理。", "target_word": "使用性能", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种新材料的使用性能很好。", "target_word": "使用性能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师正在测试这款塑料的使用性能。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种涂料的使用性能比旧产品强。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂家说，加入新成分后，使用性能提高了。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先检查包装材料的使用性能。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种纸杯的使用性能不太稳定。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验表明，两种材料的使用性能差不多。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使用性能不好的产品，很难卖出去。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了改善使用性能，公司换了原料。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "产品或材料在实际使用中表现出的效果和能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58fcc8cb-7a7f-4d32-9843-a69e1fc8fe4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使用性能", "is_correct": true, "explanation": "正确：“使用性能”指产品在使用阶段的表现，放在流程中正好指使用阶段，句意通顺。"}, {"text": "人数", "is_correct": false, "explanation": "语义：人数指人的数量，不是产品生命周期中的阶段，放在这里说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高形容人的外形，不能作为产品流程中的一个阶段。"}, {"text": "情绪", "is_correct": false, "explanation": "搭配：“情绪”不能指产品的使用阶段，也不能说“情绪到终端处理”。"}], "explanations": {"使用性能": "正确：“使用性能”指产品在使用阶段的表现，放在流程中正好指使用阶段，句意通顺。", "人数": "语义：人数指人的数量，不是产品生命周期中的阶段，放在这里说不通。", "身高": "体貌：身高形容人的外形，不能作为产品流程中的一个阶段。", "情绪": "搭配：“情绪”不能指产品的使用阶段，也不能说“情绪到终端处理”。"}, "sentence_index": 0, "correct_answer": "使用性能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种涂料的使用性能比旧产品长。", "explanation": "这里应该用〈使用寿命〉。使用性能指表现出的效果和能力，“长”形容时间，说产品用得久要用“使用寿命”。"}, {"text": "这个孩子的使用性能很强。", "explanation": "这里应该用〈能力〉。使用性能指产品实际使用时的效果，不能用来形容人的能力。"}, {"text": "这块石头的使用性能很重，有五公斤。", "explanation": "这里应该用〈重量〉。“重量”说物体的轻重；“使用性能”说实际用起来的效果，不用来形容轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使用性能", "is_correct": true, "explanation": "正确：纸杯的使用性能指实际用起来的表现，说“不太稳定”符合句意。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指受教育程度，不能用来形容纸杯。"}, {"text": "肤色", "is_correct": false, "explanation": "体貌：肤色是人或动物的外表特征，纸杯没有肤色。"}, {"text": "人品", "is_correct": false, "explanation": "语义：人品指人的品德，纸杯不具备，说“人品不太稳定”不通。"}], "explanations": {"使用性能": "正确：纸杯的使用性能指实际用起来的表现，说“不太稳定”符合句意。", "学历": "语义：学历指受教育程度，不能用来形容纸杯。", "肤色": "体貌：肤色是人或动物的外表特征，纸杯没有肤色。", "人品": "语义：人品指人的品德，纸杯不具备，说“人品不太稳定”不通。"}, "sentence_index": 6, "correct_answer": "使用性能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这款包的使用性能很好看，背起来也舒服。", "explanation": "这里应该用〈外观〉。使用性能指实际使用时的效果，“好看”形容的是外观。"}, {"text": "这件衣服的使用性能很便宜。", "explanation": "这里应该用〈价格〉。使用性能说的是效果，“便宜”形容的是价格。"}, {"text": "这把剪刀的使用性能很轻，拿着很顺手。", "explanation": "这里应该用〈重量〉。使用性能指东西用起来的效果，“轻”形容的是重量，不能用来形容使用性能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厂家把很使用性能提高了。", "corrected_sentence": "厂家把使用性能提高了。", "error_description": "语序错误：“很”是程度副词，不能直接放在名词“使用性能”前面，应去掉。应说“厂家把使用性能提高了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把新剪刀的很使用性能不稳定。", "corrected_sentence": "这把新剪刀的使用性能不稳定。", "error_description": "语序错误：“很”是程度副词，不能直接放在名词“使用性能”前面，应去掉。应说“这把新剪刀的使用性能不稳定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13017, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "始端", "is_correct": true, "explanation": "始端指线路、管道等开始的一端，与终端相对，是反义关系。"}, {"text": "中心", "is_correct": false, "explanation": "中心指事物的中间位置，与终端的末端义没有相对关系。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子是家具，与线路或流程的末端没有相对关系。"}, {"text": "天气", "is_correct": false, "explanation": "天气指大气状况，与终端没有相对关系。"}], "correct_answer": "始端", "explanations": {"始端": "始端指线路、管道等开始的一端，与终端相对，是反义关系。", "中心": "中心指事物的中间位置，与终端的末端义没有相对关系。", "桌子": "桌子是家具，与线路或流程的末端没有相对关系。", "天气": "天气指大气状况，与终端没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13017, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "始端", "is_correct": true, "explanation": "始端指线路、管道等开始的一端，与终端相对，是反义关系。"}, {"text": "中间", "is_correct": false, "explanation": "中间指位置居中，与终端的末端义没有相对关系。"}, {"text": "房间", "is_correct": false, "explanation": "房间是居住或办公的空间，与终端没有相对关系。"}, {"text": "雨水", "is_correct": false, "explanation": "雨水指从天上降下的水，与终端没有相对关系。"}], "correct_answer": "始端", "explanations": {"始端": "始端指线路、管道等开始的一端，与终端相对，是反义关系。", "中间": "中间指位置居中，与终端的末端义没有相对关系。", "房间": "房间是居住或办公的空间，与终端没有相对关系。", "雨水": "雨水指从天上降下的水，与终端没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13017, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "末端，最后的部分或环节。", "primary_collocate": null, "pronunciation": "zhōng duān", "ipa": "ʈʂʊŋ˥ twan˥", "syllable_count": 2, "sentences": [{"text": "其环境影响必须置于整个资源循环系统中权衡——从原料提取、生产能耗、使用性能到终端处理。", "target_word": "终端", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水管的终端装了一个水龙头。", "target_word": "终端", "complexity_tier": "T3", "furigana": "shuǐ guǎn de zhōng duān zhuāng le yí gè shuǐ lóng tóu", "sentence_source": "generated"}, {"text": "这条线路的终端是机场。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电线的终端连着一个小灯。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾处理是整个过程的终端。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条管子的终端接了一个喷头。", "target_word": "终端", "complexity_tier": "T3", "furigana": "zhè tiáo guǎn zi de zhōng duān jiē le yí gè pēn tóu", "sentence_source": "generated"}, {"text": "产品从工厂到终端要三天。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物的终端是各个商店。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路的终端是一个小城。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁的终端离我家很远。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "线路或流程的末端、最后环节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f775cb0c-f64a-45de-b26d-fcb784c8d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13017, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数据", "is_correct": false, "explanation": "语义：数据不是资源循环中的环节，与前面的原料提取、生产能耗、使用性能不是同一类。"}, {"text": "终端", "is_correct": true, "explanation": "终端指处理链条的最后一环，与前面的原料提取、生产能耗、使用性能依次相接。"}, {"text": "设计", "is_correct": false, "explanation": "搭配：“处理”的对象一般是废物、废水等，不说“设计处理”。"}, {"text": "原料", "is_correct": false, "explanation": "语义：“原料”已作为起点出现在“从原料提取”中，不能再作终点。"}], "explanations": {"数据": "语义：数据不是资源循环中的环节，与前面的原料提取、生产能耗、使用性能不是同一类。", "终端": "终端指处理链条的最后一环，与前面的原料提取、生产能耗、使用性能依次相接。", "设计": "搭配：“处理”的对象一般是废物、废水等，不说“设计处理”。", "原料": "语义：“原料”已作为起点出现在“从原料提取”中，不能再作终点。"}, "sentence_index": 0, "correct_answer": "终端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的终端很感人。", "explanation": "这里应该用〈结尾〉。“终端”指线路或流程的末端，作品的结尾要用〈结尾〉，不用“终端”。"}, {"text": "他冲过了比赛的终端，拿到了冠军。", "explanation": "这里应该用〈终点〉。“终端”指线路或流程的末端，比赛的到达处要说〈终点〉，不用“终端”。"}, {"text": "这条狗的终端很长。", "explanation": "这里应该用〈尾巴〉。“终端”指线路、流程的末端，不用于动物身体的部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13017, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工厂", "is_correct": false, "explanation": "语义：工厂是运输的起点，句中已有“从工厂”，不能再作终点。"}, {"text": "价格", "is_correct": false, "explanation": "配价：“到”后要接地点或环节，“价格”不能作运输的终点。"}, {"text": "终端", "is_correct": true, "explanation": "终端指运输或流程的末端，“到终端”表示运到最后的环节。"}, {"text": "上午", "is_correct": false, "explanation": "语义：上午是时间，不是运输的终点，“到上午要三天”不成立。"}], "explanations": {"工厂": "语义：工厂是运输的起点，句中已有“从工厂”，不能再作终点。", "价格": "配价：“到”后要接地点或环节，“价格”不能作运输的终点。", "终端": "终端指运输或流程的末端，“到终端”表示运到最后的环节。", "上午": "语义：上午是时间，不是运输的终点，“到上午要三天”不成立。"}, "sentence_index": 6, "correct_answer": "终端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地铁的一条终端离我家很远。", "explanation": "这里应该用〈个〉。“条”用于线状、长条形的东西，这里的终端应说“一个终端”。"}, {"text": "地铁的一根终端离我家很远。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，这里的终端不用“根”，应说“一个终端”。"}, {"text": "地铁的一张终端离我家很远。", "explanation": "这里应该用〈个〉。“张”用于平展的物件，这里的终端不用“张”，应说“一个终端”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13017, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "管道的一台终端通到地下。", "corrected_sentence": "管道的一个终端通到地下。", "error_description": "量词错误：“终端”指线路或管道的末端，量词用“个”。“台”用于机器设备，这里应说“一个终端”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13017, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "货物最后要运到一只终端。", "corrected_sentence": "货物最后要运到终端。", "error_description": "量词错误：“只”用于动物，不用于终端，应去掉量词或改用“个”。错误形式：一只终端；正确形式：终端。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
