INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13018, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指相互搭配、配合，形成完整的组合或关系。", "primary_collocate": null, "pronunciation": "pèi tào", "ipa": "pʰeɪ˥˩ tʰɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "真正的可持续性，不仅依赖材料本身的创新，更需配套的分类回收基础设施、政策法规与公众认知协同演进。", "target_word": "配套", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "新小区的配套设施很齐全。", "target_word": "配套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边有配套的宿舍楼。", "target_word": "配套", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套教材有配套的练习册。", "target_word": "配套", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买手机时，送的充电器是配套的。", "target_word": "配套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂旁边要有配套的仓库。", "target_word": "配套", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个园区的配套服务越来越好。", "target_word": "配套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府还出台了配套政策。", "target_word": "配套", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的配套道路还没修好。", "target_word": "配套", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院需要配套的停车场。", "target_word": "配套", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "配套设施", "label": "复合"}, {"form": "配套政策", "label": "复合"}], "register": "书面", "sense_fingerprint": "相互搭配配合，形成完整的组合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58fcc8cb-7a7f-4d32-9843-a69e1fc8fe4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配套", "is_correct": true, "explanation": "“配套”指相互搭配、形成完整的组合，与“协同演进”的语境相符。"}, {"text": "独立", "is_correct": false, "explanation": "语义：“独立”指各自分开、不依赖他物，与“协同演进”的要求相反。"}, {"text": "孤立", "is_correct": false, "explanation": "语义：“孤立”指脱离联系、单独存在，与“协同演进”的语境相矛盾。"}, {"text": "陈旧", "is_correct": false, "explanation": "体貌：“陈旧”描写外观或状态老旧，与“更需”所要求的新型基础设施相反。"}], "explanations": {"配套": "“配套”指相互搭配、形成完整的组合，与“协同演进”的语境相符。", "独立": "语义：“独立”指各自分开、不依赖他物，与“协同演进”的要求相反。", "孤立": "语义：“孤立”指脱离联系、单独存在，与“协同演进”的语境相矛盾。", "陈旧": "体貌：“陈旧”描写外观或状态老旧，与“更需”所要求的新型基础设施相反。"}, "sentence_index": 0, "correct_answer": "配套"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做饭很配套，一个人就能做好全部的菜。", "explanation": "这里应该用〈熟练〉。“配套”强调相互搭配、成套，不用来形容做饭的技能。"}, {"text": "她很配套，什么话都敢直说。", "explanation": "这里应该用〈直率〉。“配套”强调相互搭配、成套，不用来形容人的性格。"}, {"text": "这篇文章写得很配套，读起来很顺。", "explanation": "这里应该用〈通顺〉。“配套”强调相互搭配、成套，不用来评价文章的表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配套", "is_correct": true, "explanation": "“配套”修饰“服务”，指与园区相配套的服务，与“越来越好”的语境相符。"}, {"text": "落后", "is_correct": false, "explanation": "语义：“落后”是负面评价，与“越来越好”的进步义相矛盾。"}, {"text": "拥挤", "is_correct": false, "explanation": "搭配：“拥挤”形容人多或空间狭窄，不用来修饰“服务”。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”描写场所没有人气，与园区服务越来越好的语义不符。"}], "explanations": {"配套": "“配套”修饰“服务”，指与园区相配套的服务，与“越来越好”的语境相符。", "落后": "语义：“落后”是负面评价，与“越来越好”的进步义相矛盾。", "拥挤": "搭配：“拥挤”形容人多或空间狭窄，不用来修饰“服务”。", "冷清": "语义：“冷清”描写场所没有人气，与园区服务越来越好的语义不符。"}, "sentence_index": 6, "correct_answer": "配套"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个游戏很配套，玩起来很有意思。", "explanation": "这里应该用〈有趣〉。“配套”强调相互搭配、成套，不用来形容游戏的趣味。"}, {"text": "他很配套，每天都按时完成工作。", "explanation": "这里应该用〈认真〉。“配套”强调相互搭配、成套，不用来形容人的做事态度。"}, {"text": "这篇论文很配套，条理很清楚。", "explanation": "这里应该用〈清晰〉。“配套”强调相互搭配、成套，不用来评价论文的条理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新建的商场和停车场是配套。", "corrected_sentence": "新建的商场和停车场是配套的。", "error_description": "错误：“是”字句中作表语的“配套”后须带“的”，应说“是配套的”，不说“是配套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些家具很很配套。", "corrected_sentence": "这些家具很配套。", "error_description": "重复错误：程度副词“很”多写了一次，应删去一个，说“这些家具很配套。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
