INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13019, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指国家或政党为实现一定目标而制定的行动准则和法律规范的总称。", "primary_collocate": null, "pronunciation": "zhèng cè fǎ guī", "ipa": "tʂɤŋ˥˩ tsʰɤ˥˩ fa˨˩˦ kweɪ˥", "syllable_count": 4, "sentences": [{"text": "真正的可持续性，不仅依赖材料本身的创新，更需配套的分类回收基础设施、政策法规与公众认知协同演进。", "target_word": "政策法规", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "新公司必须先了解当地的政策法规。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家出台了新的政策法规，保护环境。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师熟悉各种政策法规，能帮企业避免风险。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国企业进入中国市场，要遵守相关政策法规。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政策法规的变化会影响整个行业。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校组织学生学习食品安全方面的政策法规。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院严格按照政策法规管理药品。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着经济发展，政策法规也在不断完善。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究政策法规多年，是这方面的专家。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套政策法规", "label": "量词"}, {"form": "政策法規", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国家或政党制定的政策与法律规范的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499dcf25-efda-40b6-ac5d-8424935f606b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13019, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政策法规", "is_correct": true, "explanation": "正确：前后并列的是推动可持续发展的制度与社会条件，“政策法规”符合这一语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能与“基础设施”“公众认知”并列，作为协同演进的条件。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“协同演进”的对象应是制度和认知等，不能说“口味”与之协同演进。"}, {"text": "午餐", "is_correct": false, "explanation": "搭配：“协同演进”的对象应是制度和认知等，“午餐”不能作为促进可持续性的条件与之并列。"}], "explanations": {"政策法规": "正确：前后并列的是推动可持续发展的制度与社会条件，“政策法规”符合这一语境。", "天气": "语义：天气是自然现象，不能与“基础设施”“公众认知”并列，作为协同演进的条件。", "口味": "搭配：“协同演进”的对象应是制度和认知等，不能说“口味”与之协同演进。", "午餐": "搭配：“协同演进”的对象应是制度和认知等，“午餐”不能作为促进可持续性的条件与之并列。"}, "sentence_index": 0, "correct_answer": "政策法规"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这顿午饭的政策法规很好吃。", "explanation": "这里应该用〈口味〉。政策法规指法律规范，描述午饭好吃与否的应是口味，不能说政策法规。"}, {"text": "这部电影的政策法规很感人。", "explanation": "这里应该用〈剧情〉。政策法规指国家或政党制定的法律规范，电影的情节不能说政策法规。"}, {"text": "下棋的政策法规很简单，你一看就会。", "explanation": "这里应该用〈规则〉。政策法规指国家或政府制定的法律规范，游戏的规则不能说政策法规。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13019, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政策法规", "is_correct": true, "explanation": "正确：“食品安全方面的”后接的是可以学习的规范内容，“政策法规”符合语境。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是日常用品，不属于食品安全方面的学习内容，句意不通。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器与食品安全无关，不能作为学生学习的规范内容。"}, {"text": "季节", "is_correct": false, "explanation": "搭配：“食品安全方面的”后不能接“季节”这类时间概念作为学习对象。"}], "explanations": {"政策法规": "正确：“食品安全方面的”后接的是可以学习的规范内容，“政策法规”符合语境。", "手机": "语义：手机是日常用品，不属于食品安全方面的学习内容，句意不通。", "乐器": "语义：乐器与食品安全无关，不能作为学生学习的规范内容。", "季节": "搭配：“食品安全方面的”后不能接“季节”这类时间概念作为学习对象。"}, "sentence_index": 6, "correct_answer": "政策法规"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都按照政策法规跳舞。", "explanation": "这里应该用〈舞步〉。政策法规指法律规范，跳舞要依据的是舞步，不能说政策法规。"}, {"text": "他每天用政策法规复习英语。", "explanation": "这里应该用〈教科书〉。政策法规是法律规范，复习英语用的是教科书，不能说政策法规。"}, {"text": "他唱歌时忘了一句政策法规。", "explanation": "这里应该用〈歌词〉。政策法规指法律规范，唱歌时忘掉的是歌词，不能说政策法规。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要认真研究这只政策法规。", "corrected_sentence": "我们要认真研究这套政策法规。", "error_description": "量词错误：“政策法规”应与量词“套”搭配（一套政策法规），“只”用于动物或小件物品，不能用来计量政策法规。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校要求老师认真学习这块政策法规。", "corrected_sentence": "学校要求老师认真学习这套政策法规。", "error_description": "量词错误：“政策法规”应用“套”计量（一套政策法规），“块”用于成块的东西，不能用来计量政策法规。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
