INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13021, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "使命指被派遣去做的重要任务或应当承担的重大责任。", "primary_collocate": null, "pronunciation": "shǐ mìng", "ipa": "ʂɻ̩˨˩˦ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "医生的使命是救人。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他带着重要的使命来到这座城市。", "target_word": "使命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "完成这个使命并不容易。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的使命是让教育更公平。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老队长把保护大家的使命交给了他。", "target_word": "使命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得照顾老人是自己的使命。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者的使命是说出真实的情况。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这艘飞船肩负着探索火星的使命。", "target_word": "使命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了完成使命，一个月没回家。", "target_word": "使命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的使命就是保护这片森林。", "target_word": "使命", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个使命", "label": "量词"}, {"form": "历史使命", "label": "复合"}], "register": "书面", "sense_fingerprint": "被派去完成的重要任务或应承担的重大责任", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499dcf25-efda-40b6-ac5d-8424935f606b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13021, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "使命", "is_correct": true, "explanation": "正确：这是听到的目标词 shǐmìng。"}, {"text": "失明", "is_correct": false, "explanation": "shīmíng（第一声）与 shǐmìng 第一音节声调不同，意思是失去视力。"}, {"text": "实名", "is_correct": false, "explanation": "shímíng（第二声）与 shǐmìng 两个音节声调都不同，意思是用真实姓名。"}, {"text": "十名", "is_correct": false, "explanation": "shímíng（第二声）与 shǐmìng 两个音节声调都不同，意思是十个人。"}], "explanations": {"使命": "正确：这是听到的目标词 shǐmìng。", "失明": "shīmíng（第一声）与 shǐmìng 第一音节声调不同，意思是失去视力。", "实名": "shímíng（第二声）与 shǐmìng 两个音节声调都不同，意思是用真实姓名。", "十名": "shímíng（第二声）与 shǐmìng 两个音节声调都不同，意思是十个人。"}, "sentence_index": null, "correct_answer": "使命"}, "level_3": {"options": [{"text": "使命", "is_correct": true, "explanation": "正确：“医生的……是救人”说的是医生承担的重大责任，“使命”符合语境。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是劳动报酬，不是医生要承担的责任，“工资是救人”句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是职责或任务，不能说是医生要做的救人之事。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“医生的……是救人”的主语应是职责或任务，“午饭”不能这样搭配。"}], "explanations": {"使命": "正确：“医生的……是救人”说的是医生承担的重大责任，“使命”符合语境。", "工资": "语义：工资是劳动报酬，不是医生要承担的责任，“工资是救人”句意不通。", "颜色": "语义：颜色不是职责或任务，不能说是医生要做的救人之事。", "午饭": "搭配：“医生的……是救人”的主语应是职责或任务，“午饭”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "使命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个按钮的使命是关机。", "explanation": "这里应该用〈用途〉。使命指重大责任或被派遣的任务，按钮的用途不能说使命。"}, {"text": "今天的使命是打扫教室。", "explanation": "这里应该用〈任务〉。使命指重大责任，日常的小任务不能说使命。"}, {"text": "这台洗衣机的使命是把衣服洗干净。", "explanation": "这里应该用〈功能〉。使命指重大责任或被派遣的任务，洗衣机的功能不能说使命。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13021, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使命", "is_correct": true, "explanation": "正确：“记者的……是说出真实的情况”说的是职责，“使命”符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为记者要承担的职责。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是工具，不是记者应说出真实情况的职责内容。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“记者的……是说出真实的情况”的主语应是职责，“考试”不能这样搭配。"}], "explanations": {"使命": "正确：“记者的……是说出真实的情况”说的是职责，“使命”符合语境。", "天气": "语义：天气是自然现象，不能作为记者要承担的职责。", "手机": "语义：手机是工具，不是记者应说出真实情况的职责内容。", "考试": "搭配：“记者的……是说出真实的情况”的主语应是职责，“考试”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "使命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯果汁的使命是解渴。", "explanation": "这里应该用〈作用〉。使命指重大责任或被派遣的任务，饮料解渴的作用不能说使命。"}, {"text": "早睡是他的使命。", "explanation": "这里应该用〈习惯〉。使命指重大责任，日常习惯不能说使命。"}, {"text": "今天的使命是背课文。", "explanation": "这里应该用〈作业〉。使命指重大责任，日常的作业不能说使命。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13021, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他觉得这次任务是一座重大的使命。", "corrected_sentence": "他觉得这次任务是一个重大的使命。", "error_description": "量词错误：“使命”应用“个”计量（一个使命），“座”用于山、楼等大型固定物，不能计量使命。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13021, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他背负着一台使命。", "corrected_sentence": "他背负着一个使命。", "error_description": "量词错误：“使命”应用“个”计量（一个使命），“台”多用于机器、演出等，不能计量使命。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
