INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13022, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指物质（如有机物或岩石）经过地质或生物作用转变为矿物或无机物的过程。", "primary_collocate": null, "pronunciation": "kuàng huà", "ipa": "kʰwɑŋ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "未来的发展或将超越“降解”范式，迈向“闭环循环”的高阶目标：即聚合物在完成使用使命后，不仅能被微生物完全矿化，其降解产物还可作为新聚合反应的绿色原料，实现碳元素的无限循环。", "target_word": "矿化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "骨头埋在地下，慢慢矿化了。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些贝壳经过很多年才矿化。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水里的矿物会让木头慢慢矿化。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究树叶怎样矿化。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机物在土壤里会逐渐矿化。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木头已经完全矿化了。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "微生物能让塑料慢慢矿化。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骨头矿化需要很长时间。", "target_word": "矿化", "complexity_tier": "T3", "furigana": "kuàng huà", "sentence_source": "generated"}, {"text": "温度太低时，有机物很难矿化。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "矿化了", "label": "体标"}, {"form": "矿化过", "label": "体标"}], "register": "书面", "sense_fingerprint": "物质经地质或生物作用转变为矿物或无机物的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58fcc8cb-7a7f-4d32-9843-a69e1fc8fe4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "矿化", "is_correct": true, "explanation": "“矿化”指物质经微生物或地质作用转变为矿物，与句中“完全”和“降解产物”的语境相符。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体受热变为液体，微生物无法使聚合物融化。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”多指用火引燃，不说被微生物点燃。"}, {"text": "烧毁", "is_correct": false, "explanation": "搭配：“烧毁”需要火或高温作用，与“被微生物”的作用方式不符。"}], "explanations": {"矿化": "“矿化”指物质经微生物或地质作用转变为矿物，与句中“完全”和“降解产物”的语境相符。", "融化": "语义：“融化”指固体受热变为液体，微生物无法使聚合物融化。", "点燃": "搭配：“点燃”多指用火引燃，不说被微生物点燃。", "烧毁": "搭配：“烧毁”需要火或高温作用，与“被微生物”的作用方式不符。"}, "sentence_index": 0, "correct_answer": "矿化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "糖水放在阴凉处，慢慢矿化了。", "explanation": "这里应该用〈结晶〉。矿化指物质经地质或生物作用转变为矿物，糖水析出晶体只说结晶。"}, {"text": "食物在胃里慢慢矿化。", "explanation": "这里应该用〈消化〉。矿化指地质或生物作用下物质变为矿物，食物在体内的分解只说消化。"}, {"text": "这台旧机器已经矿化了。", "explanation": "这里应该用〈老化〉。矿化指物质转变为矿物，机器用久了变旧只说老化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "矿化", "is_correct": true, "explanation": "“矿化”指木头转变为矿物，与“完全……了”的语境相符。"}, {"text": "挥发", "is_correct": false, "explanation": "搭配：“挥发”多指液体或香气散失，不用来形容木头。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：“凝固”指液体变为固体，与木头的状态不符。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”指因低温而凝固，木头不会因此变成这种状态。"}], "explanations": {"矿化": "“矿化”指木头转变为矿物，与“完全……了”的语境相符。", "挥发": "搭配：“挥发”多指液体或香气散失，不用来形容木头。", "凝固": "语义：“凝固”指液体变为固体，与木头的状态不符。", "冻结": "语义：“冻结”指因低温而凝固，木头不会因此变成这种状态。"}, "sentence_index": 6, "correct_answer": "矿化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "木柴在火里矿化了。", "explanation": "这里应该用〈燃烧〉。矿化是缓慢的地质或生物转变，不指遇火发光发热的燃烧。"}, {"text": "面团在温暖的地方矿化了。", "explanation": "这里应该用〈发酵〉。矿化指物质转变为矿物，面团变大变酸只说发酵。"}, {"text": "这块冰在屋里慢慢矿化了。", "explanation": "这里应该用〈融化〉。矿化指经地质或生物作用转变为矿物或无机物，冰受热变水只说融化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些木头在湖底矿化得慢很。", "corrected_sentence": "这些木头在湖底矿化得很慢。", "error_description": "错误：程度副词“很”应放在补语形容词“慢”之前，应说“矿化得很慢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些化石在地下矿化了过。", "corrected_sentence": "这些化石在地下矿化过。", "error_description": "体标错误：“了”与“过”不能同用，表示经历只用“过”，应说“矿化过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
