INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13023, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指由单体分子通过化学键结合成高分子化合物的反应。", "primary_collocate": null, "pronunciation": "jù hé fǎn yìng", "ipa": "tɕy˥˩ xɤ˧˥ fan˨˩˦ iŋ˥˩", "syllable_count": 4, "sentences": [{"text": "未来的发展或将超越“降解”范式，迈向“闭环循环”的高阶目标：即聚合物在完成使用使命后，不仅能被微生物完全矿化，其降解产物还可作为新聚合反应的绿色原料，实现碳元素的无限循环。", "target_word": "聚合反应", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "聚合反应能把小分子变成大分子。", "target_word": "聚合反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料是通过聚合反应做成的。", "target_word": "聚合反应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个实验里的聚合反应很快就结束了。", "target_word": "聚合反应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在课上讲了聚合反应的条件。", "target_word": "聚合反应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温度太高时，聚合反应会变得很难控制。", "target_word": "聚合反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用聚合反应生产新的塑料。", "target_word": "聚合反应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "聚合反应需要加入催化剂。", "target_word": "聚合反应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学过聚合反应，知道它能生成高分子。", "target_word": "聚合反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里正在进行一次聚合反应。", "target_word": "聚合反应", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种聚合反应", "label": "量词"}, {"form": "聚合反應", "label": "繁体"}], "register": "书面", "sense_fingerprint": "单体分子结合成高分子化合物的化学反应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f995feb-01f2-46a0-bd0f-015ea5999b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13023, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聚合反应", "is_correct": true, "explanation": "正确：“聚合反应”指单体结合成高分子的反应，与“作为新……的绿色原料”的语境相符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”不是化学反应，不能用来修饰“绿色原料”。"}, {"text": "微生物", "is_correct": false, "explanation": "语义：微生物是生物，不是化学过程，与“降解产物可作原料”的意思不合。"}, {"text": "废弃物", "is_correct": false, "explanation": "搭配：“废弃物”指被丢掉的东西，不能说“作为新废弃物的绿色原料”。"}], "explanations": {"聚合反应": "正确：“聚合反应”指单体结合成高分子的反应，与“作为新……的绿色原料”的语境相符。", "温度": "语义：“温度”不是化学反应，不能用来修饰“绿色原料”。", "微生物": "语义：微生物是生物，不是化学过程，与“降解产物可作原料”的意思不合。", "废弃物": "搭配：“废弃物”指被丢掉的东西，不能说“作为新废弃物的绿色原料”。"}, "sentence_index": 0, "correct_answer": "聚合反应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块铁是用多步聚合反应炼出来的。", "explanation": "这里应该用〈冶炼〉。铁是金属，靠冶炼得到，不是小分子连成大分子。"}, {"text": "水在通电的时候会发生聚合反应。", "explanation": "这里应该用〈分解反应〉。水通电分解成氢气和氧气，是分解反应；聚合反应是小分子连成大分子。"}, {"text": "蜡烛点着后会发生聚合反应。", "explanation": "这里应该用〈燃烧反应〉。蜡烛燃烧是与氧气作用、放出热量，不是小分子连成大分子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13023, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聚合反应", "is_correct": true, "explanation": "正确：“用聚合反应生产”指借助该反应制造塑料，语境相符。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：“微笑”是表情，不能用来生产塑料。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不能用来生产塑料。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是生产手段，不能用来生产塑料。"}], "explanations": {"聚合反应": "正确：“用聚合反应生产”指借助该反应制造塑料，语境相符。", "微笑": "语义：“微笑”是表情，不能用来生产塑料。", "歌曲": "语义：“歌曲”不能用来生产塑料。", "颜色": "语义：“颜色”不是生产手段，不能用来生产塑料。"}, "sentence_index": 6, "correct_answer": "聚合反应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "酸和碱混合后会发生聚合反应。", "explanation": "这里应该用〈中和反应〉。酸和碱作用生成盐和水，不是小分子连成大分子。"}, {"text": "他对这个消息的聚合反应很快。", "explanation": "这里应该用〈回应〉。聚合反应专指高分子的化学过程，不能用来指人对消息的应对。"}, {"text": "铁在潮湿的空气里会发生聚合反应。", "explanation": "这里应该用〈氧化反应〉。铁生锈是与氧气结合，不是小分子连成高分子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂里的一只聚合反应需要三个小时。", "corrected_sentence": "工厂里的一次聚合反应需要三个小时。", "error_description": "“聚合反应”的量词应用“次”，不用“只”。“只”用于动物或单个器物，不能修饰化学过程；应改为“一次聚合反应”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种塑料聚合反应中会变得很硬。", "corrected_sentence": "这种塑料在聚合反应中会变得很硬。", "error_description": "“聚合反应”表示过程发生的范围，前面要加介词“在”，说“在……中”；去掉“在”，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
