INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13025, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抛弃不用，不再使用或保留。", "primary_collocate": null, "pronunciation": "fèi qì", "ipa": "fei˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "这标志着材料科学正从“制造-废弃”线性模式，转向与自然代谢系统深度融合的生态文明范式。", "target_word": "废弃", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座工厂已经废弃很多年了。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把旧电脑废弃了，买了新的。", "target_word": "废弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府废弃了这条旧铁路。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里废弃的房子没有人住。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旧塑料不能随便废弃，要回收。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司决定废弃这个旧办法。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "废弃的瓶子可以做成花盆。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个计划太难做，我们只好废弃。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他废弃了原来的想法，重新开始。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "废弃了", "label": "体标"}, {"form": "废弃物", "label": "复合"}, {"form": "廢棄", "label": "繁体"}], "register": "书面", "sense_fingerprint": "抛弃不用，不再使用或保留", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f995feb-01f2-46a0-bd0f-015ea5999b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13025, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废弃", "is_correct": true, "explanation": "正确：“制造-废弃”指产品用完即丢的线性模式，与句意相符。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：“冷冻”不是产品生命周期中的末端环节，“制造-冷冻”说不通。"}, {"text": "设计", "is_correct": false, "explanation": "搭配：“制造-设计”不能构成线性模式的末端阶段，与“制造”并列不成链条。"}, {"text": "挥发", "is_correct": false, "explanation": "语义：“挥发”指液体变为气体，不能作为生命周期的一个阶段。"}], "explanations": {"废弃": "正确：“制造-废弃”指产品用完即丢的线性模式，与句意相符。", "冷冻": "语义：“冷冻”不是产品生命周期中的末端环节，“制造-冷冻”说不通。", "设计": "搭配：“制造-设计”不能构成线性模式的末端阶段，与“制造”并列不成链条。", "挥发": "语义：“挥发”指液体变为气体，不能作为生命周期的一个阶段。"}, "sentence_index": 0, "correct_answer": "废弃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他废弃了年迈的父母，独自搬走了。", "explanation": "这里应该用〈抛弃〉。废弃多用于物品、设施、计划；说人要用〈抛弃〉。"}, {"text": "这台每天都要用的机器，他已经废弃了。", "explanation": "这里应该用〈停用〉。废弃是永久不要了，与“每天都要用”矛盾；暂时不用才说停用。"}, {"text": "他废弃了一张珍贵的老照片，还想留作纪念。", "explanation": "这里应该用〈保存〉。废弃是不要了，与“留作纪念”矛盾；想留下的东西应说保存。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13025, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废弃", "is_correct": true, "explanation": "正确：“决定废弃这个旧办法”指不再使用旧办法，语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”一般不接“办法”，不能说“吃这个办法”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”通常接歌曲、戏曲，不接“办法”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热食物，不能用来处理“办法”。"}], "explanations": {"废弃": "正确：“决定废弃这个旧办法”指不再使用旧办法，语境相符。", "吃": "搭配：“吃”一般不接“办法”，不能说“吃这个办法”。", "唱": "搭配：“唱”通常接歌曲、戏曲，不接“办法”。", "煮": "语义：“煮”指用水加热食物，不能用来处理“办法”。"}, "sentence_index": 6, "correct_answer": "废弃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师废弃了班里最认真的学生。", "explanation": "“废弃”用于物品、设施、计划，不能用于人；说人要用〈抛弃〉。"}, {"text": "这台电脑刚买，他每天都在用，却废弃了它。", "explanation": "这里应该用〈停用〉。废弃指永久不要了，与“每天都在用”矛盾；暂时不用才说停用。"}, {"text": "这个问题我们正在研究，所以已经废弃了。", "explanation": "这里应该用〈搁置〉。废弃指不要了，与“正在研究”矛盾；暂时放下不管的事应说搁置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器早就废弃用了。", "corrected_sentence": "这台机器早就废弃不用了。", "error_description": "“废弃”后要说“废弃不用”，缺少“不”；“废弃用了”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座房子已经很废弃了。", "corrected_sentence": "这座房子已经废弃了。", "error_description": "“废弃”是动词，不能被程度副词“很”修饰；应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
