INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13026, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指人或动物体内起支撑和保护作用的坚硬组织。", "primary_collocate": null, "pronunciation": "gǔ tou", "ipa": "ku˨˩˦ tʰou", "syllable_count": 2, "sentences": [{"text": "小狗在啃一根骨头。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摔了一跤，骨头断了。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的骨头没有问题。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的骨头常常会疼。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把骨头拿给小狗吃。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多喝牛奶对骨头好。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤里有肉，也有骨头。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块骨头是狗从院子里找来的。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骨头里面有很多钙。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手受伤了，医生要看看骨头。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一根骨头", "label": "量词"}, {"form": "一块骨头", "label": "量词"}, {"form": "鱼骨头", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或动物体内起支撑保护作用的坚硬组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd70a85e3-8683-4acb-9c19-ccb5efd1bd2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13026, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "骨头", "is_correct": true, "explanation": "正确答案：骨头（gǔ tou），指人或动物体内的坚硬组织。"}, {"text": "苦头", "is_correct": false, "explanation": "苦头（kǔ tou）与骨头（gǔ tou）只有声母不同：k 送气，g 不送气，声调相同，意思是吃苦头、受苦。"}, {"text": "部头", "is_correct": false, "explanation": "部头（bù tou）与骨头第一音节声母 b 与 g 不同，声调为第四声，意思是书籍的篇幅或体量。"}, {"text": "裤头", "is_correct": false, "explanation": "裤头（kù tou）与骨头第一音节声母 k 与 g 不同，声调为第四声，意思是短裤或内裤。"}], "explanations": {"骨头": "正确答案：骨头（gǔ tou），指人或动物体内的坚硬组织。", "苦头": "苦头（kǔ tou）与骨头（gǔ tou）只有声母不同：k 送气，g 不送气，声调相同，意思是吃苦头、受苦。", "部头": "部头（bù tou）与骨头第一音节声母 b 与 g 不同，声调为第四声，意思是书籍的篇幅或体量。", "裤头": "裤头（kù tou）与骨头第一音节声母 k 与 g 不同，声调为第四声，意思是短裤或内裤。"}, "sentence_index": null, "correct_answer": "骨头"}, "level_3": {"options": [{"text": "骨头", "is_correct": true, "explanation": "正确：“一根骨头”形状细长，小狗可以啃它。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：“一根”用于细长之物，石头多为块状，应说“一块石头”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法被啃，与“啃”的对象不合。"}, {"text": "苹果", "is_correct": false, "explanation": "搭配：苹果以“个”计量，不说“一根苹果”，与量词搭配不合。"}], "explanations": {"骨头": "正确：“一根骨头”形状细长，小狗可以啃它。", "石头": "体貌：“一根”用于细长之物，石头多为块状，应说“一块石头”。", "空气": "语义：空气无法被啃，与“啃”的对象不合。", "苹果": "搭配：苹果以“个”计量，不说“一根苹果”，与量词搭配不合。"}, "sentence_index": 0, "correct_answer": "骨头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥的骨头很坚固。", "explanation": "这里应该用〈骨架〉。骨头指人或动物体内的骨，桥梁的框架要说“骨架”。"}, {"text": "这个苹果的骨头很甜。", "explanation": "这里应该用〈果核〉。骨头指动物体内的骨，果实中间的硬核要说“果核”。"}, {"text": "我买了一本骨头。", "explanation": "这里应该用〈根〉或〈块〉。骨头是长条或块状，“本”用于书籍，不用于骨头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骨头", "is_correct": true, "explanation": "正确：骨头是汤里常见的食材，与前面的“肉”并列。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能煮进汤里，与“汤里有”的食材不合。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝是金属零件，不是食物，不能放进汤里。"}, {"text": "尸体", "is_correct": false, "explanation": "语域：“尸体”语气骇人，与日常饮食的语境不合。"}], "explanations": {"骨头": "正确：骨头是汤里常见的食材，与前面的“肉”并列。", "玻璃": "语义：玻璃不能煮进汤里，与“汤里有”的食材不合。", "螺丝": "语义：螺丝是金属零件，不是食物，不能放进汤里。", "尸体": "语域：“尸体”语气骇人，与日常饮食的语境不合。"}, "sentence_index": 6, "correct_answer": "骨头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是公司的骨头，负责最重要的项目。", "explanation": "这里应该用〈骨干〉。骨头指人或动物体内的骨，公司里的核心成员要说“骨干”。"}, {"text": "这座大楼的骨头是钢铁做的。", "explanation": "这里应该用〈框架〉。骨头只指生物体内的骨，建筑的结构要说“框架”。"}, {"text": "我买了一只骨头。", "explanation": "这里应该用〈根〉或〈块〉。骨头是长条或块状，“只”不用于骨头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在厨房里切了一只骨头。", "corrected_sentence": "他在厨房里切了一块骨头。", "error_description": "错误：“一只骨头”，正确：“一块骨头”。“只”不用于骨头，骨头应用“根”或“块”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈熬汤时放了一个骨头。", "corrected_sentence": "妈妈熬汤时放了一块骨头。", "error_description": "错误：“一个骨头”，正确：“一块骨头”。“个”不用于骨头，骨头应用“根”或“块”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
