INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13027, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示在某物上增加少量。", "primary_collocate": null, "pronunciation": "jiā yì diǎn", "ipa": "tɕja˥ i˥˩ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "汤太淡了，请再加一点盐。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶有点苦，你加一点糖吧。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜不够辣，我想加一点辣椒。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水太少了，再加一点。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包太干，我想加一点牛奶。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡太苦，请给我加一点奶。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炒菜的时候，加一点油就行。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "颜色太浅，再加一点红色。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤不够热，加一点热水吧。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米饭太硬，加一点水再煮。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加一点点", "label": "重叠"}, {"form": "加点儿", "label": "口语"}], "register": "口语", "sense_fingerprint": "在某物上增加少量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd70a85e3-8683-4acb-9c19-ccb5efd1bd2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13027, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加一点", "is_correct": true, "explanation": "正确：汤太淡，应在汤里加少量盐，符合语境。"}, {"text": "减一点", "is_correct": false, "explanation": "语义：汤太淡应加盐，减盐与“太淡”的语境相反。"}, {"text": "喝一点", "is_correct": false, "explanation": "配价：“喝”的宾语应为饮品，盐是固体调料，不能说喝盐。"}, {"text": "洗一点", "is_correct": false, "explanation": "搭配：盐不用“洗”，“洗”与盐搭配不当。"}], "explanations": {"加一点": "正确：汤太淡，应在汤里加少量盐，符合语境。", "减一点": "语义：汤太淡应加盐，减盐与“太淡”的语境相反。", "喝一点": "配价：“喝”的宾语应为饮品，盐是固体调料，不能说喝盐。", "洗一点": "搭配：盐不用“洗”，“洗”与盐搭配不当。"}, "sentence_index": 0, "correct_answer": "加一点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想加一点这次比赛。", "explanation": "这里应该用〈参加〉。加一点指在某物上增加少量，参加比赛要说“参加”。"}, {"text": "我想加一点这份合同。", "explanation": "这里应该用〈签〉。加一点指增添少量，签合同要说“签”。"}, {"text": "你别给我加一点乱。", "explanation": "这里应该用〈添〉。“加一点”指增添具体的东西，“加一点乱”说不通，固定说法是“添乱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加一点", "is_correct": true, "explanation": "正确：炒菜时加少量油，是常见做法。"}, {"text": "吃一点", "is_correct": false, "explanation": "配价：“吃”的宾语应为食物，炒菜时说的是放油，不说吃油。"}, {"text": "剪一点", "is_correct": false, "explanation": "语义：油是液体，不能“剪”，与炒菜的语境不合。"}, {"text": "摘一点", "is_correct": false, "explanation": "搭配：油不能“摘”，“摘”与油搭配不当。"}], "explanations": {"加一点": "正确：炒菜时加少量油，是常见做法。", "吃一点": "配价：“吃”的宾语应为食物，炒菜时说的是放油，不说吃油。", "剪一点": "语义：油是液体，不能“剪”，与炒菜的语境不合。", "摘一点": "搭配：油不能“摘”，“摘”与油搭配不当。"}, "sentence_index": 6, "correct_answer": "加一点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想加一点感冒。", "explanation": "这里应该用〈得〉。加一点指增添少量，患病要说“得”。"}, {"text": "他加一点篮球队。", "explanation": "这里应该用〈加入〉。加一点指给某物增加少量，不能用来指加入团队。"}, {"text": "她在比赛中加一点冠军。", "explanation": "这里应该用〈赢得〉。加一点不能用来指获得荣誉，应说“赢得冠军”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汤有点淡，我刚加一点盐。", "corrected_sentence": "汤有点淡，我刚加了一点盐。", "error_description": "错误：“刚加一点盐”，正确：“刚加了一点盐”。表示动作已完成，动词“加”后应加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面有点干，我加了一点了水。", "corrected_sentence": "面有点干，我加了一点水。", "error_description": "错误：“加了一点了水”，多出一个“了”。正确：“加了一点水”，“了”只需出现一次，紧跟动词“加”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
