INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13029, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指栽种和照料花草，让它们生长、开花的过程。", "primary_collocate": null, "pronunciation": "yǎng huā", "ipa": "jɑŋ˨˩ xuɑ˥", "syllable_count": 2, "sentences": [{"text": "可以用来养花和种菜。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我奶奶很喜欢养花。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳台不大，也可以养花。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他退休以后开始养花了。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养花要常常浇水，也要多晒太阳。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太会养花，好几盆花都死了。", "target_word": "养花", "complexity_tier": "T3", "furigana": "wǒ bú tài huì yǎnghuā, hǎo jǐ pén huā dōu sǐ le.", "sentence_source": "generated"}, {"text": "养花要有耐心，花才会开。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸爱养花，每天早上都浇水。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学养花，请你教教我。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养花让妈妈的生活更有意思。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "养了花", "label": "体标"}, {"form": "养过花", "label": "体标"}], "register": "中性", "sense_fingerprint": "栽种并照料花草使其生长开花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8dcf6e-820e-41d6-966b-7b4656bddf4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13029, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "养花", "is_correct": true, "explanation": "正确：养花指栽种和照料花草，使其生长、开花。"}, {"text": "氧化", "is_correct": false, "explanation": "氧化（yǎnghuà）与养花（yǎnghuā）只有第二个音节声调不同（第四声与第一声），意思是物质与氧结合。"}, {"text": "眼花", "is_correct": false, "explanation": "眼花（yǎnhuā）与养花（yǎnghuā）第一个音节韵尾不同（an 与 ang），意思是视物模糊。"}, {"text": "养活", "is_correct": false, "explanation": "养活（yǎnghuó）与养花（yǎnghuā）第二个音节声调不同（第二声与第一声），意思是供养、维持生计。"}, {"text": "赏花", "is_correct": false, "explanation": "赏花（shǎnghuā）与养花（yǎnghuā）第一个音节声母不同（sh 与零声母），意思是观赏花开。"}], "explanations": {"养花": "正确：养花指栽种和照料花草，使其生长、开花。", "氧化": "氧化（yǎnghuà）与养花（yǎnghuā）只有第二个音节声调不同（第四声与第一声），意思是物质与氧结合。", "眼花": "眼花（yǎnhuā）与养花（yǎnghuā）第一个音节韵尾不同（an 与 ang），意思是视物模糊。", "养活": "养活（yǎnghuó）与养花（yǎnghuā）第二个音节声调不同（第二声与第一声），意思是供养、维持生计。", "赏花": "赏花（shǎnghuā）与养花（yǎnghuā）第一个音节声母不同（sh 与零声母），意思是观赏花开。"}, "sentence_index": null, "correct_answer": "养花"}, "level_3": {"options": [{"text": "养花", "is_correct": true, "explanation": "正确：“养花”与后面的“种菜”并列，都指家里的园艺活动，符合“可以用来”的语境。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是身体状况，不是可以用来做的活动，与“可以用来……和种菜”不合。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”需要宾语，“可以用来吃”之后缺少宾语，与“种菜”并列后句子不完整。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“失眠”是睡不着的状态，不能用来做事，与“可以用来”的语境冲突。"}], "explanations": {"养花": "正确：“养花”与后面的“种菜”并列，都指家里的园艺活动，符合“可以用来”的语境。", "发烧": "语义：“发烧”是身体状况，不是可以用来做的活动，与“可以用来……和种菜”不合。", "吃": "配价：“吃”需要宾语，“可以用来吃”之后缺少宾语，与“种菜”并列后句子不完整。", "失眠": "语义：“失眠”是睡不着的状态，不能用来做事，与“可以用来”的语境冲突。"}, "sentence_index": 0, "correct_answer": "养花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天到了，大家都去公园养花，看看开得正好的桃花。", "explanation": "这里应该用〈赏花〉。养花指栽种和照料花草，去公园看开花应说赏花。"}, {"text": "孩子们去山坡上养花，采了一大把野花回家。", "explanation": "这里应该用〈采花〉。养花要长期栽种照料，摘取山上的野花应说采花。"}, {"text": "情人节那天，他给我养花当礼物。", "explanation": "这里应该用〈送花〉。养花是栽培的过程，不能当作礼物送人；赠送花束应说送花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "养花", "is_correct": true, "explanation": "正确：“养花要有耐心，花才会开”说的是栽种照料花草的过程，与“花才会开”的因果一致。"}, {"text": "打游戏", "is_correct": false, "explanation": "语义：“打游戏”与“花才会开”没有因果关系，花开不是玩游戏的结果。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭要有耐心，花才会开”没有合理关联，“花才会开”的前提必须是植物的栽培。"}, {"text": "修身", "is_correct": false, "explanation": "语域：“修身”是偏书面的修养说法，与这里具体说花开的口语语境不协调。"}], "explanations": {"养花": "正确：“养花要有耐心，花才会开”说的是栽种照料花草的过程，与“花才会开”的因果一致。", "打游戏": "语义：“打游戏”与“花才会开”没有因果关系，花开不是玩游戏的结果。", "吃饭": "语义：“吃饭要有耐心，花才会开”没有合理关联，“花才会开”的前提必须是植物的栽培。", "修身": "语域：“修身”是偏书面的修养说法，与这里具体说花开的口语语境不协调。"}, "sentence_index": 6, "correct_answer": "养花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我去超市养花，把买来的花一枝一枝地插进花瓶里。", "explanation": "这里应该用〈插花〉。养花指栽培，超市不是栽培花草的地方；把买来的花插进花瓶应说插花。"}, {"text": "情人节前，他去花店养花，准备送给妻子。", "explanation": "这里应该用〈买花〉。养花是栽培的过程，在花店挑选现成的花应说买花。"}, {"text": "她喜欢养花的香味，每次经过花园都会停下来。", "explanation": "这里应该用〈闻〉。养花指栽培，不指香气；闻花的香味才是对的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她退休以后养花过，每天很开心。", "corrected_sentence": "她退休以后养过花，每天很开心。", "error_description": "体标错误：经历体“过”应紧跟动词，应说“养过花”，不能说“养花过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想学怎么了养花，请你教我。", "corrected_sentence": "我想学怎么养花，请你教我。", "error_description": "多余的「了」：疑问词「怎么」作状语修饰「养花」，二者之间不能插入「了」，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
