INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13031, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指每一个人；所有的人。", "primary_collocate": null, "pronunciation": "rén rén", "ipa": "ʐən˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "保护地球，人人可以帮忙。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "在我们班，人人都喜欢这位老师。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，人人都很紧张。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律面前人人平等。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好消息，人人都想知道。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人人都有自己的小秘密。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过节的时候，人人脸上都有笑容。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里很干净，因为人人都爱护环境。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很友好，所以人人都愿意和他做朋友。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的饭菜很好吃，人人都说好。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每一个人，不漏掉任何人，常与“都”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8dcf6e-820e-41d6-966b-7b4656bddf4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13031, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人人", "is_correct": true, "explanation": "正确：“人人”泛指每一个人，与“保护地球”的号召语境相符，“人人可以帮忙”。"}, {"text": "他", "is_correct": false, "explanation": "语义：“他”指某一个人，与“保护地球”这类面向所有人的号召不合。"}, {"text": "对方", "is_correct": false, "explanation": "语义：“对方”指与己方相对的另一方，与“保护地球”的全体语境无关。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能参与保护地球的行动，“石头可以帮忙”不通。"}], "explanations": {"人人": "正确：“人人”泛指每一个人，与“保护地球”的号召语境相符，“人人可以帮忙”。", "他": "语义：“他”指某一个人，与“保护地球”这类面向所有人的号召不合。", "对方": "语义：“对方”指与己方相对的另一方，与“保护地球”的全体语境无关。", "石头": "语义：石头不能参与保护地球的行动，“石头可以帮忙”不通。"}, "sentence_index": 0, "correct_answer": "人人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试，人人都答对了，只有少数同学答错了。", "explanation": "这里应该用〈大多数〉。“人人”指全体，没有例外；只有少数人答错应说大多数。"}, {"text": "这是我人人的爱好，别人不必干涉。", "explanation": "这里应该用〈个人〉。“个人”修饰自己的事情，“人人”指全体，不能说“我人人的爱好”。"}, {"text": "我们是人人的军队，永远为大家服务。", "explanation": "这里应该用〈人民〉。“人人”指每个人，不指国家的全体人民；“人民的军队”是固定说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13031, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人人", "is_correct": true, "explanation": "正确：“过节的时候，人人脸上都有笑容”，“人人”指全体，与“都”搭配，符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有脸，不能说脸上有笑容。"}, {"text": "某人", "is_correct": false, "explanation": "语义：“某人”指不确定的一个人，与“过节的时候”描述大家的状态不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有脸，不能说脸上有笑容。"}], "explanations": {"人人": "正确：“过节的时候，人人脸上都有笑容”，“人人”指全体，与“都”搭配，符合语境。", "桌子": "语义：桌子没有脸，不能说脸上有笑容。", "某人": "语义：“某人”指不确定的一个人，与“过节的时候”描述大家的状态不合。", "石头": "语义：石头没有脸，不能说脸上有笑容。"}, "sentence_index": 6, "correct_answer": "人人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的饭菜很好吃，人人中有一半说好，一半说不好。", "explanation": "这里应该用〈有些人〉。“人人”指全体，没有例外；只有一半人说好应说有些人。"}, {"text": "公司正在招聘，希望找到很多人人。", "explanation": "这里应该用〈人才〉。“人人”指每一个人，不指有能力的人；招聘应说人才。"}, {"text": "这家店的饭菜很好吃，这条街的人人有很多。", "explanation": "这里应该用〈人口〉。“人人”指每个人，不表示总人数；一条街的总人数应说人口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13031, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛，一人人都想拿第一。", "corrected_sentence": "这次比赛，人人都想拿第一。", "error_description": "错误形式：“一人人”。正确形式：“人人”。“人人”是代词，不能与数量词“一”组合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13031, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "节日到了，人人们都换上了新衣服。", "corrected_sentence": "节日到了，人人都换上了新衣服。", "error_description": "错误形式：“人人们”。正确形式：“人人”。“人人”已表示全体，后面不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
