INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13032, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13032, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指吃完后余留的部分或食物残渣。", "primary_collocate": null, "pronunciation": "chī shèng", "ipa": "ʈʂʰɻ̩˥ ʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "吃剩的菜、水果皮、茶叶渣都可以用。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他把吃剩的饭菜放进了冰箱。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃剩的骨头不要给小狗吃。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有很多吃剩的东西。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用吃剩的米饭做了炒饭。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃剩的面包已经变硬了。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把吃剩的水果放在盘子里。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员收走了我们吃剩的菜。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃剩的鱼骨头别扔在地上。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫在院子里找人们吃剩的食物。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吃剩了", "label": "体标"}], "register": "中性", "sense_fingerprint": "吃完后留下的食物或残渣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7bcf024-40e1-464a-b19b-d6126447d7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13032, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃剩", "is_correct": true, "explanation": "吃剩：吃完后余留的部分，修饰“菜、水果皮、茶叶渣”，指可以再用的剩余食物。"}, {"text": "腐烂", "is_correct": false, "explanation": "语义：“腐烂”的东西已经坏了，与“都可以用”矛盾。"}, {"text": "变质", "is_correct": false, "explanation": "语义：“变质”的东西已经坏了，不能再用，与“都可以用”矛盾。"}, {"text": "发霉", "is_correct": false, "explanation": "语义：发霉的食物不能再用，与“都可以用”不符。"}], "explanations": {"吃剩": "吃剩：吃完后余留的部分，修饰“菜、水果皮、茶叶渣”，指可以再用的剩余食物。", "腐烂": "语义：“腐烂”的东西已经坏了，与“都可以用”矛盾。", "变质": "语义：“变质”的东西已经坏了，不能再用，与“都可以用”矛盾。", "发霉": "语义：发霉的食物不能再用，与“都可以用”不符。"}, "sentence_index": 0, "correct_answer": "吃剩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把碗里的饭都吃剩了。", "explanation": "这里应该用〈吃完〉。吃剩指吃完后留下的部分，说“都吃剩了”等于没有剩余，应说“吃完”。"}, {"text": "我们吃剩了很多时间。", "explanation": "这里应该用〈浪费〉。吃剩只用于饭菜等食物，时间不能“吃剩”，应说“浪费时间”。"}, {"text": "衣柜里吃剩了一件旧衣服。", "explanation": "这里应该用〈剩下〉。吃剩指吃过后留下的食物，衣服没有被吃过，应说“剩下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃剩", "is_correct": true, "explanation": "吃剩：吃完后剩下的，修饰“水果”，指剩下的、可以放进盘子的水果。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：“扔掉”的东西已被丢弃，不能再“放在盘子里”。"}, {"text": "用掉", "is_correct": false, "explanation": "搭配：“用”多指用材料、钱物，不说“用掉水果”。"}, {"text": "踩烂", "is_correct": false, "explanation": "语义：被踩烂的水果已不成形，无法整齐地放进盘子。"}], "explanations": {"吃剩": "吃剩：吃完后剩下的，修饰“水果”，指剩下的、可以放进盘子的水果。", "扔掉": "语义：“扔掉”的东西已被丢弃，不能再“放在盘子里”。", "用掉": "搭配：“用”多指用材料、钱物，不说“用掉水果”。", "踩烂": "语义：被踩烂的水果已不成形，无法整齐地放进盘子。"}, "sentence_index": 6, "correct_answer": "吃剩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块地里吃剩了很多化学品。", "explanation": "这里应该用〈残留〉。化学品残留在地里，吃剩只用于被吃过的食物。"}, {"text": "我昨天吃剩了一部电影。", "explanation": "这里应该用〈看完〉。电影是看的，不是吃的，吃剩只用于食物。"}, {"text": "他终于吃剩了作业。", "explanation": "这里应该用〈做完〉。作业要做完，不能“吃剩”，吃剩只用于食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把吃剩粥热了一下。", "corrected_sentence": "妈妈把吃剩的粥热了一下。", "error_description": "错误：“吃剩粥”。“吃剩”修饰名词“粥”时，中间要加“的”，应说“吃剩的粥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹把吃剩地蛋糕藏起来了。", "corrected_sentence": "我妹妹把吃剩的蛋糕藏起来了。", "error_description": "“吃剩”修饰“蛋糕”，后面要用“的”，不能用“地”（“地”用于修饰动词或形容词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
