INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13033, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13033, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水果皮是包裹在水果果肉外面的外层部分，通常可以剥去或直接食用。", "primary_collocate": null, "pronunciation": "shuǐ guǒ pí", "ipa": "ʂweɪ˨˩˦ kwo˨˩˦ pʰi˧˥", "syllable_count": 3, "sentences": [{"text": "吃剩的菜、水果皮、茶叶渣都可以用。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "请把水果皮扔进垃圾桶。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果皮很薄，可以直接吃。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一块水果皮，小心滑倒。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说水果皮可以当肥料。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我吃完橙子，把水果皮放在桌上。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果皮里有很多维生素。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不爱吃水果皮，只吃果肉。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的水果皮有点臭了。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗干净的水果皮可以煮水喝。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块水果皮", "label": "量词"}, {"form": "一片水果皮", "label": "量词"}], "register": "中性", "sense_fingerprint": "水果果肉外面的一层皮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7bcf024-40e1-464a-b19b-d6126447d7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13033, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水果皮", "is_correct": true, "explanation": "水果皮：水果外层的皮，可以用，与“菜、茶叶渣”同类。"}, {"text": "废电池", "is_correct": false, "explanation": "语义：废电池有毒，不能说“都可以用”。"}, {"text": "玻璃碎片", "is_correct": false, "explanation": "语义：玻璃碎片有割伤危险，与“都可以用”不符。"}, {"text": "纸尿裤", "is_correct": false, "explanation": "搭配：“纸尿裤”与“菜”“茶叶渣”不同类，不能并列为“都可以用”的东西。"}], "explanations": {"水果皮": "水果皮：水果外层的皮，可以用，与“菜、茶叶渣”同类。", "废电池": "语义：废电池有毒，不能说“都可以用”。", "玻璃碎片": "语义：玻璃碎片有割伤危险，与“都可以用”不符。", "纸尿裤": "搭配：“纸尿裤”与“菜”“茶叶渣”不同类，不能并列为“都可以用”的东西。"}, "sentence_index": 0, "correct_answer": "水果皮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜的水果皮是红色的，又甜又多汁。", "explanation": "这里应该用〈果肉〉。红色、又甜又多汁说的是西瓜的果肉，水果皮是外层的皮。"}, {"text": "我每天早上喝水果皮。", "explanation": "这里应该用〈果汁〉。喝的是液体，水果皮不能喝，应说“果汁”。"}, {"text": "他摸着树干，感觉水果皮很粗糙。", "explanation": "这里应该用〈树皮〉。水果皮只指水果外层的皮，树干表面的皮要说“树皮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13033, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水果皮", "is_correct": true, "explanation": "水果皮：水果外层的皮，维生素多存在于此，能放在“里”。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水不含维生素，与“有很多维生素”矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头里没有维生素，与句意不符。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：“里有维生素”多用于食物，“汽油”不能与“维生素”搭配。"}], "explanations": {"水果皮": "水果皮：水果外层的皮，维生素多存在于此，能放在“里”。", "墨水": "语义：墨水不含维生素，与“有很多维生素”矛盾。", "石头": "语义：石头里没有维生素，与句意不符。", "汽油": "搭配：“里有维生素”多用于食物，“汽油”不能与“维生素”搭配。"}, "sentence_index": 6, "correct_answer": "水果皮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的水果皮很粗糙，需要保养。", "explanation": "这里应该用〈皮肤〉。水果皮指水果的外皮，不能用来指人的皮肤。"}, {"text": "他每天都读水果皮。", "explanation": "这里应该用〈书〉。“读”的对象是书籍等文字材料，水果皮不能读。"}, {"text": "他穿着水果皮。", "explanation": "这里应该用〈衣服〉。“穿”用于衣物、鞋帽，水果皮不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13033, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把两只水果皮扔进了垃圾桶。", "corrected_sentence": "妈妈把两块水果皮扔进了垃圾桶。", "error_description": "“水果皮”的量词应用“块”或“片”，不能用“只”（“只”用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13033, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把晒干水果皮收了起来。", "corrected_sentence": "妈妈把晒干的水果皮收了起来。", "error_description": "“晒干”修饰“水果皮”，中间要加“的”，应说“晒干的水果皮”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
