INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13034, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "茶树的嫩叶，经过加工后用于冲泡饮用。", "primary_collocate": null, "pronunciation": "chá yè", "ipa": "ʈʂʰa˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "吃剩的菜、水果皮、茶叶渣都可以拿去沤肥。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有一包新茶叶。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶叶是从云南带来的。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用热水泡茶叶。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶叶放太多，茶会很苦。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢喝用好茶叶泡的茶。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶叶要放在干燥的地方。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在商店买了两盒茶叶。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天采的茶叶味道最好。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯茶里的茶叶已经沉到底了。", "target_word": "茶叶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一包茶叶", "label": "量词"}, {"form": "一片茶叶", "label": "量词"}, {"form": "茶叶蛋", "label": "复合"}, {"form": "茶葉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "茶树嫩叶加工后用来泡茶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7bcf024-40e1-464a-b19b-d6126447d7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13034, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "煤渣", "is_correct": false, "explanation": "语义：煤渣不能沤肥，与吃剩的菜、水果皮不同类，句子不成立。"}, {"text": "茶叶", "is_correct": true, "explanation": "茶叶渣指泡过后剩下的茶叶碎末，可以沤肥，与吃剩的菜、水果皮一样，符合句意。"}, {"text": "钢渣", "is_correct": false, "explanation": "语义：钢渣是炼钢废料，不能沤肥，句子不成立。"}, {"text": "蟑螂", "is_correct": false, "explanation": "搭配：“渣”指碎末，不说“蟑螂渣”，而且蟑螂不是可以用的废料。"}], "explanations": {"煤渣": "语义：煤渣不能沤肥，与吃剩的菜、水果皮不同类，句子不成立。", "茶叶": "茶叶渣指泡过后剩下的茶叶碎末，可以沤肥，与吃剩的菜、水果皮一样，符合句意。", "钢渣": "语义：钢渣是炼钢废料，不能沤肥，句子不成立。", "蟑螂": "搭配：“渣”指碎末，不说“蟑螂渣”，而且蟑螂不是可以用的废料。"}, "sentence_index": 0, "correct_answer": "茶叶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把干茶叶当成主食，一口一口吃了下去。", "explanation": "这里应该用〈米饭〉。主食是米饭、面条这类能饱腹的食物；茶叶是干叶子，要泡水喝，不能当主食吃。"}, {"text": "这片山坡的茶叶开了白色的花。", "explanation": "这里应该用〈茶树〉。开花的是茶树；茶叶是采下来的叶子，不会开花。"}, {"text": "妈妈买了一只茶叶。", "explanation": "这里应该用〈包〉或〈盒〉。茶叶要按包、盒、罐等量词计量，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鲜鱼", "is_correct": false, "explanation": "语义：鲜鱼需要冷藏，与“干燥的地方”的保存要求相冲突。"}, {"text": "茶叶", "is_correct": true, "explanation": "茶叶需要干燥保存，放在干燥的地方符合句意。"}, {"text": "冰淇淋", "is_correct": false, "explanation": "语义：冰淇淋需要冷冻保存，不能放在干燥的地方。"}, {"text": "雪", "is_correct": false, "explanation": "搭配：“放”用于可以保存的物品，不说“雪要放在……”。"}], "explanations": {"鲜鱼": "语义：鲜鱼需要冷藏，与“干燥的地方”的保存要求相冲突。", "茶叶": "茶叶需要干燥保存，放在干燥的地方符合句意。", "冰淇淋": "语义：冰淇淋需要冷冻保存，不能放在干燥的地方。", "雪": "搭配：“放”用于可以保存的物品，不说“雪要放在……”。"}, "sentence_index": 6, "correct_answer": "茶叶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我给客人拿出茶叶当点心吃。", "explanation": "这里应该用〈饼干〉。饼干是可以直接吃的食品；茶叶是干叶子，要泡开才能喝，不能直接当点心吃。"}, {"text": "奶奶每天早上喝茶叶，喝完就出门散步。", "explanation": "这里应该用〈茶水〉。喝的应是泡好的茶水；茶叶是干叶子，不能直接喝。"}, {"text": "工人们在茶叶里采茶。", "explanation": "这里应该用〈茶园〉。采茶的场所是茶园；茶叶是采下的叶子，不是工作的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家昨天买了一包新地茶叶。", "corrected_sentence": "我家昨天买了一包新茶叶。", "error_description": "错误：“新”修饰“茶叶”时直接放在名词前，不能加“地”（“地”用于动词、形容词前作状语）。正确：“一包新茶叶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈上周在超市买了两条茶叶。", "corrected_sentence": "妈妈上周在超市买了两包茶叶。", "error_description": "错误：“茶叶”的量词用“包”“盒”等，不能用“条”（“条”用于长条形的东西）。正确：“两包茶叶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
