INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13035, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "使用后剩下的植物性废弃物，如茶叶或食物残渣", "primary_collocate": null, "pronunciation": "zhā", "ipa": "ʈʂa˥", "syllable_count": 1, "sentences": [{"text": "用过的咖啡别急着扔，剩下的渣晒干后可以当肥料。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃剩的菜、水果皮、茶叶渣都可以用。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "茶泡完了，渣可以放在花盆里。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "咖啡喝完以后，渣可以放在冰箱里除味。", "target_word": "渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把菜叶和渣放进桶里，过几天就能变成肥料。", "target_word": "渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "榨完甘蔗，剩下的渣可以喂牛。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花生油做好了，渣还可以做饲料。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "茶叶泡过几次，渣就可以拿去种花。", "target_word": "渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完豆浆，剩下的渣可以做饼。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水果榨汁后的渣，也能放进花园里当肥料。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "茶渣", "label": "复合"}, {"form": "豆渣", "label": "复合"}], "register": "中性", "sense_fingerprint": "使用后剩下的植物性废料，如茶叶渣、咖啡渣、甘蔗渣，可用作肥料或饲料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d079ee5-3e48-4f10-9b81-1c61d5a1cf7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13035, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。渣（zhā）指使用后剩下的植物性残余，如茶渣、豆渣。"}, {"text": "炸", "is_correct": false, "explanation": "zhà（第四声）与 zhā（第一声）声调不同，意思是“油炸”。"}, {"text": "叉", "is_correct": false, "explanation": "chā 与 zhā 声母不同（ch 与 zh），意思是“叉子”。"}, {"text": "张", "is_correct": false, "explanation": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“张开”。"}, {"text": "遮", "is_correct": false, "explanation": "zhē 与 zhā 韵母不同（e 与 a），意思是“遮挡”。"}, {"text": "眨", "is_correct": false, "explanation": "zhǎ（第三声）与 zhā（第一声）声调不同，意思是“眨眼”。"}], "explanations": {"渣": "正确。渣（zhā）指使用后剩下的植物性残余，如茶渣、豆渣。", "炸": "zhà（第四声）与 zhā（第一声）声调不同，意思是“油炸”。", "叉": "chā 与 zhā 声母不同（ch 与 zh），意思是“叉子”。", "张": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“张开”。", "遮": "zhē 与 zhā 韵母不同（e 与 a），意思是“遮挡”。", "眨": "zhǎ（第三声）与 zhā（第一声）声调不同，意思是“眨眼”。"}, "sentence_index": null, "correct_answer": "渣"}, "level_3": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。“剩下的渣”指咖啡用后留下的残余，晒干后可当肥料，与句意相符。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是金属工具，晒干后不能当肥料，句意不通。"}, {"text": "硬币", "is_correct": false, "explanation": "语义：硬币是货币，不是可当肥料的残余，句意不通。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是器具，不是可当肥料的残余，句意不通。"}], "explanations": {"渣": "正确。“剩下的渣”指咖啡用后留下的残余，晒干后可当肥料，与句意相符。", "钥匙": "语义：钥匙是金属工具，晒干后不能当肥料，句意不通。", "硬币": "语义：硬币是货币，不是可当肥料的残余，句意不通。", "眼镜": "语义：眼镜是器具，不是可当肥料的残余，句意不通。"}, "sentence_index": 0, "correct_answer": "渣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯啤酒上面全是渣。", "explanation": "这里应该用〈泡沫〉。渣指使用后剩下的植物性废弃物，啤酒表面的气泡要说“泡沫”，不能说“渣”。"}, {"text": "泡茶最珍贵的部分其实是渣。", "explanation": "这里应该用〈茶汤〉。渣是使用后剩下的废弃物，泡茶时真正有价值的是茶汤，不能说渣最珍贵。"}, {"text": "泡茶用的渣很新鲜。", "explanation": "这里应该用〈茶叶〉。渣是使用后剩下的废弃物，泡茶用的材料要说“茶叶”，不能说“渣”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13035, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。渣（zhā）指使用后剩下的植物性残余。"}, {"text": "榨", "is_correct": false, "explanation": "zhà（第四声）与 zhā（第一声）声调不同，意思是“压出汁液”。"}, {"text": "插", "is_correct": false, "explanation": "chā 与 zhā 声母不同（ch 与 zh），意思是“插入”。"}, {"text": "章", "is_correct": false, "explanation": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“文章”或“图章”。"}, {"text": "闸", "is_correct": false, "explanation": "zhá（第二声）与 zhā（第一声）声调不同，意思是“闸门”。"}], "explanations": {"渣": "正确。渣（zhā）指使用后剩下的植物性残余。", "榨": "zhà（第四声）与 zhā（第一声）声调不同，意思是“压出汁液”。", "插": "chā 与 zhā 声母不同（ch 与 zh），意思是“插入”。", "章": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“文章”或“图章”。", "闸": "zhá（第二声）与 zhā（第一声）声调不同，意思是“闸门”。"}, "sentence_index": null, "correct_answer": "渣"}, "level_3": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。榨油后剩下的渣还可以做饲料，与语境相符。"}, {"text": "油瓶", "is_correct": false, "explanation": "语义：油瓶是器具，榨油做好后不会剩下可以做饲料的东西。"}, {"text": "碗", "is_correct": false, "explanation": "搭配：“做饲料”只用于残余或原料，不说器皿。"}, {"text": "桶", "is_correct": false, "explanation": "语义：桶是容器，与“做饲料”所指的物料不相符。"}], "explanations": {"渣": "正确。榨油后剩下的渣还可以做饲料，与语境相符。", "油瓶": "语义：油瓶是器具，榨油做好后不会剩下可以做饲料的东西。", "碗": "搭配：“做饲料”只用于残余或原料，不说器皿。", "桶": "语义：桶是容器，与“做饲料”所指的物料不相符。"}, "sentence_index": 6, "correct_answer": "渣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杯底还剩一根渣。", "explanation": "这里应该用〈点〉。“根”用于细长的东西，渣是细碎的残余，不能用“根”计量。"}, {"text": "茶壶里还剩一只渣。", "explanation": "这里应该用〈点〉。“只”多用于动物或成对的物品，渣不用“只”来计量。"}, {"text": "灶台上还剩一条渣。", "explanation": "这里应该用〈点〉。“条”用于细长的物品，渣不能用“条”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13035, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "碗底还剩下一条渣。", "corrected_sentence": "碗底还剩下一点渣。", "error_description": "量词错误：“条”用于细长的东西，渣是细碎的残余，不能用“条”计量，应说“一点渣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13035, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "榨完甘蔗，剩下的一条渣都可以喂牛。", "corrected_sentence": "榨完甘蔗，剩下的一点渣都可以喂牛。", "error_description": "量词错误：“条”用于细长的东西，渣是细碎的残余，不能用“条”计量，应说“一点渣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
