INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13036, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "寻找并准备使用某个东西、地方或人。", "primary_collocate": null, "pronunciation": "zhǎo", "ipa": "ʈʂaʊ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "我想找一支笔写名字。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找了一块布擦桌子。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请找个袋子装这些苹果。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太热了，我们找个地方坐一坐。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下雨了，快去找把伞。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找了一把锤子挂画。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要找张纸写电话号码。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈找了一件旧衣服给我穿。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子找了几块石头搭小房子。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先找个人帮忙搬桌子吧。", "target_word": "找", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找了", "label": "完成体"}, {"form": "找过", "label": "经历体"}, {"form": "找找", "label": "重叠"}, {"form": "寻找", "label": "复合词"}], "register": "中性", "sense_fingerprint": "找来某物、某处或某人，准备用它做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb44a393-77f6-42c1-bc0b-0d5ca4c2aee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13036, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "找", "is_correct": true, "explanation": "正确答案：找（zhǎo），表示寻找并准备使用。"}, {"text": "炒", "is_correct": false, "explanation": "chǎo 与 zhǎo 声母不同（ch 与 zh），意思是炒菜。"}, {"text": "罩", "is_correct": false, "explanation": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是罩子。"}, {"text": "招", "is_correct": false, "explanation": "zhāo（第一声）与 zhǎo（第三声）声调不同，意思是招手、招呼。"}, {"text": "早", "is_correct": false, "explanation": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是早晨。"}], "explanations": {"找": "正确答案：找（zhǎo），表示寻找并准备使用。", "炒": "chǎo 与 zhǎo 声母不同（ch 与 zh），意思是炒菜。", "罩": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是罩子。", "招": "zhāo（第一声）与 zhǎo（第三声）声调不同，意思是招手、招呼。", "早": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是早晨。"}, "sentence_index": null, "correct_answer": "找"}, "level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：扔掉笔与“写名字”的目的相反。"}, {"text": "找", "is_correct": true, "explanation": "正确答案：找，表示找来一支笔备用。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象应是可食用之物，“一支笔”不能吃。"}, {"text": "折", "is_correct": false, "explanation": "语义：折断笔就不能写字，与“写名字”的目的冲突。"}], "explanations": {"扔": "语义：扔掉笔与“写名字”的目的相反。", "找": "正确答案：找，表示找来一支笔备用。", "吃": "搭配：“吃”的对象应是可食用之物，“一支笔”不能吃。", "折": "语义：折断笔就不能写字，与“写名字”的目的冲突。"}, "sentence_index": 0, "correct_answer": "找"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找了一个微笑。", "explanation": "这里应该用〈露出〉。找是寻找，不表示做出表情，应说“露出一个微笑”。"}, {"text": "这首歌找了很多听众。", "explanation": "这里应该用〈吸引〉。找是寻找，不表示引来听众；使人喜爱、来到身边要用吸引。"}, {"text": "他找了老师的批评。", "explanation": "这里应该用〈接受〉。找表示寻找，不能与“批评”搭配表示承受，承受批评要用接受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13036, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "找", "is_correct": true, "explanation": "正确答案：找（zhǎo），表示寻找并准备使用。"}, {"text": "草", "is_correct": false, "explanation": "cǎo 与 zhǎo 声母不同（c 与 zh），意思是草。"}, {"text": "照", "is_correct": false, "explanation": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是照射、照片。"}, {"text": "枣", "is_correct": false, "explanation": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是枣子。"}, {"text": "澡", "is_correct": false, "explanation": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是洗澡。"}], "explanations": {"找": "正确答案：找（zhǎo），表示寻找并准备使用。", "草": "cǎo 与 zhǎo 声母不同（c 与 zh），意思是草。", "照": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是照射、照片。", "枣": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是枣子。", "澡": "zǎo 与 zhǎo 声母不同（z 与 zh），意思是洗澡。"}, "sentence_index": null, "correct_answer": "找"}, "level_3": {"options": [{"text": "撕", "is_correct": false, "explanation": "语义：撕掉的纸无法用来写字，与“写电话号码”的目的冲突。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧掉的纸无法用来写电话号码。"}, {"text": "找", "is_correct": true, "explanation": "正确答案：找，表示找来一张纸备用。"}, {"text": "嚼", "is_correct": false, "explanation": "搭配：“嚼”一般用于食物，“纸”不能嚼。"}], "explanations": {"撕": "语义：撕掉的纸无法用来写字，与“写电话号码”的目的冲突。", "烧": "语义：烧掉的纸无法用来写电话号码。", "找": "正确答案：找，表示找来一张纸备用。", "嚼": "搭配：“嚼”一般用于食物，“纸”不能嚼。"}, "sentence_index": 6, "correct_answer": "找"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找了考试。", "explanation": "这里应该用〈通过〉。找是寻找，不能与“考试”搭配表示顺利过关，应说“通过考试”。"}, {"text": "他找了一副好心肠。", "explanation": "这里应该用〈有〉。找是寻找，不能表示具有某种品性，应说“有一副好心肠”。"}, {"text": "妈妈正在用布找桌子。", "explanation": "这里应该用〈擦〉。找是寻找，不表示擦拭桌面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下雨了，我终于找了到一把伞。", "corrected_sentence": "下雨了，我终于找到了一把伞。", "error_description": "错误在“找了到”。结果补语“到”必须紧跟动词，应为“找到”，再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想找了过一本旧字典查单词。", "corrected_sentence": "我想找一本旧字典查单词。", "error_description": "错误在“找了过”。“了”与“过”不能同时用在动词后，且此处是打算去找，只需用“找”；正确说法是“想找一本旧字典”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13037, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拔", "is_correct": true, "explanation": "拔：拔出，与“刺入”方向相反，构成反义。"}, {"text": "摸", "is_correct": false, "explanation": "摸：用手接触，与“刺入”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃：咽下食物，与“扎”的意思无关，不构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "跑：快速移动，与“扎”的意思无关，不构成反义。"}], "correct_answer": "拔", "explanations": {"拔": "拔：拔出，与“刺入”方向相反，构成反义。", "摸": "摸：用手接触，与“刺入”没有反义关系。", "吃": "吃：咽下食物，与“扎”的意思无关，不构成反义。", "跑": "跑：快速移动，与“扎”的意思无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13037, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拔", "is_correct": true, "explanation": "拔：拔出，与“刺入”方向相反，构成反义。"}, {"text": "看", "is_correct": false, "explanation": "看：观看，与“扎”的意思无关，不构成反义。"}, {"text": "喝", "is_correct": false, "explanation": "喝：饮用液体，与“扎”的意思无关，不构成反义。"}, {"text": "唱", "is_correct": false, "explanation": "唱：发出歌声，与“扎”的意思无关，不构成反义。"}], "correct_answer": "拔", "explanations": {"拔": "拔：拔出，与“刺入”方向相反，构成反义。", "看": "看：观看，与“扎”的意思无关，不构成反义。", "喝": "喝：饮用液体，与“扎”的意思无关，不构成反义。", "唱": "唱：发出歌声，与“扎”的意思无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13037, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指用尖锐的物体刺入或插入。", "primary_collocate": null, "pronunciation": "zhā", "ipa": "ʈʂa⁵⁵", "syllable_count": 1, "sentences": [{"text": "在箱子的底部和侧面扎一些小孔。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他用针扎了一下手指。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，别让刺扎到手。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用牙签扎了一块苹果。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玫瑰的刺扎到了她的手。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用叉子扎起一块肉。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根钉子扎进了他的鞋底。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在塑料盖上扎几个小洞。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脚上扎了一根刺。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蒸鸡蛋以前，先在蛋壳上扎一个小孔。", "target_word": "扎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扎了", "label": "完成体"}, {"form": "扎过", "label": "经历体"}, {"form": "扎着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "用尖锐的东西刺入物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffaa23c-0615-48bd-8fdc-16ab6fa2cc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13037, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扎", "is_correct": true, "explanation": "扎 zhā（第一声）：用尖锐的物体刺入。"}, {"text": "炸", "is_correct": false, "explanation": "zhà（第四声）与 zhā（第一声）声调不同，炸的意思是油炸或爆炸。"}, {"text": "眨", "is_correct": false, "explanation": "zhǎ（第三声）与 zhā（第一声）声调不同，眨的意思是眨眼。"}, {"text": "沙", "is_correct": false, "explanation": "shā 与 zhā 声母不同（sh 与 zh），沙的意思是沙子。"}, {"text": "杀", "is_correct": false, "explanation": "shā 与 zhā 声母不同（sh 与 zh），杀的意思是杀死。"}], "explanations": {"扎": "扎 zhā（第一声）：用尖锐的物体刺入。", "炸": "zhà（第四声）与 zhā（第一声）声调不同，炸的意思是油炸或爆炸。", "眨": "zhǎ（第三声）与 zhā（第一声）声调不同，眨的意思是眨眼。", "沙": "shā 与 zhā 声母不同（sh 与 zh），沙的意思是沙子。", "杀": "shā 与 zhā 声母不同（sh 与 zh），杀的意思是杀死。"}, "sentence_index": null, "correct_answer": "扎"}, "level_3": {"options": [{"text": "扎", "is_correct": true, "explanation": "扎：用尖物刺入，与“小孔”相符，符合句意。"}, {"text": "涂", "is_correct": false, "explanation": "搭配：“涂”配的是颜料、油漆，不能说涂小孔。"}, {"text": "挂", "is_correct": false, "explanation": "语义：“挂”指悬挂物体，小孔不是可以挂上去的东西。"}, {"text": "贴", "is_correct": false, "explanation": "搭配：“贴”配的是纸张、标签，不能说贴小孔。"}], "explanations": {"扎": "扎：用尖物刺入，与“小孔”相符，符合句意。", "涂": "搭配：“涂”配的是颜料、油漆，不能说涂小孔。", "挂": "语义：“挂”指悬挂物体，小孔不是可以挂上去的东西。", "贴": "搭配：“贴”配的是纸张、标签，不能说贴小孔。"}, "sentence_index": 0, "correct_answer": "扎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一张邮票扎在信封上，准备寄出去。", "explanation": "这里应该用〈贴〉。贴指把平面的东西粘到另一物的表面；扎强调尖锐物刺入，邮票不会被刺入信封，用“扎”不符合说法。"}, {"text": "他把钥匙扎进了锁孔，轻轻一转门就开了。", "explanation": "这里应该用〈插〉。插指把细长的东西放进孔或缝里；扎强调尖锐物刺入，钥匙不是尖锐物，用“扎”不符合说法。"}, {"text": "他用抹布扎了一下桌面，把灰尘弄掉了。", "explanation": "这里应该用〈擦〉。擦指用布或手来回摩擦去掉灰尘；扎强调尖锐物刺入，抹布擦桌面不能用“扎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13037, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扎", "is_correct": true, "explanation": "扎 zhā（第一声）：用尖锐的物体刺入。"}, {"text": "诈", "is_correct": false, "explanation": "zhà（第四声）与 zhā（第一声）声调不同，诈的意思是欺骗。"}, {"text": "闸", "is_correct": false, "explanation": "zhá（第二声）与 zhā（第一声）声调不同，闸的意思是闸门。"}, {"text": "纱", "is_correct": false, "explanation": "shā 与 zhā 声母不同（sh 与 zh），纱的意思是纱布或纱线。"}, {"text": "砂", "is_correct": false, "explanation": "shā 与 zhā 声母不同（sh 与 zh），砂的意思是沙子。"}], "explanations": {"扎": "扎 zhā（第一声）：用尖锐的物体刺入。", "诈": "zhà（第四声）与 zhā（第一声）声调不同，诈的意思是欺骗。", "闸": "zhá（第二声）与 zhā（第一声）声调不同，闸的意思是闸门。", "纱": "shā 与 zhā 声母不同（sh 与 zh），纱的意思是纱布或纱线。", "砂": "shā 与 zhā 声母不同（sh 与 zh），砂的意思是沙子。"}, "sentence_index": null, "correct_answer": "扎"}, "level_3": {"options": [{"text": "扎", "is_correct": true, "explanation": "扎：尖锐的钉子刺入鞋底，符合句意。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”是咽下，钉子不能被吞入鞋底。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”配的是线、布，钉子不能缝进鞋底。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能说吃进鞋底。"}], "explanations": {"扎": "扎：尖锐的钉子刺入鞋底，符合句意。", "吞": "语义：“吞”是咽下，钉子不能被吞入鞋底。", "缝": "搭配：“缝”配的是线、布，钉子不能缝进鞋底。", "吃": "语义：“吃”指进食，不能说吃进鞋底。"}, "sentence_index": 6, "correct_answer": "扎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把外套扎在衣架上，准备出门。", "explanation": "这里应该用〈挂〉。挂指把东西悬挂在架子或钩子上；扎强调尖锐物刺入，外套挂在衣架上不是刺入，用“扎”不符合说法。"}, {"text": "他用手指扎了扎我的脸，像在逗我。", "explanation": "这里应该用〈戳〉。戳指用手指或尖物轻轻碰、刺；扎强调尖锐物用力刺入，用手指轻轻戳脸不能用“扎”。"}, {"text": "他用力扎了扎桌子，吓了大家一跳。", "explanation": "这里应该用〈拍〉。拍指用手掌击打；扎强调尖锐物刺入，用手掌拍桌子不能用“扎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根刺扎得深很，拔的时候特别疼。", "corrected_sentence": "这根刺扎得很深，拔的时候特别疼。", "error_description": "“很”位置错误：程度补语应说“扎得很深”，“很”须放在形容词“深”之前，不能说“扎得深很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "针进扎了他的手心。", "corrected_sentence": "针扎进了他的手心。", "error_description": "错误形式是“进扎”，趋向补语“进”应紧跟在动词“扎”之后，说“扎进了”，不能把“进”放在“扎”前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
