INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "自然中的普通泥土，常用于园艺或混合堆肥", "primary_collocate": null, "pronunciation": "tǔ", "ipa": "tʰu˨˩", "syllable_count": 1, "sentences": [{"text": "过几周，厨余会变成黑黑的土。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我把落叶和土放在一起做肥料。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小花园里的土需要经常翻一翻。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买一袋土，我们就可以种花了。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在土里放了一些菜叶。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些土里有很多小虫子。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先在盆里放土，再放种子。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把水果皮埋进土里，会变成肥料。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳台上的土不多，只能种小花。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用旧茶叶和土一起养花。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一袋", "label": "量词"}, {"form": "一堆", "label": "量词"}], "register": "中性", "sense_fingerprint": "园艺、堆肥中使用的普通泥土", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8dcf6e-820e-41d6-966b-7b4656bddf4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13038, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "土", "is_correct": true, "explanation": "土（tǔ）指普通泥土，是正确答案。"}, {"text": "苦", "is_correct": false, "explanation": "k 与 t 声母不同，苦 kǔ 意思是味道苦。"}, {"text": "补", "is_correct": false, "explanation": "b 与 t 声母不同，补 bǔ 意思是补充、修补。"}, {"text": "途", "is_correct": false, "explanation": "tú（第二声）与 tǔ（第三声）声调不同，途 tú 意思是道路。"}, {"text": "突", "is_correct": false, "explanation": "tū（第一声）与 tǔ（第三声）声调不同，突 tū 意思是突然。"}], "explanations": {"土": "土（tǔ）指普通泥土，是正确答案。", "苦": "k 与 t 声母不同，苦 kǔ 意思是味道苦。", "补": "b 与 t 声母不同，补 bǔ 意思是补充、修补。", "途": "tú（第二声）与 tǔ（第三声）声调不同，途 tú 意思是道路。", "突": "tū（第一声）与 tǔ（第三声）声调不同，突 tū 意思是突然。"}, "sentence_index": null, "correct_answer": "土"}, "level_3": {"options": [{"text": "土", "is_correct": true, "explanation": "正确：厨余腐烂后会变成黑黑的泥土，符合句意。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：厨余不会变成钥匙，句子讲的是腐烂后的结果。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“黑黑的”形容有形的东西，不能修饰歌声。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不是由厨余变成的，与句意不符。"}], "explanations": {"土": "正确：厨余腐烂后会变成黑黑的泥土，符合句意。", "钥匙": "语义：厨余不会变成钥匙，句子讲的是腐烂后的结果。", "歌声": "搭配：“黑黑的”形容有形的东西，不能修饰歌声。", "阳光": "语义：阳光不是由厨余变成的，与句意不符。"}, "sentence_index": 0, "correct_answer": "土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在粥里加了一勺土。", "explanation": "这里应该用〈糖〉。粥里加的是糖等调味品，土不能用来调味。"}, {"text": "周末烧烤，要先买一袋土。", "explanation": "这里应该用〈木炭〉。烧烤要用能燃烧的木炭，土不能燃烧。"}, {"text": "花盆底下铺一层土，就可以排水了。", "explanation": "这里应该用〈石子〉。排水要用颗粒大的石子，土颗粒细，会把水堵住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13038, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "土", "is_correct": true, "explanation": "土（tǔ）指普通泥土，是正确答案。"}, {"text": "堵", "is_correct": false, "explanation": "d 与 t 声母不同，堵 dǔ 意思是堵塞、堵车。"}, {"text": "兔", "is_correct": false, "explanation": "tù（第四声）与 tǔ（第三声）声调不同，兔 tù 意思是兔子。"}, {"text": "图", "is_correct": false, "explanation": "tú（第二声）与 tǔ（第三声）声调不同，图 tú 意思是图画、地图。"}, {"text": "秃", "is_correct": false, "explanation": "tū（第一声）与 tǔ（第三声）声调不同，秃 tū 意思是没有头发。"}], "explanations": {"土": "土（tǔ）指普通泥土，是正确答案。", "堵": "d 与 t 声母不同，堵 dǔ 意思是堵塞、堵车。", "兔": "tù（第四声）与 tǔ（第三声）声调不同，兔 tù 意思是兔子。", "图": "tú（第二声）与 tǔ（第三声）声调不同，图 tú 意思是图画、地图。", "秃": "tū（第一声）与 tǔ（第三声）声调不同，秃 tū 意思是没有头发。"}, "sentence_index": null, "correct_answer": "土"}, "level_3": {"options": [{"text": "土", "is_correct": true, "explanation": "正确：先在盆里放泥土，再放种子，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子体积太大，放不进花盆。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“放”的宾语要能装进盆里，不能说放音乐。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能放进花盆里，句意不通。"}], "explanations": {"土": "正确：先在盆里放泥土，再放种子，符合句意。", "桌子": "语义：桌子体积太大，放不进花盆。", "音乐": "搭配：“放”的宾语要能装进盆里，不能说放音乐。", "窗户": "语义：窗户不能放进花盆里，句意不通。"}, "sentence_index": 6, "correct_answer": "土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把剪刀是用土做的，很锋利。", "explanation": "这里应该用〈钢〉。剪刀要用钢铁才能锋利，土做不出刀刃。"}, {"text": "这双鞋底是用土做的，很防滑。", "explanation": "这里应该用〈橡胶〉。鞋底要用橡胶才能防滑，土不能做鞋底。"}, {"text": "这条裙子是用土做的，很漂亮。", "explanation": "这里应该用〈布〉。裙子要用布料做，土不能做衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一颗土，准备种菜。", "corrected_sentence": "我买了一袋土，准备种菜。", "error_description": "量词错误：土是散状的，应说“一袋土”，不能用“颗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "园子里的土已经翻了好。", "corrected_sentence": "园子里的土已经翻好了。", "error_description": "补语错误：“翻”的结果补语要紧跟动词，应说“翻好了”，不说“翻了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
