INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13040, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体因腐败或变质而产生难闻的气味。", "primary_collocate": null, "pronunciation": "fā chòu", "ipa": "fa⁵⁵ ʈʂʰou̯⁵¹", "syllable_count": 2, "sentences": [{"text": "鱼放了三天，已经发臭了。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，剩饭不放冰箱很快就会发臭。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾桶里的东西发臭了，快倒掉吧。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块肉发臭了，不能吃。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条河的水发臭，附近的人都很难受。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶坏了就会发臭。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袜子好几天没洗，都发臭了。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的冰箱里有东西发臭，你帮我找找。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿衣服放久了也会发臭。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡蛋放坏了，一打开就发臭。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发臭了", "label": "完成体"}, {"form": "发臭过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "东西腐败变质后散发臭味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffaa23c-0615-48bd-8fdc-16ab6fa2cc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发臭", "is_correct": true, "explanation": "发臭：东西腐坏后散发臭味，与“放了三天”相符，符合句意。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”只用于金属，鱼不会生锈。"}, {"text": "开花", "is_correct": false, "explanation": "语义：“开花”指植物开放，与鱼的腐坏无关。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”指体温升高，与鱼腐坏无关，句子不通。"}], "explanations": {"发臭": "发臭：东西腐坏后散发臭味，与“放了三天”相符，符合句意。", "生锈": "搭配：“生锈”只用于金属，鱼不会生锈。", "开花": "语义：“开花”指植物开放，与鱼的腐坏无关。", "发烧": "语义：“发烧”指体温升高，与鱼腐坏无关，句子不通。"}, "sentence_index": 0, "correct_answer": "发臭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一阵饭菜的香味发臭而来。", "explanation": "这里应该用〈扑鼻〉。扑鼻形容香味直冲鼻子；发臭只指东西腐败后有臭味，不能形容香味。"}, {"text": "这个消息很快就发臭了。", "explanation": "这里应该用〈传开〉。传开指消息、气味等四处流传；发臭只指东西腐败后有难闻的气味，不能用于消息。"}, {"text": "一股烤肉的香味发臭了。", "explanation": "这里应该用〈飘〉。飘指气味随风传开；发臭只指东西腐败后有臭味，不能形容香味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发臭", "is_correct": true, "explanation": "发臭：袜子久不洗而腐臭，与“好几天没洗”相符，符合句意。"}, {"text": "变白", "is_correct": false, "explanation": "语义：“变白”指颜色变白，与“没洗”的脏污语境不符。"}, {"text": "发亮", "is_correct": false, "explanation": "语义：“发亮”指发光，与袜子没洗的语境无关。"}, {"text": "长高", "is_correct": false, "explanation": "搭配：“长高”只用于人或植物，不能说袜子长高。"}], "explanations": {"发臭": "发臭：袜子久不洗而腐臭，与“好几天没洗”相符，符合句意。", "变白": "语义：“变白”指颜色变白，与“没洗”的脏污语境不符。", "发亮": "语义：“发亮”指发光，与袜子没洗的语境无关。", "长高": "搭配：“长高”只用于人或植物，不能说袜子长高。"}, "sentence_index": 6, "correct_answer": "发臭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山谷里的雾气发臭了，大家都捂住了鼻子。", "explanation": "这里应该用〈弥漫〉。弥漫指雾气、烟尘充满一片；发臭只指东西腐败后有难闻的气味，不能形容雾气。"}, {"text": "锅里的热气发臭了。", "explanation": "这里应该用〈冒〉。冒指热气、烟等向上升起；发臭只指东西腐败后有难闻的气味，不能形容热气。"}, {"text": "窗外的阳光发臭了。", "explanation": "这里应该用〈照〉。照指光线射到某处；发臭只指东西腐败后有难闻的气味，不能形容光线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天热，剩饭快很就会发臭。", "corrected_sentence": "天热，剩饭很快就会发臭。", "error_description": "副词字序颠倒：“很快”写成“快很”是错误的，应为“很快”，修饰“发臭”，写成“很快就会发臭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这碗汤放了一天，已经发臭了了。", "corrected_sentence": "这碗汤放了一天，已经发臭了。", "error_description": "多余的“了”：“发臭了”已带完成的“了”，末尾再加“了”是错误的，应删去多余的“了”，说“已经发臭了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
