INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13042, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "烹制饭菜。", "primary_collocate": null, "pronunciation": "zuò fàn", "ipa": "tswɔ˥˩ fan˥˩", "syllable_count": 2, "sentences": [{"text": "每天做饭后，我们会剩下很多厨余，比如果皮、菜叶、咖啡渣和蛋壳。", "target_word": "做饭", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "妈妈每天晚上六点回家做饭。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不会做饭，所以常常去饭馆吃。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸今天不上班，在家给我们做饭。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做饭做得很好，朋友都爱去他家吃饭。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天太累了，我不想做饭了。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在客厅玩，妈妈在厨房做饭。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们三个人轮流做饭，今天轮到我。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚学会做饭，做的菜还不太好吃。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶年纪大了，不能再给全家做饭了。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "做了饭", "label": "体标：了"}, {"form": "做过饭", "label": "体标：过"}, {"form": "做完饭", "label": "结果补语"}], "register": "口语", "sense_fingerprint": "烹制饭菜，为自己或家人准备一餐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7463c093-f860-4636-af40-85cf1daafb3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13042, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "做饭", "is_correct": true, "explanation": "做饭（zuò fàn）：烹制饭菜，为正确答案。"}, {"text": "做法", "is_correct": false, "explanation": "fǎ（第三声）与 fàn（第四声）声调不同，「做法」意思是方法、做的办法。"}, {"text": "做反", "is_correct": false, "explanation": "fǎn（第三声）与 fàn（第四声）声调不同，「做反」意思是做得与原来相反。"}, {"text": "罪犯", "is_correct": false, "explanation": "zuì 与 zuò 韵母不同，「罪犯」（zuì fàn）意思是犯罪的人。"}], "explanations": {"做饭": "做饭（zuò fàn）：烹制饭菜，为正确答案。", "做法": "fǎ（第三声）与 fàn（第四声）声调不同，「做法」意思是方法、做的办法。", "做反": "fǎn（第三声）与 fàn（第四声）声调不同，「做反」意思是做得与原来相反。", "罪犯": "zuì 与 zuò 韵母不同，「罪犯」（zuì fàn）意思是犯罪的人。"}, "sentence_index": null, "correct_answer": "做饭"}, "level_3": {"options": [{"text": "做饭", "is_correct": true, "explanation": "做饭：烹制饭菜，会产生果皮、菜叶等厨余，句意成立。"}, {"text": "扫地", "is_correct": false, "explanation": "语义：扫地扫出的是灰尘，不会产生果皮、菜叶之类的厨余。"}, {"text": "洗衣服", "is_correct": false, "explanation": "语义：洗衣服不产生厨余，句中列举的都是食物残渣。"}, {"text": "修车", "is_correct": false, "explanation": "搭配：「修车」与「厨余」不搭配，厨余来自做饭、吃饭之类的活动。"}], "explanations": {"做饭": "做饭：烹制饭菜，会产生果皮、菜叶等厨余，句意成立。", "扫地": "语义：扫地扫出的是灰尘，不会产生果皮、菜叶之类的厨余。", "洗衣服": "语义：洗衣服不产生厨余，句中列举的都是食物残渣。", "修车": "搭配：「修车」与「厨余」不搭配，厨余来自做饭、吃饭之类的活动。"}, "sentence_index": 0, "correct_answer": "做饭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服务员过来，我们开始做饭。", "explanation": "这里应该用〈点菜〉。点菜是向服务员选菜，做饭是在厨房里烹制食物，二者不能互换。"}, {"text": "妈妈每周六早上在超市做饭。", "explanation": "这里应该用〈买菜〉。在超市是买菜，做饭要在厨房里把食物弄熟。"}, {"text": "吃完饭，他去柜台做饭。", "explanation": "这里应该用〈付钱〉。去柜台是付钱，做饭是烹制食物，不表示结账。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做饭", "is_correct": true, "explanation": "做饭：妈妈在厨房烹制饭菜，与“厨房”和“家务”的场景相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：厨房不是睡觉的地方，与“孩子们在客厅玩”的家务场景不符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：厨房里不能游泳，句子描写的是家里的日常。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：洗澡一般在浴室进行，「在厨房洗澡」搭配不当。"}], "explanations": {"做饭": "做饭：妈妈在厨房烹制饭菜，与“厨房”和“家务”的场景相符。", "睡觉": "语义：厨房不是睡觉的地方，与“孩子们在客厅玩”的家务场景不符。", "游泳": "语义：厨房里不能游泳，句子描写的是家里的日常。", "洗澡": "搭配：洗澡一般在浴室进行，「在厨房洗澡」搭配不当。"}, "sentence_index": 6, "correct_answer": "做饭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们去KTV做饭。", "explanation": "这里应该用〈唱歌〉。去KTV是唱歌，做饭要在厨房里把食物弄熟，不能在包间里进行。"}, {"text": "周末我们去游泳池做饭。", "explanation": "这里应该用〈游泳〉。去游泳池是游泳，做饭要在厨房里烹制食物。"}, {"text": "周末晚上我们去电影院做饭。", "explanation": "这里应该用〈看电影〉。去电影院是看电影，做饭应在厨房进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我做饭完了，我们开始吃吧。", "corrected_sentence": "我做完饭了，我们开始吃吧。", "error_description": "「做饭完」错，结果补语「完」应紧接动词，应说「做完饭」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做饭得很好，大家都爱吃。", "corrected_sentence": "他做饭做得很好，大家都爱吃。", "error_description": "「做饭得很好」错，补语前动词「做」需要重复，应说「做饭做得很好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
