INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13043, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13043, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物被使用、消耗或去除后，仍然留存的部分。", "primary_collocate": null, "pronunciation": "shèng xià", "ipa": "ʂəŋ˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "每天做饭后，我们会剩下很多厨余，比如果皮、菜叶、咖啡渣和蛋壳。", "target_word": "剩下", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "吃完饭，桌上只剩下一盘青菜。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱都花完了，口袋里只剩下五块。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试只剩下十分钟，他还没写完。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都走了，教室里只剩下我一个人。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "苹果分完以后，还剩下三个。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天的饭菜没吃完，剩下的放进冰箱吧。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的工资用完后，只剩下几百块。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛快结束时，场上只剩下两个队员。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们吃了蛋糕，盘子里剩下几块。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "剩下了", "label": "体标：了"}, {"form": "剩下来", "label": "趋向补语"}, {"form": "剩下的", "label": "的字结构"}], "register": "中性", "sense_fingerprint": "事物被用掉或去除后仍留存的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7463c093-f860-4636-af40-85cf1daafb3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13043, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剩下", "is_correct": true, "explanation": "剩下：做饭后仍留存的部分，与「厨余」的产生相符。"}, {"text": "吃光", "is_correct": false, "explanation": "语义：厨余是丢弃的食物残渣，不能吃光，与句意相反。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：果皮、菜叶不值得收藏，句中说的是产生后丢弃。"}, {"text": "失去", "is_correct": false, "explanation": "搭配：「失去」后面一般接机会、信心等，不接「厨余」。"}], "explanations": {"剩下": "剩下：做饭后仍留存的部分，与「厨余」的产生相符。", "吃光": "语义：厨余是丢弃的食物残渣，不能吃光，与句意相反。", "收藏": "语义：果皮、菜叶不值得收藏，句中说的是产生后丢弃。", "失去": "搭配：「失去」后面一般接机会、信心等，不接「厨余」。"}, "sentence_index": 0, "correct_answer": "剩下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家都走了，他剩下来打扫教室。", "explanation": "这里应该用〈留下来〉。剩下表示用掉或拿走后的余留，不表示主动留下做事。"}, {"text": "他从图书馆剩下了三本书。", "explanation": "这里应该用〈借走〉。借走是把书带出去，剩下表示余留，不表示从图书馆取书。"}, {"text": "他一生气就把杯子剩下了。", "explanation": "这里应该用〈摔〉。摔是使东西落地破碎，剩下表示余留，不能表示摔坏东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13043, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剩下", "is_correct": true, "explanation": "剩下：没吃完、留存的部分，正好放进冰箱。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：吃掉的已经进了肚子，不能再放进冰箱。"}, {"text": "倒掉", "is_correct": false, "explanation": "语义：倒掉的东西不会再放进冰箱保存，与句意相反。"}, {"text": "卖掉", "is_correct": false, "explanation": "搭配：「卖掉」的对象一般是商品，不能用于家里没吃完的饭菜。"}], "explanations": {"剩下": "剩下：没吃完、留存的部分，正好放进冰箱。", "吃掉": "语义：吃掉的已经进了肚子，不能再放进冰箱。", "倒掉": "语义：倒掉的东西不会再放进冰箱保存，与句意相反。", "卖掉": "搭配：「卖掉」的对象一般是商品，不能用于家里没吃完的饭菜。"}, "sentence_index": 6, "correct_answer": "剩下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他决定剩下这个项目，没有再管。", "explanation": "这里应该用〈放弃〉。剩下表示余留，不表示主动放弃做事。"}, {"text": "她回来后剩下了厨房。", "explanation": "这里应该用〈收拾〉。收拾是整理物品，剩下表示余留，不能用来说整理厨房。"}, {"text": "妈妈去超市剩下了几块蛋糕。", "explanation": "这里应该用〈买回〉。去超市是买回东西，剩下表示余留，不表示买东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌上被剩下一个杯子了。", "corrected_sentence": "桌上只剩下一个杯子了。", "error_description": "「被剩下」错：「剩下」表示余留，不能用被字句；应把「被」换成「只」，说「桌上只剩下一个杯子了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "碗里还剩下完两个饺子。", "corrected_sentence": "碗里还剩下两个饺子。", "error_description": "「剩下完两个饺子」错，「完」表示用尽，与「剩下」的留存义矛盾，应删去「完」，说「还剩下两个饺子」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
