INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13045, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蛋壳是包裹在蛋外面的硬质外壳，主要成分是碳酸钙，起到保护蛋内部的作用。", "primary_collocate": null, "pronunciation": "dàn ké", "ipa": "tan˥˩ kʰɤ˧˥", "syllable_count": 2, "sentences": [{"text": "每天做饭后，我们会剩下很多厨余，比如果皮、菜叶、咖啡渣和蛋壳。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "煮好的鸡蛋要先剥蛋壳，再放进盘子里。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋壳很硬，可是用力一敲就破了。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟从蛋壳里钻出来了。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把蛋壳放进花盆里，当作肥料。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心把蛋壳掉进了汤里。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋壳上画着一只可爱的小熊。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋壳里面有一层薄薄的白膜。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用彩色的蛋壳做了一幅画。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋壳磨碎以后可以给花草补钙。", "target_word": "蛋壳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个蛋壳", "label": "量词"}, {"form": "鸡蛋壳", "label": "复合"}], "register": "中性", "sense_fingerprint": "蛋外面起保护作用的硬壳，主要成分是碳酸钙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7463c093-f860-4636-af40-85cf1daafb3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13045, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蛋壳", "is_correct": true, "explanation": "正确答案：蛋壳（dàn ké）是包在蛋外面的硬壳。"}, {"text": "弹壳", "is_correct": false, "explanation": "弹壳（tán ké）：tán（第二声）与 dàn（第四声）声母不同（t/d），意思是子弹的壳。"}, {"text": "蛋盒", "is_correct": false, "explanation": "蛋盒（dàn hé）：hé 与 ké 声母不同（h/k），意思是装鸡蛋的盒子。"}, {"text": "单科", "is_correct": false, "explanation": "单科（dān kē）：两个音节的声调都与 dàn ké 不同，意思是一门学科。"}], "explanations": {"蛋壳": "正确答案：蛋壳（dàn ké）是包在蛋外面的硬壳。", "弹壳": "弹壳（tán ké）：tán（第二声）与 dàn（第四声）声母不同（t/d），意思是子弹的壳。", "蛋盒": "蛋盒（dàn hé）：hé 与 ké 声母不同（h/k），意思是装鸡蛋的盒子。", "单科": "单科（dān kē）：两个音节的声调都与 dàn ké 不同，意思是一门学科。"}, "sentence_index": null, "correct_answer": "蛋壳"}, "level_3": {"options": [{"text": "蛋壳", "is_correct": true, "explanation": "蛋壳属于食物残渣，与果皮、菜叶、咖啡渣并列，符合“厨余”。"}, {"text": "碗筷", "is_correct": false, "explanation": "语义：碗筷是餐具，不属于厨余，与“厨余”的意思矛盾。"}, {"text": "砖块", "is_correct": false, "explanation": "语义：砖块是建筑材料，不会出现在厨房的剩余物里。"}, {"text": "电池", "is_correct": false, "explanation": "搭配：“厨余”只指食物残渣，电池属于有害垃圾，不与果皮并列。"}], "explanations": {"蛋壳": "蛋壳属于食物残渣，与果皮、菜叶、咖啡渣并列，符合“厨余”。", "碗筷": "语义：碗筷是餐具，不属于厨余，与“厨余”的意思矛盾。", "砖块": "语义：砖块是建筑材料，不会出现在厨房的剩余物里。", "电池": "搭配：“厨余”只指食物残渣，电池属于有害垃圾，不与果皮并列。"}, "sentence_index": 0, "correct_answer": "蛋壳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早上煮了两个蛋壳当早餐。", "explanation": "这里应该用〈鸡蛋〉。蛋壳是蛋外面的硬壳，不能煮来当早餐吃。"}, {"text": "他每天早上只吃蛋壳，不吃蛋黄。", "explanation": "这里应该用〈蛋白〉。蛋壳是硬壳，不能吃；可以吃的蛋内部分是蛋白。"}, {"text": "桌上放着一根蛋壳。", "explanation": "这里应该用〈片〉。蛋壳是薄片，“根”只用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13045, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蛋壳", "is_correct": true, "explanation": "蛋壳是坚硬的表面，可以在上面画画，符合“画着一只小熊”。"}, {"text": "蛋白", "is_correct": false, "explanation": "语义：蛋白是蛋里的液体，不能当作画画的表面。"}, {"text": "水面", "is_correct": false, "explanation": "语义：水面无法承载画作，与“画着”的语境矛盾。"}, {"text": "雾", "is_correct": false, "explanation": "语义：雾是气体，无法承载画作，与“画着”的语境矛盾。"}], "explanations": {"蛋壳": "蛋壳是坚硬的表面，可以在上面画画，符合“画着一只小熊”。", "蛋白": "语义：蛋白是蛋里的液体，不能当作画画的表面。", "水面": "语义：水面无法承载画作，与“画着”的语境矛盾。", "雾": "语义：雾是气体，无法承载画作，与“画着”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "蛋壳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把蛋壳打发成泡沫，做了一个蛋糕。", "explanation": "这里应该用〈蛋清〉。打发成泡沫的是蛋清；蛋壳是硬壳，打不出泡沫。"}, {"text": "妈妈用蛋壳把肉卷起来，放进锅里。", "explanation": "这里应该用〈蛋皮〉。蛋皮是摊成的薄蛋饼，可以卷东西；蛋壳太硬，不能卷肉。"}, {"text": "他把蛋壳搅匀，倒进锅里炒。", "explanation": "这里应该用〈蛋黄〉。蛋壳是硬壳，搅不匀，也不能下锅炒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他手里拿着一条蛋壳。", "corrected_sentence": "他手里拿着一片蛋壳。", "error_description": "量词错误：蛋壳是薄片，应用“片”；“条”用于细长的东西，不能用来数蛋壳。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在碗里放了很多蛋壳们。", "corrected_sentence": "孩子们在碗里放了很多蛋壳。", "error_description": "复数标记错误：“们”只加在指人的名词后，蛋壳是物，不能说“蛋壳们”，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
