INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13046, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "覆盖在容器口上，用来封闭或保护容器内部的东西。", "primary_collocate": null, "pronunciation": "gài zi", "ipa": "kaɪ˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "首先，准备一个有盖子的大塑料桶，放在阳台或厨房外的角落。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "请把锅的盖子盖好，不然菜会凉。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子的盖子找不到了。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拧开瓶子的盖子，喝了一口水。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖子上有几个小洞，可以透气。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桶的盖子没盖紧，里面有一股味道。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤开了，盖子一直在跳。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈打开饭盒的盖子，里面是热饭。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖子是红色的，瓶子是白色的。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡杯的盖子很烫，小心点。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个盖子", "label": "量词"}, {"form": "盖儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "盖在容器口上、用来封闭或保护里面东西的物件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7463c093-f860-4636-af40-85cf1daafb3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13046, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盖子", "is_correct": true, "explanation": "正确答案：盖子（gài zi）是盖在容器口上的东西。"}, {"text": "袋子", "is_correct": false, "explanation": "袋子（dài zi）：dài 与 gài 声母不同（d/g），意思是装东西的口袋。"}, {"text": "孩子", "is_correct": false, "explanation": "孩子（hái zi）：hái 与 gài 声母和声调都不同（h/g，第二声/第四声），意思是儿童。"}, {"text": "个子", "is_correct": false, "explanation": "个子（gè zi）：gè 与 gài 韵母不同（e/ai），意思是身高。"}, {"text": "牌子", "is_correct": false, "explanation": "牌子（pái zi）：pái 与 gài 声母和声调不同（p/g，第二声/第四声），意思是标记或品牌。"}], "explanations": {"盖子": "正确答案：盖子（gài zi）是盖在容器口上的东西。", "袋子": "袋子（dài zi）：dài 与 gài 声母不同（d/g），意思是装东西的口袋。", "孩子": "孩子（hái zi）：hái 与 gài 声母和声调都不同（h/g，第二声/第四声），意思是儿童。", "个子": "个子（gè zi）：gè 与 gài 韵母不同（e/ai），意思是身高。", "牌子": "牌子（pái zi）：pái 与 gài 声母和声调不同（p/g，第二声/第四声），意思是标记或品牌。"}, "sentence_index": null, "correct_answer": "盖子"}, "level_3": {"options": [{"text": "盖子", "is_correct": true, "explanation": "盖子是桶口上的盖，符合“有盖子的大塑料桶”。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不是塑料桶的部件，与“有……的大塑料桶”不符。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子不是桶的部件，与“有……的大塑料桶”不符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是桶的部件，这句说的是桶上的盖。"}], "explanations": {"盖子": "盖子是桶口上的盖，符合“有盖子的大塑料桶”。", "窗帘": "语义：窗帘不是塑料桶的部件，与“有……的大塑料桶”不符。", "鞋子": "语义：鞋子不是桶的部件，与“有……的大塑料桶”不符。", "手机": "语义：手机不是桶的部件，这句说的是桶上的盖。"}, "sentence_index": 0, "correct_answer": "盖子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拧开瓶子，拿下一根盖子，喝了一口水。", "explanation": "这里应该用〈个〉。“根”只用于细长的东西，盖子不用“根”来数。"}, {"text": "他对着盖子喝了一口水。", "explanation": "这里应该用〈瓶口〉。盖子是盖在口上的东西，喝水要对着瓶口，不能对着盖子。"}, {"text": "他拿盖子剪开了一袋饼干。", "explanation": "这里应该用〈剪刀〉。盖子是盖在容器口上的，不能用来剪东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13046, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "盖子", "is_correct": true, "explanation": "正确答案：盖子（gài zi）是盖在容器口上的东西。"}, {"text": "麦子", "is_correct": false, "explanation": "麦子（mài zi）：mài 与 gài 声母不同（m/g），意思是小麦。"}, {"text": "鸽子", "is_correct": false, "explanation": "鸽子（gē zi）：gē 与 gài 韵母和声调不同（e/ai，第一声/第四声），意思是鸽子这种鸟。"}, {"text": "柜子", "is_correct": false, "explanation": "柜子（guì zi）：guì 与 gài 韵母不同（ui/ai），意思是柜子。"}], "explanations": {"盖子": "正确答案：盖子（gài zi）是盖在容器口上的东西。", "麦子": "麦子（mài zi）：mài 与 gài 声母不同（m/g），意思是小麦。", "鸽子": "鸽子（gē zi）：gē 与 gài 韵母和声调不同（e/ai，第一声/第四声），意思是鸽子这种鸟。", "柜子": "柜子（guì zi）：guì 与 gài 韵母不同（ui/ai），意思是柜子。"}, "sentence_index": null, "correct_answer": "盖子"}, "level_3": {"options": [{"text": "盖子", "is_correct": true, "explanation": "盖子盖在锅上，汤开时会跳动，符合“汤开了，盖子一直在跳”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会因为汤开而跳动。"}, {"text": "瓶盖", "is_correct": false, "explanation": "搭配：瓶盖用来盖瓶子，不盖汤锅，与“汤开了”不搭。"}, {"text": "地板", "is_correct": false, "explanation": "语义：地板不会因为汤开而跳，与语境矛盾。"}], "explanations": {"盖子": "盖子盖在锅上，汤开时会跳动，符合“汤开了，盖子一直在跳”。", "桌子": "语义：桌子不会因为汤开而跳动。", "瓶盖": "搭配：瓶盖用来盖瓶子，不盖汤锅，与“汤开了”不搭。", "地板": "语义：地板不会因为汤开而跳，与语境矛盾。"}, "sentence_index": 6, "correct_answer": "盖子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用盖子搅拌咖啡，慢慢喝。", "explanation": "这里应该用〈勺子〉。盖子是盖东西的，不能用来搅拌咖啡。"}, {"text": "我把咖啡杯放在盖子上，等它凉。", "explanation": "这里应该用〈杯托〉。盖子是盖在杯口上的，不能承托杯子。"}, {"text": "这个盖子是用来装咖啡的。", "explanation": "这里应该用〈杯子〉。盖子是盖在杯口的，不能用来装咖啡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他盖子拧开了。", "corrected_sentence": "他把盖子拧开了。", "error_description": "把字句漏掉“把”：「盖子」是「拧开」的受事，应用“把”提到动词前，说“他把盖子拧开了”，不说“他盖子拧开了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把所有盖子们洗干净了。", "corrected_sentence": "妈妈把所有盖子洗干净了。", "error_description": "复数标记错误：“们”只加在指人的名词后，盖子是物，不能说“盖子们”，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
