INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13047, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "塑料桶是指用塑料材料制成的桶状容器，常用于盛装液体或固体物品。", "primary_collocate": null, "pronunciation": "sù liào tǒng", "ipa": "su˥˩ liɑʊ˥˩ tʰʊŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "首先，准备一个有盖子的大塑料桶，放在阳台或厨房外的角落。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个塑料桶很轻，小孩也提得动。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用塑料桶装了半桶水。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料桶用久了，会变黄变脆。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在塑料桶里种了几棵小葱。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里放着一个红色的塑料桶。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把水倒进了这个塑料桶里。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿着塑料桶去河边洗衣服。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料桶掉在地上，发出很大的声音。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买一个带盖子的塑料桶，可以放米。", "target_word": "塑料桶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个塑料桶", "label": "量词"}, {"form": "塑料水桶", "label": "复合"}], "register": "中性", "sense_fingerprint": "用塑料制成、常用来盛装液体或物品的桶状容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7463c093-f860-4636-af40-85cf1daafb3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13047, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塑料桶", "is_correct": true, "explanation": "正确：有盖子、可以盛放东西的大塑料容器，放在阳台或厨房角落很合理。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不是有盖子的盛放容器，不能这样准备。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“有盖子”不搭配报纸，报纸也不是盛放用的容器。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不能当作有盖子的容器来准备，也不能放在角落里装东西。"}], "explanations": {"塑料桶": "正确：有盖子、可以盛放东西的大塑料容器，放在阳台或厨房角落很合理。", "西瓜": "语义：西瓜是水果，不是有盖子的盛放容器，不能这样准备。", "报纸": "搭配：“有盖子”不搭配报纸，报纸也不是盛放用的容器。", "小猫": "语义：小猫是动物，不能当作有盖子的容器来准备，也不能放在角落里装东西。"}, "sentence_index": 0, "correct_answer": "塑料桶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈上周买了一张塑料桶，放在厨房里。", "explanation": "这里应该用〈个〉。〈张〉用于纸、桌子等平面的东西，塑料桶要用〈个〉。"}, {"text": "我们家新添了一辆塑料桶。", "explanation": "这里应该用〈个〉。〈辆〉用于车辆，塑料桶要用〈个〉。"}, {"text": "他刚买了一本塑料桶，打算装油。", "explanation": "这里应该用〈个〉。〈本〉用于书册，塑料桶要用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塑料桶", "is_correct": true, "explanation": "正确：水要倒进能盛放液体的容器里，塑料桶合适。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不是盛放液体的器具，水倒不进去，句子不成立。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：钢笔不是盛水的器具，“倒进……里”不搭配钢笔。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸不能盛水，“把水倒进纸里”不成立。"}], "explanations": {"塑料桶": "正确：水要倒进能盛放液体的容器里，塑料桶合适。", "雨伞": "语义：雨伞不是盛放液体的器具，水倒不进去，句子不成立。", "钢笔": "搭配：钢笔不是盛水的器具，“倒进……里”不搭配钢笔。", "纸": "语义：纸不能盛水，“把水倒进纸里”不成立。"}, "sentence_index": 6, "correct_answer": "塑料桶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用塑料桶把菜地盖得严严实实。", "explanation": "这里应该用〈塑料布〉。塑料布是薄片，用来覆盖菜地；塑料桶是容器，盖不住一片地。"}, {"text": "老板订了一条塑料桶，用来装货。", "explanation": "这里应该用〈个〉。〈条〉用于细长的东西，如绳子、河流，塑料桶要用〈个〉。"}, {"text": "宿舍里多了一块塑料桶。", "explanation": "这里应该用〈个〉。〈块〉用于块状的东西，塑料桶要用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房的角落里立着一张新塑料桶。", "corrected_sentence": "厨房的角落里立着一个新塑料桶。", "error_description": "量词错误：塑料桶的量词应为“个”，“张”用于纸、桌子等平面的东西，应改为“一个新塑料桶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他塑料桶洗干净了。", "corrected_sentence": "他把塑料桶洗干净了。", "error_description": "把字句漏掉“把”：塑料桶是被洗的对象，须用“把”引出，应说“他把塑料桶洗干净了”，不说“他塑料桶洗干净了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
