INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13048, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用工具或身体旋转着进入或穿过某物。", "primary_collocate": null, "pronunciation": "zuān", "ipa": "tswan˥", "syllable_count": 1, "sentences": [{"text": "桶的底部要钻几个小洞，让多余的水分可以流出来。", "target_word": "钻", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "老鼠很快钻进了墙角的洞里。", "target_word": "钻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫从篱笆下面钻过去了。", "target_word": "钻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，孩子们都钻进帐篷里。", "target_word": "钻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅在木板上钻了两个洞。", "target_word": "钻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他弯下腰，钻过了那道矮门。", "target_word": "钻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛇钻进草丛里，一下子不见了。", "target_word": "钻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大，我们钻进车里躲雨。", "target_word": "钻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在墙上钻洞，声音很大。", "target_word": "钻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他钻到桌子下面去找笔。", "target_word": "钻", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "钻了", "label": "体标（了）"}, {"form": "钻过", "label": "体标（过）"}, {"form": "钻着", "label": "体标（着）"}, {"form": "鑽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：用工具或身体旋转着进入、穿过，如钻洞、钻进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ce08054-efb3-4993-b681-b57e21c2f1ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13048, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "钻", "is_correct": true, "explanation": "钻（zuān，第一声）：用工具或身体旋转着进入或穿过某物，正是这个音。"}, {"text": "专", "is_correct": false, "explanation": "zhuān（第一声）与 zuān 声母不同（zh 与 z），意思是专门。"}, {"text": "酸", "is_correct": false, "explanation": "suān（第一声）与 zuān 声母不同（s 与 z），意思是味道酸。"}, {"text": "尊", "is_correct": false, "explanation": "zūn（第一声）与 zuān 韵母不同（un 与 uan），意思是尊重。"}, {"text": "攥", "is_correct": false, "explanation": "zuàn（第四声）与 zuān 声调不同，意思是紧紧握住。"}], "explanations": {"钻": "钻（zuān，第一声）：用工具或身体旋转着进入或穿过某物，正是这个音。", "专": "zhuān（第一声）与 zuān 声母不同（zh 与 z），意思是专门。", "酸": "suān（第一声）与 zuān 声母不同（s 与 z），意思是味道酸。", "尊": "zūn（第一声）与 zuān 韵母不同（un 与 uan），意思是尊重。", "攥": "zuàn（第四声）与 zuān 声调不同，意思是紧紧握住。"}, "sentence_index": null, "correct_answer": "钻"}, "level_3": {"options": [{"text": "钻", "is_correct": true, "explanation": "钻：用工具或身体旋转着打通，与“几个小洞”搭配，并能使水分流出，正是本句所需。"}, {"text": "跳", "is_correct": false, "explanation": "语义：跳不能在桶底打出小洞，与“小洞”和“让水分流出来”的意思不相容。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能与“小洞”搭配。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“写几个小洞”。"}], "explanations": {"钻": "钻：用工具或身体旋转着打通，与“几个小洞”搭配，并能使水分流出，正是本句所需。", "跳": "语义：跳不能在桶底打出小洞，与“小洞”和“让水分流出来”的意思不相容。", "吃": "搭配：“吃”的对象是食物，不能与“小洞”搭配。", "写": "搭配：“写”的对象是文字，不能说“写几个小洞”。"}, "sentence_index": 0, "correct_answer": "钻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他钻过了一个很大的广场，去找朋友。", "explanation": "这里应该用〈走〉。钻指从狭窄的缝隙里挤过去，开阔的广场不需要挤，只能说“走”。"}, {"text": "他把书钻进了书包。", "explanation": "这里应该用〈放〉。钻只用于人或动物自己旋转着挤过缝隙，书是被人移动的，不能用“钻”。"}, {"text": "他钻过了那片宽阔的湖面，一直到了对岸。", "explanation": "这里应该用〈渡〉。钻指从狭窄的缝隙里挤过去，宽阔的湖面不能用“钻”，渡过湖面要说“渡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13048, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "钻", "is_correct": true, "explanation": "钻（zuān，第一声）：用工具或身体旋转着进入或穿过某物，正是这个音。"}, {"text": "砖", "is_correct": false, "explanation": "zhuān（第一声）与 zuān 声母不同（zh 与 z），意思是砖头。"}, {"text": "遵", "is_correct": false, "explanation": "zūn（第一声）与 zuān 韵母不同（un 与 uan），意思是遵守。"}, {"text": "脏", "is_correct": false, "explanation": "zāng（第一声）与 zuān 韵母不同（少了 u 介音），意思是不干净。"}], "explanations": {"钻": "钻（zuān，第一声）：用工具或身体旋转着进入或穿过某物，正是这个音。", "砖": "zhuān（第一声）与 zuān 声母不同（zh 与 z），意思是砖头。", "遵": "zūn（第一声）与 zuān 韵母不同（un 与 uan），意思是遵守。", "脏": "zāng（第一声）与 zuān 韵母不同（少了 u 介音），意思是不干净。"}, "sentence_index": null, "correct_answer": "钻"}, "level_3": {"options": [{"text": "钻", "is_correct": true, "explanation": "钻：用身体旋转着穿进缝隙，与“蛇”的动作和“草丛”的情境相合，正是本句所需。"}, {"text": "飞", "is_correct": false, "explanation": "语义：蛇不会飞，“飞”与蛇的移动方式不相符。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”需要施事把东西抛出，蛇是自己移动的，不能说“蛇扔进草丛”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能用于蛇的移动，“蛇唱进草丛”无法成立。"}], "explanations": {"钻": "钻：用身体旋转着穿进缝隙，与“蛇”的动作和“草丛”的情境相合，正是本句所需。", "飞": "语义：蛇不会飞，“飞”与蛇的移动方式不相符。", "扔": "配价：“扔”需要施事把东西抛出，蛇是自己移动的，不能说“蛇扔进草丛”。", "唱": "搭配：“唱”不能用于蛇的移动，“蛇唱进草丛”无法成立。"}, "sentence_index": 6, "correct_answer": "钻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把纸团钻进了垃圾桶。", "explanation": "这里应该用〈扔〉。钻指主体自己旋转着穿过，纸团是被人投掷的，不能用“钻”。"}, {"text": "这块石头钻进了山洞里，怎么也拿不出来。", "explanation": "这里应该用〈滚〉。钻要求主体自己旋转挤进，石头不能自己移动，应说“滚”。"}, {"text": "他把花钻进了花瓶里。", "explanation": "这里应该用〈插〉。钻要求主体自己旋转挤过缝隙，花是人放进花瓶的，应说“插”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蚂蚁钻了墙缝里。", "corrected_sentence": "蚂蚁钻进了墙缝里。", "error_description": "趋向补语缺失：“钻”之后应接趋向补语“进”，应说“钻进了墙缝里”，不能省去“进”直接说“钻了墙缝里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猫咪钻了沙发底下。", "corrected_sentence": "猫咪钻进了沙发底下。", "error_description": "趋向补语缺失：“钻”之后应接趋向补语“进”，应说“猫咪钻进了沙发底下”，不能省去“进”直接说“猫咪钻了沙发底下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
