INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13049, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指物体内部或表面上凹陷、穿透的空隙。", "primary_collocate": null, "pronunciation": "dòng", "ipa": "toŋ˥˩", "syllable_count": 1, "sentences": [{"text": "桶的底部要钻几个小洞，让多余的水分可以流出来。", "target_word": "洞", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "墙上有一个洞，风从里面吹进来。", "target_word": "洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的袜子破了一个洞。", "target_word": "洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上有个大洞，开车要小心。", "target_word": "洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在沙滩上挖了一个很深的洞。", "target_word": "洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服上有几个小洞。", "target_word": "洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老鼠在墙角咬了一个洞。", "target_word": "洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋顶有个洞，下雨时会漏水。", "target_word": "洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球网上有个洞，球从里面掉出去了。", "target_word": "洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在冰面上凿了一个洞，准备钓鱼。", "target_word": "洞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "山洞", "label": "复合"}, {"form": "树洞", "label": "复合"}, {"form": "洞口", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：物体上凹陷或穿透的空隙，如墙上有个洞、袜子破了洞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ce08054-efb3-4993-b681-b57e21c2f1ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13049, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "洞", "is_correct": true, "explanation": "洞（dòng，第四声）：物体上凹陷或穿透的空隙，正是这个音。"}, {"text": "东", "is_correct": false, "explanation": "dōng（第一声）与 dòng 声调不同，意思是东方。"}, {"text": "痛", "is_correct": false, "explanation": "tòng（第四声）与 dòng 声母不同（t 与 d），意思是疼痛。"}, {"text": "懂", "is_correct": false, "explanation": "dǒng（第三声）与 dòng 声调不同，意思是明白。"}], "explanations": {"洞": "洞（dòng，第四声）：物体上凹陷或穿透的空隙，正是这个音。", "东": "dōng（第一声）与 dòng 声调不同，意思是东方。", "痛": "tòng（第四声）与 dòng 声母不同（t 与 d），意思是疼痛。", "懂": "dǒng（第三声）与 dòng 声调不同，意思是明白。"}, "sentence_index": null, "correct_answer": "洞"}, "level_3": {"options": [{"text": "洞", "is_correct": true, "explanation": "洞：物体上凹陷或穿透的空隙，与“钻几个小”搭配，并能让水分流出，正是本句所需。"}, {"text": "树", "is_correct": false, "explanation": "语义：桶底要钻出的是小的空隙，“树”不能让水分流出来，与句意不符。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“钻几个小书”搭配不当，书不能被钻出空隙。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不能被钻成空隙让水流出，与句中的情境不符。"}], "explanations": {"洞": "洞：物体上凹陷或穿透的空隙，与“钻几个小”搭配，并能让水分流出，正是本句所需。", "树": "语义：桶底要钻出的是小的空隙，“树”不能让水分流出来，与句意不符。", "书": "搭配：“钻几个小书”搭配不当，书不能被钻出空隙。", "鱼": "语义：鱼不能被钻成空隙让水流出，与句中的情境不符。"}, "sentence_index": 0, "correct_answer": "洞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙上有一颗洞，老鼠常从那里进出。", "explanation": "这里应该用〈个〉。洞用量词“个”，“颗”多用于圆粒状的东西，搭配不当。"}, {"text": "门后有一扇洞，风常从那里吹进来。", "explanation": "这里应该用〈个〉。“扇”用于门窗，不能用来计量洞，搭配不当。"}, {"text": "路边有一条洞，我差点掉进去。", "explanation": "这里应该用〈个〉。洞用量词“个”，“条”多用于长条形的东西，不能用于洞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13049, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "洞", "is_correct": true, "explanation": "洞（dòng，第四声）：物体上凹陷或穿透的空隙，正是这个音。"}, {"text": "弄", "is_correct": false, "explanation": "nòng（第四声）与 dòng 声母不同（n 与 d），意思是摆弄。"}, {"text": "凳", "is_correct": false, "explanation": "dèng（第四声）与 dòng 韵母不同（eng 与 ong），意思是板凳。"}, {"text": "定", "is_correct": false, "explanation": "dìng（第四声）与 dòng 韵母不同（ing 与 ong），意思是确定。"}], "explanations": {"洞": "洞（dòng，第四声）：物体上凹陷或穿透的空隙，正是这个音。", "弄": "nòng（第四声）与 dòng 声母不同（n 与 d），意思是摆弄。", "凳": "dèng（第四声）与 dòng 韵母不同（eng 与 ong），意思是板凳。", "定": "dìng（第四声）与 dòng 韵母不同（ing 与 ong），意思是确定。"}, "sentence_index": null, "correct_answer": "洞"}, "level_3": {"options": [{"text": "洞", "is_correct": true, "explanation": "洞：墙角被咬出的空隙，与“咬了一个”相合，正是本句所需。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“咬”不能与“歌”搭配，“咬了一个歌”无法成立。"}, {"text": "病", "is_correct": false, "explanation": "搭配：“咬”不能与“病”组合，“咬了一个病”无法成立。"}, {"text": "梦", "is_correct": false, "explanation": "搭配：“咬”的对象不能是“梦”，“咬了一个梦”无法成立。"}], "explanations": {"洞": "洞：墙角被咬出的空隙，与“咬了一个”相合，正是本句所需。", "歌": "搭配：“咬”不能与“歌”搭配，“咬了一个歌”无法成立。", "病": "搭配：“咬”不能与“病”组合，“咬了一个病”无法成立。", "梦": "搭配：“咬”的对象不能是“梦”，“咬了一个梦”无法成立。"}, "sentence_index": 6, "correct_answer": "洞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学针灸要先记住人体的洞位。", "explanation": "这里应该用〈穴〉。“穴位”是针灸的固定说法，指施针的部位，不能说“洞位”。"}, {"text": "墙角有一朵洞，老鼠常从那里进出。", "explanation": "这里应该用〈个〉。“朵”只用于花朵，洞要用量词“个”，搭配不当。"}, {"text": "屋顶上有一块洞，雨水常从那里漏进来。", "explanation": "这里应该用〈个〉。洞用量词“个”，“块”多用于块状的东西，搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙角有三条洞，老鼠常从那里进出。", "corrected_sentence": "墙角有三个洞，老鼠常从那里进出。", "error_description": "错误形式“三条洞”，正确形式“三个洞”。洞用量词“个”，“条”用于长条形的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子角落有一个很大洞的。", "corrected_sentence": "院子角落有一个很大的洞。", "error_description": "错误形式“很大洞的”，正确形式“很大的洞”。修饰语“很大”和助词“的”应放在名词之前，“的”须紧接修饰语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
