INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13050, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从封闭空间中移动到外面。", "primary_collocate": null, "pronunciation": "chū lái", "ipa": "tʂʰu˥ lai˧˥", "syllable_count": 2, "sentences": [{"text": "桶的底部要钻几个小洞，让多余的水分可以流出来。", "target_word": "出来", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他从房间里出来了。", "target_word": "出来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你在里面吗？快出来吧！", "target_word": "出来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门开了，一个小孩走出来。", "target_word": "出来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从水里爬出来，浑身都湿了。", "target_word": "出来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗从箱子里跑出来了。", "target_word": "出来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车停了，大家都从车里出来。", "target_word": "出来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从商店里走出来，手里提着东西。", "target_word": "出来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从办公室里出来，叫我们进去。", "target_word": "出来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水从管子里流出来了。", "target_word": "出来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "出来了", "label": "体标（了）"}, {"form": "出来过", "label": "体标（过）"}, {"form": "出來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词/趋向：从里面移动到外面，如走出来、流出来、跑出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ce08054-efb3-4993-b681-b57e21c2f1ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13050, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出来", "is_correct": true, "explanation": "“流出来”指水从桶底的小洞向外流，“出来”是表示朝外移动的补语，符合句意。"}, {"text": "进去", "is_correct": false, "explanation": "语义：进去指向内移动，与水从桶底小洞向外流的方向相反。"}, {"text": "进来", "is_correct": false, "explanation": "语义：进来以说话人为参照向内移动，与“水分从桶底流出”的语境相矛盾。"}, {"text": "上去", "is_correct": false, "explanation": "搭配：“流上去”指水向上流，不符合水从桶底漏出的常理，搭配不当。"}], "explanations": {"出来": "“流出来”指水从桶底的小洞向外流，“出来”是表示朝外移动的补语，符合句意。", "进去": "语义：进去指向内移动，与水从桶底小洞向外流的方向相反。", "进来": "语义：进来以说话人为参照向内移动，与“水分从桶底流出”的语境相矛盾。", "上去": "搭配：“流上去”指水向上流，不符合水从桶底漏出的常理，搭配不当。"}, "sentence_index": 0, "correct_answer": "出来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚从外面出来，身上还带着雨。", "explanation": "这里应该用〈进来〉。出来表示从里往外，而“从外面”进入屋里要用进来。"}, {"text": "他往屋里出来，去厨房拿了碗。", "explanation": "这里应该用〈进去〉。出来表示从里往外，“往屋里”是向内移动，要用进去。"}, {"text": "他沿着楼梯往楼上出来，找到了妈妈。", "explanation": "这里应该用〈上去〉。出来表示从里往外，“往楼上”是向上移动，要用上去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13050, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出来", "is_correct": true, "explanation": "“从车里出来”指大家从车内走到车外，与“车停了”的语境一致。"}, {"text": "上来", "is_correct": false, "explanation": "搭配：“从车里上来”指从车内向上走，车里的人不能这样移动，搭配不当。"}, {"text": "躺下", "is_correct": false, "explanation": "语义：“躺下”指躺卧，与车停后人从车内走到车外的动作不符。"}, {"text": "进去", "is_correct": false, "explanation": "语义：“进去”指向内移动，人已在车里，不能从车里“进去”。"}], "explanations": {"出来": "“从车里出来”指大家从车内走到车外，与“车停了”的语境一致。", "上来": "搭配：“从车里上来”指从车内向上走，车里的人不能这样移动，搭配不当。", "躺下": "语义：“躺下”指躺卧，与车停后人从车内走到车外的动作不符。", "进去": "语义：“进去”指向内移动，人已在车里，不能从车里“进去”。"}, "sentence_index": 6, "correct_answer": "出来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从昏迷中醒出来了，还有点糊涂。", "explanation": "这里应该用〈过来〉。醒来、恢复知觉要用“过来”，“出来”只表示从里往外移动，不能表示恢复状态。"}, {"text": "这件事过后，他的心情慢慢好出来了。", "explanation": "这里应该用〈起来〉。表示状态由差变好、开始变化要用“起来”，不能用“出来”。"}, {"text": "听到消息后，他一下子冷静出来了。", "explanation": "这里应该用〈下来〉。表示情绪由激动转为平静要用“下来”，“出来”不能表示这种变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他慢慢地从水里走出来来了。", "corrected_sentence": "他慢慢地从水里走出来了。", "error_description": "重复：“出来”的“来”字被重复，应说“他慢慢地从水里走出来了”，不能说“走出来来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从屋里的出来，走到院子里。", "corrected_sentence": "他从屋里出来，走到院子里。", "error_description": "多余的“的”：“从屋里”后直接接趋向动词“出来”，中间不能加“的”，应说“他从屋里出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
