INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13051, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指物质所具有的能使舌头得到某种味觉的特性，也比喻事物带给人的某种感受或体验。", "primary_collocate": null, "pronunciation": "wèi dao", "ipa": "weɪ˥˩ tɑʊ", "syllable_count": 2, "sentences": [{"text": "在桶里先放一层干的材料，比如落叶或撕碎的纸箱，这样可以防止味道太大。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这道菜的味道很好。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个咖啡的味道有点苦，我加了一点糖。", "target_word": "味道", "complexity_tier": "T3", "furigana": "wèi dao", "sentence_source": "generated"}, {"text": "这个汤的味道太咸了。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这家店面包的味道。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块蛋糕的味道很甜，孩子吃得很开心。", "target_word": "味道", "complexity_tier": "T3", "furigana": "wèi dao", "sentence_source": "generated"}, {"text": "妈妈做的饺子，味道和以前一样。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个橘子的味道又甜又酸，很特别。", "target_word": "味道", "complexity_tier": "T3", "furigana": "wèi dao", "sentence_source": "generated"}, {"text": "这条老街很有生活的味道。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌有一种怀旧的味道。", "target_word": "味道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股味道", "label": "量词"}, {"form": "一种味道", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，指食物的味或气味，也比喻事物给人的感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4db93df3-ec4d-4ac1-b668-c97e971d1734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13051, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味道", "is_correct": true, "explanation": "味道：指气味，与“防止”异味的语境相合。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”指听觉，与桶中异味的防止无关。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“太大”来形容，应说“太深”。"}, {"text": "力气", "is_correct": false, "explanation": "语义：“力气”指人的体力，与桶中的气味无关。"}], "explanations": {"味道": "味道：指气味，与“防止”异味的语境相合。", "声音": "语义：“声音”指听觉，与桶中异味的防止无关。", "颜色": "搭配：“颜色”不能用“太大”来形容，应说“太深”。", "力气": "语义：“力气”指人的体力，与桶中的气味无关。"}, "sentence_index": 0, "correct_answer": "味道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤的味道太烫了。", "explanation": "这里应该用〈温度〉。冷热要用“温度”，“味道”不能用“太烫”来形容。"}, {"text": "这块蛋糕的味道很松软。", "explanation": "这里应该用〈口感〉。松软、有嚼劲等质地要用“口感”，“味道”不能用来形容质地。"}, {"text": "这台电脑的味道很快。", "explanation": "这里应该用〈速度〉。“快”形容的是速度，味道不能用快慢来形容，应说“运行速度很快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13051, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": true, "explanation": "味道：指食物或事物给人的感受，与“和以前一样”相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：饺子没有年龄，“年龄和以前一样”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人或动物的高度，不能用于饺子。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”用于人，不能说饺子的“脾气”。"}], "explanations": {"味道": "味道：指食物或事物给人的感受，与“和以前一样”相合。", "年龄": "语义：饺子没有年龄，“年龄和以前一样”说不通。", "身高": "语义：“身高”指人或动物的高度，不能用于饺子。", "脾气": "搭配：“脾气”用于人，不能说饺子的“脾气”。"}, "sentence_index": 6, "correct_answer": "味道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的味道很鲜艳。", "explanation": "这里应该用〈颜色〉。鲜艳是颜色的特征，“味道”不能用“鲜艳”来形容。"}, {"text": "这盏灯的味道很高。", "explanation": "这里应该用〈亮度〉。描述明暗程度要用“亮度”，“味道”不能用“高”来衡量。"}, {"text": "这根面条的味道有一米。", "explanation": "这里应该用〈长度〉。说有多长要用“长度”，“味道”不能用数字来量化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这瓶酱油有一只浓郁的味道。", "corrected_sentence": "这瓶酱油有一股浓郁的味道。", "error_description": "错误：“味道”的量词用了“只”。“只”用于动物或成对物品中的一个，“味道”应用“一股”或“一种”，正确说法是“一股浓郁的味道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13051, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这杯茶的味道了很清香。", "corrected_sentence": "这杯茶的味道很清香。", "error_description": "错误：名词“味道”后面加了“了”。“了”不能用在名词后，正确说法是“这杯茶的味道很清香”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13052, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13052, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13052, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将某物放入某个容器或空间之内。", "primary_collocate": null, "pronunciation": "fàng jìn qù", "ipa": "fɑŋ˥˩ tɕin˥˩ tɕʰy˥˩", "syllable_count": 3, "sentences": [{"text": "然后，把每天的厨余放进去，再盖上一层干材料。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "请把苹果放进去，再关上冰箱门。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开书包，把水杯放进去了。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤做好以后，把盐放进去再尝一尝。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把洗好的衣服放进去，然后按下洗衣机的开关。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水开了，你把面条放进去吧。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子很大，可以把玩具都放进去。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手机放进去，然后关上了抽屉。", "target_word": "放进去", "complexity_tier": "T3", "furigana": "tā bǎ shǒu jī fàng jìn qù, rán hòu guān shàng le chōu ti.", "sentence_source": "generated"}, {"text": "盘子里还有空位，再放进去一块蛋糕吧。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烤箱热了以后，再把面包放进去。", "target_word": "放进去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放进去了", "label": "体标（了）"}, {"form": "放进去过", "label": "体标（过）"}, {"form": "放得进去", "label": "可能补语"}, {"form": "放进来", "label": "趋向相对形式"}], "register": "中性", "sense_fingerprint": "把东西放入容器或空间里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ce08054-efb3-4993-b681-b57e21c2f1ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放进去", "is_correct": true, "explanation": "“放进去”指把厨余放入容器内，与后文“再盖上一层干材料”的做法相合。"}, {"text": "放出去", "is_correct": false, "explanation": "语义：放出去指向外放，与把厨余放入容器的动作方向相反。"}, {"text": "放进来", "is_correct": false, "explanation": "语义：放进来以说话人为参照，与把厨余放入容器的语境不合。"}, {"text": "放回去", "is_correct": false, "explanation": "搭配：“放回去”指归还原处，厨余并非原先放在容器里，搭配不当。"}], "explanations": {"放进去": "“放进去”指把厨余放入容器内，与后文“再盖上一层干材料”的做法相合。", "放出去": "语义：放出去指向外放，与把厨余放入容器的动作方向相反。", "放进来": "语义：放进来以说话人为参照，与把厨余放入容器的语境不合。", "放回去": "搭配：“放回去”指归还原处，厨余并非原先放在容器里，搭配不当。"}, "sentence_index": 0, "correct_answer": "放进去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个建议我会放进去考虑，你先别急。", "explanation": "这里的“放进去”表示纳入考虑，属于另一义项，不是把东西放入某个地方。"}, {"text": "他把假期放进去，一直工作到深夜。", "explanation": "这里的“放进去”要求把具体东西放入容器、空间或范围，“假期”是时间段，不能放进去，应说〈安排〉。"}, {"text": "他把一年的时光都放进去，结果一事无成。", "explanation": "这里的“放进去”表示把具体事物放入某处，“时光”不能放入容器，应说〈投入〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放进去", "is_correct": true, "explanation": "“放进去”指把玩具装入盒子内，与“盒子很大，可以装玩具”的语境相符。"}, {"text": "放出来", "is_correct": false, "explanation": "语义：放出来指取出或释放，与把玩具装入盒中的语境相反。"}, {"text": "放上去", "is_correct": false, "explanation": "语义：放上去指放在表面，不是装入盒内，与“盒子很大”的语境不符。"}, {"text": "放下去", "is_correct": false, "explanation": "搭配：“放下去”一般指往下放低，不用于把玩具装进盒子里，搭配不当。"}], "explanations": {"放进去": "“放进去”指把玩具装入盒子内，与“盒子很大，可以装玩具”的语境相符。", "放出来": "语义：放出来指取出或释放，与把玩具装入盒中的语境相反。", "放上去": "语义：放上去指放在表面，不是装入盒内，与“盒子很大”的语境不符。", "放下去": "搭配：“放下去”一般指往下放低，不用于把玩具装进盒子里，搭配不当。"}, "sentence_index": 6, "correct_answer": "放进去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直把这句话放进去，从来不对别人说。", "explanation": "这里的“放进去”表示放入具体的容器或空间，此处用于抽象的话语，应说〈记在心里〉。"}, {"text": "他把一整天的工作都放进去，直到深夜才回家。", "explanation": "这里的“放进去”不能用于时段，“一整天的工作”不能放入容器，应说〈完成〉。"}, {"text": "他把这个问题放进去，结果谁也没有解决。", "explanation": "这里的“放进去”表示放入某处，“问题”不能放入容器，应说〈提出〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把书把放进去，然后关上了柜门。", "corrected_sentence": "他把书放进去，然后关上了柜门。", "error_description": "“把”重复：处置式只用一个“把”，应说“他把书放进去”，不能在“把”后再加“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他钥匙放进去，然后锁上了抽屉。", "corrected_sentence": "他把钥匙放进去，然后锁上了抽屉。", "error_description": "缺少“把”：处置式“把钥匙放进去”需要用“把”引出被处置的宾语，省去“把”不合规范。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
