INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13053, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指柄较长的勺子，常用于舀取汤、粥等液体食物。", "primary_collocate": null, "pronunciation": "cháng sháo", "ipa": "ʈʂʰɑŋ˧˥ ʂɑʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "堆肥的过程中，需要每周用铲子或长勺搅拌一次。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "妈妈用长勺给我们盛汤。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅很深，要用长勺才能舀到底下的粥。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的墙上挂着一把长勺。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起长勺，在大锅里舀了一碗汤。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把长勺的柄很长，手不会碰到热汤。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食堂师傅用长勺给每个人盛粥。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火锅里的菜可以用长勺捞出来。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把长勺洗干净，放回厨房的抽屉里。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用长勺舀起一点汤，尝了尝味道。", "target_word": "长勺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一把长勺", "label": "量词搭配"}, {"form": "長勺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "柄很长、用来舀汤或粥的勺子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ce08054-efb3-4993-b681-b57e21c2f1ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13053, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "长勺", "is_correct": true, "explanation": "长勺：柄很长、用来舀汤或粥的勺子。"}, {"text": "糖勺", "is_correct": false, "explanation": "声母不同：táng 的 t 与 cháng 的 ch 不同，糖勺是舀糖用的勺子。"}, {"text": "长哨", "is_correct": false, "explanation": "声调不同：shào（第四声）与 sháo（第二声）只差声调，长哨是长长的哨声。"}, {"text": "掌勺", "is_correct": false, "explanation": "声母和声调都不同：zhǎng（第三声）与 cháng（第二声），掌勺指主持烹调。"}], "explanations": {"长勺": "长勺：柄很长、用来舀汤或粥的勺子。", "糖勺": "声母不同：táng 的 t 与 cháng 的 ch 不同，糖勺是舀糖用的勺子。", "长哨": "声调不同：shào（第四声）与 sháo（第二声）只差声调，长哨是长长的哨声。", "掌勺": "声母和声调都不同：zhǎng（第三声）与 cháng（第二声），掌勺指主持烹调。"}, "sentence_index": null, "correct_answer": "长勺"}, "level_3": {"options": [{"text": "长勺", "is_correct": true, "explanation": "正确：长勺是柄很长的勺子，可以用来搅堆肥，与“铲子”并列作工具。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是搅拌的工具，不能用来搅堆肥。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚用来扫地，不能用来搅动堆肥。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：花瓶是盛花的器皿，不能与“铲子或……搅拌”的工具并列。"}], "explanations": {"长勺": "正确：长勺是柄很长的勺子，可以用来搅堆肥，与“铲子”并列作工具。", "手机": "语义：手机不是搅拌的工具，不能用来搅堆肥。", "扫帚": "语义：扫帚用来扫地，不能用来搅动堆肥。", "花瓶": "搭配：花瓶是盛花的器皿，不能与“铲子或……搅拌”的工具并列。"}, "sentence_index": 0, "correct_answer": "长勺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用长勺把钉子钉进了墙里。", "explanation": "这里应该用〈锤子〉。把钉子钉进墙要用锤子敲打，长勺是盛汤的勺子，不能用来敲钉子。"}, {"text": "他用长勺把菜切成了丝。", "explanation": "这里应该用〈菜刀〉。切菜要用刀，长勺是盛汤的勺子，不能用来切东西。"}, {"text": "他用长勺把窗户擦得很亮。", "explanation": "这里应该用〈抹布〉。擦窗户要用抹布，长勺是盛汤的勺子，不能用来擦东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13053, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长勺", "is_correct": true, "explanation": "正确：长勺是盛粥的勺子，师傅用它给每个人盛粥。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套不是盛粥的器具，不能用来给人盛粥。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能用来盛粥。"}, {"text": "拖把", "is_correct": false, "explanation": "搭配：拖把是清洁用具，不能与“给每个人盛粥”搭配。"}], "explanations": {"长勺": "正确：长勺是盛粥的勺子，师傅用它给每个人盛粥。", "手套": "语义：手套不是盛粥的器具，不能用来给人盛粥。", "书包": "语义：书包不能用来盛粥。", "拖把": "搭配：拖把是清洁用具，不能与“给每个人盛粥”搭配。"}, "sentence_index": 6, "correct_answer": "长勺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用长勺把蛋清打发，做了一个蛋糕。", "explanation": "这里应该用〈打蛋器〉。打发蛋清要靠打蛋器快速搅打，长勺打不出泡沫。"}, {"text": "他用长勺把烤好的面包夹出来，放在盘子里。", "explanation": "这里应该用〈夹子〉。夹子能夹住面包，长勺是勺子，夹不住面包。"}, {"text": "他用长勺给自己梳头。", "explanation": "这里应该用〈梳子〉。梳头要用梳子，长勺是盛汤的勺子，不能用来梳理头发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13053, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从柜子里拿出一条长勺。", "corrected_sentence": "他从柜子里拿出一把长勺。", "error_description": "错误形式：“一条长勺”；正确形式：“一把长勺”。长勺带柄，量词用“把”；“条”用于细长的东西，不用于勺子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13053, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他长勺给弟弟盛了一碗汤。", "corrected_sentence": "他用长勺给弟弟盛了一碗汤。", "error_description": "错误形式：“他长勺给弟弟盛了一碗汤”；正确形式：“他用长勺给弟弟盛了一碗汤”。表示工具要用“用”引出，“长勺”前漏了“用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
