INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13054, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用工具或手在液体或混合物中反复转动，使成分均匀混合。", "primary_collocate": null, "pronunciation": "jiǎo bàn", "ipa": "tɕjɑʊ̯˨˩˦ pan˥˩", "syllable_count": 2, "sentences": [{"text": "堆肥的过程中，需要每周用铲子或长勺搅拌一次。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "煮面的时候，要不停地搅拌，面才不会粘锅。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把鸡蛋和牛奶放在一起搅拌。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用勺子搅拌着杯子里的咖啡。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水泥要先搅拌均匀，才能用来盖墙。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做蛋糕前，先把面粉和糖搅拌一下。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤快好了，你再搅拌几下吧。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搅拌了很久，可是糖还没有化开。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶茶放了糖，先搅拌一下再喝。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在用铁棒搅拌锅里的热糖。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搅拌了", "label": "体标（了）"}, {"form": "搅拌着", "label": "体标（着）"}, {"form": "搅拌过", "label": "体标（过）"}, {"form": "搅拌搅拌", "label": "重叠"}, {"form": "搅拌机", "label": "复合"}, {"form": "攪拌", "label": "繁体"}], "register": "中性", "sense_fingerprint": "反复转动使混合物成分均匀", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ce08054-efb3-4993-b681-b57e21c2f1ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13054, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搅拌", "is_correct": true, "explanation": "正确：搅拌是用工具反复转动、使堆肥均匀混合，可以与“铲子或长勺”搭配。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热烹饪，堆肥的过程不是用来煮的，句子不通。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”要用刀类工具，“铲子或长勺”不是切的工具，不能搭配。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要带可以吃的宾语，堆肥不能吃，这里没有合适的宾语。"}], "explanations": {"搅拌": "正确：搅拌是用工具反复转动、使堆肥均匀混合，可以与“铲子或长勺”搭配。", "煮": "语义：“煮”是加热烹饪，堆肥的过程不是用来煮的，句子不通。", "切": "搭配：“切”要用刀类工具，“铲子或长勺”不是切的工具，不能搭配。", "吃": "配价：“吃”要带可以吃的宾语，堆肥不能吃，这里没有合适的宾语。"}, "sentence_index": 0, "correct_answer": "搅拌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "喝之前，先把瓶子搅拌一下。", "explanation": "这里应该用〈摇〉。搅拌作用于瓶中的内容物，不能直接用于瓶子本身；晃动瓶子要用“摇”。"}, {"text": "风把湖面搅拌，泛起了一圈圈波纹。", "explanation": "这里应该用〈搅动〉。搅拌指人或工具把材料混合，风吹动湖面不能说搅拌。"}, {"text": "出门前，把外套搅拌一下。", "explanation": "这里应该用〈抖〉。抖是把衣服轻轻甩动，外套不是可以搅拌的混合物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13054, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搅拌", "is_correct": true, "explanation": "正确：搅拌是反复转动使汤混合，与“汤快好了，你再……几下”相配。"}, {"text": "扫", "is_correct": false, "explanation": "语义：“扫”是清除灰尘，不能用来搅动汤。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是抹去污物，汤不能用擦的方式来做。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”的对象不能是汤，“拍汤”不搭配。"}], "explanations": {"搅拌": "正确：搅拌是反复转动使汤混合，与“汤快好了，你再……几下”相配。", "扫": "语义：“扫”是清除灰尘，不能用来搅动汤。", "擦": "语义：“擦”是抹去污物，汤不能用擦的方式来做。", "拍": "搭配：“拍”的对象不能是汤，“拍汤”不搭配。"}, "sentence_index": 6, "correct_answer": "搅拌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用抹布搅拌桌上的水。", "explanation": "这里应该用〈擦〉。擦是抹去桌上的水；搅拌是在混合物中转动，不能用于擦水。"}, {"text": "他把书搅拌了一下，想找出夹在里面的照片。", "explanation": "这里应该用〈翻〉。翻书是把书页翻动找东西；搅拌是在混合物中转动，不能用于书。"}, {"text": "拿扫帚把地上的灰搅拌干净。", "explanation": "这里应该用〈扫〉。扫是清除灰尘，搅拌不能用来清扫地面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把饼干粉和黄油搅拌的在一起。", "corrected_sentence": "请把饼干粉和黄油搅拌在一起。", "error_description": "多余的“的”：“搅拌”与补语“在一起”之间不能加“的”，应说“请把饼干粉和黄油搅拌在一起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把汤搅拌拌，再尝一口。", "corrected_sentence": "他把汤搅拌搅拌，再尝一口。", "error_description": "错误形式：“搅拌拌”；正确形式：“搅拌搅拌”。双音节动词重叠应为“ABAB”式，即“搅拌搅拌”，不能只重复后一个字。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13056, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出来", "is_correct": true, "explanation": "与“进去”构成反义，指从里面到外面。"}, {"text": "起来", "is_correct": false, "explanation": "语义：“起来”表示向上或开始，与“进去”不构成反义。"}, {"text": "过来", "is_correct": false, "explanation": "语义：“过来”表示朝说话人一侧移动，不是“进去”的反义词。"}, {"text": "下来", "is_correct": false, "explanation": "语义：“下来”表示从高处向低处，与“进去”不构成反义。"}], "correct_answer": "出来", "explanations": {"出来": "与“进去”构成反义，指从里面到外面。", "起来": "语义：“起来”表示向上或开始，与“进去”不构成反义。", "过来": "语义：“过来”表示朝说话人一侧移动，不是“进去”的反义词。", "下来": "语义：“下来”表示从高处向低处，与“进去”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13056, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出来", "is_correct": true, "explanation": "与“进去”构成反义，指从里面到外面。"}, {"text": "上来", "is_correct": false, "explanation": "语义：“上来”表示向上或朝说话人一侧移动，不是“进去”的反义词。"}, {"text": "回来", "is_correct": false, "explanation": "语义：“回来”表示返回原处，不是“进去”的反义词。"}, {"text": "走开", "is_correct": false, "explanation": "语义：“走开”表示离去，与“进去”不构成反义。"}], "correct_answer": "出来", "explanations": {"出来": "与“进去”构成反义，指从里面到外面。", "上来": "语义：“上来”表示向上或朝说话人一侧移动，不是“进去”的反义词。", "回来": "语义：“回来”表示返回原处，不是“进去”的反义词。", "走开": "语义：“走开”表示离去，与“进去”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13056, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放进某个封闭的空间里", "primary_collocate": null, "pronunciation": "jìn qù", "ipa": "tɕin˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "然后，把每天的厨余放进去，再盖上一层干材料。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "饼干盒快满了，你把这几块饼干也放进去吧。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "包还有地方，你把水杯装进去吧。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子打开着，把礼物放进去就行。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水壶空了，再把热水倒进去。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洞里有空位，把这块小石头塞进去。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱很空，把牛奶都放进去吧。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤太淡了，再把一点盐放进去。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子很大，衣服都能装进去。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信写好了，快把它放进去再封口。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放进去", "label": "复合"}, {"form": "装进去", "label": "复合"}, {"form": "倒进去", "label": "复合"}], "register": "中性", "sense_fingerprint": "接在放、装、倒、塞后，表示把东西放入箱子、包等封闭空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '646a9811-93f6-4f9b-bfec-56a7c7ff221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13056, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进去", "is_correct": true, "explanation": "正确：进去（jìn qù）表示把东西放入某个空间。"}, {"text": "进取", "is_correct": false, "explanation": "qǔ（第三声）与 qù（第四声）声调不同，进取意思是努力向上。"}, {"text": "禁区", "is_correct": false, "explanation": "qū（第一声）与 qù（第四声）声调不同，禁区意思是禁止进入的区域。"}, {"text": "进气", "is_correct": false, "explanation": "qì 与 qù 的韵母不同（i 与 ü），进气意思是空气等进入发动机或身体。"}, {"text": "金曲", "is_correct": false, "explanation": "jīn qǔ 两个音节的声调都与 jìn qù 不同，金曲意思是流行歌曲。"}], "explanations": {"进去": "正确：进去（jìn qù）表示把东西放入某个空间。", "进取": "qǔ（第三声）与 qù（第四声）声调不同，进取意思是努力向上。", "禁区": "qū（第一声）与 qù（第四声）声调不同，禁区意思是禁止进入的区域。", "进气": "qì 与 qù 的韵母不同（i 与 ü），进气意思是空气等进入发动机或身体。", "金曲": "jīn qǔ 两个音节的声调都与 jìn qù 不同，金曲意思是流行歌曲。"}, "sentence_index": null, "correct_answer": "进去"}, "level_3": {"options": [{"text": "进去", "is_correct": true, "explanation": "正确：把厨余放入堆肥容器内部，应用“进去”。"}, {"text": "出去", "is_correct": false, "explanation": "语义：“出去”指从里往外，与把厨余放入堆肥的动作相反。"}, {"text": "出来", "is_correct": false, "explanation": "语义：“出来”指从里面出来，不能表示把厨余放入。"}, {"text": "过去", "is_correct": false, "explanation": "搭配：“放过去”需要说明放到哪一边，这句没有这样的地点。"}], "explanations": {"进去": "正确：把厨余放入堆肥容器内部，应用“进去”。", "出去": "语义：“出去”指从里往外，与把厨余放入堆肥的动作相反。", "出来": "语义：“出来”指从里面出来，不能表示把厨余放入。", "过去": "搭配：“放过去”需要说明放到哪一边，这句没有这样的地点。"}, "sentence_index": 0, "correct_answer": "进去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把书放进去桌子上。", "explanation": "这里应该用〈放在〉。“进去”表示放入封闭的空间，桌面是开放的，应说“放在桌子上”。"}, {"text": "我把画挂进去墙上。", "explanation": "这里应该用〈挂在〉。“进去”表示放入封闭的空间，墙面是开放的，应说“挂在墙上”。"}, {"text": "我把被子铺进去床上。", "explanation": "这里应该用〈铺在〉。“进去”表示放入封闭的空间，床面是开放的，应说“铺在床上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进去", "is_correct": true, "explanation": "正确：冰箱里放入牛奶，应用“进去”表示放入封闭空间。"}, {"text": "上去", "is_correct": false, "explanation": "搭配：“放上去”指放到较高处，冰箱里放牛奶通常说“放进去”，句意不自然。"}, {"text": "下去", "is_correct": false, "explanation": "语义：“下去”表示向下移动，不说把牛奶放下去。"}, {"text": "出去", "is_correct": false, "explanation": "语义：“放出去”指放到外面，与往空冰箱里放牛奶的句意相反。"}], "explanations": {"进去": "正确：冰箱里放入牛奶，应用“进去”表示放入封闭空间。", "上去": "搭配：“放上去”指放到较高处，冰箱里放牛奶通常说“放进去”，句意不自然。", "下去": "语义：“下去”表示向下移动，不说把牛奶放下去。", "出去": "语义：“放出去”指放到外面，与往空冰箱里放牛奶的句意相反。"}, "sentence_index": 6, "correct_answer": "进去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在屋里，你把东西放进去吧。", "explanation": "这里应该用〈放进来〉。说话人在屋里，叫对方从外面把东西送进来时要用“进来”，不用“进去”。"}, {"text": "我把会议放进去下周了。", "explanation": "这里应该用〈安排〉。“进去”表示放入封闭的空间，时间不是空间，应说“把会议安排在下周”。"}, {"text": "他把名字贴进去大门上。", "explanation": "这里应该用〈贴在〉。“进去”表示放入封闭的空间，大门表面是开放的，应说“贴在大门上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "垃圾袋满了，你把它扔去进去吧。", "corrected_sentence": "垃圾袋满了，你把它扔进去吧。", "error_description": "错误形式：“扔去进去”。正确形式：“扔进去”。“去”不能放在动词“扔”和补语“进去”之间，多余的“去”要删掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个纸箱还空着，你把书放进去着吧。", "corrected_sentence": "这个纸箱还空着，你把书放进去吧。", "error_description": "错误形式：“进去着”。正确形式：“进去”。“着”表示动作持续，不能加在趋向补语“进去”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
