INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13057, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示对数量、时间、程度等不精确的估计或推测。", "primary_collocate": null, "pronunciation": "dà gài", "ipa": "ta˥˩ kaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "大概过一个月到两个月，原来的厨余就会变成深褐色、松软的土壤。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "从我家到学校，大概要二十分钟。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班大概有三十个学生。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今年大概四十岁。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们大概八点出发，你别迟到。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书大概二百页。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个菜大概要一个小时。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里大概坐了五十个人。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机大概三点半到北京。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服大概要两百块钱。", "target_word": "大概", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，用在数量、时间前，表示大约、不精确的估计", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4db93df3-ec4d-4ac1-b668-c97e971d1734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13057, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大概", "is_correct": true, "explanation": "大概：副词，表示对数量、时间等不精确的估计，如“大概二十分钟”。"}, {"text": "大干", "is_correct": false, "explanation": "韵母不同（ai 与 an），大干指用力去干，意思不同。"}, {"text": "大纲", "is_correct": false, "explanation": "韵母与声调都不同（第四声与第一声），大纲指文件或课程的提要。"}, {"text": "大改", "is_correct": false, "explanation": "声调不同（第三声与第四声），大改指大规模修改。"}, {"text": "大港", "is_correct": false, "explanation": "韵母与声调不同（第三声与第四声），大港指大型港口。"}], "explanations": {"大概": "大概：副词，表示对数量、时间等不精确的估计，如“大概二十分钟”。", "大干": "韵母不同（ai 与 an），大干指用力去干，意思不同。", "大纲": "韵母与声调都不同（第四声与第一声），大纲指文件或课程的提要。", "大改": "声调不同（第三声与第四声），大改指大规模修改。", "大港": "韵母与声调不同（第三声与第四声），大港指大型港口。"}, "sentence_index": null, "correct_answer": "大概"}, "level_3": {"options": [{"text": "大概", "is_correct": true, "explanation": "大概：表示不精确的估计，与“一个月到两个月”这种时长估计相合。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快发生，与“一个月到两个月”的较长时段矛盾。"}, {"text": "刚刚", "is_correct": false, "explanation": "搭配：“刚刚”后接的是刚发生不久的事，不能接“过一个月到两个月”这种时段。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“就会变成”这种必然的过程矛盾。"}], "explanations": {"大概": "大概：表示不精确的估计，与“一个月到两个月”这种时长估计相合。", "马上": "语义：“马上”表示很快发生，与“一个月到两个月”的较长时段矛盾。", "刚刚": "搭配：“刚刚”后接的是刚发生不久的事，不能接“过一个月到两个月”这种时段。", "偶尔": "语义：“偶尔”表示不常发生，与“就会变成”这种必然的过程矛盾。"}, "sentence_index": 0, "correct_answer": "大概"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师给我们讲了课文的大概。", "explanation": "这里的“大概”是名词，指主要内容或梗概，不是表示不精确估计的副词；句子讲的是内容概要，与数量估计无关。"}, {"text": "这笔钱大概是一千块，一分不差。", "explanation": "这里应该用〈恰好〉。“一分不差”说明数目精确，与“大概”的估计矛盾，应说“恰好是一千块”。"}, {"text": "火车大概在八点整出发。", "explanation": "这里应该用〈准时〉。“八点整”已是精确的时刻，“大概”不能与之同用，应说“火车准时在八点整出发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13057, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大概", "is_correct": true, "explanation": "大概：表示对时长的不精确估计，与“要一个小时”相合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与“要一个小时”的时长矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多用于否定句或习惯，不能直接修饰“要一个小时”。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，不能与“要一个小时”这种时长组合。"}], "explanations": {"大概": "大概：表示对时长的不精确估计，与“要一个小时”相合。", "立刻": "语义：“立刻”表示马上发生，与“要一个小时”的时长矛盾。", "从来": "搭配：“从来”多用于否定句或习惯，不能直接修饰“要一个小时”。", "正在": "体貌：“正在”表示动作进行中，不能与“要一个小时”这种时长组合。"}, "sentence_index": 6, "correct_answer": "大概"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大概是中国人，护照上写得清清楚楚。", "explanation": "这里不该用〈大概〉。“大概”表示不确定的估计，而国籍有护照为证，属确定事实，应直接说明，不能用估计修饰。"}, {"text": "这个月的房租大概规定为两千块。", "explanation": "这里不该用〈大概〉。“大概”表示不确定的估计，而房租数额是明确的约定，应用确定的数额来说明，不能用估计修饰。"}, {"text": "车站内大概严禁吸烟。", "explanation": "这里不该用〈大概〉。“大概”表示不确定的估计，而禁令必须明确，不能用估计的语气来表示禁止。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动大概的有一百人。", "corrected_sentence": "这次活动大概有一百人。", "error_description": "错误：“大概”后多加了“的”。“大概”是副词，直接修饰动词“有”，应说“大概有一百人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目有大概的三十个观众。", "corrected_sentence": "这个节目有大概三十个观众。", "error_description": "错误：“大概”后多加了“的”。“大概”是副词，修饰数词前，不能接“的”，应说“有大概三十个观众”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13058, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚硬", "is_correct": true, "explanation": "反义：“松软”指柔软有弹性，“坚硬”指硬而不软，二者在物体质地上相对。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线或颜色鲜亮，与物体的软硬质地无关，不构成反义。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度快，与“松软”不在同一维度，没有反义关系。"}, {"text": "富裕", "is_correct": false, "explanation": "“富裕”形容财物充足，与“松软”的质地无关，不是它的反义词。"}], "correct_answer": "坚硬", "explanations": {"坚硬": "反义：“松软”指柔软有弹性，“坚硬”指硬而不软，二者在物体质地上相对。", "明亮": "“明亮”形容光线或颜色鲜亮，与物体的软硬质地无关，不构成反义。", "迅速": "“迅速”形容速度快，与“松软”不在同一维度，没有反义关系。", "富裕": "“富裕”形容财物充足，与“松软”的质地无关，不是它的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13058, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚硬", "is_correct": true, "explanation": "反义：“松软”指柔软有弹性，“坚硬”指硬而不软，二者在物体质地上相对。"}, {"text": "冰冷", "is_correct": false, "explanation": "“冰冷”形容温度低，与“松软”的质地无关，不构成反义。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容清洁程度，与“松软”描述的软硬质地无关。"}, {"text": "迟缓", "is_correct": false, "explanation": "“迟缓”形容速度慢，与“松软”不在同一维度，没有反义关系。"}], "correct_answer": "坚硬", "explanations": {"坚硬": "反义：“松软”指柔软有弹性，“坚硬”指硬而不软，二者在物体质地上相对。", "冰冷": "“冰冷”形容温度低，与“松软”的质地无关，不构成反义。", "干净": "“干净”形容清洁程度，与“松软”描述的软硬质地无关。", "迟缓": "“迟缓”形容速度慢，与“松软”不在同一维度，没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13058, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容物体柔软，有弹性，不坚硬。", "primary_collocate": null, "pronunciation": "sōng ruǎn", "ipa": "sʊŋ˥ ʐwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "大概过一个月到两个月，原来的厨余就会变成深褐色、松软的土壤。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这块蛋糕又松软又好吃。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的土地很松软。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新买的面包松软可口。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子躺在松软的沙发上睡着了。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把枕头拍得松软。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种馒头吃起来松软香甜。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙滩上的沙子很松软。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在松软的草地上跑步。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚晒过的被子又松软又暖和。", "target_word": "松软", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词，形容土壤、食物、被褥等物体松散柔软、有弹性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4db93df3-ec4d-4ac1-b668-c97e971d1734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13058, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "松软", "is_correct": true, "explanation": "“松软”形容土壤疏松、有弹性，与“深褐色”的堆肥土相符，可以修饰“土壤”。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：厨余变成的土壤应当疏松，“坚硬”与这一变化方向相反，也与“松软”的定义相反。"}, {"text": "透明", "is_correct": false, "explanation": "语义：土壤没有透光的性质，“透明”无法描述土壤。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”与前面的“深褐色”颜色相矛盾，两个颜色词不能并列修饰同一块土壤。"}], "explanations": {"松软": "“松软”形容土壤疏松、有弹性，与“深褐色”的堆肥土相符，可以修饰“土壤”。", "坚硬": "语义：厨余变成的土壤应当疏松，“坚硬”与这一变化方向相反，也与“松软”的定义相反。", "透明": "语义：土壤没有透光的性质，“透明”无法描述土壤。", "雪白": "搭配：“雪白”与前面的“深褐色”颜色相矛盾，两个颜色词不能并列修饰同一块土壤。"}, "sentence_index": 0, "correct_answer": "松软"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他经过训练，身体非常松软。", "explanation": "这里应该用〈柔软〉。松软形容食物、土壤等松散、有弹性的东西；形容人的身体柔韧要用柔软。"}, {"text": "他说话的语气很松软，没有力度。", "explanation": "这里应该用〈柔和〉。松软形容物体柔软、有弹性；说话语气温和要用柔和。"}, {"text": "这群人很松软。", "explanation": "这里应该用〈松散〉。松软形容物体柔软有弹性；形容人群、组织稀疏要用松散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "松软", "is_correct": true, "explanation": "“松软”形容食物口感柔软、有弹性，与“吃起来”和“香甜”搭配自然。"}, {"text": "鲜红", "is_correct": false, "explanation": "搭配：“鲜红”是颜色词，“吃起来”后接的应是口感或味道，不能接颜色。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描述形体大小，不能用来描述食物的口感。"}, {"text": "粗壮", "is_correct": false, "explanation": "体貌：“粗壮”描述形体粗大结实，用于馒头的口感描述不合适。"}], "explanations": {"松软": "“松软”形容食物口感柔软、有弹性，与“吃起来”和“香甜”搭配自然。", "鲜红": "搭配：“鲜红”是颜色词，“吃起来”后接的应是口感或味道，不能接颜色。", "高大": "体貌：“高大”描述形体大小，不能用来描述食物的口感。", "粗壮": "体貌：“粗壮”描述形体粗大结实，用于馒头的口感描述不合适。"}, "sentence_index": 6, "correct_answer": "松软"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的颜色很松软，看着很舒服。", "explanation": "这里应该用〈柔和〉。“松软”形容物体柔软、有弹性；形容颜色淡雅、不刺眼要用“柔和”，颜色不能说松软。"}, {"text": "这个孩子性格很松软，凡事都要大人替他拿主意。", "explanation": "这里应该用〈软弱〉。松软形容物体柔软、有弹性；形容性格、意志不坚定要用软弱。"}, {"text": "这块石头很松软，用手就能压扁。", "explanation": "这里应该用〈坚硬〉。“松软”指柔软有弹性，石头坚硬，不能用“松软”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块蛋糕很很松软。", "corrected_sentence": "这块蛋糕很松软。", "error_description": "错误：程度副词“很”重复。“很”只用一次，放在形容词“松软”前，应说“很松软”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这床被子晒了得很松软。", "corrected_sentence": "这床被子晒得很松软。", "error_description": "错误：动词“晒”与补语标记“得”之间多加了“了”。“得”应紧跟动词，应说“晒得很松软”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
