INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13059, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "完成制作，可以使用的东西", "primary_collocate": null, "pronunciation": "zuò hǎo", "ipa": "tswo˥˩ xaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "把做好的堆肥混进花盆的土里，植物会长得更好。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "妈妈做好了晚饭，我们一起吃吧。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着刚做好的蛋糕。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是奶奶昨天做好的衣服。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做好的面包还很热。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把做好的卡片送给老师。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做好了一只木头小船。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸做好的椅子很结实。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭做好了，快来洗手吃饭。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把做好的饺子放在盘子里。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做好了", "label": "体标（了）"}, {"form": "做好的", "label": "定语形式（的）"}], "register": "中性", "sense_fingerprint": "做成、制作完成（已做成可以使用的东西）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4db93df3-ec4d-4ac1-b668-c97e971d1734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13059, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做好", "is_correct": true, "explanation": "“做好”指制作完成，堆肥经过制作后可以混进土里，与“把……的堆肥”搭配自然。"}, {"text": "煮好", "is_correct": false, "explanation": "语义：堆肥是发酵制成的，不能煮，“煮好的堆肥”与堆肥的制作方式矛盾。"}, {"text": "缝好", "is_correct": false, "explanation": "搭配：“缝”只用于衣物、布料等，不能用于堆肥。"}, {"text": "烤好", "is_correct": false, "explanation": "语义：堆肥不是用火烤制的，“烤好的堆肥”与前后的“混进花盆的土里”不合。"}], "explanations": {"做好": "“做好”指制作完成，堆肥经过制作后可以混进土里，与“把……的堆肥”搭配自然。", "煮好": "语义：堆肥是发酵制成的，不能煮，“煮好的堆肥”与堆肥的制作方式矛盾。", "缝好": "搭配：“缝”只用于衣物、布料等，不能用于堆肥。", "烤好": "语义：堆肥不是用火烤制的，“烤好的堆肥”与前后的“混进花盆的土里”不合。"}, "sentence_index": 0, "correct_answer": "做好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈做好了一壶开水。", "explanation": "这里应该用〈烧好〉。做好指制作成可以使用的东西，烧开水要用“烧”。"}, {"text": "他做好了一封信，寄给了朋友。", "explanation": "这里应该用〈写〉。做好指制作成可以使用的东西；信是写出来的，要用「写」。"}, {"text": "他做好了去北京的机票。", "explanation": "这里应该用〈订好〉。做好指制作成可以使用的东西，机票是订购来的，要用“订”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13059, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做好", "is_correct": true, "explanation": "“做好”指制作完成，木头小船是做出来的，与“他……了一只木头小船”搭配自然。"}, {"text": "吃好", "is_correct": false, "explanation": "语义：木头小船不能吃，“吃好了一只木头小船”不合常理。"}, {"text": "绣好", "is_correct": false, "explanation": "搭配：“绣”用于布料上的刺绣，不能用于木头小船。"}, {"text": "炖好", "is_correct": false, "explanation": "语义：炖的对象是食物，木头小船不能炖。"}], "explanations": {"做好": "“做好”指制作完成，木头小船是做出来的，与“他……了一只木头小船”搭配自然。", "吃好": "语义：木头小船不能吃，“吃好了一只木头小船”不合常理。", "绣好": "搭配：“绣”用于布料上的刺绣，不能用于木头小船。", "炖好": "语义：炖的对象是食物，木头小船不能炖。"}, "sentence_index": 6, "correct_answer": "做好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她做好了一个梦，醒来后很高兴。", "explanation": "这里应该用〈做〉（做梦）。做好指制作完成、可以使用的东西；梦不是制作出来的，要说做梦。"}, {"text": "工人把那台坏掉的洗衣机做好了。", "explanation": "这里应该用〈修好〉。做好指制作完成；修理坏掉的机器要用「修好」。"}, {"text": "他终于把签证做好了。", "explanation": "这里应该用〈办好〉。签证是办理出来的，做好指制作成可以使用的东西，不用于办手续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13059, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把晚饭做好了了。", "corrected_sentence": "我已经把晚饭做好了。", "error_description": "错误：“做好了”后多加了一个“了”，结果补语与体标重复，应删去多余的“了”，即“我已经把晚饭做好了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13059, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "饭还没做好了呢。", "corrected_sentence": "饭还没做好呢。", "error_description": "错误形式：「没做好了」；正确形式：「没做好」。“没”表示尚未完成，与表示完成的“了”不能同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13060, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "反义：“节省”是省着用，“浪费”是白白耗费，二者构成反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "“购买”指买进，与“节省”没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指探讨、琢磨，与“节省”不构成反义。"}, {"text": "欢迎", "is_correct": false, "explanation": "“欢迎”指接纳、迎接，与“节省”没有反义关系。"}], "correct_answer": "浪费", "explanations": {"浪费": "反义：“节省”是省着用，“浪费”是白白耗费，二者构成反义关系。", "购买": "“购买”指买进，与“节省”没有反义关系。", "研究": "“研究”指探讨、琢磨，与“节省”不构成反义。", "欢迎": "“欢迎”指接纳、迎接，与“节省”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13060, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "反义：“节省”是省着用，“浪费”是白白耗费，二者构成反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指修复损坏的东西，与“节省”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指动脑筋考虑，与“节省”不构成反义。"}, {"text": "出发", "is_correct": false, "explanation": "“出发”指动身前往，与“节省”没有反义关系。"}], "correct_answer": "浪费", "explanations": {"浪费": "反义：“节省”是省着用，“浪费”是白白耗费，二者构成反义关系。", "修理": "“修理”指修复损坏的东西，与“节省”没有反义关系。", "思考": "“思考”指动脑筋考虑，与“节省”不构成反义。", "出发": "“出发”指动身前往，与“节省”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13060, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指在使用时间、金钱或物资时避免浪费。", "primary_collocate": null, "pronunciation": "jié shěng", "ipa": "tɕjɛ˧˥ ʂɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这不仅节省了买肥料的钱，也减少了家里的垃圾量。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "坐地铁上班可以节省很多时间。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要节省用水，不要浪费。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他节省了一个月的零花钱买书。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用电脑写信节省了不少纸。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在家做饭节省了不少钱。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前先把材料准备好，可以节省不少时间。", "target_word": "节省", "complexity_tier": "T3", "furigana": "kāihuì qián xiān bǎ cáiliào zhǔnbèi hǎo, kěyǐ jiéshěng bù shǎo shíjiān", "sentence_source": "generated"}, {"text": "这样做能节省很多力气和时间。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门带水杯，可以节省买水的钱。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想节省材料，所以用了小一点的盒子。", "target_word": "节省", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "节省了", "label": "体标（了）"}, {"form": "节省过", "label": "体标（过）"}, {"form": "节省着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "使用时间、金钱、物资时避免浪费，使花费减少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4db93df3-ec4d-4ac1-b668-c97e971d1734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13060, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "节省", "is_correct": true, "explanation": "正确：“节省”指省下买肥料的钱，与后句“减少垃圾量”构成正面并列，语义连贯。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”说数量变多，与“不仅……也……”要求的正面递进相反，买肥料的钱增加不是好事。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，“钱”不能被购买。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是房屋、道路等工程，不能说修建“钱”。"}], "explanations": {"节省": "正确：“节省”指省下买肥料的钱，与后句“减少垃圾量”构成正面并列，语义连贯。", "增加": "语义：“增加”说数量变多，与“不仅……也……”要求的正面递进相反，买肥料的钱增加不是好事。", "购买": "搭配：“购买”的对象是商品，“钱”不能被购买。", "修建": "搭配：“修建”的对象是房屋、道路等工程，不能说修建“钱”。"}, "sentence_index": 0, "correct_answer": "节省"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月家里的垃圾节省了三袋。", "explanation": "这里应该用〈减少〉。节省用于时间、金钱、物资的使用；垃圾是使用之后的结果，只能说减少。"}, {"text": "这家公司的员工节省了二十人。", "explanation": "这里应该用〈减少〉。节省只用于时间、金钱、物资的使用，人员变少要用减少，不能说节省。"}, {"text": "他的汉语水平节省了很多。", "explanation": "这里应该用〈提高〉。提高用于水平、质量；节省只用于时间、金钱、物资的使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节省", "is_correct": true, "explanation": "正确：“节省”指准备好材料带来的时间好处，与“可以”搭配，语义通顺。"}, {"text": "耽误", "is_correct": false, "explanation": "语义：“耽误”指拖延、误了时间，与“准备好材料”能省下时间的好处相反，句意不通。"}, {"text": "修改", "is_correct": false, "explanation": "搭配：“修改”的对象是文字、方案等，不能说修改“时间”。"}, {"text": "解决", "is_correct": false, "explanation": "搭配：“解决”的对象是问题、矛盾，“时间”不能被解决。"}], "explanations": {"节省": "正确：“节省”指准备好材料带来的时间好处，与“可以”搭配，语义通顺。", "耽误": "语义：“耽误”指拖延、误了时间，与“准备好材料”能省下时间的好处相反，句意不通。", "修改": "搭配：“修改”的对象是文字、方案等，不能说修改“时间”。", "解决": "搭配：“解决”的对象是问题、矛盾，“时间”不能被解决。"}, "sentence_index": 6, "correct_answer": "节省"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的压力节省了不少。", "explanation": "这里应该用〈减轻〉。减轻用于压力、负担；节省只用于时间、金钱、物资的使用。"}, {"text": "这台机器的噪音节省了三分贝。", "explanation": "这里应该用〈降低〉。噪音等数值下降要用降低，不能说节省。"}, {"text": "公司终于节省了那个安全隐患。", "explanation": "这里应该用〈消除〉。隐患是要排除的问题，要说消除；节省只用于时间、金钱、物资的使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把零花钱节省，买了一辆自行车。", "corrected_sentence": "他把零花钱节省下来，买了一辆自行车。", "error_description": "错误形式：“把零花钱节省”，“把”字句中动词后缺少补语。正确形式：“把零花钱节省下来”。原因：“把”字句的动词后要带补语来说明结果，“节省下来”表示把钱省了下来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "加班以后，他能把节省一笔路费。", "corrected_sentence": "加班以后，他能节省一笔路费。", "error_description": "错误：“把”字句中“把”要接宾语，“节省”前不能直接加“把”，“能把节省一笔路费”不成立，应删去“把”，即“他能节省一笔路费。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6abf136-6e78-4c68-996e-79145c85f81a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
