INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13064, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为实现共同目标所做出的努力或贡献", "primary_collocate": null, "pronunciation": "lì", "ipa": "li˥˩", "syllable_count": 1, "sentences": [{"text": "通过这样一个简单的系统，每个人都能为保护地球出一份力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "大家都愿意为学校出一份力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王为这个项目出了很多力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有时间的话，也来出点力吧。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都想为社区出一份力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动能成功，你也出了力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想为山区的孩子出点力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他过去为这座城市出过不少力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每个人都该为环境出一份力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人也想为村子出点力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出力", "label": "复合词"}, {"form": "尽力", "label": "复合词"}, {"form": "合力", "label": "复合词"}], "register": "中性", "sense_fingerprint": "为共同目标出的努力或贡献", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d954bdb-808a-46ea-869b-37621b1d7757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13064, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "力", "is_correct": true, "explanation": "正确：lì（第四声），意思是为共同目标出的努力。"}, {"text": "梨", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，“梨”意思是梨子。"}, {"text": "礼", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，“礼”意思是礼物、礼节。"}, {"text": "腻", "is_correct": false, "explanation": "nì（第四声）与 lì 声母不同（n 与 l），“腻”意思是油腻。"}, {"text": "黎", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，“黎”意思是黎明。"}], "explanations": {"力": "正确：lì（第四声），意思是为共同目标出的努力。", "梨": "lí（第二声）与 lì（第四声）声调不同，“梨”意思是梨子。", "礼": "lǐ（第三声）与 lì（第四声）声调不同，“礼”意思是礼物、礼节。", "腻": "nì（第四声）与 lì 声母不同（n 与 l），“腻”意思是油腻。", "黎": "lí（第二声）与 lì（第四声）声调不同，“黎”意思是黎明。"}, "sentence_index": null, "correct_answer": "力"}, "level_3": {"options": [{"text": "力", "is_correct": true, "explanation": "正确：“出一份力”指为共同目标付出的努力或贡献。"}, {"text": "心", "is_correct": false, "explanation": "搭配：“出一份心”不是固定说法，表示付出贡献要说“出一份力”。"}, {"text": "汗", "is_correct": false, "explanation": "搭配：“出汗”是动宾短语，不说“出一份汗”来表示付出贡献。"}, {"text": "票", "is_correct": false, "explanation": "语义：“票”指凭证或选票，不能表示为地球付出的努力。"}], "explanations": {"力": "正确：“出一份力”指为共同目标付出的努力或贡献。", "心": "搭配：“出一份心”不是固定说法，表示付出贡献要说“出一份力”。", "汗": "搭配：“出汗”是动宾短语，不说“出一份汗”来表示付出贡献。", "票": "语义：“票”指凭证或选票，不能表示为地球付出的努力。"}, "sentence_index": 0, "correct_answer": "力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为学校做了很大的力。", "explanation": "这里应该用〈贡献〉。做贡献要说“做了很大的贡献”，表示努力时要说“出力”，不说“做力”。"}, {"text": "这次改革对学校的发展起了很大的力。", "explanation": "这里应该用〈作用〉。“起……作用”要用“作用”，“力”不能和“起”搭配；表示推动应说“推动力”。"}, {"text": "我们要为山区出一只力。", "explanation": "这里应该用〈份〉。“出力”用“一份力”，“只”用于动物等，不能用于努力之义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13064, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "力", "is_correct": true, "explanation": "正确：lì（第四声），意思是为共同目标出的努力。"}, {"text": "离", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，“离”意思是离开。"}, {"text": "理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，“理”意思是道理。"}, {"text": "里", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，“里”意思是里面。"}, {"text": "日", "is_correct": false, "explanation": "rì（第四声）与 lì 声母不同（r 与 l），“日”意思是太阳、日子。"}], "explanations": {"力": "正确：lì（第四声），意思是为共同目标出的努力。", "离": "lí（第二声）与 lì（第四声）声调不同，“离”意思是离开。", "理": "lǐ（第三声）与 lì（第四声）声调不同，“理”意思是道理。", "里": "lǐ（第三声）与 lì（第四声）声调不同，“里”意思是里面。", "日": "rì（第四声）与 lì 声母不同（r 与 l），“日”意思是太阳、日子。"}, "sentence_index": null, "correct_answer": "力"}, "level_3": {"options": [{"text": "力", "is_correct": true, "explanation": "正确：“出点力”指为孩子付出努力或帮助。"}, {"text": "猫", "is_correct": false, "explanation": "语义：“猫”是动物，不能用“出点”表示为孩子付出帮助。"}, {"text": "光", "is_correct": false, "explanation": "搭配：“出点光”不是固定说法，不能用来表示为孩子付出帮助。"}, {"text": "梦", "is_correct": false, "explanation": "语义：“梦”指睡梦或理想，不能用“出”表示为别人付出帮助。"}], "explanations": {"力": "正确：“出点力”指为孩子付出努力或帮助。", "猫": "语义：“猫”是动物，不能用“出点”表示为孩子付出帮助。", "光": "搭配：“出点光”不是固定说法，不能用来表示为孩子付出帮助。", "梦": "语义：“梦”指睡梦或理想，不能用“出”表示为别人付出帮助。"}, "sentence_index": 6, "correct_answer": "力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小水电站为村子提供了清洁的力。", "explanation": "这里应该用〈能源〉。“能源”指可供利用的能量来源，“力”不能用“清洁的”修饰成供应的资源，应说“清洁能源”。"}, {"text": "我们也想为村子出一条力。", "explanation": "这里应该用〈份〉。“出力”用“一份力”，“条”用于细长的东西，不能用于努力之义。"}, {"text": "这台机器储存了很多力。", "explanation": "这里应该用〈能量〉。机器储存的是能量，力不能被储存。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们都愿意为灾区出一只力。", "corrected_sentence": "我们都愿意为灾区出一份力。", "error_description": "“出力”的量词应为“份”，“只”不能用于努力之义。应说“出一份力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他也想为学校出一份很大地力。", "corrected_sentence": "他也想为学校出一份很大的力。", "error_description": "“力”前的修饰语“很大”应用结构助词“的”，不能用“地”（“地”用于状语）。应说“出一份很大的力”，不说“出一份很大地力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
