INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13065, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人或生物为生存和发展而进行的各种活动；也指日常的衣食住行。", "primary_collocate": null, "pronunciation": "shēng huó", "ipa": "ʂəŋ˥ xuo˧˥", "syllable_count": 2, "sentences": [{"text": "在城市化进程日益加速的今天，人们对美好的生活充满期待。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在北京的生活很忙。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢农村安静的生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学生活让我学会了照顾自己。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷奶奶的生活过得很简单。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的生活很规律，每天六点起床。", "target_word": "生活", "complexity_tier": "T3", "furigana": "tā men de shēng huó hěn guī lǜ, měi tiān liù diǎn qǐ chuáng.", "sentence_source": "generated"}, {"text": "你喜欢现在的生活吗？", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚到国外时，我不习惯那里的生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休以后，爷爷的生活很轻松。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是一个小城市里的生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生活水平", "label": "复合"}, {"form": "生活费", "label": "复合"}], "register": "中性", "sense_fingerprint": "人为生存发展而进行的各种活动，包括衣食住行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405dfc4a-6ee0-42e9-8dd9-f58f27602e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13065, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生活", "is_correct": true, "explanation": "正确：“对美好的生活充满期待”中“生活”指人的生存与发展状况，句意通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“美好的颜色”不成立，颜色不能被“充满期待”。"}, {"text": "身份证", "is_correct": false, "explanation": "搭配：“美好的身份证”不成立，身份证不是可以“充满期待”的对象。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：“美好的形状”不成立，形状不能被“充满期待”。"}], "explanations": {"生活": "正确：“对美好的生活充满期待”中“生活”指人的生存与发展状况，句意通顺。", "颜色": "搭配：“美好的颜色”不成立，颜色不能被“充满期待”。", "身份证": "搭配：“美好的身份证”不成立，身份证不是可以“充满期待”的对象。", "形状": "搭配：“美好的形状”不成立，形状不能被“充满期待”。"}, "sentence_index": 0, "correct_answer": "生活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱的生活很长。", "explanation": "这里应该用〈寿命〉。生活指人或生物的生存活动，不用于形容机器的使用年限。"}, {"text": "他每个月的生活存进了银行。", "explanation": "这里应该用〈工资〉。生活指衣食住行和日常活动，不能说“生活存进了银行”，存进银行的是工资。"}, {"text": "他的生活是司机。", "explanation": "这里应该用〈职业〉。生活指衣食住行和日常活动，不能用来说“是司机”，说工作要用职业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13065, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生活", "is_correct": true, "explanation": "正确：“现在的生活”是常用说法，可以被喜欢或不喜欢。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：寿命不是可以“喜欢”的对象，句义不通。"}, {"text": "身份证", "is_correct": false, "explanation": "搭配：“喜欢”不能与“身份证”搭配，句子读来不通。"}, {"text": "病历", "is_correct": false, "explanation": "语域：病历是医疗文书，与日常闲谈的语境不合。"}], "explanations": {"生活": "正确：“现在的生活”是常用说法，可以被喜欢或不喜欢。", "寿命": "语义：寿命不是可以“喜欢”的对象，句义不通。", "身份证": "搭配：“喜欢”不能与“身份证”搭配，句子读来不通。", "病历": "语域：病历是医疗文书，与日常闲谈的语境不合。"}, "sentence_index": 6, "correct_answer": "生活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月他的生活很低。", "explanation": "这里应该用〈收入〉。生活指日常的衣食住行和各种活动，不能用“很低”来形容每月收入的多少。"}, {"text": "这个城市的生活越来越多。", "explanation": "这里应该用〈人口〉。生活指生存活动，不表示人数，人数增加要说“人口越来越多”。"}, {"text": "这所房子的生活很大。", "explanation": "这里应该用〈面积〉。生活指生存活动和日常事务，不能用“很大”来形容房屋的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13065, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的一个生活很充实。", "corrected_sentence": "她的一段生活很充实。", "error_description": "量词错误：“生活”指一段经历时用量词“段”，不用“个”，应说“一段生活”，不能说“一个生活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13065, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的生活过的很充实。", "corrected_sentence": "她的生活过得很充实。", "error_description": "结构助词错误：“过得”后带补语“很充实”，要用“得”，不能用“的”；应说“生活过得很充实”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
