INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13068, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "构成整体所需要的各个部分或因素。", "primary_collocate": null, "pronunciation": "zǔ chéng bù fen", "ipa": "tsu˨˩ ʈʂʰɤŋ˧˥ pu˥˩ fən", "syllable_count": 4, "sentences": [{"text": "其中，厨余垃圾作为家庭废弃物中占比最高的组成部分，若仅以填埋或焚烧方式处置，不仅占用土地资源，更会产生甲烷等强效温室气体，加剧全球气候危机。", "target_word": "组成部分", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "从苹果、杏仁到咖啡与可可，这些人类饮食结构中的重要组成部分，其产量与质量皆深刻受制于蜂类活动的稳定性。", "target_word": "组成部分", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水是我们身体的重要组成部分。", "target_word": "组成部分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音乐是他生活的一个组成部分。", "target_word": "组成部分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蔬菜是健康饮食的重要组成部分。", "target_word": "组成部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家庭是社会最小的组成部分。", "target_word": "组成部分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气的主要组成部分是氮气和氧气。", "target_word": "组成部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的组成部分包括老城和新区。", "target_word": "组成部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动是学习生活中不可少的组成部分。", "target_word": "组成部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境保护是这个计划的重要组成部分。", "target_word": "组成部分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "组成部分：构成整体的各个部分或成分，可指具体事物或抽象因素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ae535a-9ea1-4936-80af-cc9fd7df8a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "组成部分", "is_correct": true, "explanation": "组成部分指构成整体的各个部分。此处说厨余垃圾是家庭废弃物中占比最高的部分，语义完整。"}, {"text": "收入", "is_correct": false, "explanation": "语义：“收入”指钱财的进项，不属于废弃物的构成，句意不通。"}, {"text": "季节", "is_correct": false, "explanation": "搭配：“占比”说的是数量比例，“季节”不能说占比最高。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是场所，不是废弃物的构成成分，与“占比最高”不相容。"}], "explanations": {"组成部分": "组成部分指构成整体的各个部分。此处说厨余垃圾是家庭废弃物中占比最高的部分，语义完整。", "收入": "语义：“收入”指钱财的进项，不属于废弃物的构成，句意不通。", "季节": "搭配：“占比”说的是数量比例，“季节”不能说占比最高。", "厨房": "语义：“厨房”是场所，不是废弃物的构成成分，与“占比最高”不相容。"}, "sentence_index": 0, "correct_answer": "组成部分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "音乐是他生活的一台组成部分。", "explanation": "这里应该用〈个〉。“台”用于机器、设备，抽象的组成部分不能用“台”计量。"}, {"text": "音乐是他生活的一条组成部分。", "explanation": "这里应该用〈个〉。“条”用于河流、道路等细长的东西，不用来计量抽象的组成部分。"}, {"text": "音乐是他生活的一座组成部分。", "explanation": "这里应该用〈个〉。“座”用于山、桥、建筑等大型固定物，不能用来计量抽象的组成部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "组成部分", "is_correct": true, "explanation": "组成部分指构成整体的各个部分。此处说空气的主要部分是氮气和氧气，语义完整。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指物体的视觉属性，不能说空气的主要颜色是氮气和氧气，句意荒谬。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”用于人或有性格的事物，空气不能说“主要性格”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或物体的重量，不能用于说明空气的成分，搭配不当。"}], "explanations": {"组成部分": "组成部分指构成整体的各个部分。此处说空气的主要部分是氮气和氧气，语义完整。", "颜色": "语义：“颜色”指物体的视觉属性，不能说空气的主要颜色是氮气和氧气，句意荒谬。", "性格": "搭配：“性格”用于人或有性格的事物，空气不能说“主要性格”。", "体重": "搭配：“体重”指人或物体的重量，不能用于说明空气的成分，搭配不当。"}, "sentence_index": 6, "correct_answer": "组成部分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "环境保护是这个计划的一本组成部分。", "explanation": "这里应该用〈个〉。“本”用于书籍、册子，不用来计量“组成部分”这类抽象的构成因素。"}, {"text": "环境保护是这个计划的一张组成部分。", "explanation": "这里应该用〈个〉。“张”用于纸张、桌子等平面的东西，不用来计量抽象的组成部分。"}, {"text": "环境保护是这个计划的一把组成部分。", "explanation": "这里应该用〈个〉。“把”用于有柄可握的器具，不用来计量抽象的组成部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阅读是她生活的一件组成部分。", "corrected_sentence": "阅读是她生活的一个组成部分。", "error_description": "量词误用：“组成部分”前应用量词“个”，不能用“件”。“件”多用于衣物、事情等，应为「一个组成部分」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "空气是人类生存的重要组成部分们。", "corrected_sentence": "空气是人类生存的重要组成部分。", "error_description": "多用了“们”。“组成部分”表示构成的成分，不能加“们”表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
