INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13069, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用火焰把物体烧毁。", "primary_collocate": null, "pronunciation": "fén shāo", "ipa": "fən˧˥ ʂɑʊ˥˥", "syllable_count": 2, "sentences": [{"text": "其中，厨余垃圾作为家庭废弃物中占比最高的组成部分，若仅以填埋或焚烧方式处置，不仅占用土地资源，更会产生甲烷等强效温室气体，加剧全球气候危机。", "target_word": "焚烧", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "衣物从“耐用品”异化为“一次性消费品”，大量未被穿着或仅短时间使用的服装最终被填埋或焚烧，形成巨大的资源浪费。", "target_word": "焚烧", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工人把旧衣服送去焚烧。", "target_word": "焚烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "垃圾焚烧会产生很多烟。", "target_word": "焚烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里禁止焚烧秸秆。", "target_word": "焚烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在空地上焚烧落叶。", "target_word": "焚烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂焚烧了大量废纸。", "target_word": "焚烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "废纸焚烧后只剩下灰。", "target_word": "焚烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院把用过的口罩集中焚烧。", "target_word": "焚烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人焚烧干草来驱赶蚊虫。", "target_word": "焚烧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "焚烧了", "label": "体标"}, {"form": "焚烧着", "label": "体标"}, {"form": "焚烧过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用火焰烧毁垃圾、废物等物体，多指处理废弃物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ae535a-9ea1-4936-80af-cc9fd7df8a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13069, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焚烧", "is_correct": true, "explanation": "正确。焚烧指用火把废弃物烧毁，与「填埋」并列，都是处置废弃物的方式。"}, {"text": "烧烤", "is_correct": false, "explanation": "语义：烧烤是烹调食物的方法，不用于处置废弃物。"}, {"text": "洗涤", "is_correct": false, "explanation": "搭配：「洗涤」多用于衣物、器皿，不能与「填埋」并列作垃圾处置方式。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪指做饭做菜，与废弃物处置无关。"}], "explanations": {"焚烧": "正确。焚烧指用火把废弃物烧毁，与「填埋」并列，都是处置废弃物的方式。", "烧烤": "语义：烧烤是烹调食物的方法，不用于处置废弃物。", "洗涤": "搭配：「洗涤」多用于衣物、器皿，不能与「填埋」并列作垃圾处置方式。", "烹饪": "语义：烹饪指做饭做菜，与废弃物处置无关。"}, "sentence_index": 0, "correct_answer": "焚烧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生在烤箱里焚烧面包。", "explanation": "这里应该用〈烘焙〉。烘焙指用烤箱加热制作面包等食品，焚烧是把物体烧毁，做面包不能说焚烧。"}, {"text": "公司把过期的数据焚烧了。", "explanation": "这里应该用〈销毁〉。焚烧只用于能被火烧的实物，数据无法焚烧，删除过期数据应说销毁。"}, {"text": "奶奶在厨房里焚烧水。", "explanation": "这里应该用〈煮〉。煮是把水放在锅里加热至沸腾，焚烧是把物体烧毁，水不能被焚烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焚烧", "is_correct": true, "explanation": "正确。「这家工厂焚烧了大量废纸」中，焚烧指把废纸烧毁。"}, {"text": "雕刻", "is_correct": false, "explanation": "搭配：「雕刻」用于木石等硬材料，不用于废纸。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：「播放」用于影音节目，不能用于废纸，句意不通。"}, {"text": "熨", "is_correct": false, "explanation": "语义：熨是用熨斗把衣物弄平整，不能用于废纸的处理。"}], "explanations": {"焚烧": "正确。「这家工厂焚烧了大量废纸」中，焚烧指把废纸烧毁。", "雕刻": "搭配：「雕刻」用于木石等硬材料，不用于废纸。", "播放": "搭配：「播放」用于影音节目，不能用于废纸，句意不通。", "熨": "语义：熨是用熨斗把衣物弄平整，不能用于废纸的处理。"}, "sentence_index": 6, "correct_answer": "焚烧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春天到了，河上的冰焚烧了。", "explanation": "这里应该用〈融化〉。冰遇热只会融化，焚烧指烧毁，不能用于冰。"}, {"text": "农民用水焚烧麦田。", "explanation": "这里应该用〈灌溉〉。灌溉是用水浇地，水不能用来焚烧麦田。"}, {"text": "他把脏衣服放进洗衣机里焚烧。", "explanation": "这里应该用〈清洗〉。清洗指用水或洗涤剂去除衣物上的污物，焚烧是用火烧毁，把衣服放进机器去污应说清洗，不能说焚烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂把有毒废料焚烧了掉。", "corrected_sentence": "工厂把有毒废料焚烧掉了。", "error_description": "「焚烧」后的结果补语「掉」应紧跟动词，「了」放在句末。正确形式是「焚烧掉了」，「焚烧了掉」语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府禁止焚烧了秸秆。", "corrected_sentence": "政府禁止焚烧秸秆。", "error_description": "「禁止」表示不允许做某事，后面的「焚烧」后不能加「了」表示已完成。正确形式是「禁止焚烧」，「焚烧了」与「禁止」矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
