INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13070, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "处置指对事情或问题进行处理、安排或解决。", "primary_collocate": null, "pronunciation": "chǔ zhì", "ipa": "ʈʂʰu˨˩ ʈʂɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "公司已经处置了这次事故。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事要尽快处置，不能再拖了。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察妥善处置了现场的突发情况。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于违规的员工，经理会依规处置。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板还没决定怎样处置这些旧设备。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他处置问题的办法，大家都很满意。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院已经依法处置了这个案子。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生冷静处置了病人的紧急情况。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这批过期的食品处置掉。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校会根据情况处置打架的学生。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处置了", "label": "体标"}, {"form": "处置过", "label": "体标"}, {"form": "处置方式", "label": "复合"}, {"form": "处置权", "label": "复合"}], "register": "书面", "sense_fingerprint": "处理、安排并解决事情或问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12bffa6a-c330-4612-90ca-b7a2113d6df9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13070, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "处置", "is_correct": true, "explanation": "处置（chǔ zhì）：正确答案，意思是处理、安排或解决事情。"}, {"text": "主治", "is_correct": false, "explanation": "声母不同：zhǔ 的 zh 与 chǔ 的 ch 不同，意思是医生治疗疾病。"}, {"text": "储值", "is_correct": false, "explanation": "第二个音节声调不同：zhí 与 zhì 不同，意思是把钱存入以备使用。"}, {"text": "初志", "is_correct": false, "explanation": "第一个音节声调不同：chū 与 chǔ 不同，意思是最初的志向。"}, {"text": "初值", "is_correct": false, "explanation": "两个音节的声调都不同：chū、zhí 与 chǔ、zhì 不同，意思是最初的数值。"}], "explanations": {"处置": "处置（chǔ zhì）：正确答案，意思是处理、安排或解决事情。", "主治": "声母不同：zhǔ 的 zh 与 chǔ 的 ch 不同，意思是医生治疗疾病。", "储值": "第二个音节声调不同：zhí 与 zhì 不同，意思是把钱存入以备使用。", "初志": "第一个音节声调不同：chū 与 chǔ 不同，意思是最初的志向。", "初值": "两个音节的声调都不同：chū、zhí 与 chǔ、zhì 不同，意思是最初的数值。"}, "sentence_index": null, "correct_answer": "处置"}, "level_3": {"options": [{"text": "处置", "is_correct": true, "explanation": "处置：意思是处理、解决事故，符合句意。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”的宾语应是生活、待遇等好事，不能说享受事故。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”表示为好事而欢庆，事故不能被庆祝。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”要求带指人的宾语，事故不能被感谢。"}], "explanations": {"处置": "处置：意思是处理、解决事故，符合句意。", "享受": "搭配：“享受”的宾语应是生活、待遇等好事，不能说享受事故。", "庆祝": "语义：“庆祝”表示为好事而欢庆，事故不能被庆祝。", "感谢": "配价：“感谢”要求带指人的宾语，事故不能被感谢。"}, "sentence_index": 0, "correct_answer": "处置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想处置一下心情，先去散散步吧。", "explanation": "这里应该用〈调整〉。处置用于事情或问题，心情应说调整。"}, {"text": "他很会处置朋友，大家都愿意跟他来往。", "explanation": "这里应该用〈相处〉。处置用于事情或问题，人与人之间应说相处。"}, {"text": "他每天都处置英语，成绩提高了很多。", "explanation": "这里应该用〈学习〉。处置用于事情或问题，学习语言应说学习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "处置", "is_correct": true, "explanation": "处置：意思是处理、解决案子，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指喜爱美好的事物，案子不能被欣赏。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”要求带指人或过错的宾语，案子不能被原谅。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：“品尝”指尝食物的味道，案子不能被品尝。"}], "explanations": {"处置": "处置：意思是处理、解决案子，符合句意。", "欣赏": "语义：“欣赏”指喜爱美好的事物，案子不能被欣赏。", "原谅": "配价：“原谅”要求带指人或过错的宾语，案子不能被原谅。", "品尝": "语义：“品尝”指尝食物的味道，案子不能被品尝。"}, "sentence_index": 6, "correct_answer": "处置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在新学校很快就处置了新朋友。", "explanation": "这里应该用〈结交〉。处置用于事情或问题，交朋友不能用处置。"}, {"text": "他在音乐会上处置了一首钢琴曲。", "explanation": "这里应该用〈演奏〉。处置用于事情或问题，弹奏乐曲应说演奏。"}, {"text": "老师处置了一个有趣的故事，同学们都听得很认真。", "explanation": "这里应该用〈讲述〉。处置用于事情或问题，讲故事应说讲述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理把这件事处置很妥当。", "corrected_sentence": "经理把这件事处置得很妥当。", "error_description": "错误：“处置”后带情态补语“很妥当”时，中间要加“得”，应说“处置得很妥当”，不能说“处置很妥当”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经把那些过期的文件处置了完。", "corrected_sentence": "我们已经把那些过期的文件处置完了。", "error_description": "错误：结果补语“完”要紧接动词，应说“处置完了”，不能说“处置了完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
