INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13071, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13071, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "意思是‘考虑到这种情况’，常用来引出后面的做法或决定。", "primary_collocate": null, "pronunciation": "yǒu jiàn yú cǐ", "ipa": "joʊ̯˨˩ tɕjɛn˥˩ y˧˥ tsʰɹ̩˨˩", "syllable_count": 4, "sentences": [{"text": "城市垃圾量连年攀升，有鉴于此，自制家庭堆肥系统应运而生，成为连接个体实践与生态伦理的微观技术路径。", "target_word": "有鉴于此", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "今年订单减少很多，有鉴于此，公司决定提前放假。", "target_word": "有鉴于此", "complexity_tier": "T3", "furigana": "jīnnián dìngdān jiǎnshǎo hěn duō, yǒu jiàn yú cǐ, gōngsī juédìng tíqián fàngjià.", "sentence_source": "generated"}, {"text": "天气越来越冷，有鉴于此，学校推迟了运动会。", "target_word": "有鉴于此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年事故很多，有鉴于此，我们加强了检查。", "target_word": "有鉴于此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纠纷增多，有鉴于此，政府出台了新的规定。", "target_word": "有鉴于此", "complexity_tier": "T3", "furigana": "jiūfēn zēngduō, yǒu jiàn yú cǐ, zhèngfǔ chūtái le xīn de guīdìng.", "sentence_source": "generated"}, {"text": "房价一直在涨，有鉴于此，他放弃了买房。", "target_word": "有鉴于此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上车多，有鉴于此，我建议大家早点出发。", "target_word": "有鉴于此", "complexity_tier": "T3", "furigana": "lùshang chē duō, yǒu jiàn yú cǐ, wǒ jiànyì dàjiā zǎodiǎn chūfā.", "sentence_source": "generated"}, {"text": "网上骗子太多，有鉴于此，银行发了提醒。", "target_word": "有鉴于此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "急诊病人很多，有鉴于此，医院增加了夜间的医生。", "target_word": "有鉴于此", "complexity_tier": "T3", "furigana": "jízhěn bìngrén hěn duō, yǒu jiàn yú cǐ, yīyuàn zēngjiā le yèjiān de yīshēng.", "sentence_source": "generated"}, {"text": "孩子们都爱玩手机，有鉴于此，家长定了规矩。", "target_word": "有鉴于此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "考虑到上述情况，引出后面的做法或决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12bffa6a-c330-4612-90ca-b7a2113d6df9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13071, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有鉴于此", "is_correct": true, "explanation": "有鉴于此：意思是考虑到这种情况，引出后面的做法，符合句意。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”要与后文“但是”或“仍然”呼应，这里没有让步的分句。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与后文“但是”呼应，句中没有让步的内容。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，但前文没有需要转折的内容。"}], "explanations": {"有鉴于此": "有鉴于此：意思是考虑到这种情况，引出后面的做法，符合句意。", "尽管": "搭配：“尽管”要与后文“但是”或“仍然”呼应，这里没有让步的分句。", "虽然": "搭配：“虽然”要与后文“但是”呼应，句中没有让步的内容。", "然而": "语义：“然而”表示转折，但前文没有需要转折的内容。"}, "sentence_index": 0, "correct_answer": "有鉴于此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他连续熬夜，有鉴于此，身体变差了。", "explanation": "这里应该用〈因此〉。有鉴于此后面要接做法或决定，不能接“身体变差”这样的结果。"}, {"text": "他听到了这个消息，有鉴于此，哭了。", "explanation": "这里应该用〈于是〉。有鉴于此要引出做法或决定，不能引出“哭了”这样的反应。"}, {"text": "他迟到了，有鉴于此，老师生气。", "explanation": "这里应该用〈难怪〉。有鉴于此要引出做法或决定，不能引出“老师生气”这样的心理反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13071, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有鉴于此", "is_correct": true, "explanation": "有鉴于此：意思是考虑到路上车多的情况，引出建议，符合句意。"}, {"text": "无论", "is_correct": false, "explanation": "搭配：“无论”要与后文“都”呼应，句中没有这样的呼应。"}, {"text": "不但", "is_correct": false, "explanation": "搭配：“不但”要与后文“而且”或“还”呼应，这里句式不成立。"}, {"text": "如果", "is_correct": false, "explanation": "语义：“如果”表示假设，但“路上车多”是已经发生的事实。"}], "explanations": {"有鉴于此": "有鉴于此：意思是考虑到路上车多的情况，引出建议，符合句意。", "无论": "搭配：“无论”要与后文“都”呼应，句中没有这样的呼应。", "不但": "搭配：“不但”要与后文“而且”或“还”呼应，这里句式不成立。", "如果": "语义：“如果”表示假设，但“路上车多”是已经发生的事实。"}, "sentence_index": 6, "correct_answer": "有鉴于此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没复习，有鉴于此，考砸了。", "explanation": "这里应该用〈所以〉。有鉴于此要引出做法或决定，不能引出“考砸了”这样的结果。"}, {"text": "他终于找到了钥匙，有鉴于此，松了口气。", "explanation": "这里应该用〈才〉。有鉴于此要引出做法或决定，不能引出“松了口气”这样的反应。"}, {"text": "他每天都练琴，有鉴于此，他很努力。", "explanation": "这里应该用〈可见〉。有鉴于此要引出做法或决定，不能引出对人的评价“很努力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年冬天特别冷，有鉴于此了，学校提前放了寒假。", "corrected_sentence": "今年冬天特别冷，有鉴于此，学校提前放了寒假。", "error_description": "错误：“有鉴于此”是连词，不能带“了”，应说“有鉴于此，”，不说“有鉴于此了，”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天气很热，有鉴于此的，学校调整了上课时间。", "corrected_sentence": "天气很热，有鉴于此，学校调整了上课时间。", "error_description": "错误：“有鉴于此”是连词，后面不能加“的”，应说“有鉴于此，”，不说“有鉴于此的，”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13072, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现象", "is_correct": true, "explanation": "与“本质”构成反义：现象指事物表现于外的样子，与其内在根本属性相对。"}, {"text": "天气", "is_correct": false, "explanation": "不构成反义：天气与“本质”没有对立关系，不是同一概念的对立面。"}, {"text": "颜色", "is_correct": false, "explanation": "不构成反义：颜色是具体的外部特征，与“本质”不是对立关系。"}, {"text": "歌曲", "is_correct": false, "explanation": "不构成反义：歌曲与“本质”之间没有对立关系。"}], "correct_answer": "现象", "explanations": {"现象": "与“本质”构成反义：现象指事物表现于外的样子，与其内在根本属性相对。", "天气": "不构成反义：天气与“本质”没有对立关系，不是同一概念的对立面。", "颜色": "不构成反义：颜色是具体的外部特征，与“本质”不是对立关系。", "歌曲": "不构成反义：歌曲与“本质”之间没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13072, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现象", "is_correct": true, "explanation": "与“本质”构成反义：现象指事物表现于外的样子，与其内在根本属性相对。"}, {"text": "价格", "is_correct": false, "explanation": "不构成反义：价格与“本质”没有对立关系。"}, {"text": "花朵", "is_correct": false, "explanation": "不构成反义：花朵是具体事物，与“本质”不是对立概念。"}, {"text": "乐器", "is_correct": false, "explanation": "不构成反义：乐器与“本质”之间没有对立关系。"}], "correct_answer": "现象", "explanations": {"现象": "与“本质”构成反义：现象指事物表现于外的样子，与其内在根本属性相对。", "价格": "不构成反义：价格与“本质”没有对立关系。", "花朵": "不构成反义：花朵是具体事物，与“本质”不是对立概念。", "乐器": "不构成反义：乐器与“本质”之间没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13072, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物本身所具有的根本属性或内在特性。", "primary_collocate": null, "pronunciation": "qí běn zhì", "ipa": "tɕʰi˧˥ pən˨˩ ʈʂɹ̩˥˩", "syllable_count": 3, "sentences": [{"text": "其本质在于将有机物质通过微生物的代谢作用，转化为富含腐殖质的稳定有机肥，从而实现食物残渣的闭环再生。", "target_word": "其本质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种游戏看起来复杂，其本质却很简单。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多广告很好看，其本质是为了卖东西。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "友谊是什么？其本质是互相信任。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题表面是钱，其本质是沟通。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试只是一种方法，其本质是检查学习。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事看似很小，其本质关系到安全。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话很好听，其本质是在推卸责任。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要看清事物，了解其本质。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法能解决问题，但没改变其本质。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "某事物自身的根本属性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12bffa6a-c330-4612-90ca-b7a2113d6df9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "其本质", "is_correct": true, "explanation": "正确：“其本质”指事物的根本属性，在此与“在于”搭配，引出对本质的说明。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指金额高低，不能说明事物的根本属性，与句中的转化过程不相关。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能与“在于”引出的转化过程搭配，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是外部特征，与有机物转化为肥料的过程无关。"}], "explanations": {"其本质": "正确：“其本质”指事物的根本属性，在此与“在于”搭配，引出对本质的说明。", "价格": "语义：价格指金额高低，不能说明事物的根本属性，与句中的转化过程不相关。", "天气": "搭配：“天气”不能与“在于”引出的转化过程搭配，句意不通。", "颜色": "语义：颜色是外部特征，与有机物转化为肥料的过程无关。"}, "sentence_index": 0, "correct_answer": "其本质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱省电，其本质有两扇门。", "explanation": "〈其本质〉指事物的根本属性，不能用来说明实物有几扇门，这里把它当作〈数量〉来用。应说「这台冰箱有两扇门」。"}, {"text": "我的书包其本质在厨房里。", "explanation": "〈其本质〉指事物的根本属性，这里却当作〈位置〉来用，说某物在哪里。应说「我的书包在厨房里」。"}, {"text": "这家店东西很多，其本质比较便宜。", "explanation": "〈其本质〉指事物的根本属性，不能用来说明价格高低，这里把它当作〈价格〉来用。应说「这家店比较便宜」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "其本质", "is_correct": true, "explanation": "正确：“其本质”指根本属性，与“看似很小”形成对比，说明事情内在的重要性。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲本身不关系到安全，与“这件事”的内在性质不符。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵与安全没有关系，句子所说的内在重要性不成立。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“关系到安全”的主语应是事件或行为，乐器不能与之搭配。"}], "explanations": {"其本质": "正确：“其本质”指根本属性，与“看似很小”形成对比，说明事情内在的重要性。", "歌曲": "语义：歌曲本身不关系到安全，与“这件事”的内在性质不符。", "花朵": "语义：花朵与安全没有关系，句子所说的内在重要性不成立。", "乐器": "搭配：“关系到安全”的主语应是事件或行为，乐器不能与之搭配。"}, "sentence_index": 6, "correct_answer": "其本质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个团队，其本质明天就要出发了。", "explanation": "〈其本质〉指事物的根本属性，不能作为“出发”的主语，这里把它当作〈主体〉来用。应说「这个团队明天就要出发了」。"}, {"text": "这支笔，其本质很大声。", "explanation": "〈其本质〉指事物的根本属性，不能用来描述声音的大小，这里把它当作〈音量〉来用。应说「这支笔的声音很大」。"}, {"text": "这匹马，其本质跑得很快。", "explanation": "〈其本质〉是抽象的根本属性，不能作为动作的主语，这里把它当作〈动物〉来用。应说「这匹马跑得很快」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个玩具看着很贵，其本质了只是塑料。", "corrected_sentence": "这个玩具看着很贵，其本质只是塑料。", "error_description": "错误：“其本质”是名词性词语，后面不能直接加“了”，应说“其本质只是塑料”，不说“其本质了只是塑料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作看着轻松，很其本质关系到责任。", "corrected_sentence": "这份工作看着轻松，其本质关系到责任。", "error_description": "“其本质”是名词性成分，前面不能用副词“很”修饰，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
