INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13073, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生物体内发生的化学反应和能量转换过程，包括物质的合成与分解，以维持生命活动。", "primary_collocate": null, "pronunciation": "dài xiè zuò yòng", "ipa": "tai˥˩ ɕiɛ˥˩ tsuɔ˥˩ yŋ˥˩", "syllable_count": 4, "sentences": [{"text": "其本质在于将有机物质通过微生物的代谢作用，转化为富含腐殖质的稳定有机肥，从而实现食物残渣的闭环再生。", "target_word": "代谢作用", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "细菌的代谢作用能分解有机物。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物通过代谢作用获得生长所需的能量。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度太低时，酵母的代谢作用会变慢。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "微生物的代谢作用会产生热量。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土壤中的细菌靠代谢作用分解落叶。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验显示，这种菌的代谢作用很旺盛。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酶可以加快细胞的代谢作用。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水里的藻类通过代谢作用释放氧气。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代谢作用停止后，细胞就会死亡。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "代谢", "label": "简称"}, {"form": "代謝作用", "label": "繁体"}], "register": "书面", "sense_fingerprint": "生物体内物质合成分解与能量转换的化学过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12bffa6a-c330-4612-90ca-b7a2113d6df9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13073, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代谢作用", "is_correct": true, "explanation": "正确：“代谢作用”是生物体内的化学过程，此处指微生物转化有机物的途径。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度是快慢的程度，不能作为有机物转化的途径。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是化学过程，无法通过它转化有机物。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“乐器”不能与“通过……转化有机物”搭配，与化学过程无关。"}], "explanations": {"代谢作用": "正确：“代谢作用”是生物体内的化学过程，此处指微生物转化有机物的途径。", "速度": "语义：速度是快慢的程度，不能作为有机物转化的途径。", "颜色": "语义：颜色不是化学过程，无法通过它转化有机物。", "乐器": "搭配：“乐器”不能与“通过……转化有机物”搭配，与化学过程无关。"}, "sentence_index": 0, "correct_answer": "代谢作用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个培养皿里的代谢作用会唱歌。", "explanation": "〈代谢作用〉是化学过程，没有唱歌的能力，这里把它当作〈表演者〉来用。应说「这个培养皿里的代谢作用很旺盛」。"}, {"text": "这张桌子上有很多代谢作用。", "explanation": "〈代谢作用〉是生物体内的过程，这里却当作〈物体〉一样摆在桌子上并计数。应说「细菌的代谢作用很旺盛」。"}, {"text": "他的代谢作用跑得很快。", "explanation": "〈代谢作用〉是生理过程，不能作为“跑”的主语，这里把它当作〈身体〉来用。应说「他跑得很快」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代谢作用", "is_correct": true, "explanation": "正确：“代谢作用”指生物体内的过程，此处说这种菌的过程很旺盛。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是大气状况，不能用“很旺盛”来形容，句意不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是生物的生理过程，不能说“很旺盛”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“旺盛”不修饰价格，与“很旺盛”的搭配不当。"}], "explanations": {"代谢作用": "正确：“代谢作用”指生物体内的过程，此处说这种菌的过程很旺盛。", "天气": "语义：天气是大气状况，不能用“很旺盛”来形容，句意不通。", "歌曲": "语义：歌曲不是生物的生理过程，不能说“很旺盛”。", "价格": "搭配：“旺盛”不修饰价格，与“很旺盛”的搭配不当。"}, "sentence_index": 6, "correct_answer": "代谢作用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的代谢作用很甜。", "explanation": "〈代谢作用〉是生理过程，这里却当作〈味道〉来用，不能用来形容甜不甜。应说「这碗汤很甜」。"}, {"text": "代谢作用明天下午举行婚礼。", "explanation": "〈代谢作用〉是生理过程，这里却当作〈人〉来用，不能举行婚礼。应说「他们明天下午举行婚礼」。"}, {"text": "代谢作用的颜色是红色的。", "explanation": "〈代谢作用〉是生理过程，没有颜色，这里却当作〈物体〉来用。应说「血液是红色的」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "低温时，细菌的代谢作用变很慢。", "corrected_sentence": "低温时，细菌的代谢作用变得很慢。", "error_description": "补语应用“变得很慢”，“变很慢”漏了“得”，应改为“变得很慢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吃药以后，酵母的代谢作用停止了后。", "corrected_sentence": "吃药以后，酵母的代谢作用停止了。", "error_description": "“了”之后不能再加“后”，应删去“后”，改为“停止了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13074, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13074, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13074, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有机肥是一种主要来源于植物和动物（如粪便、秸秆、绿肥）的肥料，富含有机质，能改善土壤结构、提高土壤肥力。", "primary_collocate": null, "pronunciation": "yǒu jī féi", "ipa": "iou˨˩˦ tɕi˥ fei˧˥", "syllable_count": 3, "sentences": [{"text": "其本质在于将有机物质通过微生物的代谢作用，转化为富含腐殖质的稳定有机肥，从而实现食物残渣的闭环再生。", "target_word": "有机肥", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其次，所得有机肥用于家庭园艺，可改良土壤团粒结构，提升保水保肥能力，减少对化学肥料的依赖，形成“厨房—土壤—餐桌”的营养回路。", "target_word": "有机肥", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农民在菜地里施了有机肥。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机肥能让土壤变得更松软。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家农场只用有机肥种菜。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用有机肥种出来的苹果很甜。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把落叶沤成了有机肥。", "target_word": "有机肥", "complexity_tier": "T3", "furigana": "yǒu jī féi", "sentence_source": "generated"}, {"text": "花盆里加点有机肥，花开得更好。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机肥比化肥慢，但效果持久。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里卖的有机肥一袋二十元。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有机肥料", "label": "复合"}, {"form": "有機肥", "label": "繁体"}], "register": "书面", "sense_fingerprint": "来源于动植物、富含有机质、改良土壤的肥料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12bffa6a-c330-4612-90ca-b7a2113d6df9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有机肥", "is_correct": true, "explanation": "正确：有机物质经微生物分解转化而成，富含腐殖质，与句中“稳定”“富含腐殖质”相符。"}, {"text": "燃料", "is_correct": false, "explanation": "语义：燃料不含腐殖质，也不是由微生物代谢转化而来，与“富含腐殖质”矛盾。"}, {"text": "塑料", "is_correct": false, "explanation": "搭配：“富含腐殖质”和“微生物的代谢作用”只能指向有机肥料，不能与“塑料”搭配。"}, {"text": "农药", "is_correct": false, "explanation": "语义：农药是化学制剂，不靠微生物代谢产生，也不富含腐殖质。"}], "explanations": {"有机肥": "正确：有机物质经微生物分解转化而成，富含腐殖质，与句中“稳定”“富含腐殖质”相符。", "燃料": "语义：燃料不含腐殖质，也不是由微生物代谢转化而来，与“富含腐殖质”矛盾。", "塑料": "搭配：“富含腐殖质”和“微生物的代谢作用”只能指向有机肥料，不能与“塑料”搭配。", "农药": "语义：农药是化学制剂，不靠微生物代谢产生，也不富含腐殖质。"}, "sentence_index": 0, "correct_answer": "有机肥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一本有机肥。", "explanation": "量词：有机肥是成袋、成堆的肥料，应用“袋”或“堆”计量，“本”只用于书册，这里应该用〈袋〉。"}, {"text": "院子里喷了有机肥，蚊子就没了。", "explanation": "这里应该用〈杀虫剂〉。有机肥用来增加土壤肥力，不能杀蚊子，要杀蚊子应使用杀虫剂。"}, {"text": "炒菜的时候，用有机肥调味。", "explanation": "这里应该用〈酱油〉。有机肥是肥料，不能用来调味，调味应使用酱油。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有机肥", "is_correct": true, "explanation": "正确：落叶经沤制发酵后得到的是有机肥，与“沤成了”的过程相符。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：落叶沤制只能得到腐殖质类肥料，不可能变成汽油。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料是化工产品，落叶沤制不会产生颜料。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“沤”多用于植物腐烂发酵，不与“钢铁”搭配。"}], "explanations": {"有机肥": "正确：落叶经沤制发酵后得到的是有机肥，与“沤成了”的过程相符。", "汽油": "语义：落叶沤制只能得到腐殖质类肥料，不可能变成汽油。", "颜料": "语义：颜料是化工产品，落叶沤制不会产生颜料。", "钢铁": "搭配：“沤”多用于植物腐烂发酵，不与“钢铁”搭配。"}, "sentence_index": 6, "correct_answer": "有机肥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每天早上用有机肥洗头。", "explanation": "这里应该用〈洗发水〉。有机肥是肥料，不能用来洗头，洗头应使用洗发水。"}, {"text": "早上用有机肥刷牙。", "explanation": "这里应该用〈牙膏〉。有机肥不能用来刷牙，刷牙应使用牙膏。"}, {"text": "咖啡里加了一勺有机肥。", "explanation": "这里应该用〈糖〉。有机肥不能加进咖啡调味，加入的应是糖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "园子里的土太硬了，应该多加一条有机肥。", "corrected_sentence": "园子里的土太硬了，应该多加一袋有机肥。", "error_description": "量词错误：“有机肥”通常以袋、堆计量，“条”用于细长之物，应说“一袋有机肥”；用“条”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "施了有机肥菜地长得很好。", "corrected_sentence": "施了有机肥的菜地长得很好。", "error_description": "结构错误：“有机肥”修饰“菜地”时，中间需要加“的”，应说“施了有机肥的菜地”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
