INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13075, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "吃完食物后留下的碎屑或剩余部分。", "primary_collocate": null, "pronunciation": "shí wù cán zhā", "ipa": "ʂʐ̩˧˥ u˥˩ tsʰan˧˥ ʈʂa˥", "syllable_count": 4, "sentences": [{"text": "其本质在于将有机物质通过微生物的代谢作用，转化为富含腐殖质的稳定有机肥，从而实现食物残渣的闭环再生。", "target_word": "食物残渣", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "洗碗前，先倒掉盘子里的食物残渣。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水槽里的食物残渣会堵住下水道。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物残渣放久了会发臭。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾桶里全是食物残渣。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙缝里的食物残渣容易让牙齿坏掉。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把食物残渣倒进了堆肥桶。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食堂每天产生很多食物残渣。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过滤网能挡住水里的食物残渣。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物残渣可以喂给院子里的鸡。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "残渣", "label": "泛称"}, {"form": "食物殘渣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "吃完食物后留下的碎屑或剩余部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12bffa6a-c330-4612-90ca-b7a2113d6df9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13075, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食物残渣", "is_correct": true, "explanation": "正确：食物残渣是吃剩的碎屑，可以再被转化利用，与“闭环再生”相符。"}, {"text": "化肥", "is_correct": false, "explanation": "语义：化肥多为无机合成，不经微生物代谢，与句中“有机物质”和“微生物”矛盾。"}, {"text": "矿石", "is_correct": false, "explanation": "语义：矿石是无机矿物，不是有机物质，也不会被微生物分解。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“通过微生物的代谢作用”只能作用于有机物，不能与“钢铁”搭配。"}], "explanations": {"食物残渣": "正确：食物残渣是吃剩的碎屑，可以再被转化利用，与“闭环再生”相符。", "化肥": "语义：化肥多为无机合成，不经微生物代谢，与句中“有机物质”和“微生物”矛盾。", "矿石": "语义：矿石是无机矿物，不是有机物质，也不会被微生物分解。", "钢铁": "搭配：“通过微生物的代谢作用”只能作用于有机物，不能与“钢铁”搭配。"}, "sentence_index": 0, "correct_answer": "食物残渣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚饭我们吃食物残渣。", "explanation": "这里应该用〈剩菜〉。食物残渣是吃完后剩下的碎屑，不能当正餐吃，应说“剩菜”。"}, {"text": "我在超市买了食物残渣。", "explanation": "这里应该用〈食材〉。食物残渣不能买卖，超市里买的应是食材。"}, {"text": "桌上放着一瓶食物残渣。", "explanation": "量词：食物残渣是碎屑，不能用“瓶”计量，应说“一点”或“一些”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13075, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食物残渣", "is_correct": true, "explanation": "正确：食物残渣可以倒入堆肥桶，与“堆肥桶”相符。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：堆肥桶只收有机废料，玻璃不能堆肥，与“堆肥桶”的用途矛盾。"}, {"text": "石块", "is_correct": false, "explanation": "语义：石块不会在堆肥中分解，与“堆肥桶”的用途矛盾。"}, {"text": "钢筋", "is_correct": false, "explanation": "搭配：“倒进”多用于碎屑、液体，不与“钢筋”这类条状物搭配。"}], "explanations": {"食物残渣": "正确：食物残渣可以倒入堆肥桶，与“堆肥桶”相符。", "玻璃": "语义：堆肥桶只收有机废料，玻璃不能堆肥，与“堆肥桶”的用途矛盾。", "石块": "语义：石块不会在堆肥中分解，与“堆肥桶”的用途矛盾。", "钢筋": "搭配：“倒进”多用于碎屑、液体，不与“钢筋”这类条状物搭配。"}, "sentence_index": 6, "correct_answer": "食物残渣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "炒菜时加了一点食物残渣。", "explanation": "这里应该用〈调料〉。食物残渣是吃剩的碎屑，不能用来调味，应说“调料”。"}, {"text": "孩子放学后爱吃食物残渣。", "explanation": "这里应该用〈零食〉。食物残渣不是可以吃的东西，孩子爱吃的应是零食。"}, {"text": "我渴了，想喝一杯食物残渣。", "explanation": "这里应该用〈饮料〉。食物残渣是固体碎屑，不能用来喝，应说“饮料”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13075, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房的地上有一台食物残渣。", "corrected_sentence": "厨房的地上有一些食物残渣。", "error_description": "量词错误：“台”用于机器，不能用来计量食物残渣，应说“一些食物残渣”；用“台”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13075, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨房里有一堆食物残渣们。", "corrected_sentence": "厨房里有一堆食物残渣。", "error_description": "词缀错误：“们”不能加在“食物残渣”后面。“们”只用于指人或拟人的复数，表示物质的残渣应直接说“一堆食物残渣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
