INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13076, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13076, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使空气流通，也比喻交换意见或情况。", "primary_collocate": null, "pronunciation": "tōng qì", "ipa": "tʰʊŋ˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "稳定的堆肥需要在碳氮比、水分与微生物群落之间保持平衡，而翻堆时能否及时通气，往往决定了整个过程的成败。", "target_word": "通气", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "房间太闷了，打开窗户通气吧。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会以前，我们先通气，再做决定。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个仓库不通气，里面有一股潮味。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理出差前给大家通气，说了公司的新计划。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天要常开门窗通气，屋里才不会太热。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个部门有事要及时通气，别让对方不知道。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房没有窗户，不通气，油烟很大。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发前老师跟家长通气，告诉他们活动时间。", "target_word": "通气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣柜要定期开门通气，不然衣服容易发霉。", "target_word": "通气", "complexity_tier": "T3", "furigana": "yī guì yào dìng qī kāi mén tōng qì, bù rán yī fu róng yì fā méi", "sentence_source": "generated"}], "morphological_forms": [{"form": "通通气", "label": "重叠"}, {"form": "通气性", "label": "复合"}, {"form": "通氣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使空气流通；比喻互相交换意见、情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91551975-d9d1-42af-a4e4-1a8bfc2d0b91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13076, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通气", "is_correct": true, "explanation": "正确：通气，使空气流通，也比喻交换情况。"}, {"text": "空气", "is_correct": false, "explanation": "kōng 与 tōng 声母不同（k 与 t），意思是空气。"}, {"text": "同期", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，qī（第一声）与 qì（第四声）声调也不同，意思是同一时期。"}, {"text": "铜器", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，意思是铜制的器具。"}], "explanations": {"通气": "正确：通气，使空气流通，也比喻交换情况。", "空气": "kōng 与 tōng 声母不同（k 与 t），意思是空气。", "同期": "tóng（第二声）与 tōng（第一声）声调不同，qī（第一声）与 qì（第四声）声调也不同，意思是同一时期。", "铜器": "tóng（第二声）与 tōng（第一声）声调不同，意思是铜制的器具。"}, "sentence_index": null, "correct_answer": "通气"}, "level_3": {"options": [{"text": "通气", "is_correct": true, "explanation": "正确：“及时通气”指及时使空气流动，与翻堆的语境相合。"}, {"text": "通车", "is_correct": false, "explanation": "搭配：“通车”指道路、桥梁开放交通，不能用于翻堆时的空气流动。"}, {"text": "通航", "is_correct": false, "explanation": "配价：“通航”指河道或航线可以行船，与堆肥翻堆无关。"}, {"text": "通话", "is_correct": false, "explanation": "语义：“通话”指双方用电话交谈，与堆肥翻堆无关。"}], "explanations": {"通气": "正确：“及时通气”指及时使空气流动，与翻堆的语境相合。", "通车": "搭配：“通车”指道路、桥梁开放交通，不能用于翻堆时的空气流动。", "通航": "配价：“通航”指河道或航线可以行船，与堆肥翻堆无关。", "通话": "语义：“通话”指双方用电话交谈，与堆肥翻堆无关。"}, "sentence_index": 0, "correct_answer": "通气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件运动服很通气，夏天穿着很舒服。", "explanation": "这里应该用〈透气〉。通气指使空气流通或交换情况，衣物让空气穿过要说透气。"}, {"text": "这条路堵了一早上，现在终于通气了。", "explanation": "这里应该用〈畅通〉。通气不用于道路交通，道路顺畅要说畅通。"}, {"text": "这篇文章写得很通气。", "explanation": "这里应该用〈通顺〉。通气不用于文字，文章读起来通顺要说通顺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通气", "is_correct": true, "explanation": "正确：“及时通气”指及时交换情况、互相告知，符合句意。"}, {"text": "通商", "is_correct": false, "explanation": "搭配：“通商”指国与国、地区之间进行贸易往来，主语不能是“部门”，也不用于部门之间互相告知。"}, {"text": "通婚", "is_correct": false, "explanation": "语义：“通婚”指不同家族、民族或国家之间结为婚姻，与部门之间及时告知情况的意思无关。"}, {"text": "通电", "is_correct": false, "explanation": "语义：“通电”指接通电流，与两个部门之间互相告知的意思无关。"}], "explanations": {"通气": "正确：“及时通气”指及时交换情况、互相告知，符合句意。", "通商": "搭配：“通商”指国与国、地区之间进行贸易往来，主语不能是“部门”，也不用于部门之间互相告知。", "通婚": "语义：“通婚”指不同家族、民族或国家之间结为婚姻，与部门之间及时告知情况的意思无关。", "通电": "语义：“通电”指接通电流，与两个部门之间互相告知的意思无关。"}, "sentence_index": 6, "correct_answer": "通气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这笔资金要在市场上通气，才能带动经济。", "explanation": "这里应该用〈流通〉。通气指空气流动或交换情况，资金在市场上的流动要说流通。"}, {"text": "这条隧道下个月就能通气了。", "explanation": "这里应该用〈通车〉。通气不用于道路开放，隧道开放交通要说通车。"}, {"text": "这条河明年开始通气。", "explanation": "这里应该用〈通航〉。通气只指空气流动或交换情况，船只能在河里行驶要说通航。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要经常房间通气。", "corrected_sentence": "我们要经常给房间通气。", "error_description": "错误：离合词“通气”后直接带宾语“房间”，漏了引出对象的“给”。正确说法是“给房间通气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天早上都通气一个。", "corrected_sentence": "我每天早上都通气一下。", "error_description": "错误：动量词用错。“通气”表示一次动作，应用动量词“下”计量，说“通气一下”。“一个”是计量事物的个体量词，不能用来计量“通气”这一动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
