INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13079, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生产或制造过程中使用的材料或原料。", "primary_collocate": null, "pronunciation": "wù liào", "ipa": "u˥˩ ljɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "工厂买了很多物料，准备下个月生产。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里的物料要分类放好。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有物料，工人们今天不能开工。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批物料昨天已经送到工厂了。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理让小王去检查物料的数量。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做一辆自行车需要很多种物料。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物料太贵，所以产品的价格也涨了。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把物料搬进了车间。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每个月都要买新的物料。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些物料质量很好，做出来的东西很结实。", "target_word": "物料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批", "label": "量词"}], "register": "中性", "sense_fingerprint": "工厂生产中使用的材料、原料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91551975-d9d1-42af-a4e4-1a8bfc2d0b91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13079, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物料", "is_correct": true, "explanation": "正确：物料，生产或制造过程中使用的材料。"}, {"text": "预料", "is_correct": false, "explanation": "yù 与 wù 韵母不同（ü 与 u），意思是事先估计。"}, {"text": "木料", "is_correct": false, "explanation": "mù 与 wù 声母不同（m 与 w），意思是木材。"}, {"text": "无聊", "is_correct": false, "explanation": "wú 与 wù 声调不同，liáo 与 liào 声调也不同，意思是没意思。"}], "explanations": {"物料": "正确：物料，生产或制造过程中使用的材料。", "预料": "yù 与 wù 韵母不同（ü 与 u），意思是事先估计。", "木料": "mù 与 wù 声母不同（m 与 w），意思是木材。", "无聊": "wú 与 wù 声调不同，liáo 与 liào 声调也不同，意思是没意思。"}, "sentence_index": null, "correct_answer": "物料"}, "level_3": {"options": [{"text": "物料", "is_correct": true, "explanation": "正确：工厂买来的“物料”可以用于生产，符合句意。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不是生产用的材料，与“准备下个月生产”的语境不合。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是工厂生产的原料，与句中的生产语境不合。"}, {"text": "草地", "is_correct": false, "explanation": "搭配：“生产”的对象通常是产品或材料，草地不能被当作生产用的东西。"}], "explanations": {"物料": "正确：工厂买来的“物料”可以用于生产，符合句意。", "花朵": "语义：花朵不是生产用的材料，与“准备下个月生产”的语境不合。", "歌曲": "语义：歌曲不是工厂生产的原料，与句中的生产语境不合。", "草地": "搭配：“生产”的对象通常是产品或材料，草地不能被当作生产用的东西。"}, "sentence_index": 0, "correct_answer": "物料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师把学习物料发给了每个学生。", "explanation": "这里应该用〈材料〉。物料指生产或制造过程中使用的材料，学习用的资料不能说物料。"}, {"text": "妈妈去市场买了做饭用的物料。", "explanation": "这里应该用〈食材〉。物料指工业生产用的材料，做饭用的食材要说食材。"}, {"text": "他今天穿了一身新物料。", "explanation": "这里应该用〈衣服〉。物料指生产或制造过程中使用的材料，穿在身上的衣物要说衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13079, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "物料", "is_correct": true, "explanation": "正确：物料，生产或制造过程中使用的材料。"}, {"text": "塑料", "is_correct": false, "explanation": "sù 与 wù 声母不同（s 与 w），意思是塑胶材料。"}, {"text": "预料", "is_correct": false, "explanation": "yù 与 wù 韵母不同（ü 与 u），意思是事先估计。"}, {"text": "补料", "is_correct": false, "explanation": "bǔ 与 wù 声母不同（b 与 w），意思是补充加入的材料。"}], "explanations": {"物料": "正确：物料，生产或制造过程中使用的材料。", "塑料": "sù 与 wù 声母不同（s 与 w），意思是塑胶材料。", "预料": "yù 与 wù 韵母不同（ü 与 u），意思是事先估计。", "补料": "bǔ 与 wù 声母不同（b 与 w），意思是补充加入的材料。"}, "sentence_index": null, "correct_answer": "物料"}, "level_3": {"options": [{"text": "物料", "is_correct": true, "explanation": "正确：物料太贵，会让产品价格上涨，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能说“太贵”，与产品价格上涨的语境无关。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“贵”说的是价格，性格不能用“太贵”来形容。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以买卖的东西，不会因为“太贵”而让产品涨价。"}], "explanations": {"物料": "正确：物料太贵，会让产品价格上涨，符合句意。", "天气": "语义：天气不能说“太贵”，与产品价格上涨的语境无关。", "性格": "搭配：“贵”说的是价格，性格不能用“太贵”来形容。", "天空": "语义：天空不是可以买卖的东西，不会因为“太贵”而让产品涨价。"}, "sentence_index": 6, "correct_answer": "物料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的物料坏了，需要更换。", "explanation": "这里应该用〈零件〉。物料指生产中用的材料，机器上的部件要说零件。"}, {"text": "这位作家收集了很多物料，准备写一部小说。", "explanation": "这里应该用〈素材〉。物料指生产或制造过程中使用的材料，写作用的材料要说素材。"}, {"text": "他带着物料去拜访老师。", "explanation": "这里应该用〈礼物〉。物料指生产中使用的材料，拿去送人的东西要说礼物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们买了一台物料，明天就能用。", "corrected_sentence": "我们买了一批物料，明天就能用。", "error_description": "错误：物料的量词用错。“台”用于机器、设备，物料应按“批”计，正确说法是“一批物料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们需要一批新地物料。", "corrected_sentence": "我们需要一批新的物料。", "error_description": "错误：修饰名词“物料”的“新”后应用“的”，不能用“地”。“地”用于修饰动词，正确说法是“一批新的物料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
