INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13080, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指枯萎或破碎的树叶，常用来形容秋天或衰败的景象。", "primary_collocate": null, "pronunciation": "cán yè", "ipa": "tsʰan˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "理想的堆肥原料应包含“绿色”与“棕色”两类物料：前者如蔬菜残叶、咖啡渣、青草，富含氮元素，提供微生物繁殖所需的蛋白质基质；后者如干落叶、碎纸板、秸秆、果核，富含纤维素与木质素，作为碳源维持能量代谢，并改善物料孔隙度。", "target_word": "残叶", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "秋风吹过，地上全是残叶。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里的残叶，他一早就扫干净了。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一片残叶落在了我的肩上。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的树上只剩下几片残叶。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，路边的水里漂着残叶。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把残叶放进桶里，可以做肥料。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的残叶在风里一动一动的。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河里有很多残叶，水看起来很脏。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着树上的残叶，觉得秋天真的来了。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "殘葉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "枯萎或破碎的树叶，常象征秋天、衰败", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91551975-d9d1-42af-a4e4-1a8bfc2d0b91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13080, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残叶", "is_correct": true, "explanation": "残叶指枯萎破碎的叶子，属于前者“绿色”物料中的蔬菜残叶，与前文的分类相符。"}, {"text": "秸秆", "is_correct": false, "explanation": "语义：秸秆是后者的棕色物料，句中已将其列入后者，不属于前者的绿色物料。"}, {"text": "碎纸板", "is_correct": false, "explanation": "语义：碎纸板同样是后者的棕色物料，不是蔬菜，也不属于前者的绿色物料。"}, {"text": "干落叶", "is_correct": false, "explanation": "搭配：“蔬菜”修饰的是新鲜可食的菜，“干落叶”是干燥的落叶，两者不搭配，且干落叶属于后者的棕色物料。"}], "explanations": {"残叶": "残叶指枯萎破碎的叶子，属于前者“绿色”物料中的蔬菜残叶，与前文的分类相符。", "秸秆": "语义：秸秆是后者的棕色物料，句中已将其列入后者，不属于前者的绿色物料。", "碎纸板": "语义：碎纸板同样是后者的棕色物料，不是蔬菜，也不属于前者的绿色物料。", "干落叶": "搭配：“蔬菜”修饰的是新鲜可食的菜，“干落叶”是干燥的落叶，两者不搭配，且干落叶属于后者的棕色物料。"}, "sentence_index": 0, "correct_answer": "残叶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天到了，树枝上长出了许多残叶。", "explanation": "这里应该用〈嫩叶〉。残叶指枯萎、破碎的叶子，不会在春天新长出来，刚长出的叶子要说嫩叶。"}, {"text": "这盘沙拉里加了不少新鲜的残叶。", "explanation": "这里应该用〈菜叶〉。残叶指枯萎、破碎的叶子，不新鲜，做沙拉要用新鲜的菜叶。"}, {"text": "残叶通过光合作用，为植物制造养分。", "explanation": "这里应该用〈叶片〉。残叶已经枯萎破碎，不再进行光合作用，不能为植物制造养分；能进行光合作用的要说叶片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残叶", "is_correct": true, "explanation": "残叶放进桶里与其他有机物料一起堆肥，可以做肥料，符合语境。"}, {"text": "砖头", "is_correct": false, "explanation": "语义：砖头是无机矿物，不会被微生物分解，不能做肥料。"}, {"text": "塑料袋", "is_correct": false, "explanation": "语义：塑料袋是合成材料，不能被分解，也不能做肥料。"}, {"text": "洗洁精", "is_correct": false, "explanation": "搭配：“做肥料”需要有机物质，洗洁精是化学清洁剂，不能与之搭配。"}], "explanations": {"残叶": "残叶放进桶里与其他有机物料一起堆肥，可以做肥料，符合语境。", "砖头": "语义：砖头是无机矿物，不会被微生物分解，不能做肥料。", "塑料袋": "语义：塑料袋是合成材料，不能被分解，也不能做肥料。", "洗洁精": "搭配：“做肥料”需要有机物质，洗洁精是化学清洁剂，不能与之搭配。"}, "sentence_index": 6, "correct_answer": "残叶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆绿萝的叶子水灵灵的，一片片都是残叶。", "explanation": "这里应该用〈绿叶〉。残叶指枯萎、破碎的叶子，水灵灵的绿叶不能说成残叶。"}, {"text": "刚播下种子，地里就冒出了几片残叶。", "explanation": "这里应该用〈幼苗〉。残叶指枯萎、破碎的叶子，刚发出来的嫩苗不能说残叶。"}, {"text": "这壶新采的残叶泡出来的茶，清香扑鼻。", "explanation": "这里应该用〈茶叶〉。残叶指枯萎、破碎的叶子，新采来泡茶的叶子要说茶叶，不能说残叶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风把一片的残叶吹到了窗台上。", "corrected_sentence": "风把一片残叶吹到了窗台上。", "error_description": "错误形式“一片的残叶”，多加了“的”；正确形式“一片残叶”，数量短语“一片”直接修饰名词，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗台上落着一根残叶。", "corrected_sentence": "窗台上落着一片残叶。", "error_description": "错误形式“一根残叶”；正确形式“一片残叶”。“根”用于细长的东西，叶子是薄片，要用“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
