INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13081, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水果的种子或核心部分，通常不能吃。", "primary_collocate": null, "pronunciation": "guǒ hé", "ipa": "kuɔ˨˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "理想的堆肥原料应包含“绿色”与“棕色”两类物料：前者如蔬菜残叶、咖啡渣、青草，富含氮元素，提供微生物繁殖所需的蛋白质基质；后者如干落叶、碎纸板、秸秆、果核，富含纤维素与木质素，作为碳源维持能量代谢，并改善物料孔隙度。", "target_word": "果核", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "吃完苹果，请把果核扔进垃圾桶。", "target_word": "果核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桃子的果核很硬，不能直接吃。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把果核埋在花园的土里，想种出一棵树。", "target_word": "果核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "樱桃的果核很小，吃的时候要吐出来。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃杏的时候，要小心别咬到果核。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用小刀去掉了梨的果核，再切成小块。", "target_word": "果核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗捡起一个果核，在草地上玩了半天。", "target_word": "果核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "芒果的果核又大又扁，果肉都贴在上面。", "target_word": "果核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杏的果核里有仁，可以做药。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "颗", "label": "量词"}], "register": "中性", "sense_fingerprint": "水果中间不能吃的硬核或种子部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91551975-d9d1-42af-a4e4-1a8bfc2d0b91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13081, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "果核", "is_correct": true, "explanation": "正确：果核木质化、质地坚硬，富含木质素，属于后者的棕色物料，与“干落叶”“碎纸板”“秸秆”并列，符合句意。"}, {"text": "塑料袋", "is_correct": false, "explanation": "语义：塑料袋是合成材料，不能被微生物分解，不属于后者的棕色有机物料。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池含有重金属等有害物质，不能用作堆肥原料。"}, {"text": "洗涤剂", "is_correct": false, "explanation": "语义：洗涤剂是化学品，不是有机物料，不能与“干落叶”“碎纸板”“秸秆”并列为后者。"}], "explanations": {"果核": "正确：果核木质化、质地坚硬，富含木质素，属于后者的棕色物料，与“干落叶”“碎纸板”“秸秆”并列，符合句意。", "塑料袋": "语义：塑料袋是合成材料，不能被微生物分解，不属于后者的棕色有机物料。", "电池": "语义：电池含有重金属等有害物质，不能用作堆肥原料。", "洗涤剂": "语义：洗涤剂是化学品，不是有机物料，不能与“干落叶”“碎纸板”“秸秆”并列为后者。"}, "sentence_index": 0, "correct_answer": "果核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个芒果的果核又甜又软，很好吃。", "explanation": "这里应该用〈果肉〉。果核是坚硬、不能吃的部分，不能说又甜又软；甜软好吃的部分要说果肉。"}, {"text": "这杯橙子果核是刚榨出来的。", "explanation": "这里应该用〈果汁〉。果核是坚硬的固体，不能榨成液体；榨出来的饮料要说果汁。"}, {"text": "核桃的果核又香又脆，可以直接吃。", "explanation": "这里应该用〈果仁〉。果核是包着果仁的硬壳，不能直接吃；可以吃的核中之仁要说果仁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13081, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果核", "is_correct": true, "explanation": "去掉梨的果核，再切成小块，符合切梨的动作，语境通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：梨的颜色属于外观，不能用小刀去掉，与切成小块的语境不符。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是梨的实体部分，不能用小刀去掉。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能用小刀去掉，与“再切成小块”的动作无关。"}], "explanations": {"果核": "去掉梨的果核，再切成小块，符合切梨的动作，语境通顺。", "颜色": "体貌：梨的颜色属于外观，不能用小刀去掉，与切成小块的语境不符。", "名字": "语义：名字不是梨的实体部分，不能用小刀去掉。", "味道": "语义：味道不能用小刀去掉，与“再切成小块”的动作无关。"}, "sentence_index": 6, "correct_answer": "果核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个柚子的果核又薄又软，像一层纸，轻轻一撕就开了。", "explanation": "这里应该用〈果皮〉。果核是坚硬的核或籽，不会又薄又软、一撕就开；像一层纸的薄皮要说果皮。"}, {"text": "这袋南瓜籽晒得干干的，颗颗都是甜甜的果核。", "explanation": "这里应该用〈瓜子〉。果核不能说甜甜的，可以当零食嗑的瓜子要说瓜子。"}, {"text": "这棵苹果树结满了果核，个个红彤彤的。", "explanation": "这里应该用〈果实〉。果核是藏在果实中间的硬核，树上结的红彤彤的果子要说果实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里躺着一颗的果核。", "corrected_sentence": "院子里躺着一颗果核。", "error_description": "错误形式“一颗的果核”，多加了“的”；正确形式“一颗果核”，数量短语直接修饰名词，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "碗里有一只果核。", "corrected_sentence": "碗里有一颗果核。", "error_description": "错误形式“一只果核”；正确形式“一颗果核”。“只”用于动物或成对器物中的一个，果核要用“颗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
