INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13082, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生物产生后代的过程，如动物生子、植物结种子。", "primary_collocate": null, "pronunciation": "fán zhí", "ipa": "fan˧˥ ʈʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "例如，苹果、杏仁和蓝莓等作物，大部分都要靠蜜蜂来帮助繁殖。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "兔子繁殖得很快。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天是很多动物繁殖的季节。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些鸟每年在湖边繁殖。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细菌在热的地方繁殖得更快。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民让牛羊多繁殖，数量越来越多。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护区帮助大熊猫繁殖后代。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠繁殖太快，很难消灭。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海龟上岸来繁殖，把蛋产在沙里。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水太脏，鱼就不能繁殖。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "繁殖了", "label": "体标"}, {"form": "繁殖过", "label": "体标"}, {"form": "繁殖期", "label": "复合"}], "register": "中性", "sense_fingerprint": "生物产生后代、使数量增多的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9da955b2-9cb2-4719-95b9-57d75913c78c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13082, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "繁殖", "is_correct": true, "explanation": "繁殖（fán zhí）指生物产生后代，是目标词本身。"}, {"text": "反制", "is_correct": false, "explanation": "声调不同：「反制」为 fǎn zhì，与 fán zhí 两个音节都只差声调，意思是反过来制约对方。"}, {"text": "泛指", "is_correct": false, "explanation": "声调不同：「泛指」为 fàn zhǐ，两个音节都只差声调，意思是笼统地指称。"}, {"text": "繁枝", "is_correct": false, "explanation": "声调不同：「繁枝」为 fán zhī，只有第二音节声调不同，意思是茂密的枝叶。"}], "explanations": {"繁殖": "繁殖（fán zhí）指生物产生后代，是目标词本身。", "反制": "声调不同：「反制」为 fǎn zhì，与 fán zhí 两个音节都只差声调，意思是反过来制约对方。", "泛指": "声调不同：「泛指」为 fàn zhǐ，两个音节都只差声调，意思是笼统地指称。", "繁枝": "声调不同：「繁枝」为 fán zhī，只有第二音节声调不同，意思是茂密的枝叶。"}, "sentence_index": null, "correct_answer": "繁殖"}, "level_3": {"options": [{"text": "繁殖", "is_correct": true, "explanation": "“帮助繁殖”指蜜蜂帮作物产生种子、结出果实，与语境相合。"}, {"text": "排队", "is_correct": false, "explanation": "语义：排队指人按次序等候，作物和蜜蜂不能排队。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：讨论指交换意见，与作物和蜜蜂的授粉无关。"}, {"text": "歼灭", "is_correct": false, "explanation": "语域：歼灭是正式的军事用语，指彻底消灭，与农作物语境不协调。"}], "explanations": {"繁殖": "“帮助繁殖”指蜜蜂帮作物产生种子、结出果实，与语境相合。", "排队": "语义：排队指人按次序等候，作物和蜜蜂不能排队。", "讨论": "语义：讨论指交换意见，与作物和蜜蜂的授粉无关。", "歼灭": "语域：歼灭是正式的军事用语，指彻底消灭，与农作物语境不协调。"}, "sentence_index": 0, "correct_answer": "繁殖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的产量繁殖了三倍。", "explanation": "这里应该用〈增加〉。繁殖只用于生物产生后代，产量等数量要用增加。"}, {"text": "这个城市的经济越来越繁殖。", "explanation": "这里应该用〈繁荣〉。繁殖指生物繁衍，经济的兴旺要用繁荣。"}, {"text": "工厂每天繁殖很多零件。", "explanation": "这里应该用〈生产〉。零件是人造的，繁殖只指生物产生后代，要用生产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13082, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繁殖", "is_correct": true, "explanation": "“帮助大熊猫繁殖后代”指保护区帮助大熊猫生育，与语境相合。"}, {"text": "消灭", "is_correct": false, "explanation": "语义：消灭指除去，与保护区帮助大熊猫的意思相反，“消灭后代”不通。"}, {"text": "拍卖", "is_correct": false, "explanation": "搭配：“拍卖”的对象是物品，不能与“后代”搭配。"}, {"text": "叫嚷", "is_correct": false, "explanation": "语义：叫嚷指大声喊叫，与保护区帮助大熊猫的语境无关。"}], "explanations": {"繁殖": "“帮助大熊猫繁殖后代”指保护区帮助大熊猫生育，与语境相合。", "消灭": "语义：消灭指除去，与保护区帮助大熊猫的意思相反，“消灭后代”不通。", "拍卖": "搭配：“拍卖”的对象是物品，不能与“后代”搭配。", "叫嚷": "语义：叫嚷指大声喊叫，与保护区帮助大熊猫的语境无关。"}, "sentence_index": 6, "correct_answer": "繁殖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司繁殖了市场。", "explanation": "这里应该用〈扩大〉。繁殖只用于生物产生后代，市场的范围要用扩大。"}, {"text": "孩子的身体繁殖得很好。", "explanation": "这里应该用〈发育〉。繁殖指生物产生后代，身体的成长要用发育。"}, {"text": "厨师每天繁殖很多点心。", "explanation": "这里应该用〈制作〉。点心是人做的，繁殖只指生物产生后代，要用制作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种老鼠繁殖的很快。", "corrected_sentence": "这种老鼠繁殖得很快。", "error_description": "补语标记应用“得”，说“繁殖得很快”；“的”用于修饰名词，不能接在动词后引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鱼去年繁殖着两次。", "corrected_sentence": "这种鱼去年繁殖过两次。", "error_description": "表示已发生的经历要用“过”，说“繁殖过两次”；“着”表示动作的持续或状态，不能与“去年”和次数搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
