INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13083, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "所需要的；需要的东西。", "primary_collocate": null, "pronunciation": "suǒ xū", "ipa": "swo˨˩ ɕy˥˥", "syllable_count": 2, "sentences": [{"text": "在某些干旱频发的地区，纺织工业甚至成为加剧水资源短缺的关键因素，挤占了农业、饮用水与生态系统所需的水量。", "target_word": "所需", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "请把旅行所需的东西都带上。", "target_word": "所需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做蛋糕所需的材料已经买好了。", "target_word": "所需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目所需的钱不少。", "target_word": "所需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生所需的书，学校都会发。", "target_word": "所需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人所需的药，医院里都有。", "target_word": "所需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "完成这份工作所需的时间是三天。", "target_word": "所需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物生长所需的水和阳光都很重要。", "target_word": "所需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全家一周所需的食物都在这里。", "target_word": "所需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子成长所需的营养，要靠均衡的饮食来保证。", "target_word": "所需", "complexity_tier": "T3", "furigana": "hái zi chéng zhǎng suǒ xū de yíng yǎng, yào kào jūn héng de yǐn shí lái bǎo zhèng", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "放在名词前作定语，表示做某事所需要的（东西、时间、条件）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ae535a-9ea1-4936-80af-cc9fd7df8a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13083, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所需", "is_correct": true, "explanation": "正确。「挤占了农业、饮用水与生态系统所需的水量」中，所需指这些领域需要的水。"}, {"text": "所欠", "is_correct": false, "explanation": "语义：「欠」指亏欠，与「挤占」的水量关系不合。"}, {"text": "所见", "is_correct": false, "explanation": "语义：「所见」指看到的东西，水量不能用来表示所看见的对象。"}, {"text": "所写", "is_correct": false, "explanation": "语义：「写」指书写，水量不能被书写，句意不通。"}], "explanations": {"所需": "正确。「挤占了农业、饮用水与生态系统所需的水量」中，所需指这些领域需要的水。", "所欠": "语义：「欠」指亏欠，与「挤占」的水量关系不合。", "所见": "语义：「所见」指看到的东西，水量不能用来表示所看见的对象。", "所写": "语义：「写」指书写，水量不能被书写，句意不通。"}, "sentence_index": 0, "correct_answer": "所需"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这起所需的事故造成了三人受伤。", "explanation": "这里应该用〈所发生的〉。所需指需要的东西，不能用来修饰已经发生的事故，已经发生的事应说所发生的。"}, {"text": "他一路上所需的困难很多。", "explanation": "这里应该用〈所遇到的〉。所需指需要的东西，不能用来修饰途中碰到的困难，碰到的困难应说所遇到的。"}, {"text": "这次比赛他所需的打击太重了。", "explanation": "这里应该用〈所受的〉。所需指需要的东西，不能用来表示承受的打击，承受的打击应说所受的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13083, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所需", "is_correct": true, "explanation": "正确。「完成这份工作所需的时间」中，所需指完成工作需要的时间。"}, {"text": "所爱", "is_correct": false, "explanation": "语义：「所爱」指所喜爱的人或事，与时间的需要无关。"}, {"text": "所吃", "is_correct": false, "explanation": "语义：「吃」指进食，时间不能用来吃。"}, {"text": "所唱", "is_correct": false, "explanation": "搭配：「唱」不能支配「时间」，「所唱的时间」搭配不当。"}], "explanations": {"所需": "正确。「完成这份工作所需的时间」中，所需指完成工作需要的时间。", "所爱": "语义：「所爱」指所喜爱的人或事，与时间的需要无关。", "所吃": "语义：「吃」指进食，时间不能用来吃。", "所唱": "搭配：「唱」不能支配「时间」，「所唱的时间」搭配不当。"}, "sentence_index": 6, "correct_answer": "所需"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很所需地向老师道了歉。", "explanation": "这里应该用〈真诚〉。所需只修饰名词，不能用来形容道歉的态度；应说真诚地向老师道歉。"}, {"text": "孩子在院子里所需地跑了三圈。", "explanation": "这里应该用〈飞快〉。所需只修饰名词，不能修饰跑步这类动作；跑得快应说飞快地跑。"}, {"text": "妈妈把碗所需得很干净。", "explanation": "这里应该用〈洗〉。所需只修饰名词，不能作动词；把碗洗干净应说洗得很干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们准备了旅行所需了的药品。", "corrected_sentence": "他们准备了旅行所需的药品。", "error_description": "错误：“所需了的药品”；正确：“所需的药品”。“所需”是定语，后面不能加“了”，应直接接“的”再接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校会为学生准备所需的的课本。", "corrected_sentence": "学校会为学生准备所需的课本。", "error_description": "错误：“所需的的课本”；正确：“所需的课本”。“所需”与“的”组成定语，“的”只用一个，不能重复。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
