INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蛋白质是由氨基酸组成的有机化合物，是生命活动的主要承担者。", "primary_collocate": null, "pronunciation": "dàn bái zhì", "ipa": "tan˥˩ paɪ˧˥ ʈʂʐ̩˥˩", "syllable_count": 3, "sentences": [{"text": "蛋白质由氨基酸组成。", "target_word": "蛋白质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "肌肉细胞里含有大量蛋白质。", "target_word": "蛋白质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加热鸡蛋时，里面的蛋白质会变硬。", "target_word": "蛋白质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酶是一类具有催化作用的蛋白质。", "target_word": "蛋白质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生命活动离不开蛋白质。", "target_word": "蛋白质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家正在研究这种蛋白质的结构。", "target_word": "蛋白质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血液里有一种蛋白质，专门运送氧气。", "target_word": "蛋白质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "胃会把蛋白质分解成氨基酸。", "target_word": "蛋白质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋白质遇到强酸，会改变原来的形状。", "target_word": "蛋白质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细胞需要蛋白质来修复和生长。", "target_word": "蛋白质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动物蛋白质", "label": "复合"}, {"form": "植物蛋白质", "label": "复合"}, {"form": "蛋白質", "label": "繁体"}], "register": "书面", "sense_fingerprint": "由氨基酸组成、承担生命活动的有机大分子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91551975-d9d1-42af-a4e4-1a8bfc2d0b91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13084, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蛋白质", "is_correct": true, "explanation": "蛋白质是由氨基酸组成的有机化合物，符合句中“由氨基酸组成”的说明。"}, {"text": "脂肪", "is_correct": false, "explanation": "语义：脂肪主要由甘油和脂肪酸构成，不由氨基酸组成。"}, {"text": "维生素", "is_correct": false, "explanation": "语义：维生素是小分子有机化合物，并非由氨基酸组成。"}, {"text": "淀粉", "is_correct": false, "explanation": "搭配：“由……组成”说明组成成分，淀粉的组成单位是葡萄糖，不是氨基酸。"}], "explanations": {"蛋白质": "蛋白质是由氨基酸组成的有机化合物，符合句中“由氨基酸组成”的说明。", "脂肪": "语义：脂肪主要由甘油和脂肪酸构成，不由氨基酸组成。", "维生素": "语义：维生素是小分子有机化合物，并非由氨基酸组成。", "淀粉": "搭配：“由……组成”说明组成成分，淀粉的组成单位是葡萄糖，不是氨基酸。"}, "sentence_index": 0, "correct_answer": "蛋白质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "煎鸡蛋时，要先放一点蛋白质。", "explanation": "这里应该用〈油〉。煎鸡蛋要放的是油，蛋白质是营养物质，不是烹饪用的油脂。"}, {"text": "鸡蛋的蛋白质很嫩。", "explanation": "这里应该用〈蛋白〉。蛋白质指一类物质，鸡蛋里的白色部分通常叫蛋白。"}, {"text": "咖啡里加一勺蛋白质。", "explanation": "这里应该用〈糖〉。咖啡里加的是糖来调甜，蛋白质是营养成分，不用来给咖啡调味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蛋白质", "is_correct": true, "explanation": "蛋白质能专门运送氧气，符合血液里的这种物质的说明。"}, {"text": "葡萄糖", "is_correct": false, "explanation": "语义：葡萄糖是糖类，主要供能，并不负责运送氧气。"}, {"text": "胆固醇", "is_correct": false, "explanation": "搭配：“专门运送氧气”需要以运氧为功能的载体，胆固醇是脂质，不与此搭配。"}, {"text": "食盐", "is_correct": false, "explanation": "语义：食盐是调味用的矿物盐，不承担运送氧气的功能。"}], "explanations": {"蛋白质": "蛋白质能专门运送氧气，符合血液里的这种物质的说明。", "葡萄糖": "语义：葡萄糖是糖类，主要供能，并不负责运送氧气。", "胆固醇": "搭配：“专门运送氧气”需要以运氧为功能的载体，胆固醇是脂质，不与此搭配。", "食盐": "语义：食盐是调味用的矿物盐，不承担运送氧气的功能。"}, "sentence_index": 6, "correct_answer": "蛋白质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "糖尿病患者需要注射蛋白质。", "explanation": "这里应该用〈胰岛素〉。患者注射的是胰岛素这种具体激素，不是泛指的蛋白质。"}, {"text": "感冒发烧时，应该吃蛋白质来退烧。", "explanation": "这里应该用〈退烧药〉。退烧要靠药物，蛋白质是营养成分，不能退烧。"}, {"text": "吃饭以后，身体需要蛋白质来补充水分。", "explanation": "这里应该用〈水〉。补充水分要靠喝水，蛋白质是营养成分，不能补水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只蛋白质。", "corrected_sentence": "这是一种蛋白质。", "error_description": "量词错误：“只”多用于动物等，“蛋白质”应使用“种”，说“一种蛋白质”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "胃里的酶把蛋白质喝成了氨基酸。", "corrected_sentence": "胃里的酶把蛋白质分解成了氨基酸。", "error_description": "搭配错误：蛋白质不能被“喝”，应说“分解”，即“把蛋白质分解成了氨基酸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
