INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13086, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13086, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指农作物成熟脱粒后剩下的茎秆，如玉米秆、稻草等，常作为燃料、饲料或肥料。", "primary_collocate": null, "pronunciation": "jiē gǎn", "ipa": "tɕjɛ˥ kan˨˩", "syllable_count": 2, "sentences": [{"text": "理想的堆肥原料应包含“绿色”与“棕色”两类物料：前者如蔬菜残叶、果核、咖啡渣，富含氮元素，提供微生物繁殖所需的蛋白质基质；后者如干落叶、碎纸板、秸秆，富含纤维素与木质素，作为碳源维持能量代谢，并改善物料孔隙度。", "target_word": "秸秆", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农民把玉米秸秆堆在田边，冬天用来烧火。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收完麦子，地里还留着很多秸秆。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秸秆可以做饲料，牛和羊都爱吃。", "target_word": "秸秆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些地方把秸秆粉碎后放回田里当肥料。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前农村常用秸秆做饭。", "target_word": "秸秆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秸秆不能随便在田里烧，会污染空气。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把秸秆打成捆，再运到工厂。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "稻子的秸秆也叫稻草，可以盖房顶。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秸秆还田能让土地变得更肥。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捆", "label": "量词"}, {"form": "玉米秸秆", "label": "复合"}, {"form": "秸稈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "农作物脱粒后剩下的茎秆，可作燃料饲料肥料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91551975-d9d1-42af-a4e4-1a8bfc2d0b91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秸秆", "is_correct": true, "explanation": "秸秆属于干燥的棕色物料，富含纤维素与木质素，与“后者”的列举一致。"}, {"text": "蔬菜残叶", "is_correct": false, "explanation": "语义：蔬菜残叶属于绿色物料，富含氮元素，不富含纤维素。"}, {"text": "果核", "is_correct": false, "explanation": "搭配：“干落叶、碎纸板”属于干燥的棕色物料，果核属于绿色一类，不宜并列。"}, {"text": "塑料瓶", "is_correct": false, "explanation": "语义：塑料瓶不是有机物料，不含纤维素与木质素，不能用于堆肥的碳源。"}], "explanations": {"秸秆": "秸秆属于干燥的棕色物料，富含纤维素与木质素，与“后者”的列举一致。", "蔬菜残叶": "语义：蔬菜残叶属于绿色物料，富含氮元素，不富含纤维素。", "果核": "搭配：“干落叶、碎纸板”属于干燥的棕色物料，果核属于绿色一类，不宜并列。", "塑料瓶": "语义：塑料瓶不是有机物料，不含纤维素与木质素，不能用于堆肥的碳源。"}, "sentence_index": 0, "correct_answer": "秸秆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了防虫，要给庄稼喷秸秆。", "explanation": "这里应该用〈农药〉。喷洒的是液体药剂，秸秆是茎秆，喷在庄稼上不能防虫。"}, {"text": "工人用秸秆盖了一座大桥。", "explanation": "这里应该用〈钢材〉。大桥要用钢材这样坚固的材料，秸秆是茎秆，不能用来盖桥。"}, {"text": "农民每年春天在地里播秸秆。", "explanation": "这里应该用〈种子〉。秸秆是收割后剩下的茎秆，不能用来播种，播种要用种子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秸秆", "is_correct": true, "explanation": "秸秆是可燃的农作物残留，在田里烧会污染空气，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能燃烧，不存在“在田里烧”的问题。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不可燃，不会因“在田里烧”而污染空气。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“烧”的对象应是可燃物，钢铁不是可燃物，不说“在田里烧钢铁”。"}], "explanations": {"秸秆": "秸秆是可燃的农作物残留，在田里烧会污染空气，符合句意。", "石头": "语义：石头不能燃烧，不存在“在田里烧”的问题。", "玻璃": "语义：玻璃不可燃，不会因“在田里烧”而污染空气。", "钢铁": "搭配：“烧”的对象应是可燃物，钢铁不是可燃物，不说“在田里烧钢铁”。"}, "sentence_index": 6, "correct_answer": "秸秆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秸秆脱粒以后，要先晒干再装袋。", "explanation": "这里应该用〈稻谷〉。脱粒的是稻谷，秸秆是脱粒后剩下的茎，不能再脱粒。"}, {"text": "秸秆是主要的粮食，每家都要吃。", "explanation": "这里应该用〈大米〉。大米是人吃的粮食，秸秆是收割后剩下的茎，不能当粮食吃。"}, {"text": "这一季玉米长得好，秸秆很饱满。", "explanation": "这里应该用〈籽粒〉。饱满形容的是籽粒，秸秆是茎，不说饱满。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民把一只秸秆运回家。", "corrected_sentence": "农民把一捆秸秆运回家。", "error_description": "量词错误：“只”多用于动物等，秸秆可按“根”或“捆”计量，不能说“一只秸秆”，可说“一捆秸秆”或“一根秸秆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民把秸秆种在院子里。", "corrected_sentence": "农民把秸秆堆在院子里。", "error_description": "搭配错误：“种”用于植物或种子，不能用于秸秆，应说“堆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
