INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13087, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13087, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纤维素是一种由葡萄糖单元组成的多糖，是植物细胞壁的主要成分，不溶于水，是膳食纤维的重要来源。", "primary_collocate": null, "pronunciation": "xiān wéi sù", "ipa": "ɕi̯ɛn wei̯ su", "syllable_count": 3, "sentences": [{"text": "理想的堆肥原料应包含“绿色”与“棕色”两类物料：前者如蔬菜残叶、果核、咖啡渣，富含氮元素，提供微生物繁殖所需的蛋白质基质；后者如干落叶、碎纸板、秸秆，富含纤维素与木质素，作为碳源维持能量代谢，并改善物料孔隙度。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "纤维素是植物细胞壁的主要成分。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "芹菜里含有很多纤维素。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的身体不能消化纤维素。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纤维素不溶于水。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蔬菜中的纤维素有助于肠道蠕动。", "target_word": "纤维素", "complexity_tier": "T3", "furigana": "shū cài zhōng de xiān wéi sù yǒu zhù yú cháng dào rú dòng", "sentence_source": "generated"}, {"text": "棉花几乎全是纤维素。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纤维素由许多葡萄糖连在一起组成。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纤维素对肠道很有好处。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头和稻草里都有纤维素。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纖維素", "label": "繁体"}], "register": "科技", "sense_fingerprint": "植物细胞壁的主要成分，由葡萄糖组成的多糖，膳食纤维的来源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c8b8646-9bcc-4bda-9fbd-029237946042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13087, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纤维素", "is_correct": true, "explanation": "正确：“富含纤维素与木质素”并列两种棕色物料中的碳源成分，符合“作为碳源”的语境。"}, {"text": "氮元素", "is_correct": false, "explanation": "语义：氮元素是绿色物料的特征，且不能作碳源，与“后者……作为碳源”的描述矛盾。"}, {"text": "维生素", "is_correct": false, "explanation": "搭配：“作为碳源”要求提供碳的有机物，维生素是营养素，不能作碳源。"}, {"text": "水分", "is_correct": false, "explanation": "体貌：前文列举的干落叶、碎纸板、秸秆都是干燥物料，与“富含水分”的描述冲突。"}], "explanations": {"纤维素": "正确：“富含纤维素与木质素”并列两种棕色物料中的碳源成分，符合“作为碳源”的语境。", "氮元素": "语义：氮元素是绿色物料的特征，且不能作碳源，与“后者……作为碳源”的描述矛盾。", "维生素": "搭配：“作为碳源”要求提供碳的有机物，维生素是营养素，不能作碳源。", "水分": "体貌：前文列举的干落叶、碎纸板、秸秆都是干燥物料，与“富含水分”的描述冲突。"}, "sentence_index": 0, "correct_answer": "纤维素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块布的纤维素很细软。", "explanation": "这里应该用〈纤维〉。纤维指丝状的东西，布料中的纤维是一根根的线；纤维素是化合物名称，不能用来形容布料的丝缕。"}, {"text": "这根面条的纤维素很长。", "explanation": "这里应该用〈纤维〉。面条的长短、粗细指一根根的面丝；纤维素是化合物名称，不能用来指面条里的丝。"}, {"text": "他的肌肉里有很多纤维素，所以力气很大。", "explanation": "这里应该用〈肌纤维〉。肌肉由肌纤维组成，力气与之有关；纤维素是植物细胞壁的成分，人体肌肉中并没有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13087, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纤维素", "is_correct": true, "explanation": "正确：纤维素是棉花细胞壁的主要成分，“棉花几乎全是”指的正是它。"}, {"text": "木质素", "is_correct": false, "explanation": "语义：棉花几乎不含木质素，“几乎全是木质素”与棉花的实际构成不符。"}, {"text": "蛋白质", "is_correct": false, "explanation": "语义：棉花的主要成分不是蛋白质，“几乎全是蛋白质”与事实不符。"}, {"text": "脂肪", "is_correct": false, "explanation": "搭配：说“几乎全是”时要指棉花的主要构成，脂肪不是棉花的主要成分，二者不搭配。"}], "explanations": {"纤维素": "正确：纤维素是棉花细胞壁的主要成分，“棉花几乎全是”指的正是它。", "木质素": "语义：棉花几乎不含木质素，“几乎全是木质素”与棉花的实际构成不符。", "蛋白质": "语义：棉花的主要成分不是蛋白质，“几乎全是蛋白质”与事实不符。", "脂肪": "搭配：说“几乎全是”时要指棉花的主要构成，脂肪不是棉花的主要成分，二者不搭配。"}, "sentence_index": 6, "correct_answer": "纤维素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个实验用了一颗纤维素。", "explanation": "这里应该用〈种〉。“颗”多用于粒状的东西，纤维素是一种物质，不能按颗粒计量。"}, {"text": "木头里有一根纤维素。", "explanation": "这里应该直接说“纤维素”或用〈种〉。“根”用于细长的东西，如绳子、木条；纤维素是物质，不能按根计量。"}, {"text": "这瓶溶液里有一条纤维素。", "explanation": "这里应该用〈种〉。“条”用于细长的物品，纤维素是物质，不是条状的东西，不能用“条”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13087, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "棉花的主要成分是一只纤维素。", "corrected_sentence": "棉花的主要成分是纤维素。", "error_description": "“纤维素”是物质名称，不能用个体量词“只”计量（“只”多用于动物或成对、单个的物品）。应直接说“是纤维素”，去掉“一只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13087, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在实验室里分离过一只纤维素。", "corrected_sentence": "我们在实验室里分离过纤维素。", "error_description": "“纤维素”是物质名称，不能用个体量词“只”计量（“只”多用于动物或成对、单个的物品）。应说“分离过纤维素”，去掉“一只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
