INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13088, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "木质素是存在于植物细胞壁中的一种复杂高分子化合物，使树木和草本植物具有硬度和支撑力。", "primary_collocate": null, "pronunciation": "mù zhì sù", "ipa": "mu ʈʂɨ su", "syllable_count": 3, "sentences": [{"text": "理想的堆肥原料应包含“绿色”与“棕色”两类物料：前者如蔬菜残叶、果核、咖啡渣，富含氮元素，提供微生物繁殖所需的蛋白质基质；后者如干落叶、碎纸板、秸秆，富含纤维素与木质素，作为碳源维持能量代谢，并改善物料孔隙度。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "木质素让树木变得又硬又结实。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木质素存在于植物的细胞壁中。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树干里的木质素很多。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草里的木质素比树少。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木质素使木头有很强的支撑力。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "造纸时要先除去木质素。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老树的木质素比新枝多。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木质素是一种复杂的化合物。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木质素多的木头，摸起来很硬。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "木質素", "label": "繁体"}], "register": "科技", "sense_fingerprint": "植物细胞壁中的复杂高分子化合物，使植物坚硬并有支撑力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c8b8646-9bcc-4bda-9fbd-029237946042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13088, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "木质素", "is_correct": true, "explanation": "正确：“富含纤维素与木质素”并列棕色物料中的成分，与“作为碳源”的语境相符。"}, {"text": "氮元素", "is_correct": false, "explanation": "语义：氮元素是绿色物料的特征，且不作碳源，与“后者……作为碳源”的描述矛盾。"}, {"text": "蛋白质", "is_correct": false, "explanation": "语义：蛋白质基质属于绿色物料，不能作碳源，与棕色物料的描述不符。"}, {"text": "水分", "is_correct": false, "explanation": "体貌：前文的干落叶、碎纸板、秸秆都是干燥物料，与“富含水分”的描述冲突。"}], "explanations": {"木质素": "正确：“富含纤维素与木质素”并列棕色物料中的成分，与“作为碳源”的语境相符。", "氮元素": "语义：氮元素是绿色物料的特征，且不作碳源，与“后者……作为碳源”的描述矛盾。", "蛋白质": "语义：蛋白质基质属于绿色物料，不能作碳源，与棕色物料的描述不符。", "水分": "体貌：前文的干落叶、碎纸板、秸秆都是干燥物料，与“富含水分”的描述冲突。"}, "sentence_index": 0, "correct_answer": "木质素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根绳子的木质素很粗。", "explanation": "这里应该用〈纤维〉。绳子的粗细指一根根的丝；木质素是化合物名称，不能用来指丝缕。"}, {"text": "这棵老树的木质素很漂亮。", "explanation": "这里应该用〈木纹〉。木纹是木材表面的纹理，可以漂亮；木质素是细胞壁中的化合物，看不见，不能用“漂亮”形容。"}, {"text": "这棵树的木质素一圈圈的，很清楚。", "explanation": "这里应该用〈年轮〉。年轮是树干横截面上一圈圈的纹路，可以数；木质素是化合物，看不见，不能说“一圈圈的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木质素", "is_correct": true, "explanation": "正确：造纸时要除去木质素、保留纤维素，这是常见的制浆做法。"}, {"text": "纤维素", "is_correct": false, "explanation": "语义：造纸要保留纤维素作为纸的原料，除去的是木质素，不能除去纤维素。"}, {"text": "维生素", "is_correct": false, "explanation": "搭配：“除去”要求对象是需要去掉的成分，维生素是营养物质，不与“除去”搭配。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气是气体，不是造纸时需要除去的杂质，“先除去氧气”不合常理。"}], "explanations": {"木质素": "正确：造纸时要除去木质素、保留纤维素，这是常见的制浆做法。", "纤维素": "语义：造纸要保留纤维素作为纸的原料，除去的是木质素，不能除去纤维素。", "维生素": "搭配：“除去”要求对象是需要去掉的成分，维生素是营养物质，不与“除去”搭配。", "氧气": "语义：氧气是气体，不是造纸时需要除去的杂质，“先除去氧气”不合常理。"}, "sentence_index": 6, "correct_answer": "木质素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "实验室里有一只木质素。", "explanation": "这里应该用〈种〉。“只”用于动物或成对的东西，木质素是物质，不能用“只”计量。"}, {"text": "木头断面上有一颗木质素。", "explanation": "这里应该用〈种〉。“颗”多用于粒状的东西，木质素是化合物，不能按颗粒计量。"}, {"text": "这根木头里有一条木质素。", "explanation": "这里应该用〈种〉。“条”用于细长的东西，木质素是物质，不能按条计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵老树的一个木质素很多。", "corrected_sentence": "这棵老树的木质素很多。", "error_description": "“木质素”是物质名称，不能用个体量词“个”修饰。应说“这棵老树的木质素很多”，去掉“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂从木材里分离出一根木质素。", "corrected_sentence": "工厂从木材里分离出木质素。", "error_description": "“木质素”是物质名称，不能用“根”计量（“根”用于细长的东西，如绳子、木条）。应说“分离出木质素”，去掉“一根”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
