INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13089, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生物体内物质代谢过程中所伴随的能量释放、转移和利用的过程。", "primary_collocate": null, "pronunciation": "néng liàng dài xiè", "ipa": "nɤŋ˧˥ ljɑŋ˥˩ taɪ˥˩ ɕjɛ˥˩", "syllable_count": 4, "sentences": [{"text": "理想的堆肥原料应包含“绿色”与“棕色”两类物料：前者如蔬菜残叶、果核、咖啡渣，富含氮元素，提供微生物繁殖所需的蛋白质基质；后者如干落叶、碎纸板、秸秆，富含纤维素与木质素，作为碳源维持能量代谢，并改善物料孔隙度。", "target_word": "能量代谢", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "运动以后，身体的能量代谢会变快。", "target_word": "能量代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡觉时，人的能量代谢比较慢。", "target_word": "能量代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生检查了他的能量代谢。", "target_word": "能量代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人的能量代谢一般比老人快。", "target_word": "能量代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭太少会影响能量代谢。", "target_word": "能量代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天，小动物的能量代谢会变慢。", "target_word": "能量代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "甲状腺会影响人体的能量代谢。", "target_word": "能量代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药能提高能量代谢的速度。", "target_word": "能量代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植物也有能量代谢，需要阳光和水。", "target_word": "能量代谢", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "能量代谢·名词·生物体内能量的释放转移和利用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '385e789d-21ea-49b5-b03e-4cf712cdbae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13089, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“维持颜色”不是常见说法，句中的“维持”指保持微生物的活动。"}, {"text": "声音", "is_correct": false, "explanation": "语义：句中讲的是作为碳源的物料，“声音”无法与“碳源”的语境相容，句意不通。"}, {"text": "能量代谢", "is_correct": true, "explanation": "能量代谢：指生物体内能量释放、转移和利用的过程，与“碳源”和微生物的语境相符。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：物料没有脾气，“维持脾气”与“作为碳源”的说明无关。"}], "explanations": {"颜色": "搭配：“维持颜色”不是常见说法，句中的“维持”指保持微生物的活动。", "声音": "语义：句中讲的是作为碳源的物料，“声音”无法与“碳源”的语境相容，句意不通。", "能量代谢": "能量代谢：指生物体内能量释放、转移和利用的过程，与“碳源”和微生物的语境相符。", "脾气": "语义：物料没有脾气，“维持脾气”与“作为碳源”的说明无关。"}, "sentence_index": 0, "correct_answer": "能量代谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种食物含有丰富的能量代谢。", "explanation": "这里应该用〈能量〉。食物中含有的是能量，能量代谢是身体内能量释放和利用的过程，不能说“含有”。"}, {"text": "他花钱买了便宜的能量代谢。", "explanation": "这里应该用〈营养品〉。“买”和“便宜”针对可以出售的商品，能量代谢是身体内的过程，没有价格，也不能被购买。"}, {"text": "他把能量代谢放进了冰箱里。", "explanation": "这里应该用〈食品〉。能量代谢是身体内的过程，不能放进冰箱保存，冰箱里放的是食品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13089, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "语义：“心情”不会随冬天而“变慢”，句子说的是小动物的生理过程。"}, {"text": "想法", "is_correct": false, "explanation": "语义：“想法”不会“变慢”，句中描述的是小动物身体的变化。"}, {"text": "能量代谢", "is_correct": true, "explanation": "能量代谢：指生物体内能量释放、转移和利用的过程，冬天时会变慢，与语境相符。"}, {"text": "字迹", "is_correct": false, "explanation": "搭配：“字迹”不能与“变慢”搭配，也不适用于描述小动物。"}], "explanations": {"心情": "语义：“心情”不会随冬天而“变慢”，句子说的是小动物的生理过程。", "想法": "语义：“想法”不会“变慢”，句中描述的是小动物身体的变化。", "能量代谢": "能量代谢：指生物体内能量释放、转移和利用的过程，冬天时会变慢，与语境相符。", "字迹": "搭配：“字迹”不能与“变慢”搭配，也不适用于描述小动物。"}, "sentence_index": 6, "correct_answer": "能量代谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最近没有能量代谢，什么也不想吃。", "explanation": "这里应该用〈食欲〉。食欲是想吃东西的欲望，能量代谢是身体释放和利用能量的过程，不能说“没有”。"}, {"text": "他每天要吃五顿饭，身体需要很多能量代谢。", "explanation": "这里应该用〈食物〉。身体需要的是食物，能量代谢是身体释放和利用能量的过程，不是可以被需要或摄入的东西。"}, {"text": "卡路里是能量代谢的单位。", "explanation": "这里应该用〈热量〉。卡路里计量的是热量，能量代谢是过程，不能作为计量单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年纪大以后，他的能量代谢很很慢。", "corrected_sentence": "年纪大以后，他的能量代谢很慢。", "error_description": "错误：程度副词“很”重复使用，“很很慢”不成立，应只保留一个“很”。正确：“他的能量代谢很慢。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种激素能促进人的能量代谢们。", "corrected_sentence": "这种激素能促进人的能量代谢。", "error_description": "错误：“们”只能加在指人的名词之后，不能加在抽象名词“能量代谢”后。正确：应说“人的能量代谢”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
