INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13090, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体上细小的孔洞或缝隙。", "primary_collocate": null, "pronunciation": "kǒng xì", "ipa": "kʰʊŋ ɕi", "syllable_count": 2, "sentences": [{"text": "理想的堆肥原料应包含“绿色”与“棕色”两类物料：前者如蔬菜残叶、果核、咖啡渣，富含氮元素，提供微生物繁殖所需的蛋白质基质；后者如干落叶、碎纸板、秸秆，富含纤维素与木质素，作为碳源维持能量代谢，并改善物料孔隙度。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "土壤的孔隙里有空气和水。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水从石头的孔隙里流出来。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海绵有很多细小的孔隙。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，泥土孔隙里都是水。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种砖的孔隙很小。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的孔隙让冷风吹了进来。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "松软的土孔隙多，根容易长。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灰尘钻进了木板的孔隙。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用泥把石头之间的孔隙填满。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水很快就从沙土的孔隙里漏了下去。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物体（如土壤、岩石、木头）上细小的孔洞或缝隙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c8b8646-9bcc-4bda-9fbd-029237946042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孔隙", "is_correct": true, "explanation": "正确：「孔隙」指沙土中细小的孔洞，雨水可以从中漏下去。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」是视觉属性，不是能让雨水漏过的空间。"}, {"text": "声音", "is_correct": false, "explanation": "语义：「声音」不是实体空间，雨水无法从声音里漏下去。"}, {"text": "重量", "is_correct": false, "explanation": "语义：「重量」是计量数值，雨水不能从重量里漏下去。"}], "explanations": {"孔隙": "正确：「孔隙」指沙土中细小的孔洞，雨水可以从中漏下去。", "颜色": "语义：「颜色」是视觉属性，不是能让雨水漏过的空间。", "声音": "语义：「声音」不是实体空间，雨水无法从声音里漏下去。", "重量": "语义：「重量」是计量数值，雨水不能从重量里漏下去。"}, "sentence_index": 0, "correct_answer": "孔隙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙上有一根孔隙。", "explanation": "这里应该用〈个〉或〈处〉。孔隙是细小的孔洞，不用细长条形的量词〈根〉。"}, {"text": "我们的计划有很多孔隙。", "explanation": "这里应该用〈漏洞〉。孔隙只指物体上细小的孔洞或缝隙，计划的缺陷要用〈漏洞〉。"}, {"text": "山里有一个孔隙，我们走了进去。", "explanation": "这里应该用〈洞穴〉。孔隙太小，人走不进去；能让人进入的大洞要用〈洞穴〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孔隙", "is_correct": true, "explanation": "正确。「墙上的孔隙」指墙体上细小的空隙，能让冷风穿过。"}, {"text": "壁画", "is_correct": false, "explanation": "语义：「壁画」是墙面上的装饰画，不能让冷风吹进来。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」是视觉属性，不是可以透风的开口。"}, {"text": "图案", "is_correct": false, "explanation": "配价：「让……吹进来」需要能通风的通道作主语，「图案」不具备这种语义角色。"}], "explanations": {"孔隙": "正确。「墙上的孔隙」指墙体上细小的空隙，能让冷风穿过。", "壁画": "语义：「壁画」是墙面上的装饰画，不能让冷风吹进来。", "颜色": "语义：「颜色」是视觉属性，不是可以透风的开口。", "图案": "配价：「让……吹进来」需要能通风的通道作主语，「图案」不具备这种语义角色。"}, "sentence_index": 6, "correct_answer": "孔隙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上有一道漂亮的孔隙。", "explanation": "这里应该用〈花纹〉。孔隙是物体上细小的孔洞，不是好看的装饰图案。"}, {"text": "水里有很多孔隙。", "explanation": "这里应该用〈气泡〉。孔隙指固体上的细小空隙，水里的气泡要用〈气泡〉。"}, {"text": "他从孔隙探出头来看风景。", "explanation": "这里应该用〈窗口〉。孔隙太小，人的头探不出去；能让人看出去的开口要用〈窗口〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块砖上有一根孔隙。", "corrected_sentence": "这块砖上有一处孔隙。", "error_description": "量词用错。“孔隙”应该用量词“处”，“根”用于细长条状的东西，不能用于孔隙。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "用泥把墙上的孔隙堵。", "corrected_sentence": "用泥把墙上的孔隙堵住。", "error_description": "补语缺失。“把”字句中动词后面需要结果补语，应该说“堵住”，只说“堵”不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
