INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13091, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指两个事物或两个人，常用来表示对等或对比关系。", "primary_collocate": null, "pronunciation": "liǎng zhě", "ipa": "liɑŋ˨˩ ʈʂɤ˨˩", "syllable_count": 2, "sentences": [{"text": "苹果和梨都很好吃，两者我都喜欢。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红茶和绿茶，两者都对身体好。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作和生活都很重要，两者不能只要一个。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以坐火车或坐飞机，两者都很方便。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两件衣服，两者的价格差不多。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学画画和唱歌，但两者都没有时间。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理想和现实不同，两者常常有距离。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比较这两本书，两者各有各的好处。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫和狗我都养过，两者都很可爱。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习和休息要平衡，两者缺一不可。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "代指前文已提到的两个事物或两个人，用于对等或对比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c8b8646-9bcc-4bda-9fbd-029237946042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13091, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "两者", "is_correct": true, "explanation": "正确。两者 liǎng zhě 指两个事物或两个人。"}, {"text": "讲者", "is_correct": false, "explanation": "jiǎng（第三声）与 liǎng（第三声）声母不同，l 与 j 不同，意思是讲者（讲话的人）。"}, {"text": "两只", "is_correct": false, "explanation": "第二音节 zhī（第一声）与 zhě（第三声）声调不同，意思是“两只”，是数量词组。"}, {"text": "两枝", "is_correct": false, "explanation": "与两者的第二音节声调不同，意思是“两枝”（如两枝花），是数量词组。"}], "explanations": {"两者": "正确。两者 liǎng zhě 指两个事物或两个人。", "讲者": "jiǎng（第三声）与 liǎng（第三声）声母不同，l 与 j 不同，意思是讲者（讲话的人）。", "两只": "第二音节 zhī（第一声）与 zhě（第三声）声调不同，意思是“两只”，是数量词组。", "两枝": "与两者的第二音节声调不同，意思是“两枝”（如两枝花），是数量词组。"}, "sentence_index": null, "correct_answer": "两者"}, "level_3": {"options": [{"text": "两者", "is_correct": true, "explanation": "正确。「两者」回指前面的苹果和梨，都很好吃。"}, {"text": "大家", "is_correct": false, "explanation": "语义：「大家」指一群人，不指苹果和梨。"}, {"text": "自己", "is_correct": false, "explanation": "语义：「自己」指说话人或施事者本人，不指水果。"}, {"text": "彼此", "is_correct": false, "explanation": "配价：「彼此」表示双方互相，要求有互动关系，句中“我都喜欢”不成立。"}], "explanations": {"两者": "正确。「两者」回指前面的苹果和梨，都很好吃。", "大家": "语义：「大家」指一群人，不指苹果和梨。", "自己": "语义：「自己」指说话人或施事者本人，不指水果。", "彼此": "配价：「彼此」表示双方互相，要求有互动关系，句中“我都喜欢”不成立。"}, "sentence_index": 0, "correct_answer": "两者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你可以坐火车、坐飞机或坐汽车，两者都很方便。", "explanation": "这里应该用〈三者〉。两者只指两个事物或两个人，这里列出了火车、飞机、汽车三种交通工具。"}, {"text": "我们班两者都同意这个计划。", "explanation": "这里应该用〈大家〉。两者只指两个事物或两个人，不能指整个班级。"}, {"text": "这个苹果很大，两者都很甜。", "explanation": "这里应该用〈它〉。两者指两个对象，这里只有一个苹果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13091, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "两者", "is_correct": true, "explanation": "正确。「两者」指理想和现实这两个对象。"}, {"text": "他们", "is_correct": false, "explanation": "语义：「他们」指人，「理想和现实」是抽象概念。"}, {"text": "我们", "is_correct": false, "explanation": "语义：「我们」指说话的人群，不能指理想和现实。"}, {"text": "其中", "is_correct": false, "explanation": "配价：「其中」要求前文有一个可以从中选取的整体，句中并没有这样的整体。"}], "explanations": {"两者": "正确。「两者」指理想和现实这两个对象。", "他们": "语义：「他们」指人，「理想和现实」是抽象概念。", "我们": "语义：「我们」指说话的人群，不能指理想和现实。", "其中": "配价：「其中」要求前文有一个可以从中选取的整体，句中并没有这样的整体。"}, "sentence_index": 6, "correct_answer": "两者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新年快到了，两者都很忙。", "explanation": "这里应该用〈大家〉。两者只能回指前文已提到的两个对象，这句前文没有可回指的对象。"}, {"text": "今天的作业很多，两者都要交。", "explanation": "这里应该用〈全部〉。两者只指两个，作业不止两份。"}, {"text": "这家餐厅的员工，两者都很热情。", "explanation": "这里应该用〈全体〉。两者只指两个事物或两个人，餐厅的员工是一群人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13091, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "红枣和桂圆都很补，两者个我都爱吃。", "corrected_sentence": "红枣和桂圆都很补，两者我都爱吃。", "error_description": "“两者”本身已经表示“两个”，不能再加量词“个”，应说“两者”，去掉“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13091, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "运动和饮食都重要，两者们要兼顾。", "corrected_sentence": "运动和饮食都重要，两者要兼顾。", "error_description": "后缀用错。“两者”本身已经表示“两个”，不能再加“们”，应该说“两者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
