INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13093, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将不同物质放在一起拌匀", "primary_collocate": null, "pronunciation": "hùn hé", "ipa": "xuən˥˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "把牛奶和糖混合，再慢慢加热。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把面粉和水混合起来。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色和蓝色混合以后是紫色。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水和油很难混合在一起。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把三种水果混合成果汁。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把酱油和醋混合一下。", "target_word": "混合", "complexity_tier": "T3", "furigana": "qǐng bǎ jiàngyóu hé cù hùnhé yíxià", "sentence_source": "generated"}, {"text": "做蛋糕时，要先混合鸡蛋和糖。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种药不能混合着吃。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把蜂蜜和热水混合了。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这些颜色混合好，再画画。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "混合了", "label": "体标"}, {"form": "混合物", "label": "复合"}], "register": "中性", "sense_fingerprint": "把不同的物质放在一起拌匀", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c8b8646-9bcc-4bda-9fbd-029237946042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13093, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "混合", "is_correct": true, "explanation": "“混合”指把不同的东西拌在一起，符合“把牛奶和糖……，再慢慢加热”的备料步骤。"}, {"text": "切开", "is_correct": false, "explanation": "搭配：“切开”要求对象是固体，牛奶是液体，不能说“把牛奶切开”。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”用于固体，不能说“把牛奶打碎”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清除污物，与后面的加热步骤不相符，句意讲不通。"}], "explanations": {"混合": "“混合”指把不同的东西拌在一起，符合“把牛奶和糖……，再慢慢加热”的备料步骤。", "切开": "搭配：“切开”要求对象是固体，牛奶是液体，不能说“把牛奶切开”。", "打碎": "搭配：“打碎”用于固体，不能说“把牛奶打碎”。", "洗": "语义：“洗”是清除污物，与后面的加热步骤不相符，句意讲不通。"}, "sentence_index": 0, "correct_answer": "混合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两家公司混合在一起了。", "explanation": "这里应该用〈合并〉。混合指把不同的物质拌在一起；两家公司合为一体要用合并。"}, {"text": "这两个人长得很像，我总是把他们混合。", "explanation": "这里应该用〈混淆〉。混合指把不同的东西拌在一起；把两个不同的人或事弄错、分不清要用混淆。"}, {"text": "冰在阳光下混合了。", "explanation": "这里应该用〈融化〉。混合要求把两种以上的东西拌在一起；冰受热变成水要用融化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13093, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "混合", "is_correct": true, "explanation": "“混合”指把鸡蛋和糖拌在一起，是做蛋糕时的准备步骤。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是使东西跌落破碎，不是做蛋糕的步骤。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是食用，做蛋糕时不会先吃还未加工的鸡蛋和糖。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要接受者，如“送给某人”，句中缺少这个成分。"}], "explanations": {"混合": "“混合”指把鸡蛋和糖拌在一起，是做蛋糕时的准备步骤。", "摔": "语义：“摔”是使东西跌落破碎，不是做蛋糕的步骤。", "吃": "语义：“吃”是食用，做蛋糕时不会先吃还未加工的鸡蛋和糖。", "送": "配价：“送”需要接受者，如“送给某人”，句中缺少这个成分。"}, "sentence_index": 6, "correct_answer": "混合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "氢气和氧气混合成了水。", "explanation": "这里应该用〈化合〉。混合只是把东西拌在一起，不改变成分；氢和氧生成水是化学变化，要用化合。"}, {"text": "他整天混合日子，什么也不做。", "explanation": "这里应该用〈混〉（混日子）。混合指把不同的东西拌在一起；整天虚度、不干正事要用“混”。"}, {"text": "他想混合两人的矛盾。", "explanation": "这里应该用〈调和〉。混合用于拌合实物；使矛盾缓和要用调和。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13093, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把面粉和水混合很均匀。", "corrected_sentence": "他把面粉和水混合得很均匀。", "error_description": "错误：“混合很均匀”漏掉了“得”。正确：“混合得很均匀”。动作结果的状态补语前要加“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13093, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把面粉和水混合了好。", "corrected_sentence": "他把面粉和水混合好了。", "error_description": "错误：结果补语“好”应紧跟动词，“了”放在句末；“混合了好”把“了”插在动词和补语之间。正确：“混合好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13094, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13094, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13094, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "氨水或含氨物质所具有的刺激性气味。", "primary_collocate": null, "pronunciation": "ān wèi", "ipa": "an˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "两者按体积比约为1:2至1:3混合，可避免因氮过高导致的氨味逸散，或碳过量引发的分解迟滞。", "target_word": "氨味", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "厕所里有一股很重的氨味。", "target_word": "氨味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打开那瓶氨水，我闻到了刺鼻的氨味。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猪圈里的氨味让人不想靠近。", "target_word": "氨味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "堆肥发酵不好，就会有氨味。", "target_word": "氨味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人戴上口罩，因为车间里氨味很浓。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开窗通风以后，房间里的氨味慢慢变淡了。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种肥料有一股明显的氨味。", "target_word": "氨味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老鼠笼里传出一阵氨味，该清洗了。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里的氨味，是氨水挥发出来的。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股", "label": "量词"}], "register": "中性", "sense_fingerprint": "氨水、含氨物质的刺激性气味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86537d87-dd9d-4550-9cf6-595ab4b6d796') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13094, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "氨味", "is_correct": true, "explanation": "正确：氨味是氨挥发出的气味，可以逸散，符合句意。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：「逸散」说的是气体、气味散开，温度不说逸散。"}, {"text": "固体", "is_correct": false, "explanation": "语义：固体不会像气体那样逸散，句中说的是气味。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会从容器里逸散出去，句意说不通。"}], "explanations": {"氨味": "正确：氨味是氨挥发出的气味，可以逸散，符合句意。", "温度": "搭配：「逸散」说的是气体、气味散开，温度不说逸散。", "固体": "语义：固体不会像气体那样逸散，句中说的是气味。", "颜色": "语义：颜色不会从容器里逸散出去，句意说不通。"}, "sentence_index": 0, "correct_answer": "氨味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道汤的氨味很足，喝一口就停不下来。", "explanation": "这里应该用〈鲜味〉。氨味是刺鼻的气味，不能用来形容汤的美味，汤的鲜美要说鲜味。"}, {"text": "这束花散发着好闻的氨味。", "explanation": "这里应该用〈香味〉。氨味是刺鼻的气味，不能用来形容好闻的花香。"}, {"text": "我往水里倒了一些氨味。", "explanation": "这里应该用〈氨水〉。氨味是气味，不是液体，不能倒进水里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "氨味", "is_correct": true, "explanation": "正确：氨味是气味，开窗通风后会慢慢变淡，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「淡」说的是气味、颜色的浓度，价格不会变淡。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：「变淡」不用于体温，体温说升高或降低。"}, {"text": "灰尘", "is_correct": false, "explanation": "搭配：灰尘的多少说「减少」，不说「变淡」。"}], "explanations": {"氨味": "正确：氨味是气味，开窗通风后会慢慢变淡，符合句意。", "价格": "语义：「淡」说的是气味、颜色的浓度，价格不会变淡。", "体温": "搭配：「变淡」不用于体温，体温说升高或降低。", "灰尘": "搭配：灰尘的多少说「减少」，不说「变淡」。"}, "sentence_index": 6, "correct_answer": "氨味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的氨味很鲜艳。", "explanation": "这里应该用〈色彩〉。氨味是气味，不能用来形容颜色鲜艳，画面的颜色要说色彩。"}, {"text": "春天的院子里弥漫着一阵氨味，好闻极了。", "explanation": "这里应该用〈花香〉。氨味刺鼻，不能用来形容好闻的院子。"}, {"text": "餐桌上飘来一阵氨味，香得人直流口水。", "explanation": "这里应该用〈饭香〉。氨味不是香味，不能说香得人直流口水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房里有一股很浓氨味。", "corrected_sentence": "厨房里有一股很浓的氨味。", "error_description": "「很浓」修饰「氨味」，中间要加「的」，应说「很浓的氨味」，不能省略「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人一进门就闻到一只氨味。", "corrected_sentence": "工人一进门就闻到一股氨味。", "error_description": "量词错误：「氨味」的量词应为「股」，「只」只用于动物或单个物件，不能用于气味。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
