INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13095, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13095, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指气体、气味等逐渐扩散、消失。", "primary_collocate": null, "pronunciation": "yì sàn", "ipa": "i˥˩ san˥˩", "syllable_count": 2, "sentences": [{"text": "两者按体积比约为1:2至1:3混合，可避免因氮过高导致的氨味逸散，或碳过量引发的分解迟滞。", "target_word": "逸散", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "瓶盖没拧紧，气体慢慢逸散了。", "target_word": "逸散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香味在空气中逐渐逸散。", "target_word": "逸散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "室内的臭味会逐渐逸散，空气随之净化。", "target_word": "逸散", "complexity_tier": "T3", "furigana": "yì sàn", "sentence_source": "generated"}, {"text": "实验时要盖好盖子，防止气体逸散。", "target_word": "逸散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度升高后，容器里的刺激性气味会逸散出来。", "target_word": "逸散", "complexity_tier": "T3", "furigana": "yì sàn", "sentence_source": "generated"}, {"text": "冷库门没关，里面的冷气正在逸散。", "target_word": "逸散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡放久了，香气会一点点逸散。", "target_word": "逸散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "密封袋能减少食物气味逸散。", "target_word": "逸散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "化肥里的氨气会逸散到空气中。", "target_word": "逸散", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逸散了", "label": "体标"}, {"form": "逸散过", "label": "体标"}], "register": "书面", "sense_fingerprint": "气体、气味逐渐扩散并消失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86537d87-dd9d-4550-9cf6-595ab4b6d796') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13095, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逸散", "is_correct": true, "explanation": "正确：「逸散」用于气味、气体散开，「氨味逸散」符合句意。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：氨味是气体，不会凝固，句意说不通。"}, {"text": "粉碎", "is_correct": false, "explanation": "搭配：「粉碎」用于固体，不说粉碎气味。"}, {"text": "融化", "is_correct": false, "explanation": "语义：气味不会融化，句中说的是气味散开。"}], "explanations": {"逸散": "正确：「逸散」用于气味、气体散开，「氨味逸散」符合句意。", "凝固": "语义：氨味是气体，不会凝固，句意说不通。", "粉碎": "搭配：「粉碎」用于固体，不说粉碎气味。", "融化": "语义：气味不会融化，句中说的是气味散开。"}, "sentence_index": 0, "correct_answer": "逸散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块糖放进水里，慢慢逸散了。", "explanation": "这里应该用〈溶解〉。「逸散」只说气体、气味散进空气中，糖在水里要说溶解。"}, {"text": "泥沙慢慢逸散到杯底。", "explanation": "这里应该用〈沉淀〉。「逸散」只用于气体、气味，泥沙下沉要说沉淀。"}, {"text": "冰块在阳光下慢慢逸散。", "explanation": "这里应该用〈融化〉。「逸散」用于气体、气味，冰块变成水要说融化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13095, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逸散", "is_correct": true, "explanation": "正确：冷气散开、跑出去要说「逸散」，符合句意。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：「切割」的对象是有形的东西，冷气不能切割。"}, {"text": "倒塌", "is_correct": false, "explanation": "语义：冷气不会倒塌，倒塌说的是建筑或物体垮掉。"}, {"text": "断裂", "is_correct": false, "explanation": "语义：冷气不会断裂，断裂说的是物体折断。"}], "explanations": {"逸散": "正确：冷气散开、跑出去要说「逸散」，符合句意。", "切割": "搭配：「切割」的对象是有形的东西，冷气不能切割。", "倒塌": "语义：冷气不会倒塌，倒塌说的是建筑或物体垮掉。", "断裂": "语义：冷气不会断裂，断裂说的是物体折断。"}, "sentence_index": 6, "correct_answer": "逸散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火山逸散出了滚烫的岩浆。", "explanation": "这里应该用〈迸发〉。「逸散」指气体、气味慢慢散开，岩浆从火山喷涌而出要说迸发。"}, {"text": "水蒸气遇冷逸散成了小水珠。", "explanation": "这里应该用〈凝结〉。水蒸气遇冷变成水珠是凝结，「逸散」说的是散开消失。"}, {"text": "书架上的书逸散了一地。", "explanation": "这里应该用〈散落〉。「逸散」只用于气体、气味，书散在地上要说散落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13095, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房的煤气会很逸散到屋外。", "corrected_sentence": "厨房的煤气会慢慢逸散到屋外。", "error_description": "程度副词错误：「很」不能直接修饰动词「逸散」，此处应用表示方式的「慢慢」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13095, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汤的香气很逸散到厨房里。", "corrected_sentence": "汤的香气慢慢逸散到厨房里。", "error_description": "程度副词错误：「很」不能直接修饰动词「逸散」，此处应用表示方式的「慢慢」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
