INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13096, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "超过正常的或合适的数量", "primary_collocate": null, "pronunciation": "guò liàng", "ipa": "kwo˥˩ ljaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "两者按体积比约为1:2至1:3混合，可避免因氮过高导致的氨味逸散，或碳过量引发的分解迟滞。", "target_word": "过量", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "药吃过量会伤身体。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他昨晚饮酒过量，今天头疼。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "糖摄入过量，容易变胖。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动过量对身体不好。", "target_word": "过量", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说，这种药不能过量服用。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盐放过量了，这道菜太咸。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "咖啡喝得过量，晚上会睡不着。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "肥料用过量，花反而会死。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水果吃得过量，肚子也会不舒服。", "target_word": "过量", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "過量", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数量超过正常或合适的限度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86537d87-dd9d-4550-9cf6-595ab4b6d796') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过量", "is_correct": true, "explanation": "正确：句中指碳超出所需的量，并引发分解迟滞，只有「过量」符合。"}, {"text": "适量", "is_correct": false, "explanation": "语义：「适量」指恰到好处，不会引发不良后果，与「引发的分解迟滞」矛盾。"}, {"text": "充沛", "is_correct": false, "explanation": "搭配：「充沛」多形容精力、雨水，不用来修饰「碳」。"}, {"text": "理想", "is_correct": false, "explanation": "语义：「理想」表示最好的状态，不能说它引发分解迟滞。"}], "explanations": {"过量": "正确：句中指碳超出所需的量，并引发分解迟滞，只有「过量」符合。", "适量": "语义：「适量」指恰到好处，不会引发不良后果，与「引发的分解迟滞」矛盾。", "充沛": "搭配：「充沛」多形容精力、雨水，不用来修饰「碳」。", "理想": "语义：「理想」表示最好的状态，不能说它引发分解迟滞。"}, "sentence_index": 0, "correct_answer": "过量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的温度过量了，开开窗吧。", "explanation": "这里应该用〈过高〉。过量指数量或用量超出限度，温度要说过高，不说过量。"}, {"text": "他这个月迟到的次数过量了。", "explanation": "这里应该用〈过多〉。次数可以数，应说过多；过量多用于食用、用药、用料等超出限度的量。"}, {"text": "我们在门口等的时间过量了，都快冻僵了。", "explanation": "这里应该用〈过久〉。等待的时长要说过久；过量指数量或用量超出限度，不用来形容时间的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过量", "is_correct": true, "explanation": "正确：盐放得超出所需，后半句「这道菜太咸」才成立。"}, {"text": "过少", "is_correct": false, "explanation": "语义：盐放得太少不会让菜太咸，与后半句「这道菜太咸」矛盾。"}, {"text": "不够", "is_correct": false, "explanation": "语义：盐不够，菜应当偏淡，与后半句「这道菜太咸」矛盾。"}, {"text": "过咸", "is_correct": false, "explanation": "搭配：「咸」形容味道，不能修饰放盐的动作，「盐放过咸」说法不通。"}], "explanations": {"过量": "正确：盐放得超出所需，后半句「这道菜太咸」才成立。", "过少": "语义：盐放得太少不会让菜太咸，与后半句「这道菜太咸」矛盾。", "不够": "语义：盐不够，菜应当偏淡，与后半句「这道菜太咸」矛盾。", "过咸": "搭配：「咸」形容味道，不能修饰放盐的动作，「盐放过咸」说法不通。"}, "sentence_index": 6, "correct_answer": "过量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的鞋子过量，走起路来很别扭。", "explanation": "这里应该用〈过大〉。鞋子的大小要说过大，过量只用于物质或用量超出限度，不用来形容鞋的尺寸。"}, {"text": "老师对他的夸奖过量了，他有点骄傲。", "explanation": "这里应该用〈过分〉。夸奖的程度要说过分，过量不用来形容夸奖。"}, {"text": "这部电影的片长过量，看得人很累。", "explanation": "这里应该用〈过长〉。长度要说过长，过量指数量超出限度，不用于形容时长或篇幅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天喝饮料喝地过量，晚上总是睡不着。", "corrected_sentence": "他每天喝饮料喝得过量，晚上总是睡不着。", "error_description": "补语标记错误：引出补语应用「得」，「地」是状语标记，不能用于动词后的补语，「喝地过量」不通，应说「喝得过量」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一下子吃了很过量维生素，结果肚子疼。", "corrected_sentence": "他一下子吃了过量维生素，结果肚子疼。", "error_description": "程度副词错误：「过量」是形容词，作定语修饰名词时不能加「很」，应直接说「过量维生素」；「很过量维生素」母语者会立刻觉得不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
