INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13097, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指行动或进展缓慢，停留不动，不能及时跟上。", "primary_collocate": null, "pronunciation": "chí zhì", "ipa": "tʂʰɨ˧˥ tʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "两者按体积比约为1:2至1:3混合，可避免因氮过高导致的氨味逸散，或碳过量引发的分解迟滞。", "target_word": "迟滞", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "天气不好，工程进度迟滞了。", "target_word": "迟滞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "资金不足，让项目长期迟滞。", "target_word": "迟滞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水结冰后，船只迟滞在港口。", "target_word": "迟滞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改革迟滞，企业很难发展。", "target_word": "迟滞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为大雪，火车迟滞了两个小时。", "target_word": "迟滞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作进展迟滞，老板很着急。", "target_word": "迟滞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交通迟滞，我们没有按时到。", "target_word": "迟滞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题让整个计划迟滞不前。", "target_word": "迟滞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场迟滞的原因是需求太少。", "target_word": "迟滞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "行动或进展缓慢停滞，跟不上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86537d87-dd9d-4550-9cf6-595ab4b6d796') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13097, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迟滞", "is_correct": true, "explanation": "正确：「迟滞」指分解过程变慢、停留，符合「引发的分解」的语义。"}, {"text": "复原", "is_correct": false, "explanation": "搭配：「复原」指恢复原状，不能与「分解」搭配，句子不通。"}, {"text": "驱散", "is_correct": false, "explanation": "搭配：「驱散」用于人群、雾气等，不说「分解驱散」。"}, {"text": "增殖", "is_correct": false, "explanation": "语义：「增殖」指数量增加，与「引发的分解」所表达的效果不符。"}], "explanations": {"迟滞": "正确：「迟滞」指分解过程变慢、停留，符合「引发的分解」的语义。", "复原": "搭配：「复原」指恢复原状，不能与「分解」搭配，句子不通。", "驱散": "搭配：「驱散」用于人群、雾气等，不说「分解驱散」。", "增殖": "语义：「增殖」指数量增加，与「引发的分解」所表达的效果不符。"}, "sentence_index": 0, "correct_answer": "迟滞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议迟滞到了下午。", "explanation": "这里应该用〈推迟〉。会议、活动的时间往后改要说推迟；迟滞指进展缓慢、停滞不前，不用于安排的时间改期。"}, {"text": "那次展览迟滞到了下个月。", "explanation": "这里应该用〈延期〉。展览的举办日期往后改要说延期；迟滞指进展缓慢、停滞不前，不用于日期的推后。"}, {"text": "他迟滞了三十分钟。", "explanation": "这里应该用〈迟到〉。到达时间晚要说迟到；迟滞不指时间上的晚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13097, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迟滞", "is_correct": true, "explanation": "正确：进展缓慢停滞，老板才会着急。"}, {"text": "挥发", "is_correct": false, "explanation": "搭配：「挥发」多用于液体、气味，不说「进展挥发」。"}, {"text": "中和", "is_correct": false, "explanation": "语义：「中和」指两种力量相互抵消，与「进展」的状态不符，句子意思不通。"}, {"text": "消弭", "is_correct": false, "explanation": "语义：「消弭」指消除，进展被消除与「老板很着急」的语境不合。"}], "explanations": {"迟滞": "正确：进展缓慢停滞，老板才会着急。", "挥发": "搭配：「挥发」多用于液体、气味，不说「进展挥发」。", "中和": "语义：「中和」指两种力量相互抵消，与「进展」的状态不符，句子意思不通。", "消弭": "语义：「消弭」指消除，进展被消除与「老板很着急」的语境不合。"}, "sentence_index": 6, "correct_answer": "迟滞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他迟滞了一下，才回答问题。", "explanation": "这里应该用〈迟疑〉。心里犹豫、拿不定主意用迟疑；迟滞指进展或动作缓慢停滞，不指心理犹豫。"}, {"text": "讲到这里，他迟滞了一下。", "explanation": "这里应该用〈停顿〉。说话时的短暂中断用停顿；迟滞不指说话间的间歇。"}, {"text": "疼痛迟滞了，他终于能睡着了。", "explanation": "这里应该用〈消退〉。疼痛、症状减轻要说消退；迟滞不指痛感减轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨过后，施工进度迟滞得三天。", "corrected_sentence": "大雨过后，施工进度迟滞了三天。", "error_description": "补语标记错误：「得」后面要接描述程度的补语（如「迟滞得很厉害」），表示时长要用「了」，应说「迟滞了三天」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上周因为大雪，货物迟滞了在仓库里。", "corrected_sentence": "上周因为大雪，货物迟滞在仓库里。", "error_description": "「了」不应插在「迟滞」和处所「在仓库里」之间，应说「货物迟滞在仓库里」；「迟滞了在仓库里」母语者会立刻觉得不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13098, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自制", "is_correct": true, "explanation": "正确答案。自制指自己制作，与“市售”（在商店里卖的）相对。"}, {"text": "进口", "is_correct": false, "explanation": "进口指从国外输入，与市售不构成反义关系。"}, {"text": "精美", "is_correct": false, "explanation": "精美指精致漂亮，与市售不构成反义关系。"}, {"text": "廉价", "is_correct": false, "explanation": "廉价指价格低，与市售不构成反义关系。"}], "correct_answer": "自制", "explanations": {"自制": "正确答案。自制指自己制作，与“市售”（在商店里卖的）相对。", "进口": "进口指从国外输入，与市售不构成反义关系。", "精美": "精美指精致漂亮，与市售不构成反义关系。", "廉价": "廉价指价格低，与市售不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13098, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自制", "is_correct": true, "explanation": "正确答案。自制指自己制作，与“市售”（在商店里卖的）相对。"}, {"text": "高档", "is_correct": false, "explanation": "高档指等级高，与市售不构成反义关系。"}, {"text": "常见", "is_correct": false, "explanation": "常见指经常看到，与市售不构成反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "便宜指价格低，与市售不构成反义关系。"}], "correct_answer": "自制", "explanations": {"自制": "正确答案。自制指自己制作，与“市售”（在商店里卖的）相对。", "高档": "高档指等级高，与市售不构成反义关系。", "常见": "常见指经常看到，与市售不构成反义关系。", "便宜": "便宜指价格低，与市售不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13098, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指在商店中出售的，通常与自制或仅在特定渠道销售相对。", "primary_collocate": null, "pronunciation": "shì shòu", "ipa": "ʂɨ˥˩ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "容器选择亦具弹性，可采用市售多层发酵箱，亦可自制木质或塑料封闭结构，关键是底部设排水孔，顶部配置可开启盖板以调控温湿度。", "target_word": "市售", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "市售牛奶都有保质期。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我更喜欢自己做面包，不买市售的。", "target_word": "市售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市售的蜂蜜价格不一样。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药是市售的，药店就能买到。", "target_word": "市售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多市售果汁里都加了糖。", "target_word": "市售", "complexity_tier": "T3", "furigana": "shì shòu", "sentence_source": "generated"}, {"text": "他用市售的盒子装东西。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自制酸奶比市售酸奶便宜。", "target_word": "市售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市售的鸡蛋大小差不多。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种面条是市售产品，很方便。", "target_word": "市售", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "商店里公开出售的，相对自制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86537d87-dd9d-4550-9cf6-595ab4b6d796') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13098, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "市售", "is_correct": true, "explanation": "正确答案。shì shòu 指在商店里卖的。"}, {"text": "制售", "is_correct": false, "explanation": "zhì shòu（第四声）与 shì shòu 声母不同（zh 与 sh），意思是生产并销售。"}, {"text": "失守", "is_correct": false, "explanation": "shī shǒu 第一个音节声调不同，第二个音节也不同，意思是丢掉阵地。"}, {"text": "私售", "is_correct": false, "explanation": "sī shòu（第一声）与 shì shòu 声母与声调都不同（s 与 sh），意思是私下出售。"}], "explanations": {"市售": "正确答案。shì shòu 指在商店里卖的。", "制售": "zhì shòu（第四声）与 shì shòu 声母不同（zh 与 sh），意思是生产并销售。", "失守": "shī shǒu 第一个音节声调不同，第二个音节也不同，意思是丢掉阵地。", "私售": "sī shòu（第一声）与 shì shòu 声母与声调都不同（s 与 sh），意思是私下出售。"}, "sentence_index": null, "correct_answer": "市售"}, "level_3": {"options": [{"text": "市售", "is_correct": true, "explanation": "正确答案。与“可采用……多层发酵箱”搭配，并与“亦可自制”形成对照。"}, {"text": "无孔", "is_correct": false, "explanation": "语义：后文“底部设排水孔”要求箱子有孔，“无孔”与之矛盾。"}, {"text": "密封", "is_correct": false, "explanation": "语义：后文“顶部配置可开启盖板”要求可以开合，“密封”与之矛盾。"}, {"text": "一次性", "is_correct": false, "explanation": "搭配：“一次性”多用于餐具等用品，不与“多层发酵箱”搭配。"}], "explanations": {"市售": "正确答案。与“可采用……多层发酵箱”搭配，并与“亦可自制”形成对照。", "无孔": "语义：后文“底部设排水孔”要求箱子有孔，“无孔”与之矛盾。", "密封": "语义：后文“顶部配置可开启盖板”要求可以开合，“密封”与之矛盾。", "一次性": "搭配：“一次性”多用于餐具等用品，不与“多层发酵箱”搭配。"}, "sentence_index": 0, "correct_answer": "市售"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在厨房亲手做了一瓶市售的果酱。", "explanation": "这里应该用〈自制〉。市售指在商店里卖的成品，不能用来形容自己亲手做的果酱。"}, {"text": "这座公园是市售的，人人都能进去。", "explanation": "这里应该用〈对外开放〉。市售指在商店里卖的商品，公园不是商品，不能用市售修饰。"}, {"text": "这种饼干是市售的，不用买，味道也很好。", "explanation": "这里应该用〈自制〉。市售指在商店里卖的，要去买；此处说不用买，应说自制的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13098, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "市售", "is_correct": true, "explanation": "正确答案。shì shòu 指在商店里卖的。"}, {"text": "失手", "is_correct": false, "explanation": "shī shǒu 两个音节的声调都不同，意思是出错或没拿稳。"}, {"text": "失收", "is_correct": false, "explanation": "shī shōu 两个音节的声调都不同，意思是农作物歉收。"}, {"text": "实收", "is_correct": false, "explanation": "shí shōu 两个音节的声调都不同，意思是实际收到的。"}], "explanations": {"市售": "正确答案。shì shòu 指在商店里卖的。", "失手": "shī shǒu 两个音节的声调都不同，意思是出错或没拿稳。", "失收": "shī shōu 两个音节的声调都不同，意思是农作物歉收。", "实收": "shí shōu 两个音节的声调都不同，意思是实际收到的。"}, "sentence_index": null, "correct_answer": "市售"}, "level_3": {"options": [{"text": "市售", "is_correct": true, "explanation": "正确答案。与“盒子”搭配，说明盒子是在商店里买的。"}, {"text": "易燃", "is_correct": false, "explanation": "语义：易燃的盒子不适合用来装东西，与句子的常见用途冲突。"}, {"text": "冰冻", "is_correct": false, "explanation": "搭配：“冰冻”多修饰食物，一般不说冰冻的盒子。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：滚烫的盒子不适合装东西，与句子的常见用途冲突。"}], "explanations": {"市售": "正确答案。与“盒子”搭配，说明盒子是在商店里买的。", "易燃": "语义：易燃的盒子不适合用来装东西，与句子的常见用途冲突。", "冰冻": "搭配：“冰冻”多修饰食物，一般不说冰冻的盒子。", "滚烫": "语义：滚烫的盒子不适合装东西，与句子的常见用途冲突。"}, "sentence_index": 6, "correct_answer": "市售"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这瓶酒是市售的，从来不对外卖。", "explanation": "这里应该用〈私藏〉。市售指在商店里卖的，与“从来不对外卖”自相矛盾；私藏指自己收着，不拿出来卖。"}, {"text": "他的新想法是市售的，大家都很喜欢。", "explanation": "这里应该用〈独创〉。市售指在商店里卖的商品，想法不能拿来卖；表示自己想出来的新想法，应说独创的。"}, {"text": "今天的比赛是市售的，很精彩。", "explanation": "这里应该用〈直播〉。市售指在商店里卖的商品，比赛不是商品；播送比赛要用直播。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种面包是市售，超市就能买到。", "corrected_sentence": "这种面包是市售的，超市就能买到。", "error_description": "“市售”作谓语时后面要加“的”，应说“是市售的”，不能只说“是市售”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种面条是很市售的，买回家就能煮。", "corrected_sentence": "这种面条是市售的，买回家就能煮。", "error_description": "“市售”是非等级形容词，不能受“很”修饰，应说“是市售的”，不说“是很市售的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13099, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
