INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13099, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示同样可以；在某种情况下也能成立", "primary_collocate": null, "pronunciation": "yì kě", "ipa": "i˥˩ kʰɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "容器选择亦具弹性，可采用市售多层发酵箱，亦可自制木质或塑料封闭结构，关键是底部设排水孔，顶部配置可开启盖板以调控温湿度。", "target_word": "亦可", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "你可以坐车去，步行亦可。", "target_word": "亦可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用手机付钱，现金亦可。", "target_word": "亦可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天太忙，明天去亦可。", "target_word": "亦可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有咖啡，喝茶亦可。", "target_word": "亦可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用笔写亦可，用电脑打字亦可。", "target_word": "亦可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米饭吃不完，带回家亦可。", "target_word": "亦可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不想做饭，叫外卖亦可。", "target_word": "亦可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先交一半钱，晚点再交亦可。", "target_word": "亦可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不在，留下电话亦可。", "target_word": "亦可", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示另一种做法同样可以", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86537d87-dd9d-4550-9cf6-595ab4b6d796') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13099, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亦可", "is_correct": true, "explanation": "正确答案。yì kě 表示另一种做法同样可以。"}, {"text": "一课", "is_correct": false, "explanation": "yī kè 两个音节的声调都不同（yī 与 yì，kè 与 kě），意思是一节课。"}, {"text": "一颗", "is_correct": false, "explanation": "yī kē 两个音节的声调都不同，意思是一粒。"}, {"text": "一刻", "is_correct": false, "explanation": "yí kè 两个音节的声调都不同，意思是十五分钟。"}], "explanations": {"亦可": "正确答案。yì kě 表示另一种做法同样可以。", "一课": "yī kè 两个音节的声调都不同（yī 与 yì，kè 与 kě），意思是一节课。", "一颗": "yī kē 两个音节的声调都不同，意思是一粒。", "一刻": "yí kè 两个音节的声调都不同，意思是十五分钟。"}, "sentence_index": null, "correct_answer": "亦可"}, "level_3": {"options": [{"text": "亦可", "is_correct": true, "explanation": "正确答案。表示“也可以自制”，与前文“可采用市售”形成并列。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示强制，与前文“亦具弹性”的可选之意冲突。"}, {"text": "只能", "is_correct": false, "explanation": "语义：“只能”表示唯一选择，与前文“可采用”的多种选择冲突。"}, {"text": "不能", "is_correct": false, "explanation": "搭配：“不能自制”与前文“可采用……”的并列结构不协调。"}], "explanations": {"亦可": "正确答案。表示“也可以自制”，与前文“可采用市售”形成并列。", "必须": "语义：“必须”表示强制，与前文“亦具弹性”的可选之意冲突。", "只能": "语义：“只能”表示唯一选择，与前文“可采用”的多种选择冲突。", "不能": "搭配：“不能自制”与前文“可采用……”的并列结构不协调。"}, "sentence_index": 0, "correct_answer": "亦可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他亦可是医生，每天都在医院工作。", "explanation": "这里应该用〈也〉。亦可表示另一做法或情况同样可以，不用来说明已经确定的事实；“每天都在医院工作”说明他确实是医生，应说“也是医生”。"}, {"text": "他昨天去了图书馆，亦可去了博物馆。", "explanation": "这里应该用〈也〉。亦可表示“也可以”，不用来说明已经完成的动作；“去了博物馆”是已经发生的事实，应说“也去了博物馆”。"}, {"text": "这个问题我已经解决了，亦可很简单。", "explanation": "这里应该用〈也〉。亦可表示可能或另一情况也成立，不能用来描述已经确定的情况；“已经解决了”说明事情已经完成，应说“也很简单”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13099, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亦可", "is_correct": true, "explanation": "正确答案。表示带回家也可以，与前文“吃不完”的语境相符。"}, {"text": "不宜", "is_correct": false, "explanation": "语义：“不宜”表示不适合，与“也可以”的许可之意相反。"}, {"text": "务必", "is_correct": false, "explanation": "语义：“务必”表示一定要，与“吃不完”后的可选语境冲突。"}, {"text": "应当", "is_correct": false, "explanation": "搭配：“应当”后面需要动词或小句，句末单用不通顺。"}], "explanations": {"亦可": "正确答案。表示带回家也可以，与前文“吃不完”的语境相符。", "不宜": "语义：“不宜”表示不适合，与“也可以”的许可之意相反。", "务必": "语义：“务必”表示一定要，与“吃不完”后的可选语境冲突。", "应当": "搭配：“应当”后面需要动词或小句，句末单用不通顺。"}, "sentence_index": 6, "correct_answer": "亦可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我觉得他很好，亦可很喜欢他。", "explanation": "这里应该用〈也〉。亦可表示另一做法同样可以，不用于表达感情的程度，此处应说“也很喜欢他”。"}, {"text": "这些书都很好，亦可看完了。", "explanation": "这里应该用〈也〉。亦可表示“也可以”，不用来陈述动作已经完成，此处应说“我也看完了”。"}, {"text": "天气很热，亦可热得出汗。", "explanation": "这里应该用〈也〉。亦可表示“也可以”，不用于描述已经发生的结果；“热得出汗”是实际结果，应说“也热得出汗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你可以打电话问我，发消息也亦可。", "corrected_sentence": "你可以打电话问我，发消息亦可。", "error_description": "“亦可”本身已含“也可以”的意思，与“也”叠用，语义重复，应只说“发消息亦可”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13099, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事今天办亦可可以。", "corrected_sentence": "这件事今天办亦可。", "error_description": "“亦可”本身已含“可以”的意思，后面不能再加“可以”，应说“今天办亦可”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
