INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13100, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13100, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用木材制成的。", "primary_collocate": null, "pronunciation": "mù zhì", "ipa": "mu˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "回望历史，从木质风车到纳米级光伏材料，能源技术的演化本质是人类对自然规律认知深度的具象化。", "target_word": "木质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "容器选择亦具弹性，可采用市售多层发酵箱，亦可自制木质或塑料封闭结构，关键是底部设排水孔，顶部配置可开启盖板以调控温湿度。", "target_word": "木质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我家有一张木质的小桌子。", "target_word": "木质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木质地板踩上去很舒服。", "target_word": "木质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这把木质椅子是爷爷做的。", "target_word": "木质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木质玩具比塑料玩具安全。", "target_word": "木质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了一个木质的书架放在房间里。", "target_word": "木质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座木质小桥已经有一百年了。", "target_word": "木质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木质的东西怕水，要放在干的地方。", "target_word": "木质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个木质盒子里放着奶奶的旧照片。", "target_word": "木质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "木質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物品的材料是木头，用木材制成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07a53c-a9cf-4bf8-a96d-3c0a8dd8e503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "木质", "is_correct": true, "explanation": "正确。“木质风车”指用木材制成的风车，与“风车”搭配，句意通顺。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：风车是坚硬的机械结构，不能说“柔软风车”。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”描述温度，与风车的材料和技术演化无关，句中不成立。"}, {"text": "呆板", "is_correct": false, "explanation": "语义：“呆板”形容人或作风僵化，不能修饰风车。"}], "explanations": {"木质": "正确。“木质风车”指用木材制成的风车，与“风车”搭配，句意通顺。", "柔软": "搭配：风车是坚硬的机械结构，不能说“柔软风车”。", "冰冷": "语义：“冰冷”描述温度，与风车的材料和技术演化无关，句中不成立。", "呆板": "语义：“呆板”形容人或作风僵化，不能修饰风车。"}, "sentence_index": 0, "correct_answer": "木质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书放进了木质。", "explanation": "这里应该用〈木箱〉。“木质”是形容词，只描述材料的性质，不能指装东西的容器，句中应说“木箱”。"}, {"text": "他每天早上吃木质当早饭。", "explanation": "这里应该用〈早饭〉。“木质”只描述材料的性质，不能指可以吃的东西，这里应说“早饭”。"}, {"text": "他性格很木质，不爱说话。", "explanation": "这里应该用〈木讷〉。“木讷”形容人反应慢、不善言辞；“木质”只指材料，不能形容性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木质", "is_correct": true, "explanation": "正确。“一个木质的书架”指用木材制成的书架，与句意相符。"}, {"text": "愤怒", "is_correct": false, "explanation": "搭配：“愤怒”是人的情绪，书架不能愤怒。"}, {"text": "无声", "is_correct": false, "explanation": "语义：“无声”描述有没有声音，不能用来修饰书架。"}, {"text": "轻快", "is_correct": false, "explanation": "语义：“轻快”形容动作或节奏，不能修饰书架的材料。"}], "explanations": {"木质": "正确。“一个木质的书架”指用木材制成的书架，与句意相符。", "愤怒": "搭配：“愤怒”是人的情绪，书架不能愤怒。", "无声": "语义：“无声”描述有没有声音，不能用来修饰书架。", "轻快": "语义：“轻快”形容动作或节奏，不能修饰书架的材料。"}, "sentence_index": 6, "correct_answer": "木质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的木质响了，你接一下吧。", "explanation": "这里应该用〈手机〉。手机是会发出声音的电子设备；“木质”只指木头的性质或木制材料，不能指发出声音的东西。"}, {"text": "这块饼干很木质，嚼起来很硬。", "explanation": "这里“木质”只用于说材料，不能形容饼干的口感；饼干的口感应说“干硬”。"}, {"text": "木质很好听，我常常听。", "explanation": "这里应该用〈歌〉。“木质”只描述材料，不能形容声音；好听的是歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把椅子是木质的的。", "corrected_sentence": "这把椅子是木质的。", "error_description": "“的”重复：“木质的”已经带“的”，后面不能再加“的”。正确形式是“这把椅子是木质的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个的木质盒子很结实。", "corrected_sentence": "那个木质盒子很结实。", "error_description": "“的”位置错误：“那个”和“木质”之间不能加“的”，应说“那个木质盒子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
