INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13101, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "设立、布置、筹划。", "primary_collocate": null, "pronunciation": "shè", "ipa": "ʂɤ˥˩", "syllable_count": 1, "sentences": [{"text": "这家公司在上海设了一个分公司。", "target_word": "设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校今年设了新的奖学金。", "target_word": "设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政府在路口设了一个检查站。", "target_word": "设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里在路口设了一个摊位。", "target_word": "设", "complexity_tier": "T3", "furigana": "cūn lǐ zài lù kǒu shè le yí ge tān wèi。", "sentence_source": "generated"}, {"text": "他们在山上设了几处休息站。", "target_word": "设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板今晚要设宴招待远方来的客人。", "target_word": "设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在路上设卡检查过往的车。", "target_word": "设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "猎人在树林里设了一个陷阱。", "target_word": "设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小城以前设过一所大学。", "target_word": "设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给他设了个圈套，他没发现。", "target_word": "设", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "设了", "label": "完成体"}, {"form": "设过", "label": "经历体"}, {"form": "設", "label": "繁体"}], "register": "中性", "sense_fingerprint": "设立机构、关卡、摊点，或布置筹办宴席、圈套", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 宴 (Zipf 3.55), 招待 (Zipf 3.98), 远方 (Zipf 3.96)']::text[], '9799c0aa-2ee0-4905-9cb8-472d94641281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13101, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "设", "is_correct": true, "explanation": "正确答案。设（shè）表示设立、布置，与听到的读音一致。"}, {"text": "色", "is_correct": false, "explanation": "色（sè）与设（shè）声母不同（s 与 sh），声调相同，意思是颜色。"}, {"text": "舍", "is_correct": false, "explanation": "舍（shě）与设（shè）声调不同（第三声与第四声），意思是房屋或舍弃。"}, {"text": "十", "is_correct": false, "explanation": "十（shí）与设（shè）声调不同（第二声与第四声），意思是数字十。"}, {"text": "是", "is_correct": false, "explanation": "是（shì）与设（shè）声母、声调相同，仅韵母不同（i 与 e），意思是对、是的。"}, {"text": "蛇", "is_correct": false, "explanation": "蛇（shé）与设（shè）声调不同（第二声与第四声），意思是蛇。"}], "explanations": {"设": "正确答案。设（shè）表示设立、布置，与听到的读音一致。", "色": "色（sè）与设（shè）声母不同（s 与 sh），声调相同，意思是颜色。", "舍": "舍（shě）与设（shè）声调不同（第三声与第四声），意思是房屋或舍弃。", "十": "十（shí）与设（shè）声调不同（第二声与第四声），意思是数字十。", "是": "是（shì）与设（shè）声母、声调相同，仅韵母不同（i 与 e），意思是对、是的。", "蛇": "蛇（shé）与设（shè）声调不同（第二声与第四声），意思是蛇。"}, "sentence_index": null, "correct_answer": "设"}, "level_3": {"options": [{"text": "设", "is_correct": true, "explanation": "正确。设了一个分公司，指在上海设立分公司，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“分公司”作宾语，分公司不能被吃。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指演唱，与设立分公司的意思无关。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚碰撞，与设立机构无关。"}], "explanations": {"设": "正确。设了一个分公司，指在上海设立分公司，符合句意。", "吃": "搭配：“吃”不能带“分公司”作宾语，分公司不能被吃。", "唱": "语义：“唱”指演唱，与设立分公司的意思无关。", "踢": "语义：“踢”指用脚碰撞，与设立机构无关。"}, "sentence_index": 0, "correct_answer": "设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在院子里设了一棵树。", "explanation": "这里应该用〈种〉。设用于设立机构、关卡、摊点，种树要用〈种〉。"}, {"text": "他一个人设了一座房子。", "explanation": "这里应该用〈盖〉。设用于设立机构、关卡、摊点，盖房子要用〈盖〉。"}, {"text": "他们在河上设了一座桥。", "explanation": "这里应该用〈修〉。设用于设立机构、关卡、摊点，修桥要用〈修〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13101, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "设", "is_correct": true, "explanation": "正确答案。设（shè）表示设立、布置，与听到的读音一致。"}, {"text": "示", "is_correct": false, "explanation": "示（shì）与设（shè）声母、声调相同，仅韵母不同（i 与 e），意思是展示、表示。"}, {"text": "事", "is_correct": false, "explanation": "事（shì）与设（shè）声母、声调相同，仅韵母不同（i 与 e），意思是事情。"}, {"text": "涩", "is_correct": false, "explanation": "涩（sè）与设（shè）声母不同（s 与 sh），声调相同，意思是不光滑、难懂。"}, {"text": "奢", "is_correct": false, "explanation": "奢（shē）与设（shè）声调不同（第一声与第四声），意思是奢侈。"}], "explanations": {"设": "正确答案。设（shè）表示设立、布置，与听到的读音一致。", "示": "示（shì）与设（shè）声母、声调相同，仅韵母不同（i 与 e），意思是展示、表示。", "事": "事（shì）与设（shè）声母、声调相同，仅韵母不同（i 与 e），意思是事情。", "涩": "涩（sè）与设（shè）声母不同（s 与 sh），声调相同，意思是不光滑、难懂。", "奢": "奢（shē）与设（shè）声调不同（第一声与第四声），意思是奢侈。"}, "sentence_index": null, "correct_answer": "设"}, "level_3": {"options": [{"text": "设", "is_correct": true, "explanation": "正确。设卡指设立关卡，与后文检查过往车辆相符。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带宾语“卡”。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”不能与“卡”搭配，无法表示设立关卡。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指睡觉，与设立关卡的意思无关。"}], "explanations": {"设": "正确。设卡指设立关卡，与后文检查过往车辆相符。", "笑": "配价：“笑”是不及物动词，不能带宾语“卡”。", "哭": "搭配：“哭”不能与“卡”搭配，无法表示设立关卡。", "睡": "语义：“睡”指睡觉，与设立关卡的意思无关。"}, "sentence_index": 6, "correct_answer": "设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在地上设了一口井。", "explanation": "这里应该用〈挖〉。设用于设立机构、关卡、摊点，挖井要用〈挖〉。"}, {"text": "警察在路口设了一个小偷。", "explanation": "这里应该用〈抓〉。设不能用于人，抓小偷要用〈抓〉。"}, {"text": "他设了一首歌，很好听。", "explanation": "这里应该用〈写〉。设用于设立、布置、筹划，写歌要用〈写〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13101, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校在门口了设一个报名处。", "corrected_sentence": "学校在门口设了一个报名处。", "error_description": "“了”的位置错误：完成体“了”应紧跟动词，应说“设了”，不能放在动词“设”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13101, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个社区以前设了过一个服务站。", "corrected_sentence": "这个社区以前设过一个服务站。", "error_description": "“了”与“过”重复：经历体“过”与完成体“了”不能同时用在“设”后，应只用“设过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
