INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13102, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小洞；窟窿；像洞一样的东西。", "primary_collocate": null, "pronunciation": "kǒng", "ipa": "kʰʊŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "容器选择亦具弹性，可采用市售多层发酵箱，亦可自制木质或塑料封闭结构，关键是底部留一个孔用来排水，顶部配置可开启盖板以调控温湿度。", "target_word": "孔", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "墙上有一个孔，风从里面吹进来。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木板上的孔很小，手指放不进去。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在墙上钻了一个孔，准备挂画。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水从桶底的孔里流了出来。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在纸的中间打一个孔，再把绳子穿过去。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孔太大了，螺丝会掉出来。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠从门下面的孔跑进了房间。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮带上的每个孔都离得很近。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子侧面留了一个孔，空气可以进去。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小孔", "label": "复合词"}, {"form": "针孔", "label": "复合词"}, {"form": "气孔", "label": "复合词"}, {"form": "孔洞", "label": "复合词"}], "register": "书面", "sense_fingerprint": "物体上的小洞或窟窿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d26fe1-76de-4d72-b2de-845fecb9db9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13102, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "孔", "is_correct": true, "explanation": "孔 kǒng（第三声）意思是小洞、窟窿。"}, {"text": "空", "is_correct": false, "explanation": "kōng（第一声）与 kǒng（第三声）声调不同，意思是空，不是小洞。"}, {"text": "坑", "is_correct": false, "explanation": "kēng 与 kǒng 韵母不同（eng 与 ong），意思是坑。"}, {"text": "控", "is_correct": false, "explanation": "kòng（第四声）与 kǒng（第三声）声调不同，意思是控制。"}, {"text": "口", "is_correct": false, "explanation": "kǒu 与 kǒng 韵母不同（ou 与 ong），意思是嘴巴或口子。"}], "explanations": {"孔": "孔 kǒng（第三声）意思是小洞、窟窿。", "空": "kōng（第一声）与 kǒng（第三声）声调不同，意思是空，不是小洞。", "坑": "kēng 与 kǒng 韵母不同（eng 与 ong），意思是坑。", "控": "kòng（第四声）与 kǒng（第三声）声调不同，意思是控制。", "口": "kǒu 与 kǒng 韵母不同（ou 与 ong），意思是嘴巴或口子。"}, "sentence_index": null, "correct_answer": "孔"}, "level_3": {"options": [{"text": "孔", "is_correct": true, "explanation": "孔指物体上的小洞，「底部留一个孔用来排水」说的正是排水的洞口。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是照明器具，不是排水的开口，与底部用来排水的语境不符。"}, {"text": "线", "is_correct": false, "explanation": "搭配：「留一个……用来排水」要填排水的开口，「线」搭配不当。"}, {"text": "腿", "is_correct": false, "explanation": "语义：腿是肢体或支撑部件，与排水的功能无关，句意不通。"}], "explanations": {"孔": "孔指物体上的小洞，「底部留一个孔用来排水」说的正是排水的洞口。", "灯": "语义：灯是照明器具，不是排水的开口，与底部用来排水的语境不符。", "线": "搭配：「留一个……用来排水」要填排水的开口，「线」搭配不当。", "腿": "语义：腿是肢体或支撑部件，与排水的功能无关，句意不通。"}, "sentence_index": 0, "correct_answer": "孔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在墙上钻了一条孔，准备挂画。", "explanation": "这里的量词「条」用于细长的东西，孔应该用「个」，这是量词误用。"}, {"text": "他把墙上的孔搬回家了。", "explanation": "孔是物体上的空缺，不是能被搬动的实物，这里把它当成了具体物品。"}, {"text": "这个孔很甜，我很想吃。", "explanation": "「甜」形容味道，孔没有味道，这里搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13102, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "孔", "is_correct": true, "explanation": "孔 kǒng（第三声）意思是小洞、窟窿。"}, {"text": "工", "is_correct": false, "explanation": "声母 g 与 k 不同，声调也不同，gōng 意思是工作。"}, {"text": "红", "is_correct": false, "explanation": "声母 h 与 k 不同，声调也不同，hóng 意思是红色。"}, {"text": "扛", "is_correct": false, "explanation": "韵母 ang 与 ong 不同，声调也不同，káng 意思是用肩膀承担。"}], "explanations": {"孔": "孔 kǒng（第三声）意思是小洞、窟窿。", "工": "声母 g 与 k 不同，声调也不同，gōng 意思是工作。", "红": "声母 h 与 k 不同，声调也不同，hóng 意思是红色。", "扛": "韵母 ang 与 ong 不同，声调也不同，káng 意思是用肩膀承担。"}, "sentence_index": null, "correct_answer": "孔"}, "level_3": {"options": [{"text": "孔", "is_correct": true, "explanation": "孔指物体上的小洞，「螺丝会掉出来」说的正是洞口太大的问题。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能作为螺丝会不会掉出来的对象，句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：「太大了，螺丝会掉出来」这样的描述不适用于手机。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：「眼睛太大」说的是人的外貌，与螺丝掉出来的语境不符。"}], "explanations": {"孔": "孔指物体上的小洞，「螺丝会掉出来」说的正是洞口太大的问题。", "饼干": "语义：饼干是食品，不能作为螺丝会不会掉出来的对象，句意不通。", "手机": "搭配：「太大了，螺丝会掉出来」这样的描述不适用于手机。", "眼睛": "体貌：「眼睛太大」说的是人的外貌，与螺丝掉出来的语境不符。"}, "sentence_index": 6, "correct_answer": "孔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孔正在天上飞。", "explanation": "孔是物体上的洞，不会飞，这里把它当成了会动的东西。"}, {"text": "他是我最好的孔，经常一起玩。", "explanation": "孔是物体上的洞，不能用来称呼人，这里把它当成了人。"}, {"text": "这个孔唱得很好听。", "explanation": "「唱」是人发出声音的动作，孔不能唱歌，这里搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块铁板上有很多只孔，用来散热。", "corrected_sentence": "这块铁板上有很多孔，用来散热。", "error_description": "「孔」的量词错误。「只」多用于动物或成对物品中的一个，不能用于孔，这里误用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门板上钻了两只孔，用来装把手。", "corrected_sentence": "门板上钻了两个孔，用来装把手。", "error_description": "「孔」的量词应为「个」。「只」多用于动物或成对物品中的一个，这里误用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
