INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13103, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据需要把各种设备或物品安排组合在一起。", "primary_collocate": null, "pronunciation": "pèi zhì", "ipa": "pʰei⁵¹ ʈʂʅ⁵¹", "syllable_count": 2, "sentences": [{"text": "容器选择亦具弹性，可采用市售多层发酵箱，亦可自制木质或塑料封闭结构，关键是底部设排水孔，顶部配置可开启盖板以调控温湿度。", "target_word": "配置", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台电脑配置了最新的显卡。", "target_word": "配置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新教室配置着投影仪和空调。", "target_word": "配置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给每个员工配置一台电脑。", "target_word": "配置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要给实验室配置新的设备。", "target_word": "配置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先配置好网络，再打开软件。", "target_word": "配置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人在车间里配置了几台机器。", "target_word": "配置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他自己配置了一台电脑，花了五千块。", "target_word": "配置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院为救护车配置了急救设备。", "target_word": "配置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里配置了床、桌子和空调。", "target_word": "配置", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "配置了", "label": "体标"}, {"form": "配置着", "label": "体标"}, {"form": "配置过", "label": "体标"}, {"form": "重新配置", "label": "复合"}], "register": "中性", "sense_fingerprint": "根据需要把设备、物品安排组合在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f217853e-c44a-4a7e-bf9e-9fbe27715e66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13103, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "配置", "is_correct": true, "explanation": "正确答案，pèi zhì，意思是根据需要安排组合设备。"}, {"text": "培植", "is_correct": false, "explanation": "培植（péi zhí）与配置（pèi zhì）两个音节的声调都不同，意思是培育栽培植物。"}, {"text": "日志", "is_correct": false, "explanation": "日志（rì zhì）与配置（pèi zhì）声母不同（r 与 p），意思是按日记录的本子。"}, {"text": "皮质", "is_correct": false, "explanation": "皮质（pí zhì）与配置（pèi zhì）韵母和声调都不同，意思是皮层的物质。"}], "explanations": {"配置": "正确答案，pèi zhì，意思是根据需要安排组合设备。", "培植": "培植（péi zhí）与配置（pèi zhì）两个音节的声调都不同，意思是培育栽培植物。", "日志": "日志（rì zhì）与配置（pèi zhì）声母不同（r 与 p），意思是按日记录的本子。", "皮质": "皮质（pí zhì）与配置（pèi zhì）韵母和声调都不同，意思是皮层的物质。"}, "sentence_index": null, "correct_answer": "配置"}, "level_3": {"options": [{"text": "配置", "is_correct": true, "explanation": "正确答案。“配置”指顶部的设置与配备，与“可开启盖板”通顺。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：“歌唱”是发声唱歌，不能用来说容器的结构。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做菜，与容器顶部的结构无关。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”的主体应是人，不能与“顶部”搭配。"}], "explanations": {"配置": "正确答案。“配置”指顶部的设置与配备，与“可开启盖板”通顺。", "歌唱": "语义：“歌唱”是发声唱歌，不能用来说容器的结构。", "烹饪": "语义：“烹饪”指做菜，与容器顶部的结构无关。", "散步": "搭配：“散步”的主体应是人，不能与“顶部”搭配。"}, "sentence_index": 0, "correct_answer": "配置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "物业配置了管理费。", "explanation": "这里应该用〈收取〉。配置指安排设备或物品，不表示收取费用。"}, {"text": "他配置了一篇论文。", "explanation": "这里应该用〈发表〉。配置指按需要安排、组合设备或物品，不用于发表文章。"}, {"text": "妈妈在汤里配置了一点盐。", "explanation": "这里应该用〈放〉。配置指安排设备或物品，不用于给汤调味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13103, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配置", "is_correct": true, "explanation": "正确答案。“配置”表示安排、组装设备，与“机器”搭配通顺。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽种植物，不能用于机器。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语应是饮品，不能带“机器”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语是歌曲，与“机器”不搭配。"}], "explanations": {"配置": "正确答案。“配置”表示安排、组装设备，与“机器”搭配通顺。", "种植": "语义：“种植”指栽种植物，不能用于机器。", "喝": "配价：“喝”的宾语应是饮品，不能带“机器”作宾语。", "唱": "搭配：“唱”的宾语是歌曲，与“机器”不搭配。"}, "sentence_index": 6, "correct_answer": "配置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民配置了庄稼。", "explanation": "这里应该用〈浇灌〉。配置指安排设备、物品，不用于给植物浇水。"}, {"text": "他用相机配置了一部电影。", "explanation": "这里应该用〈拍摄〉。配置不表示拍摄影像。"}, {"text": "他热情配置了远方的客人。", "explanation": "这里应该用〈招待〉。配置不用于接待人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校给实验室配置了一空调。", "corrected_sentence": "学校给实验室配置了一台空调。", "error_description": "“空调”前用“一”时要带量词“台”，应说“一台空调”，不能说“一空调”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人已经把机器配置了好。", "corrected_sentence": "工人已经把机器配置好了。", "error_description": "结果补语“好”应紧跟动词，说“配置好了”；“配置了好”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
