INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13104, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "盖板是一种用于遮盖、封闭或保护开口或物体的板状部件。", "primary_collocate": null, "pronunciation": "gài bǎn", "ipa": "kai˥˩ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "容器选择亦具弹性，可采用市售多层发酵箱，亦可自制木质或塑料封闭结构，关键是底部设排水孔，顶部配置可开启盖板以调控温湿度。", "target_word": "盖板", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "井口放着一块盖板，大家要小心。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子的盖板坏了，雨水会进去。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把盖板盖好，不然虫子会飞进去。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块盖板是木头做的，很重。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开盖板，看了看里面的东西。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沟上面有一块盖板，人可以走过去。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖板下面是一个小水池。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖板上有一个孔，方便拿起来。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的花箱需要一块新盖板。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "一块盖板", "label": "量词搭配"}], "register": "书面", "sense_fingerprint": "用来遮盖、封闭或保护开口的板状部件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d26fe1-76de-4d72-b2de-845fecb9db9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13104, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盖板", "is_correct": true, "explanation": "正确：盖板是用来遮盖、封闭或保护开口的板状部件。"}, {"text": "改版", "is_correct": false, "explanation": "gǎi（第三声）与 gài（第四声）声调不同，意思是修改版本，与板状部件无关。"}, {"text": "再版", "is_correct": false, "explanation": "zài 与 gài 声母不同（z / g），意思是再次出版。"}, {"text": "盖碗", "is_correct": false, "explanation": "wǎn 与 bǎn 声母不同（w / b），意思是带盖的茶碗。"}, {"text": "盖满", "is_correct": false, "explanation": "mǎn 与 bǎn 声母不同（m / b），意思是盖得满满的，是动补短语，不是名词。"}], "explanations": {"盖板": "正确：盖板是用来遮盖、封闭或保护开口的板状部件。", "改版": "gǎi（第三声）与 gài（第四声）声调不同，意思是修改版本，与板状部件无关。", "再版": "zài 与 gài 声母不同（z / g），意思是再次出版。", "盖碗": "wǎn 与 bǎn 声母不同（w / b），意思是带盖的茶碗。", "盖满": "mǎn 与 bǎn 声母不同（m / b），意思是盖得满满的，是动补短语，不是名词。"}, "sentence_index": null, "correct_answer": "盖板"}, "level_3": {"options": [{"text": "底座", "is_correct": false, "explanation": "语义：底座在箱子底部，不能开启在顶部，与“顶部配置可开启”相矛盾。"}, {"text": "温度计", "is_correct": false, "explanation": "语义：温度计只能测量温度，无法借开启来调控温湿度，与「以调控温湿度」的语境不符。"}, {"text": "盖板", "is_correct": true, "explanation": "正确：顶部可开启的板状部件，与“调控温湿度”的语境相符。"}, {"text": "墙面", "is_correct": false, "explanation": "搭配：墙面不能“开启”，也不能设在箱子顶部。"}], "explanations": {"底座": "语义：底座在箱子底部，不能开启在顶部，与“顶部配置可开启”相矛盾。", "温度计": "语义：温度计只能测量温度，无法借开启来调控温湿度，与「以调控温湿度」的语境不符。", "盖板": "正确：顶部可开启的板状部件，与“调控温湿度”的语境相符。", "墙面": "搭配：墙面不能“开启”，也不能设在箱子顶部。"}, "sentence_index": 0, "correct_answer": "盖板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个瓶子的盖板拧得很紧，水不会漏出来。", "explanation": "这里应该用〈盖子〉。盖板指板状部件，拧在瓶口的盖子不说盖板。"}, {"text": "蒸饭的时候，我把盖板掀开看了一下。", "explanation": "这里应该用〈锅盖〉。盖板指封住井口、沟口等开口的板，锅上的盖子说锅盖。"}, {"text": "天冷了，妈妈给我拉上一块盖板取暖。", "explanation": "这里应该用〈被子〉。盖板是硬的板状部件，不指软的被子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "布", "is_correct": false, "explanation": "语义：布承受不住人，不能铺在沟上让人走过去。"}, {"text": "围墙", "is_correct": false, "explanation": "语义：围墙是竖立的，不能铺在沟上让人走过去。"}, {"text": "盖板", "is_correct": true, "explanation": "正确：“一块盖板”铺在沟上，人可以走过去，符合语境。"}, {"text": "水桶", "is_correct": false, "explanation": "搭配：水桶用“个”，不说“一块水桶”，也不能铺在沟上。"}], "explanations": {"布": "语义：布承受不住人，不能铺在沟上让人走过去。", "围墙": "语义：围墙是竖立的，不能铺在沟上让人走过去。", "盖板": "正确：“一块盖板”铺在沟上，人可以走过去，符合语境。", "水桶": "搭配：水桶用“个”，不说“一块水桶”，也不能铺在沟上。"}, "sentence_index": 6, "correct_answer": "盖板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这瓶酒的盖板太紧，我拔了半天也拔不出来。", "explanation": "这里应该用〈瓶塞〉。盖板是板状部件，不指塞在瓶口的东西。"}, {"text": "我借了一本书，书的盖板很破了。", "explanation": "这里应该用〈封面〉。盖板指盖住开口或箱体的板状部件，书的封面不说盖板。"}, {"text": "我把盖板当成帽子戴在头上。", "explanation": "这里应该用〈头盔〉一类的词。盖板是盖在开口上的板状部件，不指戴在头上的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "井口上面有一只盖板，小心别掉下去。", "corrected_sentence": "井口上面有一块盖板，小心别掉下去。", "error_description": "量词错误：盖板应用“块”，不用“只”。“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旧仓库门口有一根盖板，别踩坏了。", "corrected_sentence": "旧仓库门口有一块盖板，别踩坏了。", "error_description": "量词错误：盖板是板状物，应用“块”，“根”用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
