INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13105, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指温度和湿度的合称。", "primary_collocate": null, "pronunciation": "wēn shī dù", "ipa": "wən˥ ʂɨ˥ tu˥˩", "syllable_count": 3, "sentences": [{"text": "容器选择亦具弹性，可采用市售多层发酵箱，亦可自制木质或塑料封闭结构，关键是底部设排水孔，顶部配置可开启盖板以调控温湿度。", "target_word": "温湿度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个房间的温湿度很适合种花。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "仓库里的温湿度要天天检查，不然水果会坏。", "target_word": "温湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天南方的温湿度都很高，人容易觉得闷。", "target_word": "温湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆要控制温湿度，才能保护这些老画。", "target_word": "温湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上的天气软件能查今天的温湿度。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "养蘑菇的人要注意棚里的温湿度。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温湿度不合适，花就长不好。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院药房对温湿度的要求很严格。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器能自动调整室内的温湿度。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "温湿度计", "label": "复合词"}], "register": "中性", "sense_fingerprint": "温度和湿度的合称，常用于环境监测与调控", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d26fe1-76de-4d72-b2de-845fecb9db9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13105, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面粉", "is_correct": false, "explanation": "搭配：“调控”不接面粉，面粉不是可调控的环境量。"}, {"text": "体重", "is_correct": false, "explanation": "语义：此处调控的是箱内环境，不是人的体重。"}, {"text": "温湿度", "is_correct": true, "explanation": "正确：“调控温湿度”指调节环境的温度与湿度，与语境相符。"}, {"text": "酵母", "is_correct": false, "explanation": "语义：酵母是发酵的菌，不是可调控的环境量。"}], "explanations": {"面粉": "搭配：“调控”不接面粉，面粉不是可调控的环境量。", "体重": "语义：此处调控的是箱内环境，不是人的体重。", "温湿度": "正确：“调控温湿度”指调节环境的温度与湿度，与语境相符。", "酵母": "语义：酵母是发酵的菌，不是可调控的环境量。"}, "sentence_index": 0, "correct_answer": "温湿度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的温湿度是三十度，外面很热。", "explanation": "这里应该用〈温度〉。温湿度是温度与湿度的合称，不能单指一个温度数值。"}, {"text": "他发烧了，温湿度很高。", "explanation": "这里应该用〈体温〉。温湿度指环境的温度与湿度，不用来说人的体温。"}, {"text": "这间屋子的温湿度在二楼，衣服一直干不了。", "explanation": "温湿度是数值或状况，不是地点，不能说「在二楼」，这里应改说「这间屋子在二楼」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
